// ==UserScript==
// @name         CSL Helper（YouTube 上传 + Play CSL 生成）
// @namespace    csl-helper.local
// @version      3.2.61
// @description  studio.youtube.com 批量上传视频拿链接 → play.google.com/console 挑模板批量建 CSL，只决定要不要填视频
// @author       ops
// @match        https://studio.youtube.com/*
// @match        https://play.google.com/console/*
// @grant        unsafeWindow
// @grant        GM_setValue
// @grant        GM_getValue
// @grant        GM_registerMenuCommand
// @run-at       document-idle
// ==/UserScript==
// ── 变更史不在这个文件里 ──
//
// ★★★★★ 2026-09-20：这儿原来堆着 **1200 多行**版本变更史
//   （每一次真机踩坑的完整现场、走过的弯路、被推翻的假设）。
//   已**原样**挪到 `docs/CHANGELOG-开发史.md` —— 代码一行没动，
//   证据是 `node tools/code-fingerprint.js --check` 仍然绿
//   （那个指纹只认代码、不认注释）。
//
//   要查"某一版为什么改成这样" → 看那份文档，最新的在最上面。
//   要往变更史里加东西 → **往那份文档里加**，别再往这个文件顶部堆。
//
//   ★ 留在源码里的只有**下面这份清单**（"五件事"）——
//     它跟代码紧挨、读代码时随时要用，属于该在手边的东西，
//     所以没跟着走。
// 改这个脚本之前，只需要知道下面五件事。
//
//
// 一、两件事，两个站点
//
//   studio.youtube.com  选本地目录 → 上传 → 填标题 → 不是给小朋友看的
//                       → Unlisted → 发布 → 拿 videoId
//   play.google.com/console  读上面存下来的视频 → 复制模板 → 填 CSL Name
//                       → 填 Preview Video URL → 保存草稿
//
//   两边靠 GM 存储串起来（Tampermonkey 里同一个脚本的存储跨域名共享）。
//   这也是为什么这里是**一个**脚本而不是两个 —— 拆开存储就不通了。
//
//
// 二、Play 侧只改两个字段
//
//   CSL Name 和 Preview Video URL。其余（图片、文案、其它字段）全部
//   由「复制基准 listing」带过来，脚本一个字都不碰。
//   脚本在 Play 侧能做的最后一件事是**保存草稿**，绝不点发布。
//
//
// 三、选择器不分三级
//
//   就一个 CONFIG.selectors，填了就用，没填就报错停下。
//   宁可什么都不做，也不能点错按钮。
//
//   唯一的例外是 YouTube 那套分步对话框的「下一步 / 发布 / 可见性」按钮：
//   那里按可见文字找，文字串在 CONFIG.yt 里可以改 —— 比 class 名稳得多。
//
//
// 四、Shadow DOM 必须穿透
//
//   YouTube Studio 是 Polymer 应用，file input 在 shadow root 里。
//   CSS 选择器**不跨 shadow 边界**，document.querySelectorAll 一个都选不中。
//   所以有 deepQueryAll / deepQueryOne，支持跨边界语法：
//
//       ytcp-uploads-dialog >>> input[type="file"]
//
//   这不是"优化"，是这类页面能不能自动化的前提。别删。
//
//
// 五、File 对象全程不能丢
//
//   scanVideoDir → buildQueue → uploadOneVideo，必须是**同一个 File 对象**。
//   File 不可序列化，一旦被 JSON.stringify 过（比如顺手塞进 GM 存储），
//   读回来就成了普通对象，`dt.items.add()` 会抛
//   `TypeError: parameter 1 is not of type 'File'` —— 而且报错位置在几层调用之外。
//   所以队列只在内存里活着，fileProblem() 在每个关口都查一次。

(function () {
    'use strict';

    // ════════════════════════════════════════════════════════════════════
    // 1. CONFIG
    // ════════════════════════════════════════════════════════════════════

    const CONFIG = {
        // 硬闸门。不在名单里的域名上，脚本直接不启动。
        allowed_hosts: ['studio.youtube.com', 'play.google.com'],

        selectors: {
            // ── YouTube（4 项）──
            // 都可以留空：留空时脚本在页面上自己找（findFileInput / findByText）。
            // 下面这几个"自己找"是有兜底的，所以默认不填也能跑。
            yt: {
                // 上传页的 input[type=file]。留空 = 在页面上找。
                uploadInput: null,
                // 标题输入框。留空 = 找 contenteditable 的那个标题框。
                title: null,
                // 描述输入框。留空 = 找标题框后面紧挨着的那个 contenteditable。
                description: null,
                // 「不是给小朋友看的」那一项。留空 = 按 aria-label 文字找。
                notMadeForKids: null,
                // 最后一步的「完成」按钮（发布 / 保存 / 排期 / 继续）。
                // 留空 = 在对话框里按可见文字找（CONFIG.yt.finish_texts）。
                finishButton: null,
                // 缩略图那几张视频截图。留空 = 按结构找
                // （id/class/aria-label 里提到 thumbnail 的区域里、带 <img>、
                // 又不是「上传缩略图」入口的那些）。填了就用它，
                // 支持 {i} 占位符，例如 '#thumbnail-option-{i}'。
                thumbnailOption: null,
                // 发布后关掉对话框。「完成 / 关闭」按钮，留空 = 不关（不影响结果）。
                closeDialog: null,
            },

            // ── Play（14 个选择器 + 3 个文字清单）──
            // ★ 数字是**数出来的**，不是估的：`createCsl` … `savedSignal`
            //   共 14 个选择器，加上末尾 `next_texts` / `save_texts` /
            //   `draft_texts` 三个文字清单，一共 17 个键。
            //   ★★ 2026-09-18：3.2.28 删掉 3 个**死配置**
            //   （`templateOption` / `previewVideoClear` / `saveDraft`，
            //   源码引用为 0），所以从 17 个选择器 / 20 个键变成现在这个数。
            //   这里原来写着「8 项」—— 从 3.1.0 加到今天早就不是 8 了，
            //   而**过期的数字比没有数字更糟**：读的人会以为"只有 8 个要配"，
            //   配到第 9 个就以为超纲了。同类毛病在本项目文档里也犯过一次
            //   （走查清单那处的「Play 侧 8 个 / 一共 13 个」）。
            // 这几项**没有**自动兜底，填不上就会在对应步骤报错停下。
            // 第一次用之前按 F12 找到对应元素，把选择器填进来。
            // ════════════════════════════════════════════════════════════
            // Play 侧选择器。
            //
            // ★★ 这张表**按 4 步向导的顺序**排 —— 不是按字母，也不是按
            //    "哪个先写"，而是**按你手指点到它的先后**。配的时候从上往下
            //    走一遍，就等于把流程在页面上走了一遍；漏掉哪一个，一眼就能
            //    看出"卡在第几步"。
            //
            // ★ 每个都留 null。null 时 findOne 会**明确报「选择器还没配」并
            //   停下**，不会瞎点 —— 这是故意的：CSL 只有 50 个配额，而且
            //   建出来就占着、不可回收（不像 YouTube 删了能重传）。
            //   宁可停下来问你，也不能点错。
            //
            // ★★★★ 2026-09-18 订正：**步骤归属改了，以真机快照为准**。
            //
            //   原来这份注释是按"常见向导长什么样"推的，而 3.2.27 抓回来的
            //   真机三屏是这样的（同一个 SPA，只能按内容分）：
            //
            //     屏 A「1 设置」  ：名称 + 发布比例(50%) + 开始/结束日期 +
            //                      「选择受众群体」+ 单选(不设置结束日期/限时显示)
            //                      —— **全在第一屏**，不再是"第 1 屏只选模板"
            //     屏 B「2 详细信息」：应用名称 / 简短说明 / 完整说明 +
            //                      `https://www.youtube.com/watch?v=` 输入框
            //     屏 C「4 评价」  ：AI 声明两个单选 + 保存 / 保存为草稿 / 返回
            //
            //   → `name` / `publishPercent` / `audienceAds` 从"第 2 步"**挪到第 1 步**；
            //     `previewVideo` 从"第 3 步"**挪到第 2 步**。
            //   ★ 选择器本身**不看步骤**（脚本按 `nextBtn` 一路往下走），
            //     所以这**不是功能 bug** —— 但它会**误导配选择器的人**：
            //     拿着"第 2 步"这句话去第 2 屏找发布比例，是找不到的。
            //   ★ 第 3 步「资源」在真机上没单独抓到（走查卡要 4 屏，实际回来 3 屏）
            //     → **这里不写它的内容**。没有证据的事不写进注释。
            // ════════════════════════════════════════════════════════════
            play: {
                // ── 入口（列表页）：商品详情里的「创建自定义商品详情」──
                //
                // ★ 2026-09-18 填上。证据是当天抓的真机快照
                //   `snapshots/2026-09-18-1616-play-CSL列表页-创建入口.txt`：
                //     · 「创建自定义商品详情」  aria-label="创建自定义商品详情"
                //       class="mdc-button mdc-button--unelevated text-button primary"
                //
                //   ★★ 为什么不用 `text=创建自定义商品详情`：**同一屏上有两个**
                //     含这串字的按钮 ——
                //       其一（上面那条，主按钮）
                //       其二 「add_2 创建自定义商品详情」 class="…mdc-button--tonal…"
                //     `text=` 会两个都命中、然后取第一个（顺序不保证）；
                //     而 `[aria-label=…]` 只精确命中**主按钮**那一个。
                //     ★ 这是"代价不对称"的老账：点错了不会报错，只会打开别的东西。
                createCsl: '[aria-label="创建自定义商品详情"]',

                // ── 第 1 步「设置」：这一屏只有下面这三样 ──
                //      copyExisting / templateSelect / nextBtn
                //   ★★★ 2026-09-18 订正：`name` / `publishPercent` / `audience*`
                //     原来都挂在这一节下面，**那是错的** —— 它们在第 2 步。
                //     证据：15:05 那两份真机快照（带 URL 和步骤条原文）——
                //       第 1 步的正文里**一个 `input type=text` 都没有**，
                //       只有 3 个 radio + 一个「选择商品详情」下拉。
                //     ★ 这个错**不是排版问题**：照着这节标题去第 1 屏找
                //       "发布比例 / 受众群体"的人，**必然找不到** ——
                //       而"这些键为什么一直配不上"就是这么来的。
                //     下面每个键上方都标了它**真正在哪一步**。

                // 「复制现有商品详情」这个单选（一般默认就是它，但**不要
                // 指望它默认选对**：默认值会随 A/B 之类的开关变）
                // ★ 2026-09-18 填上。证据：入口屏快照
                //   `snapshots/2026-09-18-1617-play-创建向导-第1步设置.txt`：
                //     [✓] 「复制现有商品详情」  input#aD02F6935-…--140.mdc-radio__native-control
                //
                //   ★★ 为什么只能用文字：那三个单选的
                //     id  = `aD02F6935-DF7D-4638-8932-28AAD56C3B37--140`（GUID 形状）
                //     name= `radio-group-a151C66A6-…--2`（GUID 形状，而且**整组共用**）
                //     拿 name 定位会命中组里的**第一个**选项，不是这一个。
                //
                //   ★★★ 2026-09-18 第二次订正：原来这里配的是
                //     `text=复制现有商品详情` —— **它匹配不到**，真机上直接
                //         ✕ 「「复制现有商品详情」」在页面上找不到 ——
                //           按文字「复制现有商品详情」一个都没匹配上
                //     ★ 原因：`text=`（`findOneByText`）找的是元素的**文本内容**，
                //       而这一项的真身是 `input[type=radio]` —— **input 没有文本**，
                //       那四个字在旁边的 `<label>` 上。
                //     ★ 上面那条证据里白纸黑字写着 `mdc-radio__native-control`，
                //       配的时候却按 `text=` 配了 —— **证据就在眼前没用上**。
                //     → 改走 `label=`（`findOneByLabel`）：它找的正是
                //       "**被这段文字标注的控件**"，radio 就是它的典型场景。
                //     ★ 这一步**只需要"能找到 + 确认是选中的"**：真机上它
                //       默认就是 [✓]，`playEnsureChecked` 读到 true 就直接过，
                //       一次点击都不会发生。所以选择器只要定位对就行。
                copyExisting: 'label=复制现有商品详情',
                // 「选择商品详情」那个下拉
                // ★ 2026-09-18 填上。证据：入口屏快照三份都出现了它
                //     · 「选择商品详情 arrow_drop_down」  #a16713A34-…--24
                //       class="button _ngcontent-hgy-55 border"
                //   ★ 它是**按钮**（点开面板），不是字段 —— 别去字段池里找。
                //   ★ 面板展开后**具体选哪一个**不靠选择器，靠 `playFindByText`
                //     按模板名找；所以这里只管"把面板打开"。
                templateSelect: 'text=选择商品详情',
                // ══════════ 第 2 步「详细信息」══════════
                // ★★★ 2026-09-18 订正：下面这一组键**原来挂在「屏 A 第 1 步」下面**，
                //   那是错的。真机快照（15:05:17，URL 在 /custom/create、
                //   步骤条写着「2 详细信息」）里它们**全都在这**：
                //     · 「50% arrow_drop_down」
                //     · 「选择受众群体 arrow_drop_down」
                //     · input type=text label=「自定义商品详情的名称（必填）」
                //   而同一批的**第 1 步**快照里一个 `input type=text` 都没有。
                //   ★ 原先引用的 `docs/2026-09-18-真机三屏证据.md`「屏 A」
                //     （10:41 的诊断转述）把这一步的东西记到了"屏 A" ——
                //     于是所有照着它配选择器的人，都在**错的那一屏**上找，
                //     找一整天也找不着。**这份快照（带 URL + 步骤条原文）为准。**

                // 「自定义商品详情的名称」
                // ★ 2026-09-18 填上。真机 label 原文就是这样（含"（必填）"）。
                //   那个框**没有 id、没有 class** —— 唯一能把名称框和视频框
                //   分开的就是 label 上那段字。所以这条前缀（`label=`）就是
                //   为它加的，见 `findOneByLabel`。
                //   ★ 它**不在第 1 步**：第 1 步那份快照里没有任何 text 输入框。
                name: 'label=自定义商品详情的名称（必填）',

                // 「发布比例」—— 它是下拉，**这里配的是"打开面板的触发按钮"**，
                // 面板里选哪一个靠 `playPickDropdown` 的第二个参数（`'100%'`）。
                //
                // ★★★ 2026-09-18 填上。证据：15:05:17 真机快照（第 2 步）——
                //     · 「50% arrow_drop_down」  #aE2D75C88-…--8
                //       class="button _ngcontent-kje-61 border"
                //   ★★ 同一批 15:05:20 的快照里它变成了「100% arrow_drop_down」——
                //     **那是人手动点的，不是脚本**（脚本从没跑到过第 2 步）。
                //     所以它能证明的只有一件事：**这个下拉把当前值显示在自己
                //     的文字里**。它证明不了"脚本点得动它"。
                //     ★ 把手工操作的结果算成脚本的成功，是本项目的老毛病：
                //       上一轮就差点这么记账（用户当场纠正过）。见 `copyExisting`
                //       那条里写的"证据就在眼前没用上"，是同一类错。
                //
                //   ★★ 为什么这里敢用"显示文字"这种会变的值：
                //     **每一条 CSL 都是新建的，新建时它必然是 `50%`。**
                //     上面那份 50% 的证据，取的正是**新建后刚走到第 2 步**那一屏。
                //   ★★★ 但**注意**：`publishPercent` / `audienceAds` / `copyExisting`
                //     这三个（以及 `templateSelect`）都是"**配上了、但脚本一次都
                //     没成功驱动过**"的状态 —— 真机四连败全停在更早的地方，
                //     一次都没走到它们。所以它们第一次跑的时候要**当新代码看**，
                //     别当成"早就验证过的东西"。
                //
                //   ★★★ **前提**：页面必须停在**列表页**、由脚本自己新建。
                //     如果页面已经停在向导里（上一条没建完），
                //     这个值可能是 `100%` → **必须报错让人处理，不能硬往下走**。
                //     这道门在 `runPlaySteps` 开头（页面形状判断）——
                //     ★ 两处是**配套**的，别只改一边。
                publishPercent: 'text=50%',
                // ★★ 3.2.60：「受众 = 网址」那条路**整个删掉了**（`audienceUrl` /
                //   `audienceUrlInput` 两个选择器是配套的，一起没了）。
                //   运营的原话是「受众网址这个功能可以删除了」——
                //   受众固定走「广告流量」，见 `CONFIG.play.audience` 那段。
                // 「选择受众群体」那个下拉的**触发按钮**。
                //
                // ★★★ 2026-09-18 填上。证据：15:05:17 真机快照（第 2 步）——
                //     · 「选择受众群体 arrow_drop_down」  #aE2D75C88-…--18
                //       class="button _ngcontent-kje-61 border"
                //   ★ 它是**未选状态**的显示文字：新建的 CSL 上受众是空的，
                //     所以默认就显示这四个字（同 `templateSelect` 的道理）。
                //     ★ 选完之后它会变成「广告流量」——**同样受上面那条前提约束**。
                //   ★ 面板里的选项（「广告流量」）不靠这里，走
                //     `CONFIG.play.audience_ads_text`。
                audienceAds: 'text=选择受众群体',
                // 页面**右下角**的「下一步」。四步都有，所以配一个就够 ——
                // 脚本靠"点完验步骤条"往下走，不靠每步一个选择器。
                // ★ 2026-09-18 填上。证据：三份入口屏快照里都是同一个元素
                //     ·[禁用] 「下一步」  class="mdc-button mdc-button--unelevated primary"
                //   ★ 快照里它是**禁用**的，那是正常的 —— 那三张是"还没填完"的入口屏，
                //     必填项齐了才会亮。`playClickNext` 会先等它变亮（等不到才抛）。
                //   ★ 为什么配它而不是靠 `next_texts` 兜底：兜底会**扫全页**
                //     找含"下一步"的元素，而配了它就是**指名道姓**那一个。
                //     兜底照样留着当第二道保险。
                nextBtn: 'text=下一步',

                // ══════════ 第 3 步「资源」══════════
                // YouTube 链接输入框（真机 label 是
                // 「https://www.youtube.com/watch?v=」，框里是空的）
                // ★ 2026-09-18 填上。证据：`docs/2026-09-18-真机三屏证据.md`「屏 B」——
                //   那一栏的 label **就是这条网址**，一个字都不是
                //   "preview video / 预览视频"，所以原来那套关键字一个都对不上。
                //   框里是空的（复制过来的 CSL 不带视频）。
                // ★★★ 2026-09-18 订正：原来这里写的是「第 2 步 详细信息」，
                //   **那是错的** —— 步骤条的原文是
                //      1 设置 / 2 详细信息 / **3 资源** / 4 评价
                //   而运营口述也说的是"**再下一步是资源**，其他全部默认，
                //   就是在视频这里填上我们 YouTube 的视频链接"。
                //   证据本身没错（label 就是那条网址），错的是**它属于哪一步**。
                previewVideo: 'label=https://www.youtube.com/watch?v=',
                // （这一步还有 应用名称 / 简短说明 / 完整说明 / 图标 / 截图，
                //   但那几项**脚本不需要动** —— 复制出来的 CSL 会带着，
                //   所以**不配**。见 check-play-selectors 里"不用配"那一类。）

                // ── 屏 C「第 4 步 评价」──
                //
                // ★★★★★ 2026-09-18 订正：这两个键**指的是同一个单选组里的两个选项**，
                //   **互斥** —— 不是一个"AI 声明开关"加一个"无资源标签"。
                //
                //   证据：`docs/2026-09-18-真机三屏证据.md`「屏 C」原文 ——
                //     AI 声明两个单选：
                //       「不为资源添加标签」[✓] / 「将资源标记为使用 AI 生成或编辑」[ ]
                //   屏上**只有这一组**。
                //
                //   ★ 也就是说：勾了第二个就等于取消第一个。**两个都勾是不可能的。**
                //     而默认配置里 `CONFIG.play.ai_declaration` 和
                //     `no_resource_tag` **两个都是 true** —— 如果两个选择器都配上，
                //     脚本就会先勾 AI 那个、再勾「不为资源添加标签」把它取消掉，
                //     **最终状态由调用顺序决定**。这一版恰好是想要的那个赢
                //     （`noResourceTag` 在后），但那是**碰对的，不是设计出来的**。
                //
                //   ★ 处理：`aiDeclaration` **故意留 null**，
                //     并把 `CONFIG.play.ai_declaration` 置成 false ——
                //     这样脚本**不碰**这个单选组，「不为资源添加标签」保持
                //     页面默认（真机上它本来就是勾上的），终态正确且只动一次。
                //     ★ 别为了"配全"把它填上：填了会多一次点击，
                //       而它点的是**要报给 Google 的内容声明**，不是外观。
                aiDeclaration: null,
                // ★ 2026-09-18 填上。文字照抄真机原文（不是我们起的名）。
                //   ★ 它是**单选项**不是输入框，所以走 `text=`，
                //     落点在 `playEnsureChecked`（"确认它是勾上的"）。
                noResourceTag: 'text=不为资源添加标签',

                // ── 收尾 ──
                // ★ 「保存」**故意留 null**（2026-09-18）。
                //
                //   两个理由，各自都够：
                //   ① **没有可用证据**：整份快照语料里，`save` 唯一的候选是
                //      CSL **列表页**上那一条
                //        ×[禁用] 「保存」  class="mdc-button overflowable-button mdc-button--unelevated"
                //      —— 不可见 + 禁用 + 类名不唯一（同页「隐藏」用的是同一个
                //      `overflowable-button`）。它当上"推荐值"不是因为好，
                //      是因为**没有对手**。填下去就是"点到看不见的东西上"。
                //      （`tools/suggest-play-selectors.js` 已加判据把这种候选拦下。）
                //   ② **不需要它**：`playClickFinalSave` 有**文字兜底** ——
                //      `save` 空着就按 `save_texts` 找，并且用 `isDraftSaveText()`
                //      **拒绝「保存为草稿」**。这条兜底比一个来路不明的选择器可靠。
                //   ★ 真机「屏 C」上「保存」和「保存为草稿」**并排放着**，
                //     配错一个字的代价是"建出草稿"（后台看不到、也没发布）。
                save: null,
                // 保存成功的判据元素（可选，配了才知道存没存上）
                savedSignal: null,

                // ── 保存**之后**那一屏（3.2.45 新增）──
                //
                // ★★★★★ 真机证据（2026-09-20 10:18 快照 —— 点完保存 22 秒后抓的）：
                //   第 4 步的正文里**多出来**两个按钮（第 4 步表单本身没有它们）：
                //
                //     · 「以后再说」      class="mdc-button _ngcontent-bjh-52
                //                             mdc-button--text pc-text-tertiary"
                //     · 「转到概览页面」  class="mdc-button _ngcontent-bjh-52
                //                             mdc-button--unelevated"
                //
                //   运营也确认了这一屏：「这一步完你还要点击以后再说，然后循环上传视频」。
                //
                // ★★ 但**"它们只在保存后才出现"这句话当时没有证据** ——
                //   前几次真机都卡在第 4 步勾选，从没走到过保存，
                //   所以手上**没有保存前的对照快照**。
                //   本项目的规矩是"没法判断的时候停下、不挑一个结论往下走"，
                //   而在这里"停下"的意思是 **UNKNOWN**（保存很可能成功了，
                //   只是脚本不知道）—— 那就白跑一趟，还是要人去翻页面。
                //
                //   → 所以这一版**不靠断言，靠自证**：
                //     保存**前**先扫一遍记下来，保存**后**再扫 ——
                //       · 保存前没有、保存后有 → 它是保存带来的，**可以当信号**
                //       · 保存前就有           → 它**证不了**保存成功，本轮弃用
                //     两种结果都打进日志。这样**第一次真机跑就能拿到答案**，
                //     不用人去看页面，也不用一个可能是假的判据去记账。
                //
                // ★ 判据是"保存后才**出现**"，不是"页面上**存在**" ——
                //   「以后再说」是泛用词，别处也可能有；
                //   而"从无到有"这一刻是**保存这个动作造成的**，那才算证据。
                save_hints: ['转到概览页面', '以后再说'],

                // 保存后要点掉的收尾按钮（按顺序试）。
                //
                // ★ 只放「以后再说」，**不放「转到概览页面」**：
                //   运营原话是点前者；而后者会把页面**跳去概览页**，
                //   可下一条要回的是 **CSL 列表页**（`runPlaySteps` 起点那一段
                //   会判"现在在哪一屏"，不在列表页就不开工）。
                //   点错那个 = 每建一条都要人工把页面拨回去。
                save_dismiss: ['以后再说'],

                // ── 四步向导的**步骤条**（判据，不是操作对象）──
                //
                // ★★★★ 2026-09-18 新增。它不点、不填，回答两个问题：
                //   ① 现在停在**第几步**（出错时能说出"停在 2"而不是"某一步"）
                //   ② 点完「下一步」到底**翻页了没**
                //
                // ★★★ 为什么必须用**它**、而不是"看页面上有什么词"：
                //   真机快照里四条步骤条长这样（运营抓回来的第 1 屏）——
                //
                //     ·    「1 设置」      class="stepper-step _ngcontent-eir-22"
                //     ·[禁用]「2 详细信息」 class="stepper-step … is-disabled"
                //     ·[禁用]「3 资源」     class="stepper-step … is-disabled"
                //     ·[禁用]「4 评价」     class="stepper-step … last is-disabled"
                //
                //   每一条自己带 `aria-label="第 N 步，共 4 步，<名字>"` ——
                //   序号、总数、名字**全在里面**，不用去猜、不用数按钮。
                //   而"当前是第几步"要看**专门表达状态的字段**
                //   （`is-disabled` 类 / `aria-disabled` / `aria-current`），
                //   不是看"这一屏里有没有『名称』这个词"——
                //   我上一轮就是这么判错的（把第 2 屏当成第 1 屏）。
                //
                // ★ 默认值直接给真机上那两条：Play 自己的 `stepper-step`
                //   和 Angular Material 的 `mat-step-header`。
                stepper: null,

                // ── 向导里"下一步"的文字兜底（按顺序试，先精确后模糊）──
                // ★ 选择器没配时靠它；配了也留着当第二道保险。
                next_texts: ['下一步', '继续', 'Next', 'Continue'],
                // 收尾按钮的文字兜底
                save_texts: ['保存', 'Save', '儲存', '保存并发布'],
                // ★ 必须**排除**的文字。放在这里而不是写死在代码里，
                //   是因为"草稿"这个词在别的语言/版本里写法会变。
                draft_texts: ['保存为草稿', '草稿', 'Save as draft', 'Draft'],
            },
        },

        // ── YouTube ──
        yt: {
            // 认哪些后缀是视频
            video_ext: ['.mp4', '.mov', '.m4v', '.webm', '.mkv'],

            // 往下钻子目录
            recursive: true,

            // 一次最多传几个。**0 = 不限**。
            // ★ 3.2.52：20 → **0**。运营「把上限去了吧，YouTube 自己会暂停的」。
            //   189 个每次都被拦，逼他手动筛 —— 而筛选本身就是手滑的来源。
            //   ★ 完整理由写在 `docs/CHANGELOG-开发史.md` 的 3.2.52 一段
            //     （这里不重复：CONFIG 有切片行数上限，要留余量）。
            max_per_run: 0,

            // ★ 3.2.52：连着失败几条就停下整批（0 = 永不放弃）。
            //   ★ 这是"去掉上限"能成立的**前提**，两个改动必须一起做 ——
            //     理由写在 `runYtQueue` 的 catch 那段（那儿才是它的用处）。
            max_fail_streak: 3,

            // 可见性：private / unlisted / public
            // 必须让 Play 那边能访问，Private 校验不过，所以默认 unlisted。
            // ★ 2026-11-06 本地改动：原值是 'public'（与上一行注释矛盾），
            //   首次试跑前改成 'unlisted' —— 避免测试视频被直接公开发布。
            default_visibility: 'unlisted',

            // 传完要不要自动点发布。
            //
            //   false → 硬闸：面板上勾了也不发，视频停在草稿里
            //   null  → 面板说了算（现在的值）
            //   true  → 面板说了算，但默认勾上
            //
            // 不发布就没链接，Play 那边填不了 Preview Video —— 所以正常用 null。
            // false 只在"别拿真频道试"的场合用。
            auto_publish: null,

            // 标题：{prefix}{文件名（去掉后缀）} —— 只在没配 title_template 时用
            title_prefix: '',
            strip_extension: true,
            title_max: 100,

            // ── 当前产品名 ──
            //
            // ★★★★★ 3.2.54 新增。**这一个字段是给测试当哨兵用的**，
            //   它不参与任何实际拼装 —— 标题和描述里都是写死的整份文案。
            //
            //   ★ 它解决的问题：测试里原来钉的是
            //     「标题/描述里**不许出现** SLOT-02」——
            //     那条断言在 3.2.48（换成 SLOT-01）时是**对的**，
            //     但在今天（换回 SLOT-02）就变成**错的**了：
            //     它会红，而读的人第一反应是"改坏了"。
            //   ★★ 一条"钉死某个产品名"的哨兵，在**产品来回切换**的场景下
            //     每次都要改测试 —— 这就是本 skill 里那条
            //     「测试里不许写死运营文案」的**延伸**：
            //     连"不许残留谁"也不该写死，该由**配置**说了算。
            //   → 所以判据改成双向、且都由这一个字段驱动：
            //       ① 文案里**必须出现** `product_name`
            //       ② 文案里**不许出现**名单里**其他的**产品名
            //     ★ 换产品时只改这一行（还有上面那两份文案）。
            product_name: 'BUBBLE-01',

            // 我们做过的产品全集。★ 新增产品时往这里加一条。
            //   用途只有一个：`scanCopyProduct()` 拿它去扫文案里出现了谁。
            known_products: ['BUBBLE-01', 'SLOT-02', 'SLOT-01', 'SLOT-04', 'SLOT-03'],

            // ── 标题模板 ──
            //
            // 填了就用它当所有视频的标题，不再用文件名（文件名当标题太难看）。
            // `{name}` 会替换成文件名（去后缀）—— 想区分开就把它加进去，
            // 不想区分就留着现在这样（所有视频同一个标题）。
            //
            // ★ 截断是按**字符**（code point）算的，不是 JS 的 `.length`。
            //   旧标题是 99 个字符，但 `.length` 是 101 —— 🎰 🔥 各占
            //   2 个 UTF-16 code unit。用 `slice(0, 100)` 会把 🔥 从中间切开，
            //   留下一个孤立的高位代理字符；标题回读核对随即对不上，
            //   那一步抛错停下，**而配额已经扣了**。所以走 truncateChars。
            //
            // ★★★ 3.2.54：**改回 SLOT-02**（运营 2026-09-21：
            //   「现在我们只做 prod-b 的产品，可以把标题和说明改回来了」）。
            //
            //   ★ 这是一次"**换回来**"，而不是新写 —— 所以下面这份标题是
            //     从**上传记录里读回来的实测值**（记录里存着每条视频当时用的
            //     `title`），不是凭记忆写的：
            //       记录里 `Welcome to SLOT-02 — …` 用过 **21 次**
            //       （最早一条 prod-b260326_buffalo_duojitai_KT_1080_gqw.mp4）
            //     ★ 为什么强调这个：标题和描述是**对玩家的承诺**，
            //       而且它是**发出去就收不回**的（频道上那条视频就是证据）。
            //       有记录可查就别靠回忆。
            title_template: 'Welcome to BUBBLE-01 — pop bubbles, blast combos and clear cute cat levels! 🐱💥',

            // ── 描述模板 ──
            //
            // 同样支持 `{name}`。留空 = 不填描述（YouTube 描述是选填的）。
            //
            // 写这段而不是"从别处抓一段"的原因：CSL 那边只关心预览视频，
            // 描述是给 YouTube 页面看的门面。固定一份，不做变量。
            //
            // ★★★ 3.2.54：**改回 SLOT-02**（运营 2026-09-21）。
            //
            //   ★ 来源与上面那份标题不同，必须说清：
            //     标题能从**上传记录**里读回来核对（记录存了 `title` 字段），
            //     而**描述记录里不存** —— 所以这份是从本项目自己的
            //     变更记录（`docs/CHANGELOG-开发史.md` 3.2.48 那节的对照表）
            //     恢复的上一版原文。
            //   ★★ 也就是说：这份描述**没有拿到第三方证据**。
            //     发之前请核对一眼 —— 随便打开一条 9/17 传的 prod-b 视频看描述，
            //     跟下面这份对一下（`docs/CHANGELOG-开发史.md` 里有链接）。
            //     ★ 描述是**对玩家的承诺**（"100+ SLOTS"、"2 MILLION virtual coins"
            //       都是具体数字），发出去就收不回。
            //
            //   ★ 骨架：开场一句 → ⚡ 机型 → 🎁 玩法 → 💰 新手奖励 → ⚠️ 免责。
            //   ★ 改完跑 `node tools/check-copy-length.js` 核对长度（有上限）。
            description_template: [
                'Pop, match and blast your way through a world of cute cat puzzles.',
                '',
                '🐱 POP AND MATCH',
                'Aim, shoot and pop colorful bubbles to clear the board.',
                '',
                '💥 CHAIN REACTIONS',
                'Line up your shots to trigger combos and clear whole clusters in one go.',
                '',
                '😺 MEET THE CATS',
                'Adorable feline friends keep you company all the way through.',
                '',
                'Download now and start popping — open the game and play!',
            ].join('\n'),

            // 按可见文字找按钮。改版或换界面语言时改这里，不用动代码。
            //
            // ★★★ 「继续」是 2026-09-16 的真机日志抓出来的，代价是一次跑空：
            //   中文界面下，分步对话框的主按钮叫 **「继续」**（实测 id：
            //   `#next-button`），而这里原来只写 ['Next', '下一步'] ——
            //   一个都不命中，于是 `clickNextUntilDone` **一次都没点**
            //   （日志里连「点了 N 次『下一步』」这句话都没有），
            //   对话框停在「详细信息」不动，后面所有"按步骤"的动作全落在错步骤上。
            //   ★ Continue 是它的英文对应词，一起补上。
            next_texts: ['继续', 'Continue', 'Next', '下一步'],

            // ── 最后一步的「完成」按钮 ──
            //
            // ★ 这里**不能**只叫它「发布」。真机第二次试跑就是栽在这上面：
            //   视频设成 **unlisted（不公开列出）** 时，YouTube 把主按钮的
            //   文案从「发布 / Publish」换成「保存 / Save」——
            //   因为 unlisted 不是"公开发布"，是"保存成不公开列出"。
            //   而「保存」点下去**同样会让视频可用**（拿得到链接，Play 能校验）。
            //   所以这不是"没发布"，只是按钮换了个名字。
            //
            //   只配 ['Publish','发布'] 的结果：等 15 秒等不到，
            //   报「等不到发布按钮」，而按钮一直就在那里 —— 谎报军情。
            //
            //   顺序有意义：findByText 先精确匹配、再子串匹配，都按这个顺序。
            //
            // ★★★ 3.2.6：**「继续 / Continue」从这里删掉了。**
            //   它原来躺在最后当兜底，代价是一次"谎报成功"：
            //   真机上 `next_texts` 没命中「继续」（那时还没补），
            //   对话框停在「详细信息」没往前走，于是 `findByText` 一路兜底
            //   到了这里的「继续」，点下去 —— **只是翻了一页**，
            //   视频根本没保存，而日志写的是「✓ 完成：https://…」。
            //   用户以为跑通了，实际停在「公开范围」等着按保存。
            //
            //   ● 「继续」是 `#next-button`，是**翻页**按钮，不是完成按钮。
            //     完成按钮是 `#done-button`（unlisted 时叫「保存」）。
            //     一个"翻页词"混进完成按钮的候选里，最坏结果不是"找不到"，
            //     而是"找到了一个错的、然后宣布成功"——比找不到严重得多。
            //     所以宁可这一项找不到、报错停下（这一步停了不扣配额，
            //     视频也已经传上去了），也不要静默地假装完成。
            finish_texts: [
                'Publish', '发布',
                'Save', '保存',
                'Schedule', '排期',
                // ★★★ 2026-09-16 真机实测：选了「安排时间」之后，
                //   这个按钮的文字是 **「预定」**（id 还是 `#done-button`）。
                //   清单里没有它 → 「等不到最后一步的完成按钮」，
                //   而按钮一直就在那儿（结构快照里写着 `· 「预定」 #done-button`）。
                '预定', 'Reserve', 'Set',
            ],

            // ── 缩略图：从 YouTube 自动生成的视频截图里选一张 ──
            //
            // ★ 这是**选填项**。YouTube 本来就会自己挑一张，所以这一步
            //   失败就跳过，绝不为它让整批停下（跑一次就是一份配额）。
            //
            // index 是**第几张（0 起）**：0 = 第一张。
            // ★ 脚本没法判断"哪张好看" —— 那一排是自动截的视频帧，
            //   只能按位置选。真机上生成几张、哪张合适，看一眼再定。
            thumbnail_index: 0,

            // 自动截图是**系统生成**的，需要一点时间（运营原话：
            // 「缩略图那个是要系统生成需要一点时间，可以等一下再选择」）。
            // 刚投进去时这一块常常还是空的，所以这里给足等待 ——
            // 这个对话框此刻正挂着上传，等一下不占额外时间。
            // 等不到就跳过（选填项），只是这一条视频用 YouTube 自己挑的那张。
            thumbnail_wait_ms: 60000,

            // 点一下"选中式"控件之后，等它**把状态反射出来**的宽限（毫秒）。
            //
            // ★ 为什么需要这个数：控件的选中状态常常是**异步**更新的
            //   （Polymer 的 observer 走微任务/下一帧才把 aria-checked 写出来），
            //   点完立刻读会误判成"没点上"，然后白试下一层。
            // ★ 为什么要做成配置项：测试和变异测试要把它压小。
            //   每条"故意点不动"的用例都会真等这么多毫秒 × 十几次尝试，
            //   压不下去的话整套变异测试会慢到没法跑。
            click_settle_ms: 500,

            // 完成按钮从**禁用**等到**可用**最多等多久。
            //
            // ★★★ 3.2.15：这个值的存在理由是一次失败。
            //   10:35 真机：选完可见性只隔 1 秒就去点「发布」，
            //   而排期区还在异步渲染 → 按钮因联动暂时禁用 →
            //   旧代码一看禁用就抛错停下，**抢在页面准备好之前放弃了**。
            //   "禁用"是个**暂时状态**，先等一会儿再说。
            //
            // ★★★ 3.2.16：8 秒 → **30 秒**。
            //   11:05 真机：从「准备上传」到点「发布」总共只过了 **10 秒**，
            //   而那条视频 13.8 MB —— 逐条短、批量时前一条还在转码就轮到下一条，
            //   8 秒很可能不够。而且快照里出现了
            //   `ytcp-uploads-still-processing-dialog`（视频还在处理），
            //   这件事**等就能好**，只是要等得比 8 秒久。
            //
            //   ★ 等待期间每 5 秒报一次进度，并如实说"页面上有没有
            //     可见的『还在处理』对话框" —— 30 秒的沉默是最糟的：
            //     用户分不清是在等还是卡死了。
            finish_enable_timeout_ms: 30000,

            // 点完「发布」之后，最多等多久才算"YouTube 真的没收下"。
            //
            // ★★★ 3.2.18：这个数**不是"等它忙完"的时间**，是
            //   **"一条回执都没有"的耐心上限**。
            //
            //   3.2.17 原来的意思：把它当"等 YouTube 忙完"，
            //   所以一旦出现「视频还在处理」就继续死等、等满就报失败。
            //   12:11 真机证明这是错的：用户**看着那条视频变成「已发布」**，
            //   而脚本还在那儿等、最后报了一句"YouTube 没接受这次保存"。
            //
            //   → 现在的语义：**回执到了就立刻收工**（见 waitPublishOutcome ④）。
            //     这个 30 秒只兜底"连回执都没有"这一种情况：
            //     · 点了「发布」→ 对话框关掉            → 成功（①）
            //     · 点了「发布」→ 出现「视频还在处理」   → 成功（④，已受理）
            //     · 点了「发布」→ 30 秒里什么都没发生     → **这才叫没收下**
            //
            // ★ 为什么不是 0（点完就认定成功）：那会把"点了没反应"
            //   （排期没设 → `#done-button` 禁用 → 点击无效）也认成成功，
            //   而那条路径是**真的失败**、真的需要用户手动补。
            //   所以窗口必须存在，只是它等的是"回执"，不是"忙完"。
            //
            // ★★ 关键一课：**「底部按钮全灰」是"忙"的特征，不是"坏"的特征。**
            //   而"忙"和"坏"只能靠**等**来区分；抢在它忙完之前下结论，
            //   就是把成功报成失败。30 秒是运营按经验给的数
            //   （"发布后系统在自动上传和审核"）。
            post_publish_wait_ms: 30000,

            // 「排期」这一步，确认是 Short 之后只等这么久。
            //
            // ★★★ 3.2.18：Short 上排期那一组**永远不出现**
            //   （YouTube 不给 Shorts 排期），而这里原来无条件等
            //   `wait_timeout`（15 秒）—— 18 条 × 15 秒 ≈ **4.5 分钟纯白等**。
            //
            // ★ 但不能"确认是 Short 就一秒不等直接跳过"：
            //   `detectShortVideo()` 只说了"链接是 /shorts/ 形态"，
            //   万一这次 YouTube 真给了排期区，跳过的后果是
            //   **完成按钮禁用 → 点了没反应 → 整条失败**。
            //   所以给一个**短得多但仍然存在**的窗口：
            //   渲染出来了就照点，出不来才跳过。
            short_schedule_probe_ms: 2000,

            // 等待期间每隔多久报一次进度。
            // ★ 30 秒的沉默是最糟的：用户分不清是在等、还是卡死了。
            //   做成配置项是为了让测试把它压小（否则每条用例白等 5 秒）。
            post_publish_report_ms: 5000,

            visibility_texts: {
                private: ['Private', '私有', '不公开'],
                unlisted: ['Unlisted', '不公开列出'],
                public: ['Public', '公开'],
            },

            // 受众声明里要选的那一项 —— 按**文字**找的兜底清单。
            //
            // ★ 必须带 "not"。YouTube 是**一对** radio：
            //     「Yes, it's made for kids」 / 「No, it's not made for kids」
            //   只写 "made for kids" 两个都命中，先撞上哪个全看 DOM 顺序 ——
            //   那是把"选错受众"变成一个随机事件。
            //
            // ★★ 但这张表**不是**主要判据，只是个覆盖开关。
            //   真机第二次试跑把这张表的毛病暴露干净了：中文界面下真实文案是
            //     「不，并非为儿童打造」
            //   而表里写的是「不是给小朋友看的」「并非面向儿童」——
            //   **两个都不是它的子串**，于是稳定匹配不到。
            //   靠"把见过的文案一条条抄进表里"永远追不上：语种多、文案会改、
            //   还有简繁之分。所以真正的判据是 isNotForKidsLabel() 那个谓词
            //   （儿童词 + 否定词），这张表只用来覆盖谓词万一失手的场景。
            not_made_for_kids_texts: [
                'not made for kids',
                '不是给小朋友看的',
                '并非面向儿童',
            ],

            // 可见性面板下面那个「排期 / 发布时间」选项。
            //
            // ★ 真实页面里，选完可见性会出现一个可展开的 Schedule 区。
            //   不碰它的话，"选了公开"之后视频其实还停在待排期状态。
            //   这里有值就顺手点一下（选最近的/立即），**找不到就静默跳过**
            //   —— 排期是选填的，为它报错停下不值得。
            // 「什么时候发」那一组。**必须选中一个**，否则最下面那个
            // 保存 / 发布 / 预定 按钮是**禁用**的 —— 点了没反应，
            // 而对话框一动都不动（3.2.7 的守卫就是在这儿拦下来的）。
            //
            // ★★★ 3.2.16：顺序反过来了 —— **「立即发布」在前，「安排时间」在后**。
            //
            //   运营 2026-09-17 原话：「我需要批量上传的功能了，**不要排期
            //   直接发布**就行了」。而这里原来是 `['安排时间', …]` 打头 ——
            //   也就是脚本一直在优先给别人**定时**，正好和要的相反。
            //
            //   ★ 而且"排期"这个词有两个意思，改之前必须分清：
            //     · 「安排时间」= 定时发布（schedule）→ 用户**不要**这个
            //     · 「立即发布」= 现在就发（publish now）→ 用户**要**这个
            //   原来把它当成"必须点一下才能激活发布按钮的那个开关"，
            //   所以优先点「安排时间」。现在明确：要的是**立即发布**。
            //
            //   ★ 2026-09-16 那句运营原话仍然成立（不点这一组，
            //     「发布」按钮就是灰的），所以「安排时间」**留着兜底** ——
            //     但只在找不到「立即发布」时才用。
            schedule_texts: ['立即发布', '立即', '现在', 'Publish now',
                'Immediately', '安排时间', 'Schedule'],

            // 找不到东西时，把滚动区往下拨几档再找。
            //
            // ★ 这不是"优化"，是必须的：受众声明和排期都在对话框的滚动区里，
            //   实测**要滚到那一段才渲染出来**。不滚的话 findByText 找不到，
            //   日志只说一句"找不到"，看不出是"真没有"还是"没滚到"。
            //   拨 scroll_passes 次，每次 sleep scroll_pause 毫秒。
            scroll_passes: 4,
            scroll_pause: 250,
        },

        // ── Play ──
        play: {
            // ════════════════════════════════════════════════════════════
            // 下面这些值来自运营 2026-09-17 口述的**真实 4 步流程**。
            // 原话和代码的对应关系写在每一行上面 —— 改了这里，就等于改了
            // 真机上点出来的东西，所以每一条都留了出处。
            // ════════════════════════════════════════════════════════════

            // 第 1 步「选择商品详情」里选哪个。
            // 原话：「要在选择商品详情里选择默认商品详情」。
            template_name: '默认商品详情',

            // 一次最多建几个。
            // ★ 存在的意义是**防手滑**：配额 50 个、不可回收，
            //   一次跑 20 个不如先跑 2 个看看对不对。
            //
            // ★★★ 2026-09-18：6 → 20（跟 YouTube 侧那个值取齐，见 1446 行附近）。
            //   运营要的是"整批一起跑"，17 条分三批要手动搅三遍，
            //   而每搅一遍就多一次手滑的机会 —— 上限太低反而**更不安全**。
            //   ★ 这条保护的意义是拦"一上来就把 50 个配额全烧掉"，
            //     不是拦"把眼前这一批做完"。20 够用，且**上限依然开着**：
            //     真想一次跑满，改这一个值就行（改完下面那个提示会跟着变）。
            max_per_run: 20,

            // ── 第 2 步 ──

            // 发布比例。**100 = 不做 A/B**，全部流量都走这一版。
            // 原话：「我们直接 100% 发布不要 50%，他默认 50%」。
            // ★ 之所以要写死成 100 而不是"页面默认"：**默认是 50**，
            //   不主动拉就会只发一半流量，而且这事在结果上很难看出来。
            publish_percent: 100,

            // 目标受众群体：**固定走「广告流量」**。
            //
            // ★★ 2026-09-17 定的方向（运营原话「受众网址不用管了先」），
            //   2026-09-22 运营说「受众网址这个功能可以删除了」→
            //   3.2.60 把「网址」那条路**整个删掉**了：
            //     · 面板上的「受众网址」输入框、「目标受众群体」下拉
            //     · `audienceUrl` / `audienceUrlInput` 两个选择器
            //     · 网址池那套（`parseUrlList` / `remainingUrls` /
            //       `pickNextUrl` / `STORE.PLAY_URL_USED` / `audience_urls`）
            //
            //   ★ 留着这条路**不是中立的**，它会主动害人：面板下拉里
            //     「网址」那一项一旦被选中，`playState` 是**内存变量、不持久化**，
            //     而那时网址框里是空的 →
            //     `if (!task.audienceUrl) throw StepError('这条任务的受众网址是空的…')`
            //     → **一次都不点就整条失败**，而且那句错误信息把人指向一个
            //       "我们根本不打算填"的框 —— 纯误导。
            //     删掉之后，这个状态**在面板上已经无法表达**了。
            audience: 'ads',

            // 「目标受众群体」下拉里**「广告流量」那一项的文字**。
            //
            // ★★★ 2026-09-18 新增。它是**页面文案**，所以不能写死在代码里：
            //   真机上那个下拉的选项是（运营 10:56 口述）——
            //       买家状态 / 用户状态 / 广告流量 / 国家/地区 /
            //       预注册状态 / 搜索关键字 / 网址
            //   而「广告流量」这一项的**说明文字**是「通过广告流量定位的用户」。
            //   → 也就是说 **「广告流量」是它自己说明文字的子串**。
            //     这不是问题（选项匹配是"精确优先、再取最短子串"，
            //     两种情况都会落在同一个选项上），但它说明了为什么
            //     **不能**改成"第一个命中的"那种写法。
            //
            // ★ 那个下拉按钮本身的文字是**当前值**（没选过是「选择受众群体」，
            //   选过之后变成「广告流量」）—— 所以拿按钮文字当判据会在
            //   第二次跑时失效。选项文字才是稳定的那一半。
            audience_ads_text: '广告流量',

            // ── 第 4 步 ──
            // 原话：「我们在评价这步只要选择 AI 资源声明，不为资源添加标签」。
            //
            // ★★★★★ 2026-09-18 订正：这句话讲的是**一个动作**，不是两个。
            //   真机「屏 C」（见 `docs/2026-09-18-真机三屏证据.md`）上
            //   **只有一组单选**：
            //       「不为资源添加标签」[✓] / 「将资源标记为使用 AI 生成或编辑」[ ]
            //   —— **互斥**。勾一个就等于取消另一个。
            //
            //   ★ 所以 `ai_declaration` 和 `no_resource_tag` **不可能同时生效**：
            //     原来两个都是 true，意思是"两个都去勾"，而第二个会把第一个取消掉
            //     → **终态由调用顺序决定**。这一版恰好是想要的那个赢
            //     （`noResourceTag` 在后），但那是**碰对的**。
            //   ★ 更要紧的是分量：这一栏是**报给 Google 的内容声明**，
            //     不是外观。顺序哪天被调一下，或 `switch` 一下，
            //     就会往 Google 报一个"含 AI 生成内容"的假声明，而**不报错**。
            //
            // ★ 定案：`no_resource_tag: true` 负责做事（勾「不为资源添加标签」），
            //   `ai_declaration: false` = **不碰**这个单选组。
            //   真机上「不为资源添加标签」本来就是勾上的默认值，
            //   所以"只确认、不翻来覆去"就得到正确终态。
            //   ★ 反过来说：**别把 ai_declaration 改回 true**，
            //     除非先想清楚"要往 Google 报 AI 生成"这个语义。
            ai_declaration: false,
            no_resource_tag: true,
        },

        // ── 节奏 ──
        step_pause: 500,
        wait_timeout: 15000,

        // ★ 3.2.56：**被后台拖多久之后放弃等待**（毫秒）。
        //
        //   `waitFor` 把"标签页在后台"的那段时间**不计入等待预算**
        //   （后台时浏览器把定时器压到最慢一分钟一次，那不是页面没准备好，
        //   是我们自己没轮到看）。但只有这一条的话，
        //   **永远在后台 + 页面真坏了** → 永远等下去，脚本一声不吭地卡住。
        //   → 真实流逝超过 `等待预算 + 这个宽限` 就放弃。
        //   ★ 10 分钟：够覆盖"切走办点事再回来"，又不至于让人以为它死了。
        hidden_grace_ms: 600000,
        // 找一个**控件**最多等多久（元素出现，不是状态变化）。
        //
        // ★★★★ 2026-09-18 新增。起因是真机 15:19:16 那一次：
        //   点了「创建自定义商品详情」→ `sleep(step_pause * 2)` = **1000ms**
        //   → `findOne('label=复制现有商品详情')` → **找不到就报错**。
        //   而页面形状显示那一刻**还在列表页** —— 向导压根没渲染出来。
        //   ★ 那句报错读起来是"选择器配错了"（修法：改 CONFIG），
        //     而真实原因是"**向导还没打开**"（修法：等 / 查为什么没打开）。
        //     两者的修法完全相反 —— 跟 15:04 那次「入口找不到 /
        //     其实是停在向导里」是**同一个形状**。
        //
        // ★ 为什么单开一项，不复用 `wait_timeout`：
        //   15000 那项的语义是"等一个**状态变化**"（保存成功信号、翻页），
        //   而这个是"等一个**元素出现**"。两件事的合理时长差一个量级 ——
        //   一个 Angular 页面渲染一个单选要几秒，而"存上没存上"可能要更久。
        //   混用会让其中一边的等待时间明显不合身。
        //
        // ★ 只在**找不到时**才等满：命中时零额外延迟（见 findOne 里那次
        //   "先立刻试一次"）。所以这个值给得宽一点不会拖慢正常流程。
        find_timeout_ms: 8000,
        // 文件投进去之后，等 YouTube「开始上传」的反应时间。
        // 只等"页面开没开工"，不是等视频传完。
        inject_react_timeout: 15000,
    };

    // ════════════════════════════════════════════════════════════════════
    // 2. STORAGE
    // ════════════════════════════════════════════════════════════════════

    const STORE = {
        // 跨站点共享：YouTube 侧写，Play 侧读
        VIDEOS: 'csl_helper_videos',
        // 各站点自己的表单记忆
        YT_FORM: 'csl_helper_yt_form',
        PLAY_FORM: 'csl_helper_play_form',
        // 已经建过的 CSL（防重复点"生成"白占配额）
        DONE: 'csl_helper_done',
        // ★ Play 侧**自己**一份已建记录。
        //   为什么不复用 DONE：DONE 里存的是 YouTube 侧的**视频标题**
        //   （"这批传了什么"），而这里要存的是**视频文件名**（"这版建没建过"）。
        //   两者在真机上就是不一样的东西 —— 标题可以改、文件名不会。
        //   混用会出现"标题一样但文件不同"被误跳过。
        PLAY_DONE: 'csl_helper_play_done',
        // ★ 3.2.60 删掉了 `PLAY_URL_USED`（"用掉的受众网址"）——
        //   受众固定走广告流量之后，"依次填不要重复"这件事不存在了。
        //   旧存储里的那个键**不主动去清**：它已经没有任何读者，
        //   留着的代价只是几十字节，而去清它要写一次存储、还得处理"写失败"。
        // 面板被拖到哪儿了。★ 每个站点各存一份（YouTube 和 Play 的页面
        // 布局不一样，"躲开要点的东西"的位置也就不一样）。
        PANEL_POS: 'csl_helper_panel_pos',
        // ★★★★★ 3.2.47：清理上传记录之前的**自动备份**。
        //
        //   为什么要备份（而不是直接清）：
        //   `VIDEOS` 这一份是**Upload 侧和 Play 侧之间唯一的桥** ——
        //   Play 那边的视频列表、文件名、YouTube 链接全是从它读出来的。
        //   清掉之后**没法从页面上重新推出来**（YouTube 侧只能看到"传过什么"，
        //   对应不到本地的哪个文件）。清理是不可逆的，而这个代价太大了。
        //   → 所以清理永远先落一份备份在这儿，并且**备份的条数和时间
        //     要能显示在面板上** —— "能不能找回来"是这一步唯一让人不安的事，
        //     不能只靠"我们备份了"这句话让人放心。
        //
        //   ★ 只留**一份**（覆盖式），不做多版本历史：
        //     多版本会让"恢复"这个动作本身变得需要选择，而这是运营在用的面板，
        //     多一个需要选的东西就多一处会选错的地方。
        VIDEOS_BACKUP: 'csl_helper_videos_backup',

        // ★★★★★ 3.2.53：「这个文件**曾经**传过」的名单，`{fileName: 时间}`，**只增不减**。
        //
        //   为什么单独开一份、不复用 VIDEOS —— 这一条是运营问出来的：
        //   「你下次会不会显示没有上传？」
        //
        //   ★ 会，而且路径很具体：**归档会清空 VIDEOS**，而「已上传」的判据
        //     原先就是读 VIDEOS → 归档之后**标记全没了** → 下次扫目录时
        //     所有文件都显示"没传过" → 而「跳过已上传的」是**默认开**的，
        //     它以为自己跳过了什么，实际一个都没跳 → **整批重传**。
        //   ★★ 代价跟当初做这个功能的原因一模一样：
        //     频道上多出一份、额度不回收、还得专门去删。
        //
        //   → 所以两份数据必须分开，它们回答的是**两个不同的问题**：
        //     · VIDEOS        = **这一批**传了什么（会被归档清掉，给 Play 侧当队列用）
        //     · UPLOADED_EVER = **历史上**传过什么（**归档不动它**，只给"传没传过"用）
        UPLOADED_EVER: 'csl_helper_uploaded_ever',

        // ★★★★★ 3.2.56：**待补传名单** —— 上次没传成的那些。
        //
        //   运营 2026-09-21 的原话：
        //   「我不小心切后台导致失败，然后舍弃重新开始 —— **记得把舍弃的那个上传**」
        //
        //   ★ 功能上其实**本来就会补上**：失败的那条不记账（见 runYtQueue 的
        //     catch 分支），所以它不在 VIDEOS / UPLOADED_EVER 里，
        //     "跳过已上传的"不会拦它 —— 只要他下次勾上，就会被传。
        //
        //   ★★ 那为什么还要这份名单？—— 因为**看不见**：
        //     · 失败清单只在日志里，批次跑完就滚上去了，关掉页面更是什么都没了
        //     · 他不知道"失败的是哪个文件"，也就不知道下次要特意勾上谁
        //     · 而他要为此跑一趟 Studio 去搜、去对 —— 那正是他想省掉的事
        //
        //   → 这份名单的作用**不是补功能，是把那件事变成可见的**：
        //     面板上一直挂着"待补传 N 条（文件名…）"，
        //     下次点一下「只勾待补的」就能把它们全带上。
        //
        //   ★ 上限 50 条：它是**待办**，不是档案。堆到几百条说明有系统性问题，
        //     那时该看的是报错，不是这张单子。
        PENDING: 'csl_helper_pending_uploads',
    };

    function storeGet(key, fallback) {
        try {
            const raw = GM_getValue(key, null);
            if (raw === null || raw === undefined) return fallback;
            return typeof raw === 'string' ? JSON.parse(raw) : raw;
        } catch (e) {
            return fallback;
        }
    }

    function storeSet(key, value) {
        try {
            GM_setValue(key, JSON.stringify(value));
        } catch (e) {
            console.error('[CSL Helper] 写存储失败', e);
        }
    }

    /**
     * 脚本自己的版本号 —— **给日志用的**。
     *
     * ★★★★★ 2026-09-19（3.2.42）：为什么要让日志说出"跑的是哪一版"。
     *
     *   起因是实打实的一轮白干：用户到底装没装上新版，**日志里一个字都不说**。
     *   那一轮我判断"跑的还是旧版"，靠的是**对比代码特征** ——
     *   新版会多打一行 `勾选项元素：`、失败信息里会多一段"现场"。
     *   ★ 这叫**旁证**，而旁证会错：新版要是恰好没走到那一行，特征就看不出来。
     *     代价是用户白跑一轮、我白分析一轮，还得出一个**方向相反**的结论
     *     （"新版没修好" vs "根本没装上新版"）。
     *
     *   ★ 本项目早有这条规矩：**发版必须升 `@version`**
     *     （同版本号分不出装的是哪一份，实测同版本号内容差 139 行）。
     *     但升版本号只解决了"两份不一样"，没解决"**用户手里是哪一份**" ——
     *     所以还要把它**放到用户看得到的地方**（批次开头那行日志）。
     *
     *   ★ 读不出来就**如实说读不出来**：测试环境没有 `GM_info`，
     *     某些管理器也不给读。不猜、更不假装知道。
     */
    function scriptVersion() {
        try {
            if (typeof GM_info !== 'undefined' && GM_info && GM_info.script
                && GM_info.script.version) {
                return String(GM_info.script.version);
            }
        } catch (e) { /* 某些管理器读它会被拒 */ }
        return '读不到（管理器没给 GM_info）';
    }

    // 上传结果的记录。**这里只存可序列化的东西** —— 绝对不要往里放 File。
    function loadVideos() { return storeGet(STORE.VIDEOS, []); }
    function saveVideos(list) {
        // 只留可序列化的字段，顺手把 File 挡在外面（真放进去会静默变成 {}）
        const clean = (list || []).map(function (r) {
            return {
                relPath: r.relPath, fileName: r.fileName, size: r.size,
                title: r.title, videoId: r.videoId || null, url: r.url || null,
                state: r.state, at: r.at,
                // ★ 3.2.57：手动补录的标记。
                //   ★★ 这个函数是**白名单式**过滤（只留这里列出来的字段）——
                //     新加的字段**漏一个就会被静默丢掉**：不报错、读回来是
                //     `undefined`。实测就是这么被用例抓到的（补录成功、
                //     写进去了，而 `manual` 没了）。
                //   ★ 只在**真**的时候才写这个键（`undefined` 会被 JSON 丢掉），
                //     省得每条自动上传的记录都多一个 `manual:false`。
                manual: r.manual || undefined,
            };
        });
        storeSet(STORE.VIDEOS, clean);
        // ★ 3.2.53：**每一次记账都同时也进「历史上传过」那份名单。**
        //   放在这里而不是放在调用点，是因为调用点有好几个
        //   （正常上传 / 取回归档 / 以后可能还有别的），
        //   漏一个的症状是"某个来源的记录不进名单"——而那要等到
        //   **归档之后才会暴露**，中间隔着很久，根本联想不到。
        markUploadedEver(clean);
    }

    /** 读「历史上传过」的名单，`{fileName: 时间}`。读不出来就当空。 */
    function loadUploadedEver() {
        const m = storeGet(STORE.UPLOADED_EVER, null);
        if (!m || typeof m !== 'object' || Array.isArray(m)) return {};
        return m;
    }

    /**
     * 把一批文件名并入「历史上传过」的名单。**只增不减**（时间取更晚的那个）。
     *
     * 返回 `{total, missing}`：
     *   · `total`   = 并入后名单里一共有多少个
     *   · `missing` = 这批里有几个**没进名单**（= 写失败了）
     *
     * ★ 为什么要回读：`storeSet` 内部是 try/catch 吞错的，
     *   **写失败不抛**（比如油猴存储配额满）。不回读的话，
     *   "已经记下了"就是一句**没有依据的话** —— 而这份名单恰恰是
     *   "归档之后还认不认得这批"的唯一依据。
     */
    function markUploadedEver(records) {
        const m = loadUploadedEver();
        (records || []).forEach(function (r) {
            const k = r && r.fileName;
            if (!k) return;
            const at = String(r.at || '') || new Date().toISOString();
            if (!m[k] || String(m[k]) < at) m[k] = at;
        });
        storeSet(STORE.UPLOADED_EVER, m);

        const after = loadUploadedEver();
        let missing = 0;
        (records || []).forEach(function (r) {
            const k = r && r.fileName;
            if (k && !after[k]) missing += 1;
        });
        return { total: Object.keys(after).length, missing: missing };
    }

    /**
     * 手动补录一条上传记录（3.2.57）。
     *
     * ★★★ 为什么需要它：**视频发出去了、脚本却没记上账**这种事真的会发生
     *   （2026-09-21 就丢了一条 —— 见 `resolveVideoId` 那段长注释）。
     *   3.2.57 修了根因（以后会自动记账），但**已经丢掉的那条得有人补**：
     *   不补的话，面板显示"没传过"、Play 侧建不了 CSL、
     *   而且**下次跑还会把它重传一份**。
     *
     * ★ 它同时是"手动传的视频"的入口：以后在 Studio 里手工传的片子，
     *   也能补进来，Play 侧照样能给它建 CSL。
     *
     * 返回 `{ok, why, videoId, fileName}`（`ok=false` 时 `why` 是人话原因）。
     */
    function manualAddRecord(fileName, linkText) {
        const name = String(fileName || '').trim();
        if (!name) return { ok: false, why: '文件名不能空' };

        const id = extractVideoId(linkText);
        if (!id) {
            return {
                ok: false,
                why: '链接里认不出视频 id —— 要 `youtube.com/watch?v=…`、'
                    + '`youtu.be/…` 或者光秃秃的 11 位 id',
            };
        }

        const list = loadVideos();
        // ★ 同名已经在记录里就不补：一条重复的记录会让 Play 侧以为
        //   "同文件传过多次"，然后按"留最新那条"处理 —— 徒增困惑，
        //   而且面板上会显示成两条。
        const dup = list.filter(function (r) { return r && r.fileName === name; });
        if (dup.length) {
            return {
                ok: false,
                videoId: id,
                why: '这个文件名已经在记录里了（' + dup.length + ' 条）—— '
                    + '要改链接的话，先把旧的那条归档/清掉',
            };
        }

        list.push({
            // ★ 没有真实路径就填文件名：`cslKeyOf` 会退回用它去重，
            //   而 Play 侧拿的也是 fileName —— 两边口径一致。
            relPath: name,
            fileName: name,
            size: null,
            title: null,
            videoId: id,
            url: canonicalVideoUrl(id),
            state: 'published',
            at: new Date().toISOString(),
            // ★ 留一个标记：这条是**手动补录**的（不是脚本传的）。
            //   以后排查"这条怎么没在日志里"时能一眼看出来。
            manual: true,
        });
        saveVideos(list);            // ★ 它内部会顺带并进「永久名单」（3.2.53）
        forgetUploadedIndex();       // 面板上的"已上传"标记要立刻生效

        return { ok: true, why: '', videoId: id, fileName: name };
    }

    /**
     * 面板上「补录」按钮的动作：读两个输入框 → 调 `manualAddRecord` → 打日志。
     *
     * ★ 抽成独立函数是为了**能测**（跟 `reportFailures` / `logCopyProduct`
     *   一个规矩）：内联在 `onclick` 里的话，测试只能靠
     *   "源码里有没有这段字符串"来验 —— 而那挡不住 `if (false)` 那种破坏。
     */
    function doManualAdd(nameEl, linkEl) {
        const r = manualAddRecord(nameEl && nameEl.value, linkEl && linkEl.value);

        if (r.ok) {
            // ★ **成功才清空输入框**。失败时留着 —— 他要改一个字重试，
            //   清掉的话那条长链接得重新复制一遍。
            if (nameEl) nameEl.value = '';
            if (linkEl) linkEl.value = '';

            log('✓ 已补录：' + r.fileName + ' → ' + canonicalVideoUrl(r.videoId), 'ok');
            log('  ★ 这条现在算「已上传」了 —— 「跳过已上传的」不会再传它，'
                + 'Play 侧也能给它建 CSL。', 'info');
            log('  ★ **Play 那一页要刷新一下**（它的列表是渲染时读的）。', 'warn');
        } else {
            log('补录失败：' + r.why, 'error');
        }
        return r;
    }

    // ── 待补传名单（3.2.56）────────────────────────────────────────────
    //
    // ★ 它跟上面那份 UPLOADED_EVER 是**两个方向**的东西：
    //     UPLOADED_EVER = "这些**成了**"（只增不减，防重传）
    //     PENDING       = "这些**没成**"（补完就划掉，防漏传）
    //   两者合起来才是完整的账：**没在成功名单里的，就是还欠着的。**

    /** 待补名单最多记几条。★ 它是待办清单，不是档案 —— 堆太多说明有系统性问题。 */
    const PENDING_MAX = 50;

    /** 读待补名单。读到不是数组就当空（换版/手改过存储的情况）。 */
    function loadPending() {
        const l = storeGet(STORE.PENDING, null);
        if (!Array.isArray(l)) return [];
        return l.filter(function (x) { return x && x.fileName; });
    }

    /**
     * 把这次没传成的并进待补名单。**同名去重**（用最新的那次顶掉旧的）。
     *
     * 返回并入后的**实际条数**（★ 回读出来的，不是算出来的 ——
     * `storeSet` 写失败不抛错，不回读的话这个返回值就是一句没有依据的话）。
     */
    function addPending(entries) {
        const cur = loadPending();
        const idx = {};
        cur.forEach(function (x, i) { idx[x.fileName] = i; });

        (entries || []).forEach(function (e) {
            if (!e || !e.fileName) return;
            const at = idx[e.fileName];
            if (at === undefined) {
                idx[e.fileName] = cur.length;
                cur.push(e);
            } else {
                // 同一个文件失败过两次 → 留**最近**那次（原因可能变了：
                // 上次是"页面慢"、这次是"选择器没了"，后者更值得看）
                cur[at] = e;
            }
        });

        storeSet(STORE.PENDING, cur.slice(-PENDING_MAX));
        return loadPending().length;
    }

    /**
     * 这几条传成功了 → 从待补名单里划掉。返回**实际划掉了几个**。
     *
     * ★ 只在"真的从名单里消失"时才写存储：一条都没命中就不写，
     *   省掉一次没必要的写（也避免把一份好数据重写坏）。
     */
    function removePending(fileNames) {
        const names = {};
        (fileNames || []).forEach(function (n) { if (n) names[n] = 1; });

        const cur = loadPending();
        const out = cur.filter(function (x) { return !names[x.fileName]; });
        const removed = cur.length - out.length;
        if (removed > 0) storeSet(STORE.PENDING, out);
        return removed;
    }

    /** 清空待补名单（面板上那个按钮）。返回清掉了几条。 */
    function clearPending() {
        const n = loadPending().length;
        if (n > 0) storeSet(STORE.PENDING, []);
        return n;
    }

    /**
     * 某一条上传失败 → 记进待补名单。**返回失败时标签页是不是在后台。**
     *
     * ★ 抽成独立函数（而不是内联在 `runYtQueue` 的 catch 里）的原因，
     *   跟 `reportFailures` / `logCopyProduct` 一样：**能真的调一遍**。
     *   内联的话测试只能靠"源码里有没有这段字符串"来验，
     *   而那挡不住"把 if 条件改成 if(false)"这种一字不改的破坏。
     *
     * ★★ 返回值是 `hidden`，调用方拿它决定**报错措辞** ——
     *   后台失败和前台失败要说不同的话（前者大概率是误判）。
     *   所以这个信息在这里采一次、两处用，不要在两边各采一次
     *   （第二次采可能标签页已经切回来了，采到的是错的）。
     */
    function notePendingFailure(item, err) {
        const wasHidden = pageHiddenNow();

        addPending([{
            fileName: item.fileName,
            relPath: item.relPath,
            at: new Date().toISOString(),
            hidden: wasHidden,
            // ★ 只留报错的第一行：完整的多行报错是给日志看的，
            //   名单上那一条要能一行放下（面板宽度有限）。
            why: String(err && err.message || '').split('\n')[0].slice(0, 120),
        }]);

        return wasHidden;
    }

    /**
     * 上传记录这份数据的**清空 / 备份 / 恢复**。★ 3.2.47 新增。
     *
     * ── 为什么这三个动作要写在一起 ──
     *
     * 它们是同一份数据的三种操作，而且**顺序不能错**：
     * 清理时如果先清、后备份，那备份下来的是空的（而代码看起来"备份了"）。
     * 放一起才能让"先备份再清"这件事在**一眼之内**看得出来 ——
     * 分散在三处的话，下一个人挪一下顺序就悄悄坏了。
     *
     * ★ 这一份记录是 YouTube 侧和 Play 侧**唯一的桥**：
     *   Play 面板的整个视频列表、每个文件名、每一条 YouTube 链接，
     *   都是从它读出来的。清掉之后**没法从页面上重新推** ——
     *   YouTube 那边只看得到"传过什么"，对应不到本地是哪个文件。
     *   所以这里不是"删掉一个缓存"，是**删掉一条推不回来的信息**。
     */

    /** 现在有多少条上传记录。面板要显示它 —— 让人在点之前看得见"要清掉什么"。 */
    function videoRecordCount() {
        const list = loadVideos();
        return Array.isArray(list) ? list.length : 0;
    }

    // ── 归档栈 ──
    //
    // ★★★★★ 3.2.49：备份从"**只留一份**"改成"**留最近 5 份的栈**"。
    //
    //   起因是运营今天那句「之前的视频记录不显示」——
    //   他要的是"**换一批**：旧的先搁着，新的一批从零开始"。
    //   ★ 而"搁着"要是只留一份，第二次归档就会把第一次那份**覆盖掉**：
    //       归档第 1 批 → 栈里是第 1 批
    //       传了第 2 批 → 归档第 2 批 → 栈里只剩第 2 批，第 1 批**没了**
    //     而他现在手上正好有三个产品轮着来 —— 这个坑一定会踩到。
    //
    //   ★ 为什么是栈、不是"按名字存多份"：
    //     按名字存就要用户先想好叫什么（"9月那批""SLOT-01 那批"…），
    //     多一个需要填的框就多一处会填错、会忘的地方。
    //     栈只需要"归档"这一个动作，取回时默认给**最近那份**。
    //
    //   ★ 上限 5 份是刻意的：油猴存储有容量，而超过 5 批之前的记录
    //     基本不会再取回（真要留，用 `tools/export-video-records.py`
    //     导出成 md 存档 —— 那份**不在浏览器里**，不会因为清缓存而消失）。
    const ARCHIVE_MAX = 5;

    /** 读整个归档栈（最新的在前）。读不出来返回空数组。 */
    function loadVideoArchiveStack() {
        const raw = storeGet(STORE.VIDEOS_BACKUP, null);
        // ★ 兼容 3.2.47 存过的**老格式**（单份对象，不是数组）：
        //   那时候这份键里存的是 `{at, list}`。
        //   不兼容的话，老用户点了恢复会直接"没有备份" ——
        //   而他那一份是**真实存在过的**，只是格式旧了。
        if (raw && !Array.isArray(raw) && Array.isArray(raw.list)) return [raw];
        if (!Array.isArray(raw)) return [];
        return raw.filter(function (s) {
            return s && Array.isArray(s.list);
        });
    }

    /** 读**最近**那份归档。没有就返回 null（不是空对象 —— 调用方要能区分"没归档过"）。 */
    function loadVideoBackup() {
        const st = loadVideoArchiveStack();
        return st.length ? st[0] : null;
    }

    /** 把一份记录压进归档栈（新的在前，超上限的丢掉）。 */
    function pushVideoArchive(list, at) {
        const st = loadVideoArchiveStack();
        st.unshift({ at: at || new Date().toISOString(), list: list });
        storeSet(STORE.VIDEOS_BACKUP, st.slice(0, ARCHIVE_MAX));
    }

    /**
     * 清空上传记录（= 归档：不再显示，但**留着**）。
     *
     * 返回 `{cleared, everTotal, everMissing}`；`-1` = 归档没落地，什么都没清。
     * （3.2.53 之前返回的是裸数字 —— 多带两个字段是因为"这批有没有进永久名单"
     *   现在也是这一步的**后果之一**，而它必须有地方能说出来。）
     *
     * ★★★★★ 三条硬要求，缺一条这个功能就不该上线：
     *
     *   ① **先归档、再清**。而且归档失败时**不能继续清** ——
     *      `storeSet` 是 try/catch 吞错的（写不进去不会抛），
     *      所以这里必须**回读一次**确认真的落地了。
     *      ★ 这正是本项目那条老规矩：**动作做了、日志写了、事情没成** ——
     *      三者长得一模一样，所以"写完了"必须回读才算数。
     *   ② 归档里要带**时间戳和条数**。没有它们，"上次归档"这句话
     *      就只是一句话 —— 取回之后也没法确认取回的是哪一份。
     *   ③ ★★★★★ **清之前要把这批并入「历史上传过」的名单**
     *      （`UPLOADED_EVER`）。不并的话，归档之后"已上传"标记全没了 →
     *      下次扫目录时所有文件都显示"没传过" → 而「跳过已上传的」默认开，
     *      它会以为自己跳过了什么，实际一个都没跳 → **整批重传**。
     *      ★ 顺序在"归档之后、清空之前"：归档是往回看（留住这一批），
     *        并入名单是往前看（让将来的扫描还认得它们）——
     *        两件都在同一个不可逆动作之前做完。
     */
    function clearVideoRecords() {
        const list = loadVideos();
        const n = Array.isArray(list) ? list.length : 0;
        if (!n) return { cleared: 0, everTotal: Object.keys(loadUploadedEver()).length, everMissing: 0 };

        // ── ① 先归档 ──
        pushVideoArchive(list);

        // ── 回读确认真落地了 ──
        // ★ 这一步不是形式主义：`storeSet` 内部是 try/catch，
        //   写失败**不抛错**（比如油猴存储配额满了）。
        //   不回读的话，下面那句"已归档"就是一句**没有依据的话**，
        //   而用户会按它放心地把记录清掉。
        const back = loadVideoBackup();
        if (!back || back.list.length !== n) {
            return -1;   // 特殊值：归档没落地 → 调用方**不要去清**
        }

        // ── ★ ③ 把这批并入永久名单（清空之前）──
        const marked = markUploadedEver(list);

        // ── ② 再清 ──
        storeSet(STORE.VIDEOS, []);
        return {
            cleared: n,
            everTotal: marked.total,
            everMissing: marked.missing,
        };
    }

    /**
     * 把上次备份写回去。**返回恢复了多少条**（0 = 没备份过，什么都没做）。
     *
     * ★ 恢复要**覆盖**而不是合并：合并会让"清掉了什么"变得说不清
     *   （清完之后如果又传了新视频，合并进去就得到一份谁也没见过的混合体）。
     *   覆盖的语义是干净的：**回到那一刻**。
     */
    function restoreVideoRecords() {
        const b = loadVideoBackup();
        if (!b) return 0;
        saveVideos(b.list);
        return b.list.length;
    }

    // ════════════════════════════════════════════════════════════════════
    // 3. COMMON
    // ════════════════════════════════════════════════════════════════════

    const sleep = function (ms) { return new Promise(function (r) { setTimeout(r, ms); }); };

    /** 带 kind 的错误。kind 只进日志，不做状态机。 */
    function StepError(message, kind) {
        const e = new Error(message);
        e.name = 'CslStepError';
        e.kind = kind || 'unknown';
        return e;
    }

    function fmtBytes(n) {
        if (!(n > 0)) return '0 B';
        const u = ['B', 'KB', 'MB', 'GB'];
        let i = 0;
        let v = n;
        while (v >= 1024 && i < u.length - 1) { v /= 1024; i += 1; }
        return (i === 0 ? v : v.toFixed(1)) + ' ' + u[i];
    }

    function naturalSort(names) {
        return names.slice().sort(function (a, b) {
            return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: 'base' });
        });
    }

    function isVideoFile(name, exts) {
        const lower = String(name || '').toLowerCase();
        return exts.some(function (e) { return lower.slice(-e.length) === e; });
    }

    /**
     * 从一段文字里抠出 YouTube videoId。
     * 认这三种形式：
     *   youtube.com/watch?v=XXXX
     *   youtu.be/XXXX
     *   studio.youtube.com/video/XXXX/
     */
    function extractVideoId(input) {
        const s = String(input || '').trim();
        if (!s) return null;

        // 光秃秃 11 位 id
        if (/^[A-Za-z0-9_-]{11}$/.test(s)) return s;

        const pats = [
            /[?&]v=([A-Za-z0-9_-]{11})/,
            /youtu\.be\/([A-Za-z0-9_-]{11})/,
            /\/video\/([A-Za-z0-9_-]{11})/,
            /\/shorts\/([A-Za-z0-9_-]{11})/,
            /\/embed\/([A-Za-z0-9_-]{11})/,
        ];
        for (const p of pats) {
            const m = s.match(p);
            if (m) return m[1];
        }
        return null;
    }

    /** 统一输出这一种链接。 */
    function canonicalVideoUrl(videoId) {
        return 'https://www.youtube.com/watch?v=' + videoId;
    }

    /**
     * 按**字符**（code point）截断，不是按 JS 的 `.length`。
     *
     * ★ 为什么不能用 `s.slice(0, max)` —— 这个坑很隐蔽，而且是必然踩的：
     *
     *   JS 的 String 是 UTF-16，`.length` 数的是 code unit。BMP 之外的字符
     *   （emoji、部分符号）占 **2 个** code unit。所以
     *   「99 个字符的标题」`.length` 是 101 —— `slice(0, 100)` 会把最后一个
     *   emoji 从中间切开，留下一个孤立的高位代理（`\ud83d`）。
     *
     *   后果不是"标题少个字"，是**标题回读核对对不上** → 那一步抛错停下，
     *   而文件早就投进去了、配额已经扣了。表现成"填标题失败"，很难联想到
     *   截断方式。
     *
     *   emoji 在标题里是常态（营销文案都带），所以这不是理论问题。
     */
    function truncateChars(s, max) {
        const chars = Array.from(String(s === null || s === undefined ? '' : s));
        if (chars.length <= max) return chars.join('');
        return chars.slice(0, max).join('');
    }

    /**
     * 文案哨兵：现在这份标题+描述，**讲的是哪个产品**？
     *
     * 返回 `{expect, found, ok}`：
     *   · `expect` = `CONFIG.yt.product_name`（**当前产品**）
     *   · `found`  = 文案里**实际出现**的产品名（可能 0 个、1 个、或多个）
     *   · `ok`     = 恰好只出现当前产品
     *
     * ★★★★★ 为什么要有这个函数（而不只是在测试里写两条断言）：
     *
     *   文案串台是本项目**最贵的一种错**，而且它**完全静默** ——
     *   不报错、照传、照扣配额，等你在频道上看到一堆挂着别家产品名的
     *   视频时才发觉（那时已经发出去几十条）。
     *   3.2.48 就差点这样：脚本里躺着 SLOT-02 的文案，
     *   而那天要传的是 SLOT-01 的视频。
     *
     *   ★ 测试里那两条断言只在**跑测试时**管用 —— 而运营不会跑测试，
     *     他改完文案就上传了。所以判据必须**在运行时也在场**：
     *     脚本每次开工都打一行"这份文案属于 XXX"，不对就报警。
     *   ★★ 这就是本项目那条老规矩的又一次应用：
     *     **判据要放在会被执行的那条路径上**，不是放在只有开发者走的那条上。
     */
    function scanCopyProduct() {
        const expect = String((CONFIG.yt && CONFIG.yt.product_name) || '');
        const known = (CONFIG.yt && CONFIG.yt.known_products) || [];
        const text = String((CONFIG.yt && CONFIG.yt.title_template) || '')
            + '\n' + String((CONFIG.yt && CONFIG.yt.description_template) || '');

        const found = [];
        for (const n of known) {
            if (n && text.indexOf(n) >= 0) found.push(n);
        }
        // ★ 没配 product_name 时 `ok` 一律为 false（**不是** true）：
        //   "没检查" 和 "检查通过" 必须分开 —— 跟前几轮那条
        //   「UNKNOWN ≠ SUCCESS」是同一个道理。这里没检查 = 拦不住串台。
        const ok = !!expect && found.length === 1 && found[0] === expect;
        return { expect: expect, found: found, ok: ok };
    }

    /**
     * 「描述回读对不上」时，**说清是哪个方向**。
     *
     * ★★★★★ 2026-09-21 从 YouTube 频道侧核出来的真事故：
     *   9/17 那批 6 条、9/20 早上那条，**描述都被写了两遍** ——
     *   视频页上量到的是 1517 字符，而模板只有 758。
     *   （核验渠道：`youtube.com/feeds/videos.xml?channel_id=…`
     *    里的 `media:description` 是**逐字原文**，可以直接量长短。
     *     watch 页面的 HTML 也含描述，但同一段会重复出现好几次，
     *     **按字符串计数会误判** —— 只能用来判"有没有"，不能用来判"几遍"。）
     *
     * ★★ 原来这里只说"对不上"，读的人第一反应是"没填上"，
     *    而**真相常常反过来**。两种情况的处置完全相反：
     *      · 少了 → 重填一次就行
     *      · 多了 → 得**先清空**再填，否则越填越多
     *    所以判据必须带上**方向**，不能只报"不一致"。
     *
     * ★ 抽成独立函数是为了能**真跑**（而不是靠正则查源码里有没有这句话）——
     *   跟 `reportFailures` / `reportArchiveEver` / `logCopyProduct` 一个规矩。
     */
    function describeDescMismatch(fillLen, gotLen) {
        if (gotLen > fillLen) {
            return '**读回来比填进去长 ' + (gotLen - fillLen) + ' 字** ——'
                + '\n      多半是**描述框里原本就有内容**（上一次填的、或者 YouTube'
                + '\n      自己预填的），我们那份**被填在了它后面**。'
                + '\n      这一条发出去，视频描述里会有**两份文案**。';
        }
        if (gotLen < fillLen) {
            return '**读回来比填进去短 ' + (fillLen - gotLen) + ' 字** ——'
                + '\n      多半是被截断（超长）、或者填的时候丢了一部分。';
        }
        return '（长度一样但内容不同 —— 被页面改写过。）';
    }

    /**
     * 把「这份文案属于哪个产品」打出来。开工时调一次。
     *
     * ★ 抽成独立函数（而不是内联在 `runYtQueue` 里），原因跟
     *   `reportFailures` / `reportArchiveEver` 一样：
     *   **"源码里有这句话"和"这句话会被说出来"是两件事** ——
     *   抽出来才能**真的调一遍**。内联的话只能靠正则查字符串，
     *   而把 `if` 条件改成 `if (false)` 那种坏法一个字都不会少。
     */
    function logCopyProduct() {
        const cp = scanCopyProduct();

        if (cp.ok) {
            log('· 这一批的标题/文案属于：**' + cp.expect + '**', 'info');
            return;
        }
        if (!cp.expect) {
            // ★ 没配 ≠ 通过。跟「UNKNOWN ≠ SUCCESS」是同一条规矩。
            log('★ 没配 `product_name` —— **没法检查文案属于哪个产品**。'
                + '\n    这不是"检查通过"，是**没检查**：'
                + '换产品时文案串台是静默的（不报错、照传、照扣配额）。', 'warn');
            return;
        }
        if (!cp.found.length) {
            log('★ 文案里**没有出现任何已知产品名**，而当前产品是「'
                + cp.expect + '」——\n'
                + '    要么这份文案真的是别家的（只是它没写产品名），'
                + '要么 `known_products` 里漏了这个产品。\n'
                + '    → 发之前扫一眼标题。', 'warn');
            return;
        }
        log('★★ **文案里出现的是「' + cp.found.join(' / ') + '」，'
            + '而当前产品是「' + cp.expect + '」** —— 换产品忘了换文案？\n'
            + '    ★ 串台是静默的：不报错、照传、照扣配额，'
            + '等你在频道上看到一堆挂着别家名的视频才会发现。\n'
            + '    → 文案没错就继续；不对的话改 `CONFIG.yt` 的那两份模板。', 'error');
    }

    /**
     * 标题：配了 title_template 就用模板，没配就退回"文件名当标题"。
     *
     * 模板里的 `{name}` 换成文件名（按 strip_extension 决定去不去后缀）。
     */
    function buildVideoTitle(fileName, opts) {
        const o = opts || {};
        let base = String(fileName || '');
        if (o.stripExtension) base = base.replace(/\.[^.]+$/, '');

        const tpl = String(o.template || '').trim();
        if (tpl) return truncateChars(tpl.replace(/\{name\}/g, base), CONFIG.yt.title_max);

        const prefix = String(o.prefix || '').trim();
        return truncateChars(prefix ? prefix + base : base, CONFIG.yt.title_max);
    }

    /**
     * 描述：模板里的 `{name}` 同样替换。留空返回空串（调用方据此跳过填描述）。
     */
    function buildVideoDescription(fileName, opts) {
        const o = opts || {};
        const tpl = String(o.template || '');
        if (!tpl.trim()) return '';

        let base = String(fileName || '');
        if (o.stripExtension) base = base.replace(/\.[^.]+$/, '');
        return tpl.replace(/\{name\}/g, base);
    }

    // ── 标签页可见性 ────────────────────────────────────────────────────
    //
    // ★★★★★ 3.2.53 新增。运营 2026-09-20 的观察：
    //   「是不是在自动化的时候不能把这个放在后台？我看报错都是我切了才有的」
    //
    //   ★ 他这个观察**在机制上成立**，不是错觉：
    //     浏览器对**隐藏的标签页**会节流定时器 ——
    //       · 隐藏 10 秒后：定时器最小间隔 1 秒（还能跑，只是变慢）
    //       · 隐藏 5 分钟后（Chrome 的 intensive throttling）：
    //         最小间隔变成 **1 分钟**，再往后还可能整个被冻结
    //   ★ 而本脚本的每一步都在 `waitFor` 里靠定时器轮询（`sleep`）。
    //     所以后台的后果是：**页面早就准备好了，脚本还睡着** ——
    //     15 秒的等待窗口里可能一次都没轮到 → 报"等不到"。
    //   ★★ 也就是说：切后台**不会**让上传失败（上传是服务端的事），
    //     但会让脚本**误判成失败**。而这两种情况在日志里长得一模一样，
    //     修法却完全不同（一个是改选择器，一个只要切回前台）。
    //
    //   ★★★ 更要紧的是：**这个信息原先根本没被记下来**。
    //     今天那条第 13 条的失败日志里，看不出当时标签页在不在前台 ——
    //     所以事后**无法判定**是不是后台造成的（这份代码的作者当时也判不了）。
    //     观测缺了，结论就只能靠猜。所以下面这几处的价值不只是"防护"，
    //     更是**让下次能确证**。

    /** 这个标签页现在是隐藏的吗（切走了 / 窗口最小化了）。 */
    function pageHiddenNow() {
        try { return !!(typeof document !== 'undefined' && document.hidden); }
        catch (e) { return false; }
    }

    /** 后台状态下"等不到"时，附在报错后面的一句话（前台时返回空串）。 */
    function hiddenNote() {
        if (!pageHiddenNow()) return '';
        return '\n    ★★ **这个标签页现在是后台的**（切走了，或者窗口最小化了）——'
            + '\n       浏览器会节流后台标签页的定时器：隐藏越久越慢，'
            + '\n       5 分钟后可能变成**一分钟才轮到一次**。'
            + '\n       于是"页面其实早就好了"和"脚本一直没看到"会同时成立 ——'
            + '\n       也就是说**这条失败很可能不是页面坏了，是没轮到看**。'
            + '\n       → 先把这个标签页切到前台，再重跑一遍看它还在不在。';
    }

    /** 后台节流的提醒只打一次 —— 每条等待都刷一遍会把日志淹掉。 */
    let hiddenWarned = false;

    /** 可见性监听的句柄（整个页面只装一次）。 */
    let visWatchInstalled = false;

    /**
     * 装上「标签页切走 / 切回」的监听 —— **只在任务运行中出声**。
     *
     * ★ 3.2.53。为什么是"全局装一次"而不是"每次开跑装、跑完卸"：
     *   后者要在 `runYtQueue` / `runPlayQueue` 两条路径上各写一对
     *   add/remove，而漏掉一个 remove 的后果是**监听器越攒越多**
     *   （跑 5 次就有 5 个），日志里同一句话会重复出现 5 遍。
     *   装一次、用 `running` 判断该不该出声，就没有这个状态要维护。
     *
     * ★★ 平时切走切回**不记** —— 那是用户自己的事，跟脚本无关，
     *   记了只会让日志里混进一堆没用的行。
     */
    function installVisibilityWatch() {
        if (visWatchInstalled) return;
        if (typeof document === 'undefined' || !document.addEventListener) return;
        visWatchInstalled = true;
        document.addEventListener('visibilitychange', function () {
            const running = ytState.running || playState.running;
            if (!running) return;
            if (pageHiddenNow()) {
                log('★ 标签页切到**后台**了 —— 浏览器会节流它的定时器：'
                    + '隐藏越久越慢，5 分钟后可能**一分钟才轮到一次**。'
                    + '\n  → 后果是"页面其实早就好了"和"脚本一直没看到"同时成立，'
                    + '**看着像失败**（但上传本身在服务端跑，不会因此丢）。'
                    + '\n  → 想让它稳稳跑完：把这个标签页留在前台。', 'warn');
            } else {
                log('· 标签页回到前台（后台期间的等待会慢，属正常）。', 'info');
            }
        });
    }

    /**
     * 轮询等一个条件成立。成立返回它的返回值，超时返回 null。
     * 条件本身抛异常时当作"还没好"，不中断等待 —— 页面切换过程中
     * 元素暂时取不到是正常的。
     */
    async function waitFor(fn, timeout) {
        const t0 = Date.now();
        // ★★★★★ 2026-09-18 新增：**期限必须是正数，否则当场报错**。
        //
        //   原来这里写的是 `const limit = timeout || CONFIG.wait_timeout;`，
        //   然后 `if (Date.now() - t0 >= limit) return null;`。
        //   看起来没问题 —— 直到 `limit` 是 `undefined`：
        //
        //       Date.now() - t0 >= undefined   →   **恒为假**
        //       → 那个 `for(;;)` 永远不满足退出条件 → **永不返回**
        //
        //   ★ 这次是真踩到的（2026-09-18，测试副本漏抄 `CONFIG.wait_timeout`）：
        //     `node tests/core.smoke.js` **挂了 8 分钟不结束、一个字不输出**，
        //     前台超时被转后台，看进程列表才发现它还活着。
        //     而它既没有报错、也没有退出码、也没有现场 ——
        //     **这是所有失败形态里最难查的一种**，比红一条用例贵得多。
        //
        //   ★ 所以这里不"给个默认值兜住"（那样只是把配置错误藏起来，
        //     而且会让"等多久"变成一个谁都不知道的数字）。
        //     按本项目的规矩：**没法判断的时候停下，不挑一个结论往下走**。
        //     期限读不出来 = 配置错了 → 立刻抛，把话说清楚。
        //
        //   ★★★ 2026-09-18 第二版：原来写的是 `timeout || CONFIG.wait_timeout`，
        //     而 `||` 会**吞掉所有假值** —— 传 `0`、`NaN`、`''` 都会被
        //     悄悄换成 `CONFIG.wait_timeout`（真机 15 秒）。
        //     ★ 这条是**实测**出来的（写这条用例时发现 `0` 那条不过）：
        //       `0` 的语义本来是**明确的**「只探一次、不等」——
        //       而它被换成了 15 秒的等待。**调用方说的和实际做的不是一回事**，
        //       且没有任何迹象。跟"`findOne` 找不到就抛"是同一类毛病：
        //       值/意图被静默替换。
        //     → 只把 `undefined` / `null` 当成"没传"，其余**原样使用**。
        //       这样 `0` 就是真的要"只探一次"（`elapsed >= 0` 立刻成立，
        //       循环探一次就退出 —— 不是挂死）。
        const limit0 = (timeout === undefined || timeout === null)
            ? CONFIG.wait_timeout : timeout;
        const limitOk = (typeof limit0 === 'number' && isFinite(limit0) && limit0 >= 0);
        if (!limitOk) {
            throw StepError('**等待时长读不出来** —— 不能开始等。'
                + '\n    ★ 读到的是：' + JSON.stringify(limit0)
                + '（类型 ' + (typeof limit0) + '）'
                + '\n    ★ 为什么会致命：等待循环的退出条件是'
                + '「已经等了 >= 期限」。期限是 ' + JSON.stringify(limit0)
                + ' 时这个比较**恒为假**，'
                + '于是循环**永不退出** —— 脚本卡在那里不动，'
                + '既不报错也不结束。'
                + '\n    → 查 `CONFIG.wait_timeout` / `CONFIG.find_timeout_ms`，'
                + '它们必须是**非负有限数**（毫秒）。'
                + '\n    ★ `0` 是允许的，语义是"**只探一次、不等**"。'
                + '\n    ★ 真机上正常不会这样；**测试里出现这句，'
                + '说明测试那份 CONFIG 副本漏抄了这几个键**'
                + '（源码是 IIFE，副本只能手抄，漏了就是 undefined）。', 'unconfigured');
        }

        // ★★★★★ 3.2.56：**后台那段时间不计入等待预算**
        //   （它取代了 3.2.53"后台时把窗口放宽到 90 秒"那个做法。）
        //
        //   ★ 3.2.53 那个补丁能救回一部分，但留着两个窟窿：
        //     ① **90 秒可能仍然不够** —— intensive throttling 是**一分钟一轮**，
        //        切走 5 分钟以上的话，90 秒里只轮得到一两次，照样误判；
        //     ② 它把"等多久"变成了一个跟真实时间脱钩的数字。
        //
        //   ★★ 而这件事的本质是：**页面没在等我们，是我们自己在睡。**
        //     所以正确的改法不是"等久一点"，而是"**睡着的那段不算数**"——
        //     后台累计的时长从已用时间里扣掉，回到前台接着按**原预算**等。
        //
        //   ★★★ 但必须留一个**真实时长上限**（`hidden_grace_ms`，默认 10 分钟）：
        //     只做"后台不计预算"的话，"标签页永远在后台 + 页面真坏了"
        //     → **永远等下去**（脚本卡住不动，比报错还难查）。
        //     超过宽限就放弃 —— 那时候人也该注意到"它怎么不动了"。
        let hiddenMs = 0;                 // 后台累计（不计入预算）
        let lastTick = Date.now();
        const grace = Number(CONFIG.hidden_grace_ms);
        const graceOk = (typeof grace === 'number' && isFinite(grace) && grace >= 0);

        for (;;) {
            let v = null;
            try { v = fn(); } catch (e) { v = null; }
            if (v) return v;

            const now = Date.now();
            if (pageHiddenNow()) {
                hiddenMs += (now - lastTick);
                if (!hiddenWarned) {
                    hiddenWarned = true;
                    log('  ★ 标签页在**后台** —— 后台期间浏览器会把定时器节流到'
                        + '最慢**一分钟一次**，所以这段时间**不计入等待预算**'
                        + '（页面没在等我们，是我们自己在睡）。'
                        + '\n    ★ 不过最好还是切到前台：后台跑容易把"慢"'
                        + '误报成"失败"。', 'warn');
                }
            }
            lastTick = now;

            // ① 净等待（扣掉后台之后）够久了 → 它是真的没出现
            if (now - t0 - hiddenMs >= limit0) return null;
            // ② 兜底：被后台拖太久（真实流逝超过 limit + 宽限）→ 也放弃
            if (graceOk && (now - t0) >= limit0 + grace) {
                log('  ★ 这个标签页**在后台待了 '
                    + Math.round((now - t0) / 1000) + ' 秒** —— 超过宽限'
                    + '（' + Math.round(grace / 1000) + ' 秒），先放弃这一步。'
                    + '\n    → 切到前台再跑。', 'warn');
                return null;
            }
            await sleep(200);
        }
    }

    // ── 日志 ──
    const LOG_LINES = [];
    let logSink = null;

    function log(text, level) {
        const line = { at: new Date(), text: String(text), level: level || 'info' };
        LOG_LINES.push(line);
        if (LOG_LINES.length > 300) LOG_LINES.shift();

        const fn = level === 'error' ? console.error
            : level === 'warn' ? console.warn : console.log;
        fn('[CSL Helper]', text);

        if (logSink) logSink(line);
    }

    /**
     * 记一个日志位置，之后可以用来"只看这一段发生了什么"。
     */
    function logMark() {
        return LOG_LINES.length;
    }

    /**
     * 从某个位置到现在，有哪些 **warn / error** 行 —— 也就是"哪几步没做干净"。
     *
     * ★★★ 3.2.15：为什么要有它。
     *
     *   10:35 真机上，最后那句报错是这么写的：
     *       （最可能是这一步的必填项没选上：公开范围 / 受众声明。
     *         往上翻，前面那句「可见性」或「受众」如果打了 ⚠ 就是它。）
     *   —— 而**可见性和受众这两步当时都成功了**，一条 ⚠ 都没有。
     *   这句话把排查方向直接指到了两个已经做好的步骤上。
     *
     *   真相在别处（排期没设 → 按钮禁用）。用户照着这句提示去翻，
     *   会翻到两句绿字，然后卡在那里 —— **错误信息比没有信息更糟**。
     *
     * ★ 所以不猜，改成**把前面所有没做干净的地方实打实列出来**：
     *   本轮日志里所有 warn/error 行，就是"这一步之前哪里没做干净"的答案。
     *   一条都没有时，再明说"每一步都是成功的"（那原因就在别处，
     *   比如视频还在处理），而不是编一个"最可能的原因"。
     *
     * ★ 为什么扫日志而不是用返回值传：这条链上要穿过六七个函数
     *   （点击、可见性、排期、受众…），每个都加一个返回值穿透，
     *   改动面比收益大得多，而且任何一处漏传就会**静默失去这条信息**。
     *   日志本来就是这条链的**完整记录**，直接读它反而更可靠。
     */
    function troublesSince(mark) {
        const from = Math.max(0, Number(mark) || 0);
        return LOG_LINES.slice(from).filter(function (l) {
            return l.level === 'warn' || l.level === 'error';
        }).map(function (l) {
            return String(l.text).trim().replace(/\s+/g, ' ');
        });
    }

    // ════════════════════════════════════════════════════════════════════
    // 4. DOM（Shadow DOM 穿透 + 赋值）
    // ════════════════════════════════════════════════════════════════════
    /**
     * 收集一个 root 及其内部所有可达的 shadow root。
     *
     * 用 isConnected 挡掉陈货：缓存有 300ms 保质期，这期间对话框可能已经关了。
     * 脱离文档的 shadow root 照样能 query 出元素，但那些是死节点 ——
     * 对它们 click()、赋值、发事件都毫无反应。这种"选得中但没反应"
     * 是最难查的一类故障：不报错，就是卡到超时。
     */
    function collectRoots(root) {
        const r = root || document;
        const out = [r];
        const seen = new Set();

        const walk = function (node) {
            let all;
            try { all = node.querySelectorAll('*'); } catch (e) { return; }
            for (const el of all) {
                let sr = null;
                try { sr = el.shadowRoot; } catch (e) { continue; }
                if (sr && el.isConnected && !seen.has(sr)) {
                    seen.add(sr);
                    out.push(sr);
                    walk(sr);
                }
            }
        };

        walk(r);
        return out;
    }

    let rootsCacheAt = 0;
    let rootsCacheVal = null;

    // 遍历全文档找 shadow root 有成本，而 waitFor 是 200ms 一轮的轮询。
    // 300ms 缓存够覆盖同一次逻辑里的连续调用，又短到不会让"刚出现的对话框"找不到。
    function cachedRoots() {
        const now = Date.now();
        if (rootsCacheVal && now - rootsCacheAt < 300) return rootsCacheVal;
        rootsCacheVal = collectRoots(document);
        rootsCacheAt = now;
        return rootsCacheVal;
    }

    /**
     * 穿透 shadow DOM 的 querySelectorAll，返回数组。
     *
     * 支持跨边界 `>>>`：`ytcp-uploads-dialog >>> input[type=file]`
     * = 先在整页找前半段，再进它的 shadowRoot 找后半段。
     *
     * 为什么需要这个语法：CSS 选择器**不跨 shadow 边界**，
     * 一条普通选择器无论怎么写都选不中 shadow root 里的元素。
     * 所以"跨边界"必须显式表达，让查找分两段走。
     * （Chrome DevTools 控制台里 `>>>` 是同样的意思。）
     */
    function deepQueryAll(selector, scope) {
        const out = [];
        const sel = String(selector || '').trim();
        if (!sel) return out;

        const parts = sel.split(/\s*>>>\s*/);

        let current = [];
        const firstRoots = scope ? collectRoots(scope) : cachedRoots();
        for (const r of firstRoots) {
            let hits = null;
            try { hits = r.querySelectorAll(parts[0]); } catch (e) { continue; }
            for (const n of hits) current.push(n);
        }

        for (let i = 1; i < parts.length; i += 1) {
            const next = [];
            for (const host of current) {
                const sr = host.shadowRoot;
                if (!sr) continue;
                let hits = null;
                try { hits = sr.querySelectorAll(parts[i]); } catch (e) { continue; }
                for (const n of hits) next.push(n);
            }
            current = next;
            if (!current.length) return [];
        }

        // 只认还挂在页面上的节点，理由见 collectRoots 的注释
        return current.filter(function (n) { return n && n.isConnected; });
    }

    function deepQueryOne(selector, scope) {
        const all = deepQueryAll(selector, scope);
        return all.length ? all[0] : null;
    }

    /**
     * 把一个"文字所在的那个节点"还原成**真正该点的那个控件**。
     *
     * ★★★★ 为什么必须有这一层 —— 两种框架的 DOM 结构**正好相反**：
     *
     *   Angular Material（YouTube 侧用）：
     *     <mat-radio-button><label><input type="radio">文字</label></mat-radio-button>
     *     → 文字所在的节点**包着** input，往里找就对了。
     *
     *   MDC Web（Play Console 侧用）：
     *     <div class="mdc-radio"><input type="radio" id="X"></div>
     *     <label for="X">文字</label>          ← label 是 input 的**兄弟**
     *     → 文字所在的 `<label>` 里**没有** input，只能靠 `for=` 找。
     *
     * ★ 这条差别是踩出来的：3.2.22 写的"往上找 5 层取选项文字"
     *   在 Play 上**永远走不通**，因为 MDC 的 label 不在祖先链上。
     *   同一个原因，找到 label 之后也**不能**只往里找。
     */
    function clickTargetOf(node) {
        // ① <label for="X"> → 那个 X
        try {
            const tag = String(node.tagName || '').toLowerCase();
            const f = tag === 'label' && node.getAttribute && node.getAttribute('for');
            if (f) {
                const t = deepQueryOne('#' + f);
                if (t) return t;
                const g = document.getElementById && document.getElementById(f);
                if (g) return g;
            }
        } catch (e) {
            // 找不到就往下走 —— 这不是错误，只是这条捷径不通
        }
        // ② 里面包着单选/多选框 → 用它（Angular Material 的结构）
        try {
            if (node.querySelector) {
                const inner = node.querySelector(
                    'input[type="radio"], input[type="checkbox"]');
                if (inner) return inner;
            }
        } catch (e) {
            // 同上
        }
        return node;
    }

    /**
     * 按**可见文字**找一个可点的元素并还原成该点的控件。
     *
     * ★★★★ 为什么 Play 侧**必须**有这个（不是锦上添花）：
     *   Play Console 把 id 全做成了**渲染时生成的 GUID**：
     *     #a9C847B1A-0BB6-4FEE-ABB2-F0583EDB2913--63
     *   而单选组的 `name` 又是**整组共用**的：
     *     name="radio-group-aE0ECB315-…--0"（三个选项一模一样）
     *   → **CSS 选择器在这批控件上根本没有区分能力**。
     *     要挑出「复制现有商品详情」而不是它上面那个「创建新商品详情」，
     *     唯一稳定的判据就是**它自己那行字**。
     *
     * ★ 这条判据稳不稳？稳 —— 文字是**产品文案**，改它要发版、要过翻译，
     *   而 id/GUID 是每次渲染都可能变的东西。所以这里"按文字"
     *   不是"猜"，而是**比 id 更硬的证据**。
     *
     * ★★ 匹配规则：**先精确、再子串**，子串命中时取**文字最短**的那个。
     *   为什么要子串：真机上「选择商品详情」这个按钮的整行文字是
     *   「选择商品详情 arrow_drop_down」（后面挂着一个 Material 图标名）。
     *   为什么要"最短优先"：「下一步」这种词会被**外层的容器**也包含
     *   （容器的 textContent 等于所有子孙文字拼起来），
     *   不按长度排就会挑中那个包了一整块的容器，点下去等于没点。
     *
     * ★★★ `isOurs` 必须排掉：本脚本自己的面板也是可见的，
     *   上面就有「全选」「诊断页面」这些按钮。不排的话
     *   `text=保存` 之类**可能命中自家面板**，那就成了"脚本点自己"。
     */
    function findOneByText(text) {
        const want = String(text || '').trim().replace(/\s+/g, ' ').toLowerCase();
        if (!want) return null;

        // 标签清单是**照着真机快照列的**，不是想当然：
        //   button  —— 「下一步」「选择商品详情」「默认商品详情」
        //   label   —— MDC 的单选/多选选项（靠 for= 找回 input）
        //   .menu-item / [role=menuitem] —— 模板下拉展开后的那些项
        //   mat-radio-button / [role=radio] —— Angular Material 那套
        const tags = ['button', 'label', 'a',
            'mat-radio-button', 'mat-checkbox', 'mat-option', 'mat-menu-item',
            '[role="button"]', '[role="menuitem"]', '[role="option"]',
            '[role="radio"]', '[role="checkbox"]', '.menu-item'];

        const cands = [];
        for (const root of cachedRoots()) {
            for (const tag of tags) {
                let nodes;
                try { nodes = root.querySelectorAll(tag); } catch (e) { continue; }
                for (const n of nodes) {
                    // 一个节点读不出来，只跳过它自己
                    try {
                        if (!n.isConnected || !isVisible(n)) continue;
                        if (isOurs(n)) continue;
                        const s = String(n.innerText || n.textContent || '')
                            .trim().replace(/\s+/g, ' ');
                        if (!s || s.length > 60) continue;
                        cands.push({ node: n, text: s.toLowerCase() });
                    } catch (e) { continue; }
                }
            }
        }
        if (!cands.length) return null;

        // ① 精确命中（文字就是这一段）
        for (const c of cands) {
            if (c.text === want) return clickTargetOf(c.node);
        }
        // ② 子串命中，取**最短**的 —— 短的更可能是元素本身，长的多半是外层容器
        //
        // ★★★★ 2026-09-19（3.2.40）：**"最短"必须让位给"点了真的会有反应"。**
        //
        //   真机 17:41 现场（**新加的那行"下拉触发按钮"日志交出来的**）：
        //     选择商品详情 → div#…--4.button  「选择商品详情 arrow_drop_down」  ✓
        //     发布比例     → div#…--6.button  「50% arrow_drop_down」           ✓
        //     受众         → label._ngcontent-iqw-92 「选择受众群体 *」        ✗ 点的是**字段标签**
        //   三个下拉是**一模一样的 class**，却只有受众那个点不开 —— 差别就在这。
        //   ★ 之前两轮全在猜"事件序列"，其实是**根本没点到那个下拉**：
        //     标签被点了一万次也不会展开菜单 → 浮层自然"一个都没有"。
        //     **一个错误的判据（最短）比一个错误的假设更值钱，因为它每次都错。**
        //
        //   ★ 根因：`label` 也在候选标签表里（MDC 的单选/多选选项靠它 + `for=`，
        //     那是**正当用法**，不能一刀切掉）。而字段标签的文字
        //     「选择受众群体 *」（8 个字）**含有**目标词，比真下拉的
        //     「选择受众群体 arrow_drop_down」（27 个字）**短** → 被"取最短"挑走。
        //     ★ 发布比例为什么没事：它的字段标签是「发布比例 *」，**根本不含 `50%`**，
        //       于是没有别的候选跟真下拉竞争。
        //
        //   ★ 判据：**"点了等于没点"的候选，不许压过别的候选。**
        //     怎么算"点了等于没点"（两条同时成立）：
        //       ① `clickTargetOf` 解出来还是它自己 —— 没有 `for=` 指得到真元素，
        //          里面也没包着 input（`clickTargetOf` 那两条捷径都不通）；
        //       ② 它本身是个 `<label>`。
        //     ★ 为什么敢：`<label>` 的职责是"给字段起名"，不是"被点"。
        //       没有 `for=`、又没包控件的裸标签，点它就是**什么都不会发生**。
        //     ★ 但如果它是唯一的候选，**照样返回它、并出声**（见下面那段）——
        //       "点了大概没用"是如实说，"找不到"是另一回事，不能混。
        let best = null;
        let bestTarget = null;
        let bestInert = false;
        for (const c of cands) {
            if (c.text.indexOf(want) < 0) continue;
            let t = c.node;
            try { t = clickTargetOf(c.node); } catch (e) { t = c.node; }
            const tag = String(c.node.tagName || '').toLowerCase();
            const inert = (t === c.node && tag === 'label');
            // 排序优先级：① 能反应的 压过 不能反应的；② 同档里取**最短**的。
            const better = (!best)
                || (bestInert && !inert)
                || (bestInert === inert && c.text.length < best.text.length);
            if (better) { best = c; bestTarget = t; bestInert = inert; }
        }
        if (best) {
            if (bestInert) {
                // ★ 出声，但不抛：这条路上层还有"找不到就抛"的那道门，
                //   而"找到了但是个点不动的标签"是**第三种**情况 —— 必须说清楚。
                log('  · ⚠ 按文字「' + want + '」只找到**点了不会有反应**的元素：'
                    + describeNode(best.node)
                    + '\n    ★ 它是个没有 `for=` 目标的 `<label>`（字段标签），'
                    + '真正要点的控件在别处。这一步**很可能不会生效** —— '
                    + '要么配个更准的选择器，要么检查那个控件是不是没渲染出来。', 'warn');
            }
            return bestTarget;
        }
        return null;
    }

    /**
     * 一个输入框"页面上写给它看的名字"，用来**反着找控件**。
     *
     * ★★★★ 2026-09-18 新增。真机逼出来的：
     *
     *     · input type=text  label=「自定义商品详情的名称（必填）」
     *     · input type=text  label=「https://www.youtube.com/watch?v=」
     *
     *   这两个框**没有 id、没有 class**（快照里连 class 都没打印，
     *   说明是真没有）。而 Play 上光看 tag 全都是 `<input type=text>` ——
     *   `input[type=text]` 在这两屏里能匹配到好几个，**没有区分能力**。
     *   唯一能把它们分开的就是 label 上的那段文字。
     *
     *   ★ 这和 `text=` 是**同一类需求**（控件没有稳定属性 → 按"人看到的字"定位），
     *     但**方向不同**：
     *       `text=` 找的是"**显示着**这段文字的元素"（按钮、选项）；
     *       `label=` 找的是"**被这段文字标注的**控件"（输入框）——
     *       而那段文字**不在控件里面**，所以 `text=` 永远找不到它。
     *
     *   ★ 判据直接复用 `labelCandsOf`（和诊断用的 `labelOfControl` 同一份）——
     *     必须如此：不然会出现"快照能报出名字、但按那个名字配选择器却找不到"，
     *     那种现象最让人怀疑人生（会以为是自己的写法不对）。
     *
     *   ★ 匹配规则和 `findOneByText` **故意保持一致**（精确优先、再取最短子串）：
     *     两套规则不一致的话，"该用 text= 还是 label=" 会变成一个要靠试的问题。
     */
    function findOneByLabel(text) {
        const want = String(text || '').trim().replace(/\s+/g, ' ').toLowerCase();
        if (!want) return null;

        // 只找"能输入"的东西 —— 这条前缀的语义就是"按名字找输入框"。
        // 不做成"什么控件都能找"：那会让 `label=保存` 这种
        // 误配变成"莫名其妙点到了别的东西"。
        const sel = 'input, textarea, select, [contenteditable=""], '
            + '[contenteditable="true"], [role="textbox"]';
        const nodes = safeDeepAll(sel);

        const cands = [];
        for (const n of nodes) {
            try {
                if (!n.isConnected || !isVisible(n) || isOurs(n)) continue;
                const names = labelCandsOf(n);
                for (const nm of names) {
                    const s = String(nm).replace(/\s+/g, ' ').trim().toLowerCase();
                    if (!s) continue;
                    cands.push({ node: n, text: s });
                }
            } catch (e) { continue; }
        }
        if (!cands.length) return null;

        // ① 精确命中
        for (const c of cands) {
            if (c.text === want) return c.node;
        }
        // ② 子串命中取最短（同 findOneByText 的理由：长的多半是外层容器）
        let best = null;
        for (const c of cands) {
            if (c.text.indexOf(want) < 0) continue;
            if (!best || c.text.length < best.text.length) best = c;
        }
        return best ? best.node : null;
    }

    /**
     * 配了就用，没配就报错停下 —— 不猜。
     *
     * ★★★★ 2026-09-17 起支持 `text=` 前缀：**按可见文字定位**。
     *
     *     copyExisting: 'text=复制现有商品详情'
     *
     *   为什么需要：见 `findOneByText` 上面那段 ——
     *   Play Console 的 id 是渲染时生成的 GUID、单选组的 name 是整组共用，
     *   CSS 在"几个同构选项里挑一个"这类控件上**没有区分能力**。
     *
     * ★★★★ 2026-09-18 起支持 `label=` 前缀：**按标注文字定位输入框**。
     *
     *     name:         'label=自定义商品详情的名称（必填）'
     *     previewVideo: 'label=https://www.youtube.com/watch?v='
     *
     *   ★ 前缀以外的一切**行为完全不变**（还是 `deepQueryOne`），
     *     所以这是纯增量 —— 现有配置一个都不用动。
     */
    /**
     * 「现在页面在哪一屏」—— 给各种「找不到」的报错**附一张现场照片**。
     *
     * ★★★★ 2026-09-18 加。起因是真机 15:19:17 那一句：
     *
     *     ✕ 「「复制现有商品详情」」在页面上找不到 —— 按标注文字「复制现有商品详情」
     *       没找到对应的输入框。要注意这条前缀找的是"**被这段文字标注的**控件"…
     *
     *   这句话把矛头指向**选择器配错了**（修法：回 CONFIG 改配置），
     *   而 4 秒后的手动快照显示页面**还在列表页** —— 向导压根没打开。
     *   真实修法是"等 / 查为什么没打开"，和改选择器**完全相反**。
     *
     *   ★★ 这跟 15:04 那次的「入口找不到 / 其实是停在向导里」是**同一个形状**：
     *     **报出来的结论比证据说得更多**。区别只是这次多了一个
     *     "该等没等"（点完入口只 `sleep(1000ms)` 就查）。
     *
     * ★ 所以把已有的自诊断能力（`playPageShape`）接到**每一条 notfound 报错**上：
     *   形状那一行如果说的是"列表页"，读的人一眼就知道**不是选择器的问题**。
     *
     * ★ 这个函数**不许抛** —— 它是给报错路径用的，自己再炸就成了第二个问题，
     *   而且会覆盖掉本来那个更有价值的报错。
     * ★ 也不会递归：`playPageShape` → `playCurrentStep` → `playStepperItems`
     *   → `safeDeepAll`，一路都不调 `findOne`（已核）。
     */
    function pageWhereNow() {
        try {
            const s = String(playPageShape() || '');
            return s || '（形状读不出来）';
        } catch (e) {
            return '（读形状时出错：' + (e && e.message) + '）';
        }
    }

    /**
     * 按选择器找一个元素。**找不到会等一会儿，然后带现场信息报错。**
     *
     * ★★★★ 2026-09-18 从同步改成异步（加等待）。两个理由：
     *
     *   ① **"找不到"和"还没渲染出来"本来就是同一件事的两面。**
     *      真机 15:19:16 那次：点完入口等 1000ms 就查 `copyExisting`，
     *      而 Angular 还在渲染 —— 于是**把"慢"报成了"配置错"**。
     *      ★ 本项目在 YouTube 侧已经栽过同形状的一次（`sleep(1.5s)` 然后
     *        判"YouTube 拒绝保存"，而那次其实是**成功的**，见文件上方那段）。
     *        当时的结论写在注释里：**耐心不足会把成功报成失败。** 这次是
     *        "把慢报成错"，代价是让人去改一个没配错的选择器。
     *
     *   ② 6 个调用点**全是**"这一步就该有这个控件，找不到就是错"的语义
     *      （没有一个是"探测式"用法，已逐个核过）。所以让"带等待的查找"
     *      成为**唯一**的路 —— 留一个同步版并存的话，后来的人会挑错那个。
     *
     * ★ 命中时**零额外延迟**：先立刻试一次，只有没中才进等待循环。
     *   （这点很重要：`playClickNext` 里的 `locate()` 会被重复调用，
     *    每次多等一点就会累积成肉眼可见的卡顿。）
     */
    async function findOne(selector, label) {
        if (!selector) {
            throw StepError(`「${label}」的选择器还没配。在 CONFIG.selectors 里填上。`, 'unconfigured');
        }
        const raw = String(selector).trim();

        const mText = /^text=(.+)$/.exec(raw);
        const mLab = /^label=(.+)$/.exec(raw);

        // 三种前缀 → 一个统一的"试一次"函数。
        const probe = mText ? function () { return findOneByText(mText[1]); }
            : mLab ? function () { return findOneByLabel(mLab[1]); }
                : function () { return deepQueryOne(raw); };

        // ★ 先立刻试一次（命中时零延迟）。
        let node = probe();
        if (!node) {
            // ★ 这句日志必须打：它把"脚本在等"和"脚本卡住了"分开。
            //   没有它的话，用户看到的是"点了之后半天没反应"。
            log('  · 「' + label + '」还没出现，等它一会儿（最多 '
                + Math.round(CONFIG.find_timeout_ms / 1000) + ' 秒）…', 'info');
            node = await waitFor(probe, CONFIG.find_timeout_ms);
        }

        if (!node) {
            // ── 报错：把"当时在哪一屏"一起说出来 ──
            //
            // ★★★ 这一段是本函数存在的主要理由。光说"找不到"是不够的：
            //   "向导没打开"和"选择器配错了"在**这一句话里长得完全一样**，
            //   而修法相反。附上形状，读的人自己就能分流。
            const where = pageWhereNow();
            const tail = '\n    ★ 等了 ' + Math.round(CONFIG.find_timeout_ms / 1000)
                + ' 秒也没出现。**当时页面在哪一屏**：' + where
                + '\n    → 如果上一行说的**不是你要的那一屏**，那**不是选择器的问题** ——'
                + '控件当然找不到，因为那一屏还没打开。'
                + '先去解决"为什么没进到那一屏"（别改这里的配置）。';

            if (mText) {
                throw StepError(`「${label}」在页面上找不到 —— 按文字「${mText[1]}」`
                    + '一个都没匹配上（可能还没走到那一屏，或者文案变了）' + tail, 'notfound');
            }
            if (mLab) {
                throw StepError(`「${label}」在页面上找不到 —— 按标注文字「${mLab[1]}」`
                    + '没找到对应的输入框。要注意这条前缀找的是"**被这段文字标注的**控件"，'
                    + '不是"显示这段文字的元素"；'
                    + '如果那个框上压根没有可读的 label，就换 CSS 选择器。' + tail, 'notfound');
            }
            throw StepError(`「${label}」在页面上找不到（${raw}）` + tail, 'notfound');
        }
        return node;
    }

    /**
     * 按可见文字找一个可点的元素。
     *
     * 用于 YouTube 那套分步对话框 —— 按钮上没有稳定的 id/class，
     * 但文字是明写在 CONFIG 里的约定，不是"猜"。
     */
    function findByText(texts, scope) {
        const info = findByTextInfo(texts, scope);
        return info ? info.node : null;
    }

    /**
     * 和 findByText 一样，但连"命中的是哪段文字"一起返回。
     *
     * ★ 为什么要多这一个：最后一步的按钮在两个不同的名字之间切换
     *   （unlisted 时是「保存」、public 时是「发布」）。只报一句
     *   「已点发布」的话，日志里看不出当时点的到底是哪个 ——
     *   而这两个词对应的语义不一样，回看日志时要分得清。
     */
    function findByTextInfo(texts, scope) {
        const wanted = (texts || [])
            .map(function (t) { return String(t).trim().toLowerCase(); })
            .filter(Boolean);
        if (!wanted.length) return null;

        const roots = scope ? collectRoots(scope) : cachedRoots();
        const tags = ['button', 'ytcp-button', 'paper-button', 'a',
            'div[role="button"]', 'tp-yt-paper-radio-button'];

        // ★ 先把候选攒出来，再挑 —— 不要边遍历边 return。
        //
        //   原来的写法是"碰到第一个匹配就返回"，而遍历顺序是
        //   「先按标签、再按节点」，于是**命中哪个元素由标签顺序决定**，
        //   跟 CONFIG 里 wanted 的先后毫无关系。
        //   表现成：把最想要的那个词写在第一位也没用，先撞上哪个算哪个。
        //   攒下来之后按 wanted 的顺序扫，CONFIG 里的顺序才真的有意义。
        const seen = [];
        for (const root of roots) {
            for (const tag of tags) {
                let nodes;
                try { nodes = root.querySelectorAll(tag); } catch (e) { continue; }
                for (const n of nodes) {
                    if (!n.isConnected || !isVisible(n)) continue;
                    const text = (n.innerText || n.textContent || '')
                        .trim().replace(/\s+/g, ' ');
                    if (!text || text.length > 40) continue;
                    seen.push({ node: n, text: text.toLowerCase() });
                }
            }
        }
        if (!seen.length) return null;

        // 第一轮：精确匹配（按钮文字就是这个词）
        for (const w of wanted) {
            for (const c of seen) {
                if (c.text === w) return { node: c.node, text: c.text, want: w };
            }
        }
        // 第二轮：子串匹配
        for (const w of wanted) {
            for (const c of seen) {
                if (c.text.indexOf(w) >= 0) return { node: c.node, text: c.text, want: w };
            }
        }
        return null;
    }

    function isVisible(el) {
        if (!el) return false;
        // 用 getBoundingClientRect：display:none / visibility:hidden / 尺寸为 0 都算不可见
        let r;
        try { r = el.getBoundingClientRect(); } catch (e) { return false; }
        return !!(r && (r.width > 0 || r.height > 0));
    }

    /**
     * 往输入框里写值。要对付三种完全不同的东西：
     *
     *   <input>          → 走 HTMLInputElement.prototype 的 value setter
     *   <textarea>       → 走 HTMLTextAreaElement.prototype 的 value setter
     *   contenteditable  → 走 textContent + InputEvent
     *
     * 第三种不是"锦上添花"：YouTube Studio 的标题框和描述框**就是
     * contenteditable 的 div**，不是 input。对普通 div 调
     * HTMLInputElement 的原生 value setter 会**直接抛 TypeError**
     * （原生 setter 检查接收者的内部槽，div 没有 input 的槽）——
     * 不是"设不上值"，是当场炸，而且炸在「填标题」那一步，
     * 也就是文件刚投进去、配额已经扣了之后。
     *
     * 顺带说清楚为什么不能干脆 `el.value = text`：那是直接写 JS 属性，
     * 绕过了框架的 value setter，React / Polymer 内部状态不会更新 ——
     * 界面上看得见值，提交上去是空的。所以原生 setter 这条路要保留。
     */
    function setValue(el, value) {
        if (!el) throw StepError('setValue 收到空元素', 'precheck');

        const text = value === null || value === undefined ? '' : String(value);
        if (el.focus) el.focus();

        // ── contenteditable ──
        // isContentEditable 把"属性在祖先上"也算进去了，比自己读
        // getAttribute('contenteditable') 可靠。
        if (el.isContentEditable) {
            el.textContent = text;

            // 优先发 InputEvent（带 inputType/data，框架靠它判断"用户输入了什么"）。
            // 构造失败就退回普通 Event —— 特殊环境里 InputEvent 可能不可用。
            let sent = false;
            try {
                el.dispatchEvent(new InputEvent('input', {
                    bubbles: true,
                    inputType: 'insertText',
                    data: text,
                }));
                sent = true;
            } catch (e) {
                sent = false;
            }
            if (!sent) el.dispatchEvent(new Event('input', { bubbles: true }));

            el.dispatchEvent(new Event('change', { bubbles: true }));
            if (el.blur) el.blur();
            return;
        }

        // ── input / textarea ──
        let proto = null;
        if (typeof HTMLTextAreaElement !== 'undefined' && el instanceof HTMLTextAreaElement) {
            proto = HTMLTextAreaElement.prototype;
        } else if (typeof HTMLInputElement !== 'undefined' && el instanceof HTMLInputElement) {
            proto = HTMLInputElement.prototype;
        }

        if (proto) {
            const d = Object.getOwnPropertyDescriptor(proto, 'value');
            if (d && typeof d.set === 'function') d.set.call(el, text);
            else el.value = text;
        } else {
            // 既不是输入框也不是 contenteditable，退化到写文本，至少不抛
            el.textContent = text;
        }

        el.dispatchEvent(new Event('input', { bubbles: true }));
        el.dispatchEvent(new Event('change', { bubbles: true }));
        el.dispatchEvent(new Event('blur', { bubbles: true }));
        if (el.blur) el.blur();
    }

    /**
     * 把值读回来。
     *
     * contenteditable 没有 .value，得读 innerText —— 它反映**渲染后的可见文本**，
     * 跟用户眼睛看到的一致。textContent 会把隐藏元素和多余空白算进去，
     * 拿它跟期望值比对容易假失败。
     */
    function readValue(el) {
        if (!el) return '';
        if (el.isContentEditable) return String(el.innerText || el.textContent || '');
        if ('value' in el) return String(el.value || '');
        return String(el.textContent || '');
    }

    /**
     * 按 aria-label 或可见文字找一个**控件**。
     *
     * 和 findByText 的区别在这两点上，都是实测逼出来的：
     *
     * ① **认 aria-label。** YouTube 的受众声明是一对 radio，结构大致是
     *    `<tp-yt-paper-radio-button aria-label="No, it's not made for kids">`，
     *    里面再包一层 span 放同样的文字。radio 的 aria-label 比 innerText 稳：
     *    文字会被排版拆进不同子节点，innerText 拼出来的可能带多余空白。
     *
     * ② **取最深的那个匹配。** 从根往下找时，外层容器的 textContent
     *    会把所有子孙的文字拼在一起 —— 先撞上的往往是整个滚动区，
     *    点它等于没点。所以宁可多走一遍：收集所有命中，取 DOM 最深的。
     *
     * ★ 这里**故意**不判断"这个节点能不能点"。曾经有一版加了
     *   `isClickable()`，但它的每个分支最后都 `return true` ——
     *   等于没有判断，只是让读代码的人以为有。真正解决"点到容器上"
     *   的是 ② 的取最深：最里的那个节点一定在控件的可点区域里，
     *   点它的事件会冒泡上去。少一个假动作，少一处将来会骗人的地方。
     */
    /**
     * 这个节点是不是一块内容的**标题 / 说明文字**。
     *
     * ★★★ 3.2.10 是它逼出来的（18:35 真机日志）。
     *
     * 「公开范围」那一块的标题是 `p#visibility-title`，长这样：
     *     「选择视频的公开范围，可以立即发布或安排时间」
     * 它**同时含**「公开」和「立即 / 安排时间」。
     *
     * 于是同一个节点同时冒充了两个东西的候选人：
     *   · 找可见性「公开」→ 它是子串候选 → 点在标题上 → **四个选项一个都没勾**
     *   · 找排期「安排时间」→ 它也是子串候选（3.2.9 靠 looksLikeControl 挡住了）
     *
     * ★ 精确命中不受影响 —— 标题的文字是**一长串**，
     *   永远不会"正好等于"「公开」；只有选项自己的文字才会。
     *   所以这里只掐**子串**那一档：标题可以被子串找到，但不该被当成控件。
     *
     * ★ 判据要宽一点：Studio 换标签名是常事，但"标题"这件事绕不过去 ——
     *   `<p>` / `<h1>`~`<h6>` / id 以 `-title` 结尾 / class 里带 title、subtitle、
     *   heading、description。这几条覆盖了 Studio 里全部块标题。
     *
     * ★★ 3.2.15：从 `findControl` 内部**提到模块作用域** ——
     *   因为 `looksLikeControl` 也要用它（见那里的注释），
     *   两层都各自实现一遍的话，两边迟早会不一致。
     */
    function isBlockTitle(node) {
        if (!node) return false;
        const tag = String(node.tagName || '').toLowerCase();
        if (tag === 'p' || /^h[1-6]$/.test(tag)) return true;
        const id = String(node.id || '').toLowerCase();
        if (/(^|[-_])title$/.test(id)) return true;
        const cls = String((node.getAttribute && node.getAttribute('class')) || '')
            .toLowerCase();
        if (/(^|[\s_-])(title|subtitle|heading|description)([\s_-]|$)/.test(cls)) return true;
        return false;
    }

    /**
     * 这个节点是不是**落在某块标题里**（自己或近层祖先是标题）。
     *
     * ★★★ 3.2.15 的新漏网，真机 10:35:22 逮到的。
     *
     *   `isBlockTitle` 只看**节点自己**。而 `findControl` 的子串档取的是
     *   **最深**那个节点 —— 所以它命中的通常不是 `<p id="visibility-title">`，
     *   而是标题**里面**包着文字的那个 `<span>` / `<div>`。
     *   那个 span：tag 不是 p/h1-6、没有 id、class 也不带 title
     *   → **上面那条判据一条都不命中 → 放行**。
     *
     *   于是子串档还是命中了标题区域，跟 3.2.10 修之前一模一样的后果：
     *       ⚠ 排期：文字命中了 p#visibility-title…但它**不是控件**—— 不点它，跳过
     *   这次是 `settleSchedule` 撞上的：它要找「安排时间」，
     *   而标题「选择视频的公开范围，可以立即发布或安排时间」正好含这几个字。
     *
     * ★ 为什么看**祖先**而不是"看文字从哪来"：
     *   判据要能用纯结构表达（假 DOM 里也能测），而"这个节点在不在标题区域内"
     *   结构上就是"往上几层有没有标题"。
     * ★ 4 层够用：Studio 的标题内部最多包两层 span/div。
     *   再往外就跨出这一块了 —— 找太远会把标题**下面**的选项也误杀。
     */
    function inBlockTitleArea(node, levels) {
        const max = levels || 4;
        let cur = node;
        for (let i = 0; cur && i < max; i += 1) {
            if (isBlockTitle(cur)) return true;
            cur = ancestorOf(cur);
        }
        return false;
    }

    function findControl(texts, opts) {
        const o = opts || {};
        const wanted = (texts || []).map(function (t) { return String(t).trim().toLowerCase(); })
            .filter(Boolean);
        // ★ 文本清单可以为空 —— 只给了谓词（o.accept）也能找。
        const accept = typeof o.accept === 'function' ? o.accept : null;
        if (!wanted.length && !accept) return null;

        const roots = o.scope ? collectRoots(o.scope) : cachedRoots();
        const maxLen = o.maxLen || 80;

        // ★★★ 命中分两档：**先精确、再子串**。
        //
        //   为什么要分档 —— 真机上栽得很惨：
        //   「公开范围」那一块的**标题**是
        //       「将视频设为公开、不公开列出或私享」
        //   它**同时含**「公开」和「不公开列出」两个词。
        //   只看子串的话，这个词会**稳定地先命中标题**（标题比选项更靠前、
        //   而且在 DOM 里往往更深或一样深），于是：
        //     · 点「不公开列出」→ 点在标题上 → 单选一个都没选中
        //     · 点「公开」        → 同样点在标题上
        //   表现是"点了、日志写了成功、而选项一个都没勾"。
        //
        //   ★ 分档之后：选项自己的文字**正好等于**那个词（精确命中），
        //     标题的文字是别的一长串（只是**包含**），两边就分开了。
        function labelOf(node) {
            return String(node.getAttribute && node.getAttribute('aria-label') || '')
                .trim().toLowerCase();
        }
        function ownTextOf(node) {
            return String(node.innerText || node.textContent || '').trim().toLowerCase();
        }

        /**
         * 这个节点是不是一块内容的**标题 / 说明文字**（实现已提到模块作用域）。
         *
         * ★ 3.2.15 从这里搬走了 —— `looksLikeControl` 也要用它。
         *   两边各留一份的话，改了这头忘了那头，就会出现
         *   "findControl 认为它是标题、looksLikeControl 认为它是控件"这种自相矛盾。
         *   现在只有 `isBlockTitle` / `inBlockTitleArea` 一份，在文件上面。
         */

        let best = null;
        let bestDepth = -1;
        let exact = null;
        let exactDepth = -1;

        for (const root of roots) {
            let nodes;
            try { nodes = root.querySelectorAll('*'); } catch (e) { continue; }
            for (const n of nodes) {
                if (!n.isConnected || !isVisible(n)) continue;

                // ★★ 每个节点只读一次文字。
                //   这是热路径（每次滚动都要把所有节点走一遍），
                //   "精确一次、子串再一次"会把字符串开销翻倍 ——
                //   测试从 ~15 秒涨到 8 分钟以上就是这么来的。
                const label = labelOf(n);
                let text = '';
                try { text = ownTextOf(n); } catch (e2) { text = ''; }
                const tooLong = text.length > maxLen;
                if (!label && (!text || tooLong)) continue;

                const isExact = (!tooLong && text && wanted.indexOf(text) >= 0)
                    || (label && wanted.indexOf(label) >= 0);
                const isAccept = accept
                    ? (accept(text) || (label ? accept(label) : false))
                    : false;

                if (isExact || isAccept) {
                    const d = depthOf(n);
                    // ★★★ 3.2.11：精确命中的候选里，**控件优先**。
                    //
                    //   19:03 真机：`tp-yt-paper-radio-button` 和它里面的
                    //   `<b>公开</b>` **都**精确命中「公开」。按"取最深"会拿到
                    //   那个 `<b>`（深度 16），它离真正的 radio 隔了十几层壳，
                    //   于是后面"往上找控件"这步要走很远、还容易半路放弃。
                    //
                    //   我们要点的从来都是**控件**，不是最深那个字 ——
                    //   所以先比"是不是控件"，再比深度。这样 radio 直接胜出，
                    //   "往上找控件"这步只剩一个近在眼前的确认。
                    //   （`looksLikeControl` 认 tag 含 radio/checkbox、role、
                    //   aria-checked/checked —— radio 一定算，`<b>` 一定不算。）
                    const isCtl = looksLikeControl(n);
                    const curIsCtl = exact ? looksLikeControl(exact) : false;
                    if (exact === null
                        || (isCtl && !curIsCtl)
                        || (isCtl === curIsCtl && d > exactDepth)) {
                        exact = n;
                        exactDepth = d;
                    }
                    continue;
                }
                if (tooLong) continue;
                const isSub = (text && wanted.some(function (w) {
                    return text.indexOf(w) >= 0;
                })) || (label && wanted.some(function (w) {
                    return label.indexOf(w) >= 0;
                }));
                if (!isSub) continue;
                // ★★★ 块标题不参与**子串**命中（精确命中在上面那一档，不受影响）。
                //   不加这一条，`p#visibility-title` 会稳定地被当成「公开」的候选，
                //   于是脚本点在标题上 —— 日志写"点过了"，四个选项一个都没勾。
                if (isBlockTitle(n)) continue;
                // ★★★ 3.2.15：块标题**内部**的文字节点也要挡掉。
                //
                //   上面那条只看节点自己，而这一档取的是**最深**节点 ——
                //   命中的通常是标题里包着文字的那个 span/div，
                //   它既不是 p/h1-6、也没有带 title 的 id/class → 上面那条挡不住。
                //   真机 10:35:22 就是这么来的：`settleSchedule` 找「安排时间」，
                //   命中了标题内部的节点，`enclosingControl` 再一路往上
                //   停在 `p#visibility-title` 上。
                if (inBlockTitleArea(n)) continue;
                const d2 = depthOf(n);
                if (d2 > bestDepth) { best = n; bestDepth = d2; }
            }
        }
        // ★ 有精确命中的就只用精确命中 —— 子串命中是兜底，不是并列选择
        return exact || best;
    }

    /**
     * 往上走一层祖先 —— **跨 shadow 边界**。
     *
     * ★★★ 3.2.16：这是整个脚本里最容易漏、而且漏了会**静默失效**的一条。
     *
     *   规范事实：`parentElement` 只在**同一棵树**里有效。
     *   走到 shadow 树的顶点时，它的 parentNode 是 ShadowRoot —— 一个
     *   DocumentFragment，**不是元素** —— 于是 `parentElement` 返回 `null`，
     *   循环当场结束，**永远走不到宿主元素**。
     *   想跨过去必须先 `getRootNode().host`（或 `parentNode.host`）。
     *
     *   真机上的代价（11:05 那次）：
     *     · `findByTextInfo` 按标签顺序扫，`'button'` 排第一 ——
     *       拿到的是 `ytcp-button#done-button` **shadow root 里面**那个 `<button>`；
     *       而禁用标记 `aria-disabled` 挂在**宿主** `ytcp-button` 上。
     *     · `isDisabled` 从内层按钮往上走 → 撞到 boundary 就停 → 判"没禁用"
     *       → 径直去点 → 点了没反应 → 报"YouTube 拒绝了这次保存"。
     *     · 同一时刻**快照**用的是 `safeDeepAll('ytcp-button,…')`，命中的是宿主
     *       → 0 层就读到 `[禁用]`。
     *   于是日志里出现"快照说 `[禁用]`、代码说没禁用"的自相矛盾。
     *
     *   ★★ 两次真机（10:35、11:05）都栽在同一件事上，而我当时把它归因成
     *     "往上看的层数不够"，把 `isDisabled` 从 4 层提到 12 层 ——
     *     **治错了**。边界是硬墙，走 100 层也过不去。
     *     这也解释了为什么"提到 12 层"之后现象一模一样。
     *
     *   ★ 判据：**任何"从文字节点往上找控件/找状态"的循环都必须用这个函数。**
     *     只要一处用了 `parentElement`，那一处就只在"同一棵 shadow 树内部"有效。
     */
    function ancestorOf(node) {
        if (!node) return null;
        if (node.parentElement) return node.parentElement;
        const p = node.parentNode;
        if (p && p.host) return p.host;
        return null;
    }

    /** 数一个节点到文档根的深度，用来在多个候选里挑"最里面"的那个。 */
    function depthOf(node) {
        let d = 0;
        let cur = node;
        while (cur && d < 200) {
            cur = cur.parentElement
                || (cur.parentNode && cur.parentNode.host)
                || null;
            d += 1;
        }
        return d;
    }

    /**
     * 上传对话框的根节点。
     *
     * ★ 为什么要试好几个标签名，以及为什么**不能只试一个**：
     *   上一版的 findScrollContainer 只试 `ytcp-uploads-dialog`，
     *   试不到就直接 `return null`—— 然后 withScrollSweep 一次都没滚，
     *   却打印「滚动也找过了」。于是"对话框标签名对不上"这个真实原因，
     *   被伪装成"滚动滚了但就是没有"，排查方向从一开始就是错的。
     */
    function dialogRoot() {
        return deepQueryOne('ytcp-uploads-dialog')
            || deepQueryOne('ytcp-upload-dialog')
            || deepQueryOne('tp-yt-paper-dialog')
            || deepQueryOne('ytcp-video-metadata-editor')
            || deepQueryOne('ytcp-uploads-file-picker');
    }

    /** 这个节点是不是我们自己面板里的东西（扫滚动容器时要排掉）。 */
    function isOurs(node) {
        let cur = node;
        let hops = 0;
        while (cur && hops < 60) {
            const cls = (cur.getAttribute && cur.getAttribute('class')) || '';
            if (String(cls).indexOf('cslh-') >= 0) return true;
            cur = cur.parentElement || (cur.parentNode && cur.parentNode.host) || null;
            hops += 1;
        }
        return false;
    }

    /**
     * 在一棵子树（含 shadow root）里找出**所有**真的能滚的容器，深的排在前面。
     *
     * ★ 为什么是"所有"而不是"第一个"：
     *   上一版返回第一个命中的，语义是"我认为滚动区就是它"。
     *   而实测里对话框内部不止一层可滚结构（外层 dialog、里面某个
     *   #scrollable、再里面某段列表），**观众声明在哪一层是不确定的**。
     *   挑错了，表现和"没滚"一模一样。
     *   与其猜哪一层对，不如全拨一遍 —— 拨多了没有副作用，
     *   反正最后会还原位置。
     */
    function scrollablesIn(scope) {
        if (!scope) return [];
        let all = [];
        try { all = deepQueryAll('*', scope); } catch (e) { all = []; }

        const out = [];
        for (const n of [scope].concat(all)) {
            if (!n || out.indexOf(n) >= 0) continue;
            if (isOurs(n)) continue;
            let cs;
            try { cs = getComputedStyle(n); } catch (e) { continue; }
            // ① 得是能滚的样式
            //
            // ★ 页面级的滚动条要单独放行。真机快照上「可滚容器（0）」
            //   就是这么来的：<html> / <body> 的 overflow-y 默认是 **visible**
            //   （按规范它把滚动交给视口），可它**照样能滚**。
            //   只认 auto|scroll 的写法会把整页滚动整个漏掉 ——
            //   于是"内容在下面要滚才看得到"这种情况，我们会报"没有滚动过"，
            //   而那句话在页面上其实是有东西可滚的。
            const isDocRoot = n === document.documentElement || n === document.body;
            if (!isDocRoot
                && (!cs || !/auto|scroll/.test(String(cs.overflowY || '')))) continue;
            // ② 光有样式不算，得**真的滚得动**
            if (!(Number(n.scrollHeight || 0) > Number(n.clientHeight || 0) + 8)) continue;
            out.push(n);
        }
        // 深的优先：内层滚动区更可能是"真正管内容"的那个，
        // 先拨它，命中得早，少做无用功。
        out.sort(function (a, b) { return depthOf(b) - depthOf(a); });
        return out;
    }

    /**
     * 该拨哪些滚动区：优先对话框内部；对话框找不到/里面没有可滚的，
     * 才退到整页去找。
     */
    function findScrollContainers(scope) {
        if (scope) return scrollablesIn(scope);
        const inside = scrollablesIn(dialogRoot());
        if (inside.length) return inside;
        return scrollablesIn(document);
    }

    /**
     * 找最后一步的「完成」按钮。
     *
     * ★ 名字先别急着叫「发布」。视频设成 **unlisted** 时，YouTube 把主按钮的
     *   文案从「发布 / Publish」换成「保存 / Save」—— unlisted 的语义是
     *   "保存成不公开列出"，不是"公开发布"。**但点它同样会让视频可用**
     *   （拿得到链接，Play 那边能校验）。所以这不是"没发布成功"，
     *   只是按钮换了个名字。只认「发布」的写法必然在这里空等 15 秒，
     *   然后谎报"等不到发布按钮"，而按钮一直就在那里。
     *   真实文案在 CONFIG.yt.finish_texts 里，顺序有意义。
     *
     * ★ 只在**对话框里**找。页面别处也有「保存」（设置、偏好之类），
     *   不限定范围的话会点到一个跟这次上传毫无关系的按钮上 ——
     *   而点错的后果不是报错，是"视频到底发到哪去了不知道"。
     *
     * ★★ 对话框根找不到时，**绝不能退到整页去找**。
     *   finish_texts 里有「继续 / Continue」这种到处都有的词，退到整页
     *   等于把"点错一个无关按钮"从"不可能"变成"可能"。
     *   这一步本来就是对话框的第 9 步，根本身不存在说明流程已经不对了 ——
     *   停在原地报错、把结构快照打出来，比乱点一个强得多。
     *
     * ★ 单独抽成函数的理由：它是「范围」这条规则的唯一载体，而它原来
     *   内联在 uploadOneVideo 里 —— 那个函数要凑齐 File / DataTransfer /
     *   分步对话框才能跑，于是这条规则**一行测试都覆盖不到**。
     *   抽出来之后可以直接喂假对话框验它。
     */
    /**
     * 这个"完成按钮"是不是其实是个**翻页**按钮？是就返回一句人话，不是返回 null。
     *
     * ★★★ 存在的理由是一次「谎报成功」：
     *   真机上对话框没往前走（`next_texts` 那时漏了「继续」），第 9 步就一路
     *   兜底到 `finish_texts` 最后那个「继续」，点了它 —— **那只是翻页**，
     *   视频根本没保存，而日志写的是「✓ 完成：https://…」。
     *   这类失败最坏：用户以为跑通了，实际停在「公开范围」等按保存。
     *
     * ★ 判据很简单：命中的词在 `next_texts` 里（翻页词）→ 它不可能是完成按钮。
     *   换句话说，**一个词不可能既是"往前走一页"又是"这就完了"**。
     */
    function finishButtonProblem(info) {
        if (!info || !info.text) return null;
        const hit = String(info.text).trim().toLowerCase();
        const paging = (CONFIG.yt.next_texts || []).map(function (t) {
            return String(t).trim().toLowerCase();
        });
        if (paging.indexOf(hit) < 0) return null;
        return '找到的「' + info.text + '」是**翻页**按钮（下一步 / 继续），'
            + '不是完成按钮 —— 说明对话框还没走到最后一步。';
    }

    /**
     * 这个节点（或它的近层祖先）是不是"禁用"状态。
     *
     * ★ 三种写法都得认：
     *   · `aria-disabled="true"` —— Studio 的 `ytcp-button` / `paper-button` 用这个
     *   · `disabled` 属性 —— 原生 `<button>` 用这个
     *   · `node.disabled === true` —— 原生属性反射
     * ★ 往上找**几层**（不是一层）：按钮本体常常是里面那层，禁用标在外层容器上。
     *   但别找太远 —— 再往外就是整块区域，那块"禁用"不代表这个按钮禁用。
     *
     * ★★★ 3.2.15：4 层 → **12 层**。这是"同一类 bug 的第三次出现"。
     *
     *   10:35 真机的直接证据是一处**自相矛盾**：
     *     · 快照里写着    `·[禁用] 「发布」 #done-button`   ← isDisabled 说是禁用
     *     · 代码却径直去点了 ← finishDisabledProblem 说不是禁用
     *   同一个 `isDisabled`，两边结论相反，那唯一的解释就是**节点不是同一个**：
     *   快照遍历的是**按钮元素自己**（selector 直接命中它，0 层就够），
     *   而 `findFinishButton` 走的是按文字找，拿到的节点到按钮本体之间
     *   还隔着几层 Polymer 的壳（`ytcp-button-shape-impl` / `*-label` 之类）。
     *
     *   4 层对"按钮自己"够，"从文字节点往上找按钮"不够。
     *
     * ★ 这个模式前面已经出现过两次了，每次都是同一个教训：
     *     · `checkedState` 只读给的节点 → 读不到挂在外层 radio 上的 aria-checked（→ 6 层）
     *     · `enclosingControlStrict` 8 层 → 文字「公开」埋在 `<b>`（深度 16），够不着（→ 30 层）
     *     · `isDisabled` 4 层 → 够不到按钮本体（→ 12 层，就是这里）
     *   **凡是"从文字节点往上找挂在控件上的属性"，层数都要按最坏的算。**
     *
     * ★ 为什么是 12 而不是 30：禁用标记比"控件本体"更靠外一层就够，
     *   而走太远会把"整块区域被禁用"误读成"这个按钮被禁用"
     *   （对话框里某些区域整块 disabled 是常见做法）。
     *   12 层覆盖了 Polymer 按钮那几层壳，又到不了外层区域。
     */
    function isDisabled(node) {
        let cur = node;
        for (let i = 0; cur && i < 12; i += 1) {
            if (cur.disabled === true) return true;
            const g = function (k) { return cur.getAttribute && cur.getAttribute(k); };
            if (g('aria-disabled') === 'true') return true;
            if (g('disabled') !== null) return true;
            cur = ancestorOf(cur);
        }
        return false;
    }

    /**
     * 把"这个节点往上找，哪儿挂着禁用标记"说清楚 —— 只用于**诊断日志**。
     *
     * ★ 为什么需要它：`isDisabled` 返回一个 bool，而"为什么不是禁用"
     *   在真机上完全看不出来。加一句上溯路径，下次一眼就能定位
     *   （是节点找错了？还是层数还不够？还是压根没标禁用？）。
     */
    function disabledTrace(node, levels) {
        const max = levels || 12;
        const parts = [];
        let cur = node;
        for (let i = 0; cur && i < max; i += 1) {
            const g = function (k) { return cur.getAttribute && cur.getAttribute(k); };
            const marks = [];
            if (cur.disabled === true) marks.push('disabled=true');
            if (g('aria-disabled') !== null) marks.push('aria-disabled=' + g('aria-disabled'));
            if (g('disabled') !== null) marks.push('disabled属性=' + JSON.stringify(g('disabled')));
            if (marks.length) parts.push(i + '层:' + tagOf(cur) + '[' + marks.join(',') + ']');
            cur = ancestorOf(cur);
        }
        return parts.length ? parts.join(' ← ') : '往上 12 层都没有禁用标记';
    }

    /**
     * 这个控件**（连带它里面的东西）**是不是禁用的？
     *
     * ★★★★ 2026-09-18 新增，起因是一次真机上的静默跑偏：
     *
     *   `playClickNext` 原来只有一句 `clickHard(node); await sleep(...)`。
     *   而那一步**没做**（选择器没配）时，「下一步」在整个向导里是
     *   `·[禁用] 「下一步」`。**禁用按钮点下去，浏览器自己就不响应** ——
     *   不抛错、控制台干干净净，脚本 `sleep` 完无条件报「点了」，
     *   于是**后面每一步都在错误的屏上执行**。
     *
     *   → 判据：**"点了没反应"必须当成失败**，而第一道闸就是"点之前先问它禁没禁用"。
     *
     * ★★ 为什么不直接用 `isDisabled`：`isDisabled` **只往上找**。
     *   而"外面套一层壳、`disabled` 挂在内层 `<button>` 上"是 MDC / Polymer
     *   这类组件库的常规写法 —— 手配的选择器（`P.nextBtn`）很可能正好
     *   指到那层壳上，于是**明明禁用却查不出来**。
     *   所以这里补一句"往下看一层"。
     *
     * ★ 为什么只往下认**可点的**东西（button / [role=button] / a）：
     *   放开成"任意后代带 disabled"的话，一个**容器**里只要有一个
     *   无关的禁用输入框，整个容器就会被判成禁用 —— 那是**假红**，
     *   而假红会让人改代码去迁就一个不存在的问题。
     *   "点它"这个动作只可能落在这三类节点上，按这三类找就够了。
     */
    function isDisabledDeep(node) {
        if (!node) return false;
        if (isDisabled(node)) return true;

        let kids = [];
        try {
            kids = node.querySelectorAll
                ? node.querySelectorAll('button, [role="button"], a')
                : [];
        } catch (e) {
            return false;
        }
        for (const k of kids) {
            try {
                if (!k.isConnected || !isVisible(k)) continue;
                if (isDisabled(k)) return true;
            } catch (e) { continue; }
        }
        return false;
    }

    /**
     * 这个"完成按钮"是不是**禁用的**？是就返回一句人话（并指到具体哪一步）。
     *
     * ★★★ 这条判据来自运营的一句实测，而且它比"回读选中状态"可靠得多：
     *
     *     「在『保存并发布』下面还需要点击安排时间，默认就行，
     *       但是不点好像就点不了**预定**这个按钮」
     *
     *   —— 按钮禁不禁用，是 **YouTube 自己算出来的"必填项齐没齐"**：
     *      不用我们猜，也不用去读那一组单选的状态
     *      （「公开范围」那一组很可能压根没写 `aria-checked`，
     *        而受众那一组写了 —— 同样是单选，两组的可读性不一样）。
     *
     * ★ 真机上的样子：点了「保存」，对话框一动不动；脚本只能靠
     *   "点了完成但对话框没动"这条**事后**检查才发现。现在点之前就问一句。
     */
    function finishDisabledProblem(info) {
        if (!info || !info.node) return null;
        // ★★★ 3.2.15：这里**只**看按文字找到的那个节点。
        //
        //   曾经还多看一个"控件本体"（`enclosingControlStrict(info.node)`），
        //   想兜住"快照说 `#done-button` 禁用、这里却放行"的自相矛盾。
        //   后来把它删了，因为它**够不着**：
        //
        //     · `looksLikeControl` 认的是 radio / checkbox / role /
        //       `aria-checked` —— **不认 `button` / `ytcp-button`**；
        //     · `findByTextInfo` 按 `['button','ytcp-button',…]` 的顺序扫，
        //       而 `CONFIG.selectors.yt.finishButton` 是 null，
        //       所以返回的是 `#done-button` **里面那个 `<button>`**；
        //     · 从它往上走，`enclosingControlStrict` 每一层都判不出控件
        //       → **永远返回 null** → 那个分支对结果零影响。
        //
        //   ★ 证据不是推理，是变异：`finishdisabled-checks-one-node`
        //     把那个分支删掉，跑出来"通过 458 / 失败 0" ——
        //     一段代码**被删掉之后没有任何用例变红**，说明它从没生效过。
        //
        //   ★ 真机上那句自相矛盾的根因是**层数不够**（4 层够不着
        //     Polymer 那几层壳），修法是把 `isDisabled` 提到 12 层 ——
        //     那才是治本；再加一道够不着的判据只是把 bug 藏起来。
        //
        //   → 教训：**加防御之前先证明它够得着。**
        //     够不着的防御比没有更糟 —— 它会让变异套件里多一个永远全绿的
        //     条目，把"用例很强"变成假象。
        if (!isDisabled(info.node)) return null;
        return '「' + (info.text || '完成') + '」按钮是**禁用**的（灰的）—— '
            + '说明这一步还有必填项没选。最可能是「安排时间」那一组'
            + '（"什么时候发"）：运营实测**不点它就点不动这个按钮**，'
            + '默认值就行、不用改时间。其次看受众声明。'
            + '（禁用标记的位置：' + disabledTrace(info.node) + '）';
    }

    /**
     * 等一个按钮从**禁用**变回**可用**。
     *
     * ★★★ 3.2.15：这是从 10:35 那次失败里学到的最重要的一条 ——
     *   **"按钮禁用"常常是个暂时状态，不该一看禁用就放弃。**
     *
     *   那次的时间线：
     *     10:35:22  可见性：public          （选上了）
     *     10:35:22  ⚠ 排期：…不是控件——跳过   （排期区还在异步渲染）
     *     10:35:23  ✕ 点了「发布」但对话框没动
     *   排期区渲染出来需要时间，而"排期没选 → 按钮禁用"是 YouTube 的联动。
     *   旧代码是"看一眼禁用就抛错停下"，于是**抢在页面准备好之前放弃**了。
     *
     * ★ 为什么不是"等排期设好就行"：那是把两件事的因果**写死**在代码里。
     *   按钮禁用可能是排期没选、可能是视频还在处理（快照里就有
     *   `uploads-still-processing-dialog`）、也可能是别的必填项 ——
     *   而**按钮自己从不撒谎**：它可用就是可用。
     *   等它，比猜原因可靠。
     *
     * ★ 超时之后**照实报失败**，不硬点 —— 硬点就是原来那个
     *   "点了没反应、然后报 YouTube 拒绝"的老路，把用户引向错误方向。
     */
    /**
     * ★★★ 3.2.18：`stillProcessingVisible()` 的**实现搬到了
     *   `stillProcessingDialog()` 旁边**（那里才是它的语义所在：
     *   那个对话框已经是"受理回执"，不再是"忙"的特征）。
     *
     *   这里原来留着一份同名实现 —— 函数声明是**后写覆盖先写**，
     *   所以那一份永远不会被执行，但它在源码里**长得像真的**：
     *   照它去改变异、去写用例，全都是空转（改了一份不生效的代码，
     *   用例当然还是全绿）。**够不着的代码比没有更糟。**
     */

    async function waitFinishEnabled(info, timeout) {
        const limit = timeout || CONFIG.yt.finish_enable_timeout_ms || 30000;
        const t0 = Date.now();
        let rounds = 0;
        let swept = false;
        let lastReport = 0;
        for (;;) {
            rounds += 1;
            if (!isDisabled(info.node)) {
                if (rounds > 1) {
                    log('  等到了：完成按钮变成可用了（等了约 '
                        + Math.round((Date.now() - t0) / 1000) + ' 秒）', 'ok');
                }
                return true;
            }

            // ★★★ 3.2.16：按钮一直灰着，就**主动做一件事**，而不是干等。
            //
            //   排期区 / 受众那一块在对话框**下半部分**，实测"要滚到那一段
            //   才渲染"。而 11:05 真机上报的是「可滚容器（0）——这次没有
            //   滚动过」：内容还没渲染出来 → 没有溢出 → 查不到滚动容器
            //   → 不滚 → 内容永远不渲染。**这是个先有鸡还是先有蛋的死结**，
            //   干等解决不了它。
            //   `withScrollSweep` 允许强制拨一遍（传 `() => null`），
            //   拨完再查一次翻一遍节点 —— 渲染出来就赢了。
            if (!swept && rounds >= 4) {
                swept = true;
                log('  ⏳ 按钮一直灰着 —— 把对话框**强行拨一遍**，'
                    + '逼下面还没渲染出来的部分出来。', 'warn');
                await withScrollSweep(function () { return null; }, '等完成按钮可用');
            }

            // ★ 每 5 秒报一次进度。不报的话，用户看到的就是界面卡住 30 秒，
            //   完全不知道是在等、还是死了。
            if (Date.now() - lastReport > 5000) {
                lastReport = Date.now();
                const proc = stillProcessingVisible();
                log('    …还在等完成按钮变可用（已等 '
                    + Math.round((Date.now() - t0) / 1000) + ' 秒）。'
                    + (proc ? '页面上有**可见的**「视频还在处理」对话框（' + proc
                        + '）—— 它自己会好。' : '页面上**没有**可见的"还在处理"对话框。'),
                    'info');
            }

            if (Date.now() - t0 >= limit) return false;
            await sleep(250);
        }
    }

    /**
     * 对话框现在是不是**正在忙**（YouTube 自己在干活）？
     *
     * ★★★ 3.2.17 新增。这是 11:19 那次误判的直接产物。
     *
     *   真机快照里最有欺骗性的一行：
     *       ·[禁用] 「返回」  #back-button
     *       ×[禁用] 「继续」  #next-button
     *       ·[禁用] 「发布」  #done-button
     *
     *   我第一眼读成了"对话框没就绪 / 必填项没齐"——**错了**。
     *   用户当场看着屏幕说的是：「我看是发布了啊」。
     *
     *   在**最后一步**上，「返回」不该是灰的 —— 除非：
     *   ① 还在第一步（那"返回"本来就灰），或者
     *   ② **YouTube 正在发布/处理中**，它把底部一排**整体**锁掉。
     *
     *   ②才是这里的现场。而**"忙"和"坏"只能靠等来区分** ——
     *   所以这个函数返回的是"再等等"的理由，而**不是**失败结论。
     *
     * ★ 判据刻意取**宽**：只要"底部按钮≥2个且全禁用"就算忙。
     *   宁可多等 30 秒，也不要把一次成功报成失败 ——
     *   报失败会让用户重跑，而重跑的那条视频**可能已经发出去了**。
     *
     * ★★★ 3.2.18：**原来这里还有一条"still-processing 可见就算忙"，
     *   已经删掉了** —— 那个对话框现在在 `waitPublishOutcome` 的
     *   第 ④ 步就被判成**成功（受理回执）**，根本走不到这里。
     *   留着它就是个够不着的分支，而够不着的防御比没有更糟：
     *   它会让变异套件里多一个永远全绿的条目，把"用例很强"变成假象。
     *
     * 返回 '' 表示没看到忙碌特征（那才需要考虑失败）。
     */
    function finishBusyState() {
        const dlg = dialogRoot();
        if (!dlg) return '';

        // 底部一排按钮**整体**禁用 = 正在发布/送审
        //
        //   只认实测见过的三个 id。用固定 id 而不是"文字里含发布"，
        //   是因为这里判错方向的代价不对称：漏判只是多等一轮，
        //   误判会去点一个正在忙的按钮。
        const bottom = ['#back-button', '#next-button', '#done-button'];
        const found = [];
        for (const sel of bottom) {
            let n = null;
            try { n = deepQueryOne(sel); } catch (e) { n = null; }
            if (n) found.push({ sel: sel, node: n });
        }
        if (found.length >= 2) {
            const allOff = found.every(function (f) { return isDisabled(f.node); });
            if (allOff) {
                return '底部 ' + found.length + ' 个按钮（'
                    + found.map(function (f) { return f.sel; }).join(' / ')
                    + '）**全是禁用** —— 这是 YouTube 正在发布/处理的忙碌态';
            }
        }
        return '';
    }

    /**
     * 点完「发布 / 保存」之后，**等到有结果**，而不是 1.5 秒就判死刑。
     *
     * ★★★ 3.2.17：整段理由见 `post_publish_wait_ms` 的配置注释。
     *   一句话：1.5 秒的硬判断把一次**成功**报成了失败，
     *   而现场的"底部按钮全灰"其实是"正在发布"。
     *
     * ★ 判据从宽到严，命中哪个算哪个
     *   （**先判成功、再判受理、再判忙，最后才判失败**）：
     *
     *   ① 对话框没了 / 不可见          → **成功**（发完它自己关掉）
     *   ② 对话内容变了（步骤标记变了）  → **成功**（换了状态）
     *   ③ 完成按钮不在了 / 不可见      → **成功**
     *   ④ 出现「视频还在处理」对话框    → **成功（已受理）** ← 3.2.18 新增
     *   ⑤ 有忙碌特征（见 finishBusyState）→ **继续等**，不算失败
     *   ⑥ 满 post_publish_wait_ms 还没动静 → **才**判失败
     *
     * ★ 顺序不能反：①②③④ 必须先于 ⑤⑥ 判。因为"忙"的现场
     *   （底部按钮全灰）和"正在关 / 已受理"的现场**是同一帧**里
     *   可能同时成立的，先判成功能立刻返回，不用白等满 30 秒。
     *
     * ★★★ 3.2.18 为什么把「视频还在处理」从"忙"挪到"已受理"：
     *   12:11 真机里它一直挂着 → 3.2.17 把它当忙 → 死等 30 秒 →
     *   误报失败。而**用户在同一时刻看到的是这条视频「已发布」**，
     *   那个对话框上还有一个「关闭」按钮。
     *   → 它不是"还没好"，它是 YouTube 给我们的**回执**。
     *   当障碍 → 白等 + 误报；当回执 → 看到就认定成功、点关、进下一条。
     *   服务端的转码/送审照常继续，根本不需要我们在这儿杵着。
     *
     * ★ 为什么每一轮都要重新取 dialogRoot()：对话框可能在任何一轮关掉，
     *   缓存下来的节点会变成死节点（它照样能读属性，但读出来的是陈货）。
     *
     * @param {string} markBefore 点击**之前**的 dialogStepMark()
     * @param {string} label      按钮文字，用来打日志
     * @return {{ok: boolean, why: string}}
     */
    async function waitPublishOutcome(markBefore, label) {
        const budget = Number(CONFIG.yt.post_publish_wait_ms) || 30000;
        const reportEvery = Number(CONFIG.yt.post_publish_report_ms) || 5000;
        const step = 250;

        let spent = 0;
        let nextReport = reportEvery;
        let busyWhy = '';

        // ★ 先立刻判一次 —— 成功了就不该白等 250ms。
        //   （"对话框已经关了"这种情况在点完的瞬间就可能成立。）
        for (;;) {
            // ① 对话框没了
            const dlg = dialogRoot();
            if (!dlg || !isVisible(dlg)) {
                log('  ✓ 「' + label + '」生效了 —— 对话框已关闭'
                    + (spent > 0 ? '（等了 ' + Math.round(spent / 1000) + ' 秒）' : ''),
                    'ok');
                return { ok: true, why: 'dialog-gone' };
            }

            // ② 内容变了
            if (dialogStepMark() !== markBefore) {
                log('  ✓ 「' + label + '」生效了 —— 对话框内容变了'
                    + (spent > 0 ? '（等了 ' + Math.round(spent / 1000) + ' 秒）' : ''),
                    'ok');
                return { ok: true, why: 'mark-changed' };
            }

            // ③ 完成按钮不在了
            const still = findFinishButton();
            if (!still || !isVisible(still.node)) {
                log('  ✓ 「' + label + '」生效了 —— 完成按钮已经不在了'
                    + (spent > 0 ? '（等了 ' + Math.round(spent / 1000) + ' 秒）' : ''),
                    'ok');
                return { ok: true, why: 'button-gone' };
            }

            // ④ ★★★★ 回执到了 = **成功**。（3.2.18 新增，位置在"失败"之前）
            //
            //   12:11 真机的真相：点「发布」之后 Studio 弹出
            //   `ytcp-uploads-still-processing-dialog`；而用户确认
            //   **那条视频「已发布」**、对话框上有「关闭」。
            //   → 它的出现就是"YouTube 已受理这次发布"的回执，
            //     不是"还没好、继续等"。
            //
            //   ★ 3.2.17 把它当"忙"→ 死等 30 秒 → 误报失败 → 用户重跑
            //     → **重复投稿**。所以这一条必须在"判断失败"之前。
            //
            //   ★ 代价不对称，所以偏向"认成功"：
            //     误认成功（其实没发成）→ 留个草稿，手动点一下，不亏；
            //     误报失败（其实发成了）→ 重复投稿，不可逆。
            const sp = stillProcessingDialog();
            if (sp) {
                log('  ✓ 「' + label + '」**已受理** —— 出现了「视频还在处理」对话框'
                    + (spent > 0 ? '（等了 ' + Math.round(spent / 1000) + ' 秒）' : '')
                    + '。它在服务端继续，不用我们等。', 'ok');
                return { ok: true, why: 'accepted' };
            }

            // ⑤ 忙（底部一排整体禁用）—— **继续等**，不是失败
            const why = finishBusyState();
            if (why) busyWhy = why;

            if (spent >= budget) break;
            await sleep(step);
            spent += step;

            if (spent >= nextReport) {
                nextReport += reportEvery;
                log('    …已等 ' + Math.round(spent / 1000) + ' 秒'
                    + (busyWhy
                        ? ' —— ' + busyWhy + '，**继续等**'
                        : ' —— 对话框没动，也没看到忙碌特征'),
                    'info');
            }
        }

        return { ok: false, why: busyWhy };
    }

    function findFinishButton() {
        const sel = CONFIG.selectors.yt.finishButton;
        if (sel) {
            const node = deepQueryOne(sel);
            if (node) return { node: node, text: '（按配置的选择器）', want: sel };
        }
        const dlg = dialogRoot();
        if (!dlg) return null;
        return findByTextInfo(CONFIG.yt.finish_texts, dlg);
    }

    /**
     * 先找一次；找不到就把**所有**可滚容器往下拨，每拨一档再找一次。
     *
     * ★ 这不是"重试"，是**必须的**：受众声明、排期这些都在对话框滚动区的
     *   下半部分，实测要滚到那一段才渲染。不滚的话只能报一句"找不到"，
     *   而"真没有"和"没滚到"在日志里长得一模一样，没法排查。
     *
     * ★★ 日志必须说真话。上一版在"一个滚动区都没找到"时直接 return null，
     *   外面照样打印「滚动也找过了」—— 那句话是**假的**，它一次都没滚。
     *   于是真正的原因（对话框标签名对不上 / 结构变了 / getComputedStyle
     *   读到的 overflowY 不是 auto）永远浮不上来。
     *   现在：滚了几个、拨到第几档、还是一下都没滚，全都写进日志。
     *
     * find 是个同步函数（包一层闭包），因为查找本身不需要等。
     * 滚动之后要 sleep —— 渲染是异步的，立刻查还是查不到。
     *
     * ★★★ 3.2.17：新增第三个参数 `level`（默认 'warn'）。
     *
     *   "没找到能滚的容器"这句话，**对不同的 label 含义完全不同**：
     *     · 受众声明 / 缩略图 —— 该有却找不到 → 是 **warn**（这是故障）
     *     · 排期 —— Short 上**本来就没有这一区** → 只能是 **info**
     *       （11:19 快照里这句 warn 直接进了"没做干净"清单，
     *        而那一整个区域压根不在页面上）
     *
     *   ★ 为什么用参数而不是在 settleSchedule 里绕开这个函数：
     *     绕开就等于**放弃滚动**，而"有这组选项但没滚到"这条路径还在
     *     （普通视频就有排期区）。两件事要分开：**滚不滚**和**报多大声**。
     */
    async function withScrollSweep(find, label, level) {
        let hit = find();
        if (hit) return hit;

        const boxes = findScrollContainers();
        if (!boxes.length) {
            log(`  ${label}：没找到任何能滚的容器 —— **这次没有滚动过**。`
                + '（别以为滚过了；要么对话框还没出来，要么它的结构变了）',
                level || 'warn');
            return null;
        }

        const passes = Math.max(1, Number(CONFIG.yt.scroll_passes) || 1);
        const saved = boxes.map(function (b) { return Number(b.scrollTop || 0); });

        log(`  ${label}：翻一遍 ${boxes.length} 个可滚区域（每区 ${passes} 档）`, 'info');

        for (let i = 1; i <= passes; i += 1) {
            boxes.forEach(function (b, k) {
                const span = Math.max(0, Number(b.scrollHeight || 0) - Number(b.clientHeight || 0));
                b.scrollTop = saved[k] + (span * i) / passes;
            });
            await sleep(CONFIG.yt.scroll_pause);
            hit = find();
            if (hit) {
                log(`  ${label}：往下拨到第 ${i}/${passes} 档才出现`, 'ok');
                break;
            }
        }

        // 找到没找到都还原位置 ——
        // 不还原的话下一个步骤是从半路开始找的，会让"滚动"这个行为
        // 在多次运行之间表现不一致（同一份代码，跑第 2 次和第 1 次行为不同）。
        boxes.forEach(function (b, k) { b.scrollTop = saved[k]; });
        return hit || null;
    }

    // ════════════════════════════════════════════════════════════════════
    // 5. FILE（File 对象链路）
    // ════════════════════════════════════════════════════════════════════

    /**
     * 一个 File 能不能用来上传？不能就返回原因，能就返回 null。
     *
     * 为什么要有集中判据而不是到处写 `if (!file)`：「文件丢了」有好几种坏法，
     * **每一种的修法都不一样**：
     *   · undefined     → 数据链断了（谁把 File 吃了）
     *   · 不是 File     → 被序列化过 / 传错了东西
     *   · 没有文件名    → File 构造有问题
     *   · size 是 0     → 空文件，或者拿的是个假 File
     * 全报「上传失败」的话，用户和开发者都得从头猜。
     *
     * `instanceof File` 不能省：File 一旦进过 GM 存储就会变成普通对象
     * （{name, size}）。这种"长得像 File 但不是 File"的东西，
     * `dt.items.add()` 会给 `TypeError: parameter 1 is not of type 'File'`
     * —— 报错本身不难懂，难懂的是它出现在几层调用之外，
     * 而调用点只写了 add(file)，看不出 file 是从哪来的。
     */
    function fileProblem(file) {
        if (file === undefined || file === null) return '没有 File 对象';
        if (!(file instanceof File)) {
            return '不是浏览器 File（实际是 ' + Object.prototype.toString.call(file) + '）';
        }
        if (!file.name) return 'File 对象没有文件名';
        if (!(file.size > 0)) return '文件大小为 0（空文件）';
        return null;
    }

    /** 按 File 可用与否分组。预检里用来一次报完所有坏项，而不是遇到第一个就停。 */
    function splitByFile(items) {
        const good = [];
        const bad = [];
        (items || []).forEach(function (it) {
            const why = fileProblem(it && it.file);
            if (why) bad.push({ item: it, why: why });
            else good.push(it);
        });
        return { good: good, bad: bad };
    }

    /**
     * 往 input 里投文件。**一次只做一件事**：
     *   DataTransfer → input.files → input 事件 → change 事件
     *
     * 不在这里同时模拟 dragenter/dragover/drop。以前是两套一起发，
     * 结果上传失败时分不清是「input.files 那条路不通」还是
     * 「拖拽把状态搞坏了」—— DOM 层面看，两条都"没报错"，日志一片绿。
     * 拖放是另一条链，只在明确需要时单独试（见 uploadOneVideo）。
     *
     * 返回值是 input.files.length（回读 input，不是 DataTransfer ——
     * 这个函数描述的是"input 现在的状态"，那就该问 input）。
     */
    function setFileInput(input, files) {
        if (!input) throw StepError('投文件：input 为空', 'precheck');
        if (!Array.isArray(files) || !files.length) throw StepError('投文件：没有文件', 'precheck');

        for (const file of files) {
            const why = fileProblem(file);
            if (why) throw StepError('投文件：收到不可用的文件 —— ' + why, 'precheck');
        }

        const dt = new DataTransfer();
        try {
            files.forEach(function (file) { dt.items.add(file); });
        } catch (e) {
            // 走到这儿说明 fileProblem 漏放了某种东西。
            // 不把原始 TypeError 直接扔出去 —— 它只会说
            // "parameter 1 is not of type 'File'"，不说是哪个文件、什么类型，
            // 而调用点在几层之外。这里补上上下文。
            throw StepError(
                'DataTransfer 拒绝了这个文件（' + (e && e.message) + '）。'
                + '数量 ' + files.length + ' 个，类型分别是 '
                + files.map(function (f) { return Object.prototype.toString.call(f); }).join('、')
                + '。这条不该发生 —— fileProblem 预检漏放了它，是个 bug。',
                'precheck'
            );
        }

        // 事后回读，和预期不符就抛。成本几乎为零，
        // 而它挡掉的失败模式（以为投进去了、其实没有）最难查。
        if (!dt.files.length) throw StepError('DataTransfer 里没成功加入文件', 'precheck');

        try {
            input.files = dt.files;
        } catch (e) {
            throw StepError('无法设置 input.files：' + (e && e.message), 'file-injection');
        }

        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));

        return input.files ? input.files.length : 0;
    }

    /**
     * 方案 B：往拖放区发一整套拖拽事件。
     *
     * **只在方案 A 明确失败之后单独用**，不跟方案 A 一起发。
     * zone 必须是真正的拖放区 —— 传 input.parentElement 是碰运气。
     * 所以这里要求 zone 由调用方确定地给出，不靠 class 通配猜。
     */
    function injectFileByDrop(zone, files) {
        if (!zone) throw StepError('拖放：拖放区为空', 'precheck');

        const dt = new DataTransfer();
        for (const file of files) dt.items.add(file);

        for (const type of ['dragenter', 'dragover', 'drop']) {
            zone.dispatchEvent(new DragEvent(type, {
                bubbles: true, cancelable: true, dataTransfer: dt,
            }));
        }
        return dt.files.length;
    }

    /**
     * 给一个 file input 打分。<= 0 表示「这绝对不是上传视频用的」。
     *
     * ★ 为什么必须挑，不能"没有 video 的就凑合用第一个"：
     *
     *   真实页面上同时存在好几个 file input —— 上传视频的、传缩略图的、
     *   传频道头像/横幅的。抓错那个的后果**不是报错**，是静默错位：
     *   `input.files.length` 变成 1、change 也发了、日志写着「已接受」，
     *   而文件其实进了一个跟视频无关的框。
     *
     *   实测日志里就有一次拿到了 `accept=image/jpeg,image/png` 的那个
     *   （缩略图框），然后下一步照样报「已接受」。
     */
    function scoreFileInput(node) {
        if (!node) return -1;

        const accept = String(node.accept || '').toLowerCase();
        let s = 0;

        if (/video/.test(accept)) s += 100;
        else if (accept) s -= 100;        // 明确限定了别的类型 → 基本可以判死
        else s += 1;                      // 没限定类型：可能是它，但排最后

        // 上传框通常允许一次选多个
        if (node.multiple) s += 10;

        // 在 YouTube 的上传组件里 —— 最硬的信号，不依赖 accept 怎么写
        let cur = node;
        let guard = 0;
        while (cur && guard < 30) {
            guard += 1;
            const tag = String(cur.tagName || '').toLowerCase();
            if (tag === 'ytcp-uploads-file-picker') { s += 50; break; }
            if (tag === 'ytcp-uploads-dialog') { s += 30; break; }
            cur = cur.parentElement
                || (cur.getRootNode && cur.getRootNode().host)
                || null;
        }

        return s;
    }

    /**
     * 在页面里找**上传视频用的**那个 input[type=file]，找不到返回 null。
     * 会穿透 shadow DOM —— YouTube 的 file input 就在 shadow root 里。
     */
    function findFileInput() {
        const configured = CONFIG.selectors.yt.uploadInput;
        if (configured) {
            const node = deepQueryOne(configured);
            if (node) return node;
        }

        let all = [];
        try { all = deepQueryAll('input[type="file"]'); } catch (e) { all = []; }

        const picked = all
            .filter(function (n) { return n.isConnected && !n.disabled; })
            .map(function (n) { return { node: n, score: scoreFileInput(n) }; })
            .filter(function (c) { return c.score > 0; })
            .sort(function (a, b) { return b.score - a.score; });

        return picked.length ? picked[0].node : null;
    }

    /**
     * 页面上所有 file input 的清单。
     *
     * ★ 这是给"找不到上传框"那一刻用的。只报一句"找不到"没有信息量 ——
     *   要能一眼看出：页面上到底有没有 file input？有几个？都是些什么？
     *   有的话说明是**挑错了**，没有的话说明**对话框没打开**。
     *   这两种情况的修法完全相反。
     */
    function describeFileInputs() {
        let all = [];
        try { all = deepQueryAll('input[type="file"]'); } catch (e) { all = []; }
        if (!all.length) return '页面上一个 input[type=file] 都没有';

        return all.map(function (n, i) {
            const accept = String(n.accept || '').toLowerCase();
            const kind = /video/.test(accept) ? '像上传视频的'
                : (accept ? '限定了别的类型（多半是缩略图/头像框）' : '没限定类型');
            return '#' + (i + 1) + ' ' + describeInput(n) + '  → ' + kind
                + '，分 ' + scoreFileInput(n);
        }).join('\n    ');
    }

    /** 找到 input 之后把关键属性报出来 —— 出问题时"找到了 input"几乎没有信息量。 */
    function describeInput(input) {
        if (!input) return '(null)';

        const bits = ['tagName=' + (input.tagName ? input.tagName.toLowerCase() : '?')];
        bits.push('type=' + (input.type || '?'));
        bits.push('multiple=' + (input.multiple ? 'true' : 'false'));
        if (input.accept) bits.push('accept=' + input.accept);

        // shadow 深度：从元素往上数穿过了几层边界。
        // > 0 就说明 document.querySelector 够不着它 ——
        // 以后谁想"优化"掉穿透层，看到这行就知道不能动。
        let depth = 0;
        let cur = input;
        let guard = 0;
        while (cur && guard < 20) {
            guard += 1;
            let root = null;
            try { root = cur.getRootNode(); } catch (e) { root = null; }
            if (!root || root === document) break;
            depth += 1;
            cur = root.host || null;
        }
        bits.push('shadow深度=' + depth);
        return bits.join('  ');
    }

    /**
     * 上传真的开始了没？返回命中的信号名，都没有返回 null。
     *
     * ★ 这是「投了文件」和「YouTube 接受了文件」的分界线。
     * 光看 input.files.length === 1 不够 —— 那只证明 DOM 层面赋值成功。
     * 浏览器允许你给 input 设文件，页面完全可以不理你。
     * 这两种失败的修法完全不同。
     */
    function uploadSignalFound() {
        // 上传对话框本身就是最硬的信号：它是 YouTube 自己的组件名，
        // 不依赖任何配置。
        const probes = [
            ['ytcp-uploads-dialog', '上传对话框'],
            ['ytcp-upload-status', '上传状态'],
            ['ytcp-video-upload-progress', '上传进度组件'],
            ['ytcp-video-metadata-editor', '视频详情编辑器'],
        ];
        for (const pair of probes) {
            if (deepQueryOne(pair[0])) return pair[1];
        }
        // 自己配的标题框也算 —— 对话框出来之后它就在了
        const t = CONFIG.selectors.yt.title;
        if (t && deepQueryOne(t)) return '标题输入框';
        return null;
    }

    // ════════════════════════════════════════════════════════════════════
    // 6. YOUTUBE
    // ════════════════════════════════════════════════════════════════════

    let ytState = {
        running: false,
        stop: false,
        // scanVideoDir 的结果，每一项都带着活的 File 对象。
        // 勾选状态就存在每一项自己的 skip 字段上，不另建 map ——
        // 少一份要对齐的状态，就少一处会对不上的地方。
        entries: [],
        dryRun: true,
        // 面板上那个筛选框里的字。空 = 全显示。
        // ★ 它只影响"看得见什么"，不碰 skip —— 筛选和勾选是两件事，
        //   混在一起就出了"筛完之后不知道到底勾了谁"这种问题。
        filter: '',
        // ★ 2026-09-20：只看未上传的（189 个视频里挑没传过的）。
        //   跟 `filter` 同一层语义：**只影响看得见什么**，不碰 skip。
        hideUploaded: false,
        // ★★ 「已上传的就不传了」—— **默认开**。
        //
        //   为什么默认开（而不是让人自己勾）：两种错的代价**不对称**。
        //     · 重传 → 频道上**多出一份**，而且额度不可回收，还得专门去删
        //     · 漏传 → 再跑一次就行，一眼就能看出来
        //   → 默认站在**保护**这一侧。要重传的话，明确把它关掉
        //     （关掉时日志会出声，见 runYtQueue）。
        skipUploaded: true,
    };

    /**
     * 「哪些文件名已经传过了」—— 返回 `{fileName: 记录}`。
     *
     * ★★★★★ 2026-09-20 新增。运营原话：
     *   「上传过的视频标注 + 上传过的不上传的选项，视频一多就筛选不来了」
     *   ★ 背景很具体：这一批 **189 个视频**，一次最多传 20 个 ——
     *     要跑 9 批多，而且中途可能失败停下。每次接着跑之前，
     *     他必须知道"哪些已经传过了"，否则就是**盲选**。
     *
     * ── 为什么按 `fileName` 查，不按 `relPath` ──
     *
     *   `relPath` 是**扫目录那一刻**拼出来的（`子目录/文件名`）：
     *   换个目录、目录改名、或者从另一层选进来，它立刻就变了。
     *   而 `fileName` 是文件自己的名字，**跨批次稳定**。
     *   ★ 这也跟 Play 侧的配对键一致（那边也是按文件名）。
     *
     * ── 同名的只留**最新**那条 ──
     *
     *   真机上同一个文件被传过 3 次（buffalo）。标记只需要回答"传没传过"，
     *   而最新的那条链接才是该给人看的那个。
     *
     * ── ★★ 「有记录」就算传过，**不看有没有拿到链接** ──
     *
     *   `videoId` 为空**只说明没落成链接**，视频很可能已经传上去了
     *   （停在草稿、或者脚本在取链接那一步崩了）。
     *   拿它当"没传过"的话，重跑会**再传一份** —— 而 YouTube 配额不回收。
     *   ★ 所以判据放宽到"有记录"：宁可漏传（人工看一眼就能补），
     *     不可重传（重传是**多出来一份**，还得专门去删）。
     */
    function uploadedIndex() {
        // ★ 缓存 300ms。`matchYtFilter` 会被**每个条目**调一次，
        //   而 189 个条目 × 每次重建索引 = 189 次 `GM_getValue` + JSON.parse
        //   —— 面板会卡到没法用。
        //   ★ 300ms 跟 `cachedRoots` 用同一个量级：够短，上传完新记录
        //     自然就失效了（传一条要好几秒，不会踩在窗口里）。
        const now = Date.now();
        if (uploadIdxCache && now - uploadIdxAt < 300) return uploadIdxCache;

        const idx = {};

        // ── ① 底座：「历史上传过」的名单（★★★★★ **归档不会清它**）──
        //   ★ 这一层是 3.2.53 加的，起因是运营那一问：「你下次会不会
        //     显示没有上传？」——原来的判据只读 VIDEOS，而**归档会清空 VIDEOS**，
        //     所以答案是"会"。详见 STORE.UPLOADED_EVER 那段。
        //   ★ 这里只放得进文件名和时间（名单里就只有这两样），
        //     所以 `from: 'ever'` 是用来让 UI 能区分"这条只有名单、没有链接"。
        const ever = loadUploadedEver();
        Object.keys(ever).forEach(function (k) {
            idx[k] = {
                fileName: k, at: ever[k] || '', videoId: null, url: null,
                state: '', from: 'ever',
            };
        });

        // ── ② 叠加当前这批的记录（信息更全：有链接、有状态）──
        loadVideos().forEach(function (r) {
            if (!r || !r.fileName) return;
            const k = String(r.fileName);
            const prev = idx[k];
            // `at` 是 ISO 串 → 字典序就是时间序，不用 new Date()
            if (!prev || String(r.at || '') > String(prev.at || '')) idx[k] = r;
        });
        uploadIdxCache = idx;
        uploadIdxAt = now;
        return idx;
    }

    /** 这个文件传过没有。`idx` 可选（批量调用时传同一个，别每条都重建）。 */
    function isUploadedEntry(entry, idx) {
        if (!entry || !entry.fileName) return false;
        const m = idx || uploadedIndex();
        return !!m[String(entry.fileName)];
    }

    /** `uploadedIndex` 的缓存（见上面那段解释）。 */
    let uploadIdxCache = null;
    let uploadIdxAt = 0;

    /** 主动让上面的缓存失效 —— 传完一条之后要立刻用上新的记录。 */
    function forgetUploadedIndex() {
        uploadIdxCache = null;
        uploadIdxAt = 0;
    }

    /**
     * 这一批里**已经传过的**那些。
     *
     * ★ 单独抽出来是因为它有两个调用方，而它们要**同一个答案**：
     *   · 面板上那句"其中 N 个传过了"
     *   · `runYtQueue` 里真正跳过哪些
     *   两处各算一遍的话，迟早出现"面板说跳过 3 个、实际跳过 4 个"。
     */
    function uploadedInEntries(entries, idx) {
        const m = idx || uploadedIndex();
        return (entries || []).filter(function (e) {
            return isUploadedEntry(e, m);
        });
    }

    /**
     * 这条记录在当前筛选条件下可不可见。
     *
     * 匹配范围是 relPath（含子目录名），不是 fileName —— 用户的目录是
     * 「slots热门素材整理260915（片尾未删减）」，分类信息在**目录名**里。
     * 只比文件名的话，"片尾"这种关键字一个都筛不出来。
     */
    function matchYtFilter(entry) {
        // ★ 2026-09-20：「只看未上传」也走这条。
        //   ★★ 放进这里（而不是在 renderYtList 里单独判断）是**刻意的**：
        //     `bulkSetSkip` 和 `pickedYtEntries` 用的都是这一个函数，
        //     所以勾上它之后，「全选」和「真正会传哪些」都自动跟着变 ——
        //     不会出现"筛选框里看不见、但被全选勾上、然后真的传了"。
        //     （这正是这个项目反复强调的：筛选和传哪些**必须同一口径**。）
        if (ytState.hideUploaded && isUploadedEntry(entry)) return false;

        const q = String(ytState.filter || '').trim().toLowerCase();
        if (!q) return true;
        // 空格分隔的多关键字：全部命中才算命中（AND，不是 OR）。
        // 用 OR 的话，「buffalo KT」会把两个系列的东西一起筛出来，
        // 而用户写两个词的意思显然是"这两个都要有"。
        const words = q.split(/\s+/).filter(Boolean);
        const hay = String(entry.relPath || entry.fileName || '').toLowerCase();
        for (const w of words) if (hay.indexOf(w) < 0) return false;
        return true;
    }

    /**
     * 批量改勾选状态。mode: 'all' | 'none' | 'invert'。返回动到了几条。
     *
     * ★ 只作用于**当前筛选出来的**那些，不是全部。
     *   不然"筛出 5 个 → 点全选"会把另外 67 个也勾上，
     *   而面板上根本看不到它们被勾了 —— 点开始才发现在传不该传的东西。
     *
     * ★ 这里只改状态、不碰界面。画界面由调用方在之后单独做 ——
     *   混在一起的话，这个函数就没法脱离 DOM 测了。
     */
    function bulkSetSkip(mode) {
        let n = 0;
        ytState.entries.forEach(function (e) {
            if (!matchYtFilter(e)) return;
            n += 1;
            if (mode === 'all') e.skip = false;
            else if (mode === 'none') e.skip = true;
            else e.skip = !e.skip;
        });
        return n;
    }

    /**
     * 把勾选状态设成「**只有待补传的那几条**」。返回 `{hit, missed}`：
     *
     *   · `hit`    = 队列里匹配上待补名单的条数（已勾上）
     *   · `missed` = 待补名单里**在队列中找不到**的文件名
     *                （重新选的目录不对 / 文件改名了 / 被移走了）
     *
     * ★★★★★ 3.2.56 新增。运营的原话：「**记得把舍弃的那个上传**」——
     *   这条函数就是"带上它"的那一下。
     *
     * ★ 它跟上面 `bulkSetSkip` 的**作用域不一样，这是故意的**：
     *   · 「全选/全不选/反选」= "**改一堆状态**" → 只作用于筛选出来的
     *   · 这个                = "**从这一批里把漏的那几条挑出来**" → 作用于全部
     *   ★ 理由：用户点它的时候心想的是"那几个漏的在哪"，
     *     而不是"在当前筛选条件里再筛一遍"。要求他先清空筛选框才生效，
     *     是凭空加一道门 —— 而这道门只会让他以为"按钮坏了"。
     *
     * ★★ `missed` 必须返回：**"没找到"和"找到了"一样重要**。
     *   如果他重选的目录不对（比如选了另一个产品的文件夹），
     *   命中 0 条 —— 不说的话他只会看到"一个都没勾上"，然后自己猜原因。
     */
    function selectPendingOnly() {
        // ★ 只读一次：`loadPending` 每次都 parse 一遍存储，
        //   而这个函数会被点一下就跑完 —— 读两次只是白花时间。
        const pend = loadPending();
        const want = {};
        pend.forEach(function (x) { want[x.fileName] = 1; });

        const hit = {};
        let n = 0;
        ytState.entries.forEach(function (e) {
            if (want[e.fileName]) {
                e.skip = false;
                hit[e.fileName] = 1;
                n += 1;
            } else {
                e.skip = true;
            }
        });

        const missed = pend
            .filter(function (x) { return !hit[x.fileName]; })
            .map(function (x) { return x.fileName; });
        return { hit: n, missed: missed };
    }

    /**
     * 真正要传的那批：勾上了、**并且**在当前筛选条件下看得见。
     *
     * ★ 后半个条件是必须的。用户筛出 20 个、点了全选，然后点开始 ——
     *   他的心理预期是"传这 20 个"。不过滤的话会把没显示出来的也一起传，
     *   而上传会真实占用 YouTube 配额，扣了不返还。
     */
    function pickedYtEntries() {
        return ytState.entries.filter(function (e) {
            return !e.skip && matchYtFilter(e);
        });
    }

    /**
     * 把面板上的选择收成一个 form 对象，交给 buildQueue。
     *
     * ★ 单独列出来是为了**能测**。这段原来是内联在 runYtQueue 里的，
     *   而 runYtQueue 要跑完整个上传流程才走得到 —— 结果就是
     *   「form 里漏了 titleTemplate」这种错误没有任何用例挡得住。
     *   它不会报错，只在真实运行时表现成"标题全变成文件名了"，
     *   而那是最不容易让人联想到"某个字段没传"的现象。
     */
    function buildYtForm(opts) {
        const o = opts || {};
        return {
            prefix: CONFIG.yt.title_prefix,
            titleTemplate: CONFIG.yt.title_template,
            descriptionTemplate: CONFIG.yt.description_template,
            visibility: o.visibility || CONFIG.yt.default_visibility,
            autoPublish: resolveAutoPublish(o.autoPublish),
        };
    }

    /**
     * 扫描目录，收集视频文件。
     *
     * 产出 {relPath, fileName, file, size}，**file 是浏览器 File 对象**，
     * 全程不能再经过序列化。只在内存里活着。
     */
    async function scanVideoDir(dirHandle, cfg) {
        const out = [];

        async function walk(handle, prefix, depth) {
            const names = [];

            for await (const [name, child] of handle.entries()) {
                if (child.kind === 'directory') {
                    if (cfg.recursive && depth < 6) names.push({ name: name, dir: true });
                    continue;
                }
                if (!isVideoFile(name, cfg.video_ext)) continue;
                names.push({ name: name, dir: false });
            }

            names.sort(function (a, b) {
                return String(a.name).localeCompare(String(b.name), undefined,
                    { numeric: true, sensitivity: 'base' });
            });

            for (const item of names) {
                if (item.dir) {
                    let child;
                    try { child = await handle.getDirectoryHandle(item.name); } catch (e) { continue; }
                    await walk(child, prefix + item.name + '/', depth + 1);
                    continue;
                }

                let file;
                try {
                    const fh = await handle.getFileHandle(item.name);
                    file = await fh.getFile();
                } catch (e) {
                    continue;
                }

                out.push({
                    relPath: prefix + item.name,
                    fileName: item.name,
                    // ★ 浏览器 File 对象，只在内存里活着，任何阶段都不能丢
                    file: file,
                    size: file.size,
                    title: null,   // 建队列时才生成
                    skip: false,   // 面板上的勾选状态
                });
            }
        }

        await walk(dirHandle, '', 0);
        return out;
    }

    async function pickVideoDirectory() {
        const win = typeof unsafeWindow !== 'undefined' ? unsafeWindow : window;
        if (typeof win.showDirectoryPicker !== 'function') {
            throw StepError('这个浏览器不支持 showDirectoryPicker，请用 Chrome 或 Edge', 'env');
        }
        return await win.showDirectoryPicker();
    }

    /**
     * 建上传队列。
     *
     * ★ 这里必须把 file / size 原样带过去。曾经这里只挑了
     *   relPath / fileName / title / skip 四个字段重建对象 ——
     *   File 就在这一步被吃掉了，后面 setFileInput 收到的是 undefined。
     *   队列是纯内存的（从不持久化），所以带 File 是安全的。
     */
    function buildQueue(entries, form) {
        const queue = [];
        for (const e of entries) {
            const item = {
                relPath: e.relPath,
                fileName: e.fileName,
                // ★ 原样搬运，不要在这里重建对象
                file: e.file,
                size: e.size,
                skip: !!e.skip,
                title: e.title || buildVideoTitle(e.fileName, {
                    prefix: form.prefix,
                    stripExtension: CONFIG.yt.strip_extension,
                    template: form.titleTemplate,
                }),
                // 描述同样走模板。留空 = 不填（调用方据此跳过填描述那一步）。
                description: e.description || buildVideoDescription(e.fileName, {
                    stripExtension: CONFIG.yt.strip_extension,
                    template: form.descriptionTemplate,
                }),
                visibility: form.visibility,
                autoPublish: form.autoPublish,
            };
            queue.push(item);
        }
        return queue;
    }

    /**
     * 单个视频的完整上传流程。
     *
     * 任何一步失败就抛 —— 调用方接住、记日志、**停整批**。
     * 先追求稳定，失败续跑以后再说。
     */
    async function uploadOneVideo(item) {
        // ★★ 记一个日志位置：之后要报"这一步之前哪儿没做干净"时从这里截。
        //   见 troublesSince —— 它取代了原来那句猜原因的
        //   "最可能是公开范围 / 受众声明"（10:35 那次这两步其实都成功了）。
        const stepMark = logMark();

        // ── 1. 找 input ──
        //
        // ★ 用 waitFor，不是"查一次没有就报错"。
        //   上传对话框是异步渲染的 —— 实测同一个页面，11:03 那次报
        //   「找不到 input[type=file]」，11:04 那次就拿到了。两次的差别只是
        //   点"开始"的时机。查一次等于把"还没渲染出来"当成"页面上没有"，
        //   而这两种情况在日志里长得一模一样。
        let input = await waitFor(findFileInput, CONFIG.wait_timeout);

        // ★★ 还找不到就**自己把上传对话框打开**（详见 openUploadDialog）。
        //   真机第二次点「开始上传」正是这种情况：上一轮的对话框已经关了，
        //   页面上只剩一个缩略图用的 file input。
        if (!input) {
            const opened = openUploadDialog();
            if (opened) {
                log('  没找到上传 input → 点了「' + opened + '」，等对话框起来再找一轮…', 'info');
                input = await waitFor(findFileInput, CONFIG.wait_timeout);
            }
        }

        if (!input) {
            log('  页面上的 file input：\n    ' + describeFileInputs(), 'warn');
            throw StepError(
                '等了 ' + Math.round(CONFIG.wait_timeout / 1000)
                + ' 秒也没等到「上传视频用的」file input。'
                + '先手动打开 Studio 的「上传视频」页面（右上角创建 → 上传视频），'
                + '确认上传对话框已经出现，再点开始。'
                + '如果对话框开着还是这样，把上面那份 input 清单发出来 —— '
                + '有 input 说明是挑错了，没有说明对话框其实没打开。',
                'notfound'
            );
        }

        // ── 2. File 闸门（第二道，第一道在 runYtQueue 预检）──
        // 开弓没有回头箭：文件一投进去就开始上传、配额就扣了，宁可在这里早退。
        const why = fileProblem(item.file);
        if (why) {
            throw StepError(
                `没法上传「${item.relPath}」：${why}。`
                + '多半是选目录之后队列被重建过 —— 重新选一次目录再试。',
                'precheck'
            );
        }

        log(`准备上传：${item.file.name} / ${fmtBytes(item.file.size)}`, 'info');
        log('  上传 input：' + describeInput(input) + '  （分 ' + scoreFileInput(input) + '）', 'info');

        // ── 3. 投文件（方案 A）──
        const count = setFileInput(input, [item.file]);

        if (count !== 1) {
            throw StepError(
                `文件注入失败：期待 1 个，实际 ${count} 个。`
                + '这是 File API 层面的问题，跟 YouTube 页面没关系。',
                'file-injection'
            );
        }
        log(`方案A（input.files + change）：input.files.length = ${count}`, 'ok');

        // ── 4. 分界线：DOM 成功了，YouTube 理不理你？──
        let signal = await waitFor(uploadSignalFound, CONFIG.inject_react_timeout);

        if (!signal) {
            // ── Case D：注入成功但页面没反应 ──
            log('文件已经进入 input.files，但 YouTube 没有开始上传。', 'error');
            log('  不是「找不到文件」—— 是这种程序化注入方式没被接受。', 'warn');

            // 单独试一次拖放（方案 B），跟方案 A 分开跑，才知道哪条链有效
            const zone = deepQueryOne('ytcp-uploads-file-picker') || deepQueryOne('ytcp-uploads-dialog');
            if (zone) {
                log('  改试拖放方案，拖放区：' + zone.tagName.toLowerCase(), 'info');
                injectFileByDrop(zone, [item.file]);
                signal = await waitFor(uploadSignalFound, CONFIG.inject_react_timeout);
            } else {
                log('  也没找到确定的拖放区，拖放方案没跑。', 'warn');
            }
        }

        if (!signal) {
            // ★ 停在这里，不能继续往下走「填标题 / 选受众 / 发布」——
            // 页面上根本没有那条视频，后面每一步都会在无关元素上乱点，
            // 日志会变成一连串选择器错误，把真正的原因盖掉。
            throw StepError(
                'USER_SCRIPT_FILE_INJECTION_NOT_ACCEPTED —— input.files 已经是 1 个文件、'
                + 'change 也发了，但 YouTube Studio 始终没开始上传（对话框/进度都没出现）。'
                + '这不是「找不到 MP4」，是页面不接受程序化文件注入，需要换实现方式。',
                'file-injection'
            );
        }
        log('YouTube 已接受（识别到' + signal + '）', 'ok');

        // ── 5. 填标题 ──
        //
        // ★ 用 waitFor 而不是「sleep(1000) 之后查一次」。
        //   实测同一个对话框，有一次报「找不到标题输入框」、下一次又找到了，
        //   差别只是渲染时间。固定等 1 秒在快机器上够、在页面忙的时候不够，
        //   而"不够"的代价是这整批停下 —— 文件已经投进去、配额已经扣了。
        //   1 秒不是等"够久"的保证，只是把不确定性往后推了一步。
        // ★★★ 3.2.51：等不到标题框 → **再等一轮**，不当场判死。
        //
        //   真机 2026-09-20 18:10:26：连着传完 **12 条**之后，第 13 条
        //   `S2026072801_WC_03_WZT_DJT1_1080_SLJ.mp4` 报
        //   「等了 15 秒也没等到标题输入框」，而前 12 条都是 5~6 秒。
        //
        //   ★ 那条**不是选择器的问题** —— 同一份代码、同一个页面、
        //     前 12 次全部成功。是**页面/服务端变慢了**：
        //     连传十几条之后 YouTube 明显变慢（日志里"点了上传视频"
        //     到 input 出现也从 0 秒涨到了 15 秒）。
        //   ★★ 而当场判死的代价**很大**：文件**已经投进去了**，
        //     很可能已经在服务端传着 —— 这一条就处在
        //     "传了、但没记账"的模糊状态（重跑会再传一份，额度不回收）。
        //   → 所以先**再等一轮**，并且把"还在等"说出来
        //     （不说的话，用户看到的是"卡住了"，会去关标签页）。
        // ★ 3.2.53：记下真实起点 —— 下面那句"等了 N 秒"必须是**真等到的**。
        //   （原来写的是 `CONFIG.wait_timeout * 2` = 30 秒，而实际等的是
        //     15 + 30 = **45 秒**：报出来的数字跟事实不符。
        //     而"等了多久"是判断"页面坏了还是只是慢"的第一个依据。）
        const tTitle = Date.now();
        let titleBox = await waitFor(function () { return findTitleBox(); },
            CONFIG.wait_timeout);
        if (!titleBox) {
            const extra = Math.max(CONFIG.wait_timeout, 30000);
            log('  · 等了 ' + Math.round(CONFIG.wait_timeout / 1000)
                + ' 秒还没等到标题框 —— **再等 '
                + Math.round(extra / 1000) + ' 秒**。'
                + '（连着传多条之后 YouTube 会变慢：前面几条只要 5 秒。）', 'warn');
            titleBox = await waitFor(function () { return findTitleBox(); }, extra);
        }
        if (!titleBox) {
            const waitedSec = Math.round((Date.now() - tTitle) / 1000);
            // ★ 报错里**必须带文件名** —— 用户要去 Studio 里找它。
            //   不带的话他只能一条一条翻，而这一批有 189 个。
            throw StepError(
                '「' + item.fileName + '」等了 ' + waitedSec
                + ' 秒也没等到标题输入框（分两轮等：'
                + Math.round(CONFIG.wait_timeout / 1000) + ' + '
                + Math.round(Math.max(CONFIG.wait_timeout, 30000) / 1000) + ' 秒）。'
                + '\n    ★ 对话框出来了、但标题框没出来 —— 看一眼页面上是不是有报错，'
                + '或者对话框还停在"选择文件"那一步。'
                + hiddenNote()
                + '\n    ★★ **这条很可能已经传上去了**（文件早就投进去了）：'
                + '\n        · 先去 YouTube Studio 搜「' + item.fileName + '」确认一下'
                + '\n        · 传上去了 → 它已经记账了，重跑会**自动跳过**它'
                + '\n          （面板上「跳过已上传的」开着）'
                + '\n        · 没传上去 → 直接重跑，它会再来一遍'
                + '\n    ★ 想让我看结构的话：点面板上的「诊断对话框（复制结构）」，'
                + '把结果贴出来。',
                'notfound'
            );
        }
        setValue(titleBox, item.title);
        await sleep(CONFIG.step_pause);

        const back = readValue(titleBox).trim();
        if (back !== item.title) {
            throw StepError(`标题回读对不上：填的是「${item.title}」，读回来是「${back}」`, 'verify');
        }
        log('  标题已填：' + item.title, 'ok');

        // ── 4b. 顺手把视频 id 记在**这一条队列项**上 ──
        //
        // ★★ 完整理由见 rememberVideoId() 的注释。一句话：
        //    链接只在「详细信息」这一步的 DOM 里，而第 10 步读它的时机
        //    恰恰是"刚点完完成、对话框正在关"—— 真机就是这么栽的。
        // ★ 放在标题回读**通过之后**：得先确认对话框是这条视频的。
        // ★ 这一步**允许读不到**（链接随上传进度出现），
        //   所以点「继续」之前还会再试一次（见下面 7 之前那句）。
        rememberVideoId(item);

        // ── 5b. 填描述（配了模板才填）──
        if (item.description) {
            const descBox = findDescriptionBox(titleBox);
            if (!descBox) {
                // ★ 这里只警告不抛。描述是选填的，而且它填不上不影响
                //   视频能不能用 —— 跟标题不一样（标题空着 YouTube 会拿
                //   文件名兜底，描述空着就是空着）。为了一个选填字段
                //   让整批停下，代价比收益大。
                log('  ⚠ 找不到描述输入框，跳过描述。', 'warn');
            } else {
                setValue(descBox, item.description);
                await sleep(CONFIG.step_pause);
                const gotDesc = readValue(descBox).trim();
                if (gotDesc !== item.description.trim()) {
                    // ★★★★★ 3.2.55：**说清"长出来"意味着什么**。
                    //
                    //   2026-09-21 从 YouTube 频道侧核出来一个真事故：
                    //   9/17 那批 6 条（prod-b）、9/20 早上那条，**描述都被写了
                    //   两遍** —— 视频页上的描述是 1517 字符，而模板只有 758。
                    //   （另一个渠道：`youtube.com/feeds/videos.xml?channel_id=…`
                    //    的 `media:description` 是**逐字原文**，可以直接量。）
                    //
                    //   ★ 原来这里只说"对不上"，读的人第一反应是"没填上"，
                    //     而**真相反过来** —— 最常见的是"多了一份"。
                    //     两种情况的处置完全不同：
                    //       · 少 → 重填
                    //       · 多 → 得先清空再填，否则越填越多
                    //   ★★ 所以判据要带上**方向**：比长短。
                    const lenFill = item.description.trim().length;
                    const lenGot = gotDesc.length;
                    log('  ⚠ 描述回读对不上：填了 ' + lenFill + ' 字，读回来 '
                        + lenGot + ' 字。\n      ' + describeDescMismatch(lenFill, lenGot)
                        + '\n    ★ 描述是选填的，这一条照常继续 —— 但**发完去看一眼**。', 'warn');
                } else {
                    log('  描述已填：' + item.description.length + ' 字'
                        + '（回读一致）', 'ok');
                }
            }
        }

        // ── 5c. 缩略图（从自动生成的截图里选一张）──
        //
        // ★ 放在这里：缩略图和标题 / 描述在**同一个对话框步骤**里，
        //   这一步的滚动位置顺手就把它带出来了，不用等翻页。
        // ★ 它是选填的，函数自己保证"找不到就跳过、不抛" ——
        //   所以这里不用判断返回值，也不需要 try/catch。
        await pickThumbnail();

        // ── 6. 不是给小朋友看的 ──
        await selectNotMadeForKids();

        // ── 7. 一路「下一步」──
        //
        // ★ 离开「详细信息」之前**再来一次** —— 链接是随上传进度出现的，
        //   标题填完那一刻不一定就有，而走出这一步它就没了。
        if (!rememberVideoId(item)) {
            log('  还没看到视频链接（上传还没完）。后面读不到时只能靠地址栏，'
                + '更容易失败 —— 这不算错，先继续。', 'info');
        }
        await clickNextUntilDone();

        // ── 8. 可见性 ──
        await setVisibility(item.visibility);

        // ── 9. 完成（发布 / 保存 / 排期 —— 同一个按钮，名字随可见性变）──
        //
        // ★ 按钮叫什么、在哪个范围里找，全在 findFinishButton() 里 ——
        //   这里只负责"等它出现 → 点 → 报出点的是哪个词"。
        //   为什么把查找抽走：那条"只在对话框里找"的规则原来内联在这里，
        //   而本函数要凑齐 File / DataTransfer / 分步对话框才能跑，
        //   于是规则一行测试都覆盖不到。
        if (item.autoPublish) {
            const info = await waitFor(findFinishButton, CONFIG.wait_timeout);

            if (!info) {
                log('  ✕ 等不到最后一步的完成按钮。找的是：'
                    + CONFIG.yt.finish_texts.join(' / '), 'error');
                dumpDialog('等不到完成按钮');
                throw StepError(
                    '等不到最后一步的完成按钮（找的是：'
                    + CONFIG.yt.finish_texts.join(' / ') + '）。'
                    + '上面那份结构快照里列出了对话框里所有按钮的实际文字 —— '
                    + '照着把缺的那个词补进 CONFIG.yt.finish_texts，'
                    + '或者直接把带 #id 的那个填进 CONFIG.selectors.yt.finishButton。',
                    'notfound'
                );
            }

            // ★★★ 点之前先判一句：这个"完成按钮"是不是翻页按钮？
            //
            //   真机上的代价：对话框没往前走，这里兜底到了「继续」，
            //   点下去只是翻了一页，视频没保存，而日志写的是「✓ 完成」。
            //   **报告成功比停下更糟** —— 用户会以为跑通了。
            //   而且这一步停下**不亏**：视频已经在草稿里，不扣新配额、不用重传。
            const bad = finishButtonProblem(info);
            if (bad) {
                log('  ✕ ' + bad, 'error');
                log('  （这里**不会**宣布成功。点了翻页按钮视频并没有保存。）', 'error');
                dumpDialog('完成按钮其实是翻页按钮');
                throw StepError(
                    bad + ' 多半是"下一步"没点动 —— 看一眼 CONFIG.yt.next_texts '
                    + '是否包含界面上那个词（中文界面是「继续」），'
                    + '对话框正停在前面的某一步上。'
                    + '视频已经传上去了（在草稿里），手动把它走完就行：'
                    + '不用重传，也不扣新配额。',
                    'finish-not-finish'
                );
            }

            // ★★★ 点之前先问一句：这个按钮是不是**禁用**的？
            //   禁用 = YouTube 自己告诉你"必填项还没齐"，这比我们去读
            //   单选状态可靠（那一组很可能没写 aria）。真机上少了这一问，
            //   就变成"点了、没动、然后才报" —— 晚一步。
            //
            // ★★★ 3.2.15：但"禁用"**不等于"没救了"** —— 它常常是**暂时**的。
            //   10:35 那次就是：排期区还在异步渲染，按钮因联动而暂时禁用，
            //   而旧代码一看禁用就抛错停下，**抢在页面准备好之前放弃了**。
            //   所以现在先**等一会儿**，等不到才报。
            const dis = finishDisabledProblem(info);
            if (dis) {
                log('  ⏳ 完成按钮现在是禁用的，等它变可用（最多 '
                    + Math.round((CONFIG.yt.finish_enable_timeout_ms || 30000) / 1000)
                    + ' 秒）—— 禁用常常是暂时的（排期区还在渲染 / 视频还在处理）。', 'warn');
                const ok = await waitFinishEnabled(info);
                if (!ok) {
                    log('  ✕ ' + dis, 'error');
                    log('  （**不会**去点它 —— 点了也不会有任何反应。）', 'error');
                    const proc = stillProcessingVisible();
                    log('  等满之后页面上' + (proc
                        ? '**还有**可见的「视频还在处理」对话框（' + proc
                          + '）—— 视频还没转完，这种情况只能等，重跑也一样。'
                        : '**没有**可见的"还在处理"对话框 —— '
                          + '所以卡住它的不是转码，是必填项。'), 'error');
                    dumpDialog('完成按钮一直是禁用的');
                    throw StepError(
                        dis + ' 视频已经传上去了（在草稿里）：不扣新配额、不用重传，'
                        + '手动把这一步选完再点保存即可。'
                        + '★ 上面「排期」那几行如果打了 ⚠，就是它。',
                        'finish-disabled'
                    );
                }
                log('  ✓ 完成按钮已可用，继续点它。');
            }

            const markBefore = dialogStepMark();
            info.node.click();

            // ★★★ 3.2.17：**等结果**，不再 1.5 秒就判死刑。
            //
            //   旧写法在这里只 `await sleep(CONFIG.step_pause * 3)`（1.5 秒），
            //   然后比对"步骤标记没变 + 完成按钮还在"→ 报"YouTube 拒绝了这次保存"。
            //   而 11:19 真机那次，点击**是生效的**：YouTube 把底部三个按钮
            //   一起禁用、留在原地继续上传送审，**用户在屏幕上看到的就是发布了**。
            //   1.5 秒的耐心，把成功报成了失败。
            //
            //   ★ 为什么这个误判特别贵：报了失败 → 用户体验是"重跑这一条"，
            //     而那条视频**可能已经发出去了** —— 重跑就是重复投稿。
            //     所以判据一律**先判成功**，判断不了的（"忙"）算**继续等**，
            //     只有等满了还没动静才判失败。整段理由见 waitPublishOutcome。
            const outcome = await waitPublishOutcome(markBefore, info.text);

            if (!outcome.ok) {
                const waited = Math.round(
                    (Number(CONFIG.yt.post_publish_wait_ms) || 30000) / 1000);

                // ★★★ 3.2.18：**先算"前面哪几步没做干净"，再打错误行。**
                //
                //   原来顺序反了：先 `log('✕ …')`、再 `troublesSince(stepMark)`，
                //   而 `stepMark` 取的是**当前这一条的开头** —— 于是刚打的
                //   那一句必然落在扫描区间里，被自己列进清单，现场现象是：
                //       ✕ 点了「发布」后等了 30 秒…YouTube 没接受这次保存。
                //       ★ 这一步之前，有 1 处没做干净 —— 原因就在这里面：
                //           · ✕ 点了「发布」后等了 30 秒…        ← **就是它自己**
                //   等于**让错误信息引用它自己**。
                //
                //   ★ 这不是"日志不好看"，是**数据不对**：
                //     `troubles.length` 还会决定下面走哪条分支 ——
                //     有它在这儿，`troubles` 永远 ≥1，于是"前面每一步都报的成功"
                //     那句**永远打不出来**，而那句话恰恰是排查方向上最关键的一句。
                const troubles = troublesSince(stepMark);

                log('  ✕ 点了「' + info.text + '」后等了 ' + waited
                    + ' 秒，对话框还是没动 —— YouTube 没接受这次保存。', 'error');
                // ★★★ 3.2.15：把"前面哪几步没做干净"**实打实列出来**，
                //   不再写"最可能是公开范围 / 受众声明" ——
                //   10:35 那次这两步**都是成功的**，那句话把排查方向指错了。
                //   见 troublesSince 的注释。
                if (troubles.length) {
                    log('  ★ 这一步之前，有 ' + troubles.length
                        + ' 处**没做干净** —— 原因就在这里面：', 'error');
                    troubles.forEach(function (t) { log('      · ' + t, 'error'); });
                } else {
                    log('  ★ 前面每一步**都报的成功**，一条 ⚠ 都没有 —— '
                        + '那拒绝的原因不在这几步里：最可能是**视频还在处理**'
                        + '（快照里出现 still-processing 就是它），'
                        + '或者 YouTube 那边还没准备好。'
                        + '过一会儿手动点一下保存即可，同样不用重传、不扣新配额。', 'error');
                }
                dumpDialog('点了完成但对话框没动');
                throw StepError(
                    '点了完成按钮（「' + info.text + '」）但对话框停在原地 —— '
                    + 'YouTube 拒绝了这次保存。'
                    + (troubles.length
                        ? '这一步之前没做干净的地方：' + troubles.join(' ／ ')
                        : '前面每一步都报的成功，所以原因多半不在脚本控制的这几步里'
                          + '（最可能是视频还在处理）。')
                    + ' 视频已经传上去了（在草稿里），手动把这一步选完再点保存就行：'
                    + '不用重传，也不扣新配额。',
                    'finish-not-accepted'
                );
            }

            log('  已点「' + info.text + '」，可见性 ' + item.visibility, 'ok');
        } else {
            log('  跳过完成这一步（面板上把自动发布关掉了）。'
                + '视频停在草稿里，你回去点一下才有链接。', 'warn');
        }

        // ── 10. 取视频链接 ──
        const videoId = await resolveVideoId(item);

        // ── 11. 关掉对话框（可选）──
        const closeSel = CONFIG.selectors.yt.closeDialog;
        if (closeSel) {
            const node = deepQueryOne(closeSel);
            if (node) {
                node.click();
                await sleep(CONFIG.step_pause * 2);
            }
        }

        return videoId;
    }

    /**
     * 页面上所有可见的 contenteditable 文本框，按 DOM 顺序。
     *
     * 标题框和描述框都是 contenteditable 的 div，长得几乎一样 ——
     * 唯一能拿来区分的只有 aria-label 和**它们的前后顺序**。
     */
    function findEditableBoxes() {
        // ★ 对话框在的时候，只在对话框里找。
        //   页面别处（搜索框、评论区）也有 contenteditable，混在一起的话
        //   findTitleBox 的"退一步取第一个"会稳定地拿到框外的元素 ——
        //   而且是**悄没声地**拿到：它长得一样、能写进去、回读也能对上，
        //   只是写错了地方。
        const dlg = deepQueryOne('ytcp-uploads-dialog')
            || deepQueryOne('tp-yt-paper-dialog')
            || deepQueryOne('ytcp-video-metadata-editor');

        const out = [];
        const found = dlg ? deepQueryAll('[contenteditable="true"]', dlg)
            : deepQueryAll('[contenteditable="true"]');

        for (const n of found) {
            if (!n.isConnected || !isVisible(n)) continue;
            if (out.indexOf(n) >= 0) continue;
            out.push(n);
        }
        return out;
    }

    /** 找标题框：配了用配的，没配按 aria-label 找，再退一步取第一个。 */
    function findTitleBox() {
        const configured = CONFIG.selectors.yt.title;
        if (configured) return deepQueryOne(configured);

        const boxes = findEditableBoxes();
        for (const n of boxes) {
            const label = (n.getAttribute('aria-label') || '') + ' ' + (n.id || '');
            if (/title|标题/i.test(label)) return n;
        }
        // 退一步：上传对话框里第一个文本框就是标题。这不是"猜" ——
        // 标题是详情这一步的第一个字段，结构上就排在前面。
        return boxes[0] || null;
    }

    /** 找描述框。 */
    function findDescriptionBox(titleBox) {
        const configured = CONFIG.selectors.yt.description;
        if (configured) return deepQueryOne(configured);

        const boxes = findEditableBoxes();

        // ★ 先排除标题框，再说"这个像不像描述框"。
        //   反过来的话会被标题框自己骗到：实测它的 aria-label 是
        //   「Add a title that describes your video」，里面那个 "describes"
        //   正好含 "desc"。
        for (const n of boxes) {
            if (n === titleBox) continue;
            const label = (n.getAttribute('aria-label') || '') + ' ' + (n.id || '');
            if (/desc|说明|描述|tell viewers/i.test(label)) return n;
        }

        // 再退一步：标题后面紧挨着的那一个。
        // ★ 这条兜底其实比上面那条可靠 —— 标题和描述在详情这一步是相邻的，
        //   而"按词根找"依赖 YouTube 的 aria-label 文案不变。
        const idx = boxes.indexOf(titleBox);
        if (idx >= 0 && boxes[idx + 1]) return boxes[idx + 1];
        return null;
    }

    /** radio / checkbox 是不是已经选中了。 */
    function isControlChecked(node) {
        if (!node) return false;
        const aria = node.getAttribute && node.getAttribute('aria-checked');
        if (aria === 'true') return true;
        if (aria === 'false') return false;
        if (typeof node.checked === 'boolean') return node.checked;
        return false;
    }

    /** 这个节点看起来像不像一个"选中式"控件。 */
    function looksLikeControl(n) {
        if (!n) return false;
        // ★★★ 3.2.15：**块标题永远不是控件** —— 先排掉，再看别的。
        //
        //   这条是 10:35:22 真机日志逼出来的：
        //       ⚠ 排期：文字命中了 p#visibility-title…但它**不是控件**——跳过
        //   这句话自相矛盾：`enclosingControl` 已经把它当成控件返回了
        //   （否则返回的是"原地"那个节点，而原地那个是标题**内部**的 span），
        //   下一个判据又说它不是控件。
        //   说明 `enclosingControlStrict` 在标题上**停住了**，
        //   没有再往上找、也没有返回 null。
        //
        //   ★ 停在那里的代价是双份的：
        //     · 该返回 null 的时候返回了个标题 → 调用方以为"找到了控件"
        //     · 真正的控件在更上面，被这一步挡住了
        //   `setVisibility` 的 `ctl ? {...} : null` 判据也会因此放行错误命中。
        //
        // ★ 为什么不用"往上多走几层再判断"来绕过：
        //   那是治标 —— 标题上停住这件事本身就该禁止。
        if (isBlockTitle(n)) return false;
        const tag = String(n.tagName || '').toLowerCase();
        if (/radio|checkbox/.test(tag)) return true;
        const g = function (k) { return n.getAttribute && n.getAttribute(k); };
        const role = String(g('role') || '').toLowerCase();
        if (role === 'radio' || role === 'checkbox') return true;
        // ★ 有状态属性就是控件 —— 这一条最通用：Studio 换标签名也躲不掉
        if (g('aria-checked') !== null) return true;
        if (g('checked') !== null) return true;
        if (typeof n.checked === 'boolean') return true;
        return false;
    }

    /**
     * 从"文字所在的那个节点"往上找到**控件本身**。
     *
     * ★★★ 这个函数是 16:47 那次真机日志逼出来的，它一次解释了**两个**现象。
     *
     * 按文字找控件时（`findControl`）取的是**最深**的节点 —— 那是对的，
     * 为的是别误点整块容器。但"最深那一个"通常只是文字所在的
     * `<span>` / `<div>`，而：
     *   · 选中状态（`aria-checked`）挂在**外层**的 radio / checkbox 上
     *   · 点击处理也常常挂在外层
     *
     * 于是同时出现两句看着无关的日志：
     *   「⚠ 可见性点过了，但读不到选中状态（这个版本没写 aria-checked）」
     *   「[ ] 「不公开列出」」 ← 快照里明明读得到状态
     * ★ 真因不是"版本没写 aria"，是**找错节点了**：
     *   拿文字节点去问状态、拿文字节点去点，两件事都不成立。
     *
     * 判据：祖先里第一个"看起来是控件"的节点；找不到就返回原地
     * （不瞎猜更外层的东西 —— 那可能是一整块区域）。
     */
    function enclosingControl(node) {
        return enclosingControlStrict(node) || node;
    }

    /**
     * 同 `enclosingControl`，但**找不到就返回 null**。
     *
     * ★★ 为什么两种都要有：
     *   调用方的处置不一样 ——
     *     · 拿它当"点的目标"（`clickControlUntilChecked`）：返回原地还能试，
     *       点一下没反应至少不炸；
     *     · 拿它当"**找到了没有**"的判据（可见性、排期）：返回原地会把
     *       "我根本没找到控件"伪装成"我找到了"，然后点在标题文字上，
     *       日志写"点过了"，页面上一项都没选中。
     *   18:35 真机就是栽在这一条上。
     *
     * ★★★ 为什么是 30 层而不是 8 层（3.2.10 第二次踩坑）：
     *   19:00 真机日志：文字「公开」埋在一个 `<b>`（深度 16）里，而真正
     *   的 `tp-yt-paper-radio-button` 在它上面**十几层**（中间是 Studio 排版
     *   塞进去的一串 div / #radioLabel / #radioContainer 之类的壳）。
     *   8 层循环走到一半就退出、返回 null —— 于是"控件明摆着就在快照里，
     *   代码却说找不到控件"。之前测试夹具里文字是 radio 的**直接子节点**
     *   （1 层就到），8 层自然够，把这个数给惯坏了。
     *   Studio 换多少层壳都不该影响"往上找控件"这件事，放宽到 30 层
     *   （`looksLikeControl` 遇到第一个控件就停，不会误抓更外层的容器）。
     */
    function enclosingControlStrict(node) {
        let cur = node;
        for (let i = 0; cur && i < 30; i += 1) {
            if (looksLikeControl(cur)) return cur;
            cur = ancestorOf(cur);
        }
        return null;
    }

    /** 一个节点的"身份证"，写日志用：标签 + id + 头两个 class。 */
    function describeNode(node) {
        if (!node) return '(空)';
        const tag = String(node.tagName || '').toLowerCase();
        const id = node.id ? '#' + node.id : '';
        const cls = String((node.getAttribute && node.getAttribute('class')) || '')
            .trim().split(/\s+/).filter(Boolean).slice(0, 2).join('.');
        const t = String(node.innerText || node.textContent || '').trim()
            .replace(/\s+/g, ' ').slice(0, 40);
        return tag + id + (cls ? '.' + cls : '')
            + '  深度=' + depthOf(node)
            + (t ? '  文字=「' + t + '」' : '  （没有文字）');
    }

    /**
     * `clickControlUntilChecked` 试过哪些手法（它把清单记在节点上）。
     *
     * ★ 为什么要把这个带进错误信息里：
     *   "什么都试过还是点不动"和"只试了鼠标序列"是完全不同的两件事，
     *   对应两条完全不同的排查方向（前者要去看遮挡/禁用/父节点接管，
     *   后者只要补一种触发方式）。日志里不写清楚，下一轮只能靠猜。
     */
    function triedList(node) {
        const t = (node && node.__cslTried) || [];
        return t.length ? t.join('、') : '（没记录）';
    }

    /**
     * 一个"选中式"控件当前**到底选中没有**：true / false / null（读不到）。
     *
     * ★ 必须从给定节点**往上**读几层。Studio 把 `aria-checked` 挂在
     *   `tp-yt-paper-radio-button` 那一层，而 `findControl` 取的是里面
     *   **文字所在的最深节点** —— 只看那一个的话永远读到 null，
     *   于是"到底选上没有"这个问题在代码里根本问不出来。
     *
     * ★★ 读不到时返回 **null**，不是 false。
     *   "确实没选中"和"读不到状态"必须分开：拿 null 当"没选中"去报错，
     *   会在任何没写 aria 的版本上每次都误停。
     */
    /**
     * 这个节点**自己或它里面**的那个原生 radio / checkbox —— 状态的真值在它身上。
     *
     * ★ 2026-09-19（3.2.41）新增。为什么需要它，见 `checkedState` 里那段现场记录。
     *
     * ★★ 判据是"**恰好一个**"：一个容器里塞着两个以上的原生框，那是"整组"
     *   （比如 radio 组），不是"这一项" —— 从组里随便取一个读状态，
     *   读出来的是**别的选项**的状态。宁可不认，也不能认错。
     *   （跟配额那处 `nearField` 用的是同一条思路：**数量恰好一个**才算"这一个"。）
     */
    function nativeFieldOf(node) {
        if (!node) return null;
        try {
            const tag = String(node.tagName || '').toLowerCase();
            if (tag === 'input') {
                const t = String((node.getAttribute && node.getAttribute('type')) || '')
                    .toLowerCase();
                if (t === 'radio' || t === 'checkbox') return node;
            }
            if (!node.querySelectorAll) return null;
            const all = node.querySelectorAll('input[type="radio"], input[type="checkbox"]');
            if (all && all.length === 1) return all[0];
        } catch (e) { /* 读不动就当没有 —— 退回原来那套判据 */ }
        return null;
    }

    function checkedState(node) {
        let cur = node;
        for (let i = 0; cur && i < 6; i += 1) {
            const g = function (k) { return cur.getAttribute && cur.getAttribute(k); };
            // ★ 3.2.10：三种"状态属性"一起认。
            //   只认 aria-checked 的话，把状态挂在 aria-selected / aria-pressed 上的
            //   实现会一律读成"读不到"（null）—— 而 null 是不报错的，
            //   于是又变成"点了、日志写成功、页面没动"。
            const keys = ['aria-checked', 'aria-selected', 'aria-pressed'];
            for (let k = 0; k < keys.length; k += 1) {
                const v = g(keys[k]);
                if (v === 'true') return true;
                if (v === 'false') {
                    // ★★★★★ 3.2.41：**读到 `false` 先别急着信。**
                    //
                    //   真机 20:03 现场（第 4 步「评价」）：
                    //     · 脚本点了「不为资源添加标签」，然后连读 5 秒，**每次都是 false**
                    //       → 报「点了但没勾上」，停在这一步。
                    //     · 而 4 秒后用户手动打的快照里，同一个选项是 **[✓] 已选中**。
                    //   ★ 两边的判据不一样：快照读的是**原生 input**（`input.checked`），
                    //     脚本读的是"手里这个节点" —— 而它是从**外层**开始读的，
                    //     外层那个 `aria-checked="false"` **框架没有跟着更新**
                    //     （或者干脆一直就是 false），于是**真值被一个陈旧的外层属性挡在外面**。
                    //   ★ 这跟"回读要从节点往上读"是同一件事的两面：
                    //     往上读是为了**找到**状态，但不能把**外层那个旧的**当成最新的。
                    //   → 只要这个节点（或它里面）有**恰好一个**原生框，
                    //     **它的 `checked` 就是真值** —— 原生控件不会骗人。
                    //   ★ 只覆盖 `false` 这个方向：`true` 依然直接返回，
                    //     所以这条改动**不会**把"确实选中了"读成没选中，
                    //     只会把"外层说没选中、里面其实选中了"纠正过来。
                    const nf = nativeFieldOf(cur);
                    if (nf && typeof nf.checked === 'boolean') return nf.checked;
                    return false;
                }
            }
            // 退化判据：只反射 attribute、不暴露 property 的实现
            if (g('checked') !== null) return true;
            if (typeof cur.checked === 'boolean') return cur.checked;
            // ★ 3.2.10：状态只挂在内部原生 input 上的结构。
            //   外层读不到、里面读得到 —— 只问外层就会一直 null。
            let inp = null;
            try {
                inp = cur.querySelector
                    && cur.querySelector('input[type="radio"], input[type="checkbox"]');
            } catch (e) { inp = null; }
            if (inp && typeof inp.checked === 'boolean') return inp.checked;
            // class 里带 selected —— 放在最后，前面几条都比它可信
            if (/(^|[\s_-])selected([\s_-]|$)/.test(String(g('class') || '').toLowerCase())) {
                return true;
            }
            cur = ancestorOf(cur);
        }
        return null;
    }

    /**
     * 把「一次点击」完整地做出来：mousedown → mouseup → click。
     *
     * ★★★ 3.2.10：光有 `el.click()` 是不够的。
     *
     *   Studio 的单选项是 Polymer 的 `tp-yt-paper-radio-button`，它把处理
     *   挂在 **`on-tap`** 上 —— 而 `tap` 是 Polymer 用 `mousedown` + `mouseup`
     *   合成出来的手势事件，**不是**原生 click。
     *   只 dispatch 一个 click，在某些实现里 tap 根本不会触发：
     *   表现就是脚本"点过了"，而页面上一项都没选中。
     *
     *   `composed: true` 是为了让事件**穿过 shadow 边界** ——
     *   Studio 的对话框里到处是 shadow root，不写这一条事件会在边界上被吃掉。
     *
     *   09:39 真机证明**光靠这一层还是不够**（见 clickControlUntilChecked 的分层策略），
     *   但它仍然是第一顺位：最接近真实用户操作。
     */
    /**
     * 鼠标事件序列 —— **一份代码，三种打法**。
     *
     * ★★★★ 2026-09-19（3.2.39）：为什么要拆出"三种打法"。
     *
     *   真机 16:26:57 的现场（3.2.38 那份"兜底清单"交出来的答案）：
     *     · 目标文字「广告流量」**整页任何地方都不存在**
     *     · 兜底清单列出来的全是**导航项** → 那份清单确实扫了全页
     *   → 结论：菜单**从来没开过**（不是"没认出来"，是没打开）。
     *   ★ 而同一屏上「发布比例」那个下拉**点得开** ——
     *     快照里两个是**一模一样的 class**（`button _ngcontent-lmx-49 border`）。
     *     长得一样、一个开一个不开 → 差别只可能在**事件序列**上。
     *
     *   ★ 整条链是：
     *       pointerover → pointerenter → mouseover → mouseenter → pointermove
     *       → mousemove → pointerdown → mousedown → focus → pointerup → mouseup → click
     *     对"在 **click** 上打开"的组件没问题；但对"在 **pointerdown / mousedown**
     *     上打开"的组件，后面那一记 `click`（bubbles + composed，会冒到 document）
     *     正好被 CDK 的**"点到外面就关"**收到 ——
     *     于是**打开和关掉发生在同一串里**，我们的轮询一次都看不到它。
     *     ★ 这也解释了为什么读到的是"一直是 0 个"，而不是"菜单开着但没有这一项"。
     *   ★ 这是**假设，不是结论** —— 所以做成"分级尝试 + 记下哪一级生效"。
     *     **哪一级生效本身就是证据**：下一轮日志会直接告诉我们。
     */
    const MOUSE_SEQ = {
        // 整条链（默认，最接近真实用户）
        full: ['pointerover', 'pointerenter', 'mouseover', 'mouseenter', 'pointermove',
            'mousemove', 'pointerdown', 'mousedown', 'FOCUS', 'pointerup', 'mouseup', 'click'],
        // 只按下：**不补 up / click** —— 给"在按下时打开、又被后面那记 click 关掉"
        // 的组件用。收尾那两枪正是嫌疑所在，所以这里必须真的省掉。
        downOnly: ['pointerover', 'pointerenter', 'mouseover', 'mouseenter', 'pointermove',
            'mousemove', 'pointerdown', 'mousedown'],
        // 只派一次 click：给"只认 click"的组件兜底
        clickOnly: ['click'],
        // ★★★★★ 3.2.46 新增的**诊断级**：同样是"按下 → 抬起 → click"，
        //   但**一个都不冒泡**（`bubbles:false` / `composed:false`）。
        //
        //   真机 2026-09-20 10:47:51 逼出来的（第 2 条 CSL 的第 1 步）：
        //     同一条流程、同一个选择器、同一个函数，**第 1 条开得了、第 2 条开不了**，
        //     而且三种打法全试过、浮层容器探测报「**一个都没有**」。
        //
        //   ★ 前三级的共同点是：**它们派出去的事件都是冒泡的**
        //     （`bubbles:true` + `composed:true`，会一路冒到 document）。
        //     所以 "none of them works" 这件事**区分不出**下面两种：
        //       ① 事件压根没被按钮自己收到（前几枪根本没生效）
        //       ② 事件**收到了、菜单也开了**，但同一串里那记冒泡到 document 的
        //          `click` 被 CDK 的"点到外面就关"收到 → **开出即关**，
        //          刷新频率赶不上，轮询永远看到 0 个
        //     ★ 而"开到关上"这一串**可能只有几十毫秒**，200ms 的轮询粒度
        //       本来就抓不到 —— 所以"三种都没开"**不能**推出"点击没生效"。
        //
        //   → 这一级把 ② 单独排除掉：**不冒泡的事件照样能触发挂在元素自己身上的
        //     监听器**（Angular 的模板绑定就挂在元素自己上），
        //     但**到不了 document**，也就碰不到那个 outside-click 监听器。
        //     · 它在第 4 级**成功** → ② 成立（确证"开出即关"），修法已经自动生效；
        //     · 它在第 4 级**也失败** → ② 排除，剩下的路只有"点击没生效"，
        //       那时再去看浮层容器在不在（见 `overlayRootCheck`）。
        //   ★ 顺序刻意放在**最后**：前三级哪一级生效本身就是**证据**
        //     （第 1 条就是靠第 1 级 `full` 成功的），把新的插到前面会让
        //     那条证据失真。
        noBubble: ['mousedown', 'mouseup', 'click'],
    };

    function fireMouseSeq(el, mode) {
        if (!el) return;
        const seq = MOUSE_SEQ[mode] || MOUSE_SEQ.full;
        // ★ 3.2.46：只有 `noBubble` 这一级把事件关在元素内部（见 `MOUSE_SEQ.noBubble`）。
        const noBubble = (mode === 'noBubble');

        // ★ 2026-09-18：原来只派 `mousedown / mouseup / click` 三枪。
        //
        //   真机 18:10:27 那次：**人手工点得开，脚本点同一个按钮没反应** ——
        //   等满 15 秒，页面一帧没变（还是列表页），向导压根没打开。
        //   ★ 手工点得开就把"没权限 / 入口是死的"排掉了，
        //     剩下唯一的差别是**事件序列**：真实鼠标走过 pointer → mouse → focus
        //     这一整条链，而脚本只派了后半截。Angular Material（新版 `mdc-button`）
        //     有一部分交互正是挂在 **`pointerdown`** 上的 —— 少了前面几枪，
        //     处理函数压根没被叫起来，现象就是"点了没反应、也不报错"。
        //
        //   ★ 这一层的教训跟本项目别处是同一条：
        //     **模仿用户要模仿全**。装到一半的动作，在页面看来不是"弱一点的点击"，
        //     是"根本没点"。
        try {
            if (typeof el.scrollIntoView === 'function') {
                // ★ 真实用户点击时元素必然在视野内；而虚拟滚动 / 懒渲染的列表里，
                //   没滚进视野的元素压根没挂上监听。这一句不是多余的动作。
                el.scrollIntoView({ block: 'center', inline: 'center' });
            }
        } catch (e) { /* 夹具没有这个方法；真机上失败也不影响后面的尝试 */ }

        // ★★★★★ 2026-09-18 第三版：**事件的构造器要用页面那一套**。
        //
        //   真机 23:20:43 那次（3.2.33）把两个候选都试过了，两个都是
        //   `<button class="mdc-button …">`（真按钮、真入口），**都没反应**。
        //   → 于是"点到的不是按钮"和"该点的是另一个入口"**都排掉了**。
        //
        //   ★ 剩下的一个便宜嫌疑：**跨 realm 的事件**。
        //     油猴在有 `@grant` 时跑在**独立的世界**里，那里面的 `MouseEvent`
        //     和页面那个 `MouseEvent` **不是同一个构造函数**。
        //     派出去的事件页面能收到，但页面里若有 `e instanceof MouseEvent`
        //     这类判断就会**静默判否** —— 现象正是"点了、不报错、没反应"。
        //
        //   → 优先用 `unsafeWindow` 上那套（页面世界的），取不到再退回沙箱的。
        //     ★ 这跟本项目在 YouTube 侧定过的规矩是同一条：
        //       **跟页面打交道要用页面自己的东西**（那边最后是直接派 `tap`）。
        const PAGE = (typeof unsafeWindow !== 'undefined' && unsafeWindow) || null;
        const pick = function (name) {
            try {
                if (PAGE && typeof PAGE[name] === 'function') return PAGE[name];
            } catch (e) { /* 跨 realm 读属性有时会被拒 */ }
            try {
                if (typeof window !== 'undefined' && typeof window[name] === 'function') {
                    return window[name];
                }
            } catch (e) { /* 同上 */ }
            return null;
        };
        const PtrEv = pick('PointerEvent');
        const MouEv = pick('MouseEvent');
        const view = PAGE || (typeof window !== 'undefined' ? window : null);

        const fire = function (type, usePointer) {
            let ev;
            const common = {
                bubbles: !noBubble,
                cancelable: true,
                composed: !noBubble,
            };
            // 真机（油猴）环境有 MouseEvent 和 window，造一个带 view 的完整事件；
            // 测试环境（new Function 沙箱）两者都没有，退化成普通对象 ——
            // 夹具的 dispatchEvent 只认 `e.type`，一样能把 click 派出去。
            try {
                if (usePointer && PtrEv) {
                    ev = new PtrEv(type, Object.assign({}, common, {
                        view: view, button: 0, buttons: 1,
                        pointerId: 1, pointerType: 'mouse', isPrimary: true,
                        detail: type === 'click' ? 1 : 0,
                    }));
                } else if (MouEv) {
                    ev = new MouEv(type, Object.assign({}, common, {
                        view: view, button: 0, buttons: 1,
                        // ★ detail: 真实点击是 1。有些实现拿 detail 区分
                        //   "用户点的"和"代码补的"，补上更接近真点击。
                        detail: type === 'click' ? 1 : 0,
                    }));
                } else {
                    ev = Object.assign({ type: type }, common);
                }
            } catch (e) {
                ev = Object.assign({ type: type }, common);
            }
            try { el.dispatchEvent(ev); } catch (e) { /* 派不出去就算了，还有别的打法 */ }
        };

        // ★ 顺序照真实鼠标来（缩进对齐 MOUSE_SEQ 里那一行）。
        for (let i = 0; i < seq.length; i += 1) {
            const step = seq[i];
            if (step === 'FOCUS') {
                try {
                    if (typeof el.focus === 'function') el.focus();
                } catch (e) { /* 不可聚焦的元素就算了 */ }
                continue;
            }
            fire(step, step.indexOf('pointer') === 0);
        }
    }

    function clickHard(el) {
        fireMouseSeq(el, 'full');
    }

    /** ★ 3.2.39：只按下、**不补 up / click** —— 见 `MOUSE_SEQ.downOnly` 上面那段。 */
    function clickDownOnly(el) {
        fireMouseSeq(el, 'downOnly');
    }

    /** ★ 3.2.39：只派一次 `click` —— 给"只认 click"的组件兜底。 */
    function clickOnce(el) {
        fireMouseSeq(el, 'clickOnly');
    }

    /**
     * ★ 3.2.46：**不冒泡**的一枪 —— 见 `MOUSE_SEQ.noBubble` 上面那段。
     *
     * 用途是**诊断**，不是"更用力地再点一次"：它把"菜单开过又被冒泡的 click
     * 关掉"这条路径单独排除掉。所以日志里必须说清楚它**是什么**，
     * 不能让读的人以为只是"第四种点法"。
     */
    function clickNoBubble(el) {
        fireMouseSeq(el, 'noBubble');
    }


    /**
     * 直接派发 Polymer 的 **`tap`** 事件。
     *
     * ★★★ 这是 09:39 真机逼出来的。
     *
     *   `tp-yt-paper-radio-button` 的 `listeners` 里挂的是
     *       `{ 'tap': '_onTap' }`
     *   —— 监听的是 **`tap` 这个事件名**。`tap` 平时由 Polymer 的手势系统
     *   用 mousedown+mouseup **合成**出来，而合成是有前提的（两次事件都
     *   被它的手势监听收到、且落在同一个节点上）。
     *   我们的合成 mouse 序列**没被它认成一次 tap** → `_onTap` 一次都没跑
     *   → 点了 6 轮、aria-checked 一直是 false。
     *
     *   `tap` 就是个普通事件名，**可以直接派**。派出去，`_onTap` 就会跑，
     *   跟用户真点了一下等效 —— 绕开了"手势合成认不认"这件我们控制不了的事。
     */
    function fireTap(el) {
        if (!el) return false;
        let ok = false;
        const types = ['tap', 'click'];
        for (let i = 0; i < types.length; i += 1) {
            let ev;
            try {
                ev = typeof CustomEvent === 'function'
                    ? new CustomEvent(types[i], { bubbles: true, composed: true })
                    : { type: types[i], bubbles: true, composed: true };
            } catch (e) { ev = { type: types[i], bubbles: true, composed: true }; }
            try { el.dispatchEvent(ev); ok = true; } catch (e2) { /* 换下一种 */ }
            if (types[i] === 'tap') return ok;   // tap 派出去就算成功，不再补 click
        }
        return ok;
    }

    /**
     * 直接把控件的 **`checked` 属性**写上去。
     *
     * ★★ 最后一道保险。Polymer 的 `checked` 是带 `notify` / `reflectToAttribute`
     *   的正式属性，组件自己的 observer 会把它反射成 `aria-checked`、
     *   并通知父级的单选组去做互斥。
     *
     * ★ 为什么**不顺手把 aria-checked 一起写掉**：
     *   那就变成"自己写、自己读"，回读永远为真 ——
     *   正是我们要根治的那种"日志说成功、页面没动"的谎话。
     *   这里只写 `checked`，**让组件自己反射**；它不反射，我们就照实报失败。
     */
    function setCheckedProp(el) {
        if (!el) return false;
        try {
            if (!('checked' in el)) return false;
            el.checked = true;
            try {
                el.dispatchEvent(
                    typeof Event === 'function'
                        ? new Event('change', { bubbles: true, composed: true })
                        : { type: 'change', bubbles: true, composed: true }
                );
            } catch (e) { /* change 派不出去不影响属性已写 */ }
            return true;
        } catch (e) { return false; }
    }

    /**
     * 点控件内部那个**原生 input**（shadow root 里也要找）。
     *
     * ★ Polymer 的纸张控件常常把真正的状态放在一个隐藏的原生
     *   `input[type=radio|checkbox]` 上。点它比点外壳更"底层"，
     *   而且原生 input 的 click 一定会改 checked。
     */
    function clickInnerInput(el) {
        if (!el) return false;
        const sel = 'input[type="radio"], input[type="checkbox"]';
        const found = [];
        try { if (el.querySelector) found.push(el.querySelector(sel)); } catch (e) { /* 忽略 */ }
        try {
            if (el.shadowRoot && el.shadowRoot.querySelector) {
                found.push(el.shadowRoot.querySelector(sel));
            }
        } catch (e) { /* 忽略 */ }
        for (let i = 0; i < found.length; i += 1) {
            const inp = found[i];
            if (!inp || inp === el) continue;
            try {
                inp.click();
                return true;
            } catch (e2) { /* 换下一个 */ }
        }
        return false;
    }

    /**
     * 这个节点"看得见"吗 —— 只用来在 shadow 里挑候选。
     *
     * ★ 为什么要挑：真点击的 target 是**命中测试**算出来的，看不见的元素
     *   永远不会成为 target。我们照着这个规则挑，才是在模仿真点击。
     */
    function isHitTestable(n) {
        if (!n) return false;
        const tag = String(n.tagName || '').toLowerCase();
        // style / slot / template 在真实 DOM 里没有盒子，点了也没有命中测试。
        if (tag === 'style' || tag === 'slot' || tag === 'template') return false;
        try {
            if (typeof n.getBoundingClientRect === 'function') {
                const r = n.getBoundingClientRect();
                // 宽高都为 0 = 没有渲染出来（display:none / 未布局）。
                if (r && !r.width && !r.height) return false;
            }
        } catch (e) { /* 读不到就当成看得见 —— 宁可多试一个，别漏掉 */ }
        return true;
    }

    /**
     * 收集「事件真正该派到哪儿」的候选节点 —— 从宿主一路钻进 shadow root。
     *
     * ★★★ 这是 09:39 真机剩下的最后一道坎，而且原因是 DOM 规范上的硬事实，
     *     不是"再猜一种触发方式"：
     *
     *     **事件只会从 shadow 内部往外冒（composed），不会从宿主往里钻。**
     *     派在宿主 `tp-yt-paper-radio-button` 上的 mousedown / mouseup /
     *     click / tap，shadow root 里的 `#radioContainer` **一个都收不到**。
     *
     *     而 Paper 组件的 `on-tap` 恰恰挂在 `#radioContainer` 上。
     *     也就是说前面那四种手法（全都打在宿主身上）在结构上就**不可能**生效 ——
     *     "点了 6 轮、aria-checked 一直是 false、日志却写成功"和这个完全对上。
     *
     *     真人点击为什么行：真点击的 target 由命中测试决定，会落到 shadow 里
     *     最里面那个元素上，然后**往外**冒泡，一路上依次经过
     *     `#offRadio` → `#radioContainer`（on-tap 在这儿）→ 宿主。
     *     所以派在**最深处**那个节点上，比派在宿主上更接近真点击。
     *
     * ★ 返回顺序：先"真点击会落在哪"（shadow 里最深那个节点），
     *   再补"一看就是交互件"的（role=radio / radioContainer / label…）。
     *   两组互不替代 —— 前者是"真点击的 target 就是它"，后者是结构性兜底
     *   （结构变了、换 id、多套一层时还能捞回来）。
     *   顺序不能反：候选要封顶 4 个，排在后面的会被挤掉。
     */
    function shadowTargets(el) {
        if (!el) return [];
        const out = [];
        const seen = new Set();
        const push = function (n) {
            if (!n || n === el || seen.has(n)) return;
            if (!isHitTestable(n)) return;
            seen.add(n);
            out.push(n);
        };

        // ★ 自己收集 shadow root，**不用 deepQueryAll(sel, el)**：
        //   那个函数只收"后代里的 shadow root"（walk 从 `el.querySelectorAll('*')`
        //   开始，`el` 自己不在结果里），而我们要找的恰恰是**控件自己**的
        //   shadow root —— 用它的话一个都收不到，这一层会静默变成空转。
        const roots = [el];
        const seenRoot = new Set();
        const walk = function (node) {
            let sr = null;
            try { sr = node.shadowRoot; } catch (e) { sr = null; }
            if (sr && !seenRoot.has(sr)) {
                seenRoot.add(sr);
                roots.push(sr);
                walk(sr);
            }
            let all = [];
            try { all = node.querySelectorAll('*'); } catch (e) { all = []; }
            for (let i = 0; i < all.length; i += 1) walk(all[i]);
        };
        walk(el);

        // ② "真点击会落在哪"：一层层钻进 shadow root，每层取最深那个。
        //
        // ★★ 这一档**排在结构化选择器前面**，是有意的：
        //   候选要封顶（见函数末尾），排在后面的会被挤掉。
        //   而"最深那个节点"才是**真点击的 target** —— 事件从它往外冒，
        //   必然经过挂 on-tap 的那一层，这比"猜哪个 id 像容器"可靠得多。
        //   反过来放的话，真实页面上 `label` / `paper-ripple` 这些名字
        //   很可能先把 4 个名额占满，把最该试的那个挤出去。
        let cur = el;
        for (let i = 0; i < 6 && cur; i += 1) {
            let sr = null;
            try { sr = cur.shadowRoot; } catch (e) { sr = null; }
            if (!sr) break;
            let all = [];
            try { all = sr.querySelectorAll('*'); } catch (e) { all = []; }
            let deepest = null;
            let deepestDepth = -1;
            for (let j = 0; j < all.length; j += 1) {
                const n = all[j];
                if (!isHitTestable(n)) continue;
                let d = 0;
                let p = n;
                // parentElement 优先：shadow root 自己是个 DocumentFragment，
                // 它没有 parentElement，得靠 parentNode 收尾。
                while (p && p !== sr) {
                    d += 1;
                    p = p.parentElement || p.parentNode || null;
                }
                if (d > deepestDepth) { deepestDepth = d; deepest = n; }
            }
            if (!deepest) break;
            push(deepest);
            cur = deepest;
        }

        // ① 结构性特征（兜底）：Paper 的圆点容器带 role="radio"，
        //    paper-radio-button 里它的 id 就叫 radioContainer。
        //    结构变了（换 id、多套一层）时，靠这一档还能捞回来。
        const handy = ['[role="radio"]', '#radioContainer', '.radioContainer',
            'label', 'button', 'input', 'paper-ripple'];
        for (let i = 0; i < handy.length; i += 1) {
            for (let r = 0; r < roots.length; r += 1) {
                let hits = [];
                try { hits = roots[r].querySelectorAll(handy[i]); } catch (e) { hits = []; }
                for (let j = 0; j < hits.length; j += 1) push(hits[j]);
            }
        }

        // ★ 封顶 4 个：每试一个都要等一次状态回读（click_settle_ms），
        //   候选多了会把失败路径拖到十几秒 —— 而失败路径恰恰是用户要等的那条。
        return out.slice(0, 4);
    }

    /** 等状态稳定下来再读：控件的状态常是异步反射的，读完立刻判定会误报失败。 */
    async function readStateSettled(node, budgetMs) {
        const budget = budgetMs || CONFIG.yt.click_settle_ms || 500;
        const step = Math.max(10, Math.round(budget / 5));
        let st = checkedState(node);
        let spent = 0;
        while (st !== true && spent < budget) {
            await sleep(step);
            spent += step;
            st = checkedState(node);
        }
        return st;
    }

    /**
     * 点一个"选中式"控件，直到它**真的显示为选中**；返回最终状态。
     *
     * ★★ 为什么要有这个函数：真机上出过一次 ——
     *   点了、日志写了「可见性：unlisted」，而快照里那一排选项
     *   **四个一个都没勾**。之后点「保存」被 YouTube 拒绝（这一项必填），
     *   对话框停在原地，脚本却已经宣布「✓ 完成」。
     *   点了个不生效的东西 = 静默失败，而日志说"成功"。
     *
     * ★★★ 3.2.11 改成**分层策略** —— 09:39 真机：
     *   这次"找"已经对了（命中的就是 `tp-yt-paper-radio-button`，
     *   深度 13），可点了 6 轮、绕了 3 秒，`aria-checked` 一直是 false。
     *   说明**光靠合成鼠标序列推不动它**。
     *
     *   与其继续猜"是不是层数/时机不对"，不如把几种**互不依赖**的
     *   触发手法都试一遍，每种试完立刻回读：
     *     ① 鼠标序列 —— 最像真人，优先
     *     ② `tap` 事件 —— 直接打 Paper 控件的 `on-tap`
     *     ③ 钻进 shadow root 派 —— 宿主上派不进去，真点击的 target 本来就在里面（见 shadowTargets）
     *     ④ `checked` 属性 —— 写 Polymer 的正式属性，让它自己反射
     *     ⑤ 内部原生 input —— 最底层，点了必改 checked
     *   哪一层、哪种手法成了，**日志里说清楚** —— 下次就不用再猜。
     *
     * ★ 为什么还要往外层走：
     *   有些控件的处理挂在**外层容器**上，点里面那颗圆点没反应。
     *   **找的时候取控件，点的时候由内向外试**。
     */
    async function clickControlUntilChecked(node) {
        const tried = [];
        // ★ 名字直接用 `tagOf` —— 它本来就带 `#id` 和 `.class`，
        //   所以日志里是 `div#radioContainer` / `div#offRadio`，分得开
        //   挂着 on-tap 的那个和没挂的那个。
        //   （这里原本套了一层 `nameOf` 想额外补 id，其实是**死代码**：
        //    变异测试把"删掉补 id 那一句"跑成了全绿，才暴露它没起作用。
        //    留着它只会让下一个读代码的人以为 id 是这儿加的。）
        const note = function (name, el) {
            tried.push(name + '→' + tagOf(el));
        };

        // ── 第一轮：就在控件本身上，把四种手法依次试完 ──
        clickHard(node);
        note('鼠标序列', node);
        if (await readStateSettled(node) === true) return true;

        fireTap(node);
        note('tap', node);
        if (await readStateSettled(node) === true) return true;

        // ── 第一轮半：钻进 shadow root 里派（见 shadowTargets 的注释）──
        //
        // ★★★ 为什么必须单独有一轮、而且必须在属性写入**之前**：
        //   前面两种手法打在**宿主**上，而 Paper 的 on-tap 挂在 shadow root
        //   内部的 `#radioContainer` 上 —— 宿主上派的事件进不去 shadow root，
        //   在结构上就不可能生效。
        //   这一轮才是"最接近真点击"的那一个：真点击的 target 本来就在
        //   shadow 深处。它要是能成，就没必要动属性（属性写入是最后一招，
        //   因为这等于**绕开组件的正常流程直接改状态**，副作用最小但最不真）。
        const inner = shadowTargets(node);
        for (let k = 0; k < inner.length; k += 1) {
            clickHard(inner[k]);
            note('钻进shadow鼠标', inner[k]);
            if (await readStateSettled(node) === true) return true;

            fireTap(inner[k]);
            note('钻进shadow tap', inner[k]);
            if (await readStateSettled(node) === true) return true;
        }

        setCheckedProp(node);
        note('写checked', node);
        if (await readStateSettled(node) === true) return true;

        clickInnerInput(node);
        note('点内部input', node);
        if (await readStateSettled(node) === true) return true;

        // ── 第二轮：往外走几层，只试"鼠标序列 + tap"（属性/input 与层级无关）──
        let cur = ancestorOf(node);
        for (let up = 0; cur && up < 4; up += 1) {
            clickHard(cur);
            note('鼠标序列', cur);
            if (await readStateSettled(node) === true) return true;

            fireTap(cur);
            note('tap', cur);
            if (await readStateSettled(node) === true) return true;

            cur = ancestorOf(cur);
        }

        // 把试过的手法记在节点上，交给调用方写进日志/错误里 ——
        // "什么都试过了还是不行"和"只试了一种"必须能分开。
        try { node.__cslTried = tried; } catch (e) { /* 忽略 */ }
        return checkedState(node);
    }

    // ── 受众声明：「这一项是不是『不是给小朋友看的』」 ──
    //
    // ★ 为什么不用一张写死的文案表。
    //
    //   真机第二次试跑把表打法的毛病暴露干净了：中文界面下这一对的真实文案是
    //         「是的，为儿童打造」 / 「不，并非为儿童打造」
    //   而配置里当时写的是「不是给小朋友看的」「并非面向儿童」——
    //   **两个都不是它的子串**，于是稳定匹配不到。
    //   靠"见到一条补一条"永远追不上：语种多、简繁不同、文案还会改。
    //
    // ★ 换成"两个特征同时具备"的谓词，就跟具体文案脱钩了：
    //
    //   ① 必须提到"小朋友 / 儿童"这类对象  ② 必须带否定
    //
    //   「不，并非为儿童打造」 → 儿童 ✓ + 并非 ✓ → 命中（要选的就是它）
    //   「是的，为儿童打造」   → 儿童 ✓ + 无否定 → 不命中
    //   "No, it's not made for kids" → kids ✓ + not/no ✓ → 命中
    //   "Yes, it's made for kids"     → kids ✓ + 无否定 → 不命中
    //
    // ★ 否定词里**故意不收单个「否」字**：「此视频是否为儿童打造？」这句
    //   题干里就有「是否」，收了它题干本身就会被当成答案 ——
    //   而题干和选项在 DOM 里挨得很近，点错就是"给儿童看的"，
    //   属于必填项填错的最高代价那一类。
    // ★ 简繁都要收：只写「儿童」的话，繁体界面的「兒童」命中不了 ——
    //   而"漏一个写法"的表现和"这个功能没做"完全一样，都是找不到。
    const KIDS_WORDS = /kids|children|child|儿童|兒童|小朋友|孩童/;
    const NOT_WORDS = /\bnot\b|\bno\b|n't|并非|並非|不是|不，|不,/;

    function isNotForKidsLabel(raw) {
        const s = String(raw === null || raw === undefined ? '' : raw).toLowerCase();
        if (!s) return false;
        return KIDS_WORDS.test(s) && NOT_WORDS.test(s);
    }

    /**
     * 选「不是给小朋友看的」。
     *
     * ★ 这一步上一版是失败的，失败原因值得记下来：
     *   它就在对话框滚动区的下半部分，而上一版**不滚动**，
     *   `findByText` 只认 `['button','ytcp-button','paper-button','a',
     *   'div[role="button"]','tp-yt-paper-radio-button']` 这几种标签，
     *   而且只看 innerText 不看 aria-label。三重叠加的结果是稳定找不到，
     *   日志只说一句"没找到"，看不出是"真没有"还是"没滚到"。
     *
     * 现在改成：findControl（认 aria-label、取最深匹配）+ withScrollSweep（先滚再找）。
     */
    async function selectNotMadeForKids() {
        const configured = CONFIG.selectors.yt.notMadeForKids;

        const findIt = function () {
            if (configured) {
                const node = deepQueryOne(configured);
                if (node) return node;
            }
            // 两条路并用的原因：谓词管语种和新文案，清单管"谓词万一失手"
            // 那种极端情况（比如文案里一个否定词都没有，靠 "not made for kids" 兜）。
            return findControl(CONFIG.yt.not_made_for_kids_texts, {
                accept: isNotForKidsLabel,
            });
        };

        const hit = await withScrollSweep(findIt, '受众声明');

        if (!hit) {
            // 这一项 YouTube 是必填的。
            //
            // ★ 这里要**先确认它是不是已经选好了**再喊狼来了：
            //   YouTube 会记住上一次的选择，如果本来就是「不是给小朋友看的」，
            //   那"找不到"只是因为找的姿势不对，实际状态是对的 ——
            //   这两种情况的处理完全不同，日志必须分得开。
            const state = audienceState();
            if (state.notKidsChecked) {
                log('  受众：这一项本来就选着「不是给小朋友看的」（没找到它只是因为'
                    + '找的姿势不对，状态是对的），继续。', 'info');
                return;
            }

            log('  ⚠ 没找到「不是给小朋友看的」选项 —— 这一步 YouTube 是必填的。', 'warn');
            log('  ⚠ 而且它是必填项，YouTube 会拦住这一页不让往下走。', 'warn');
            dumpDialog('受众声明没找到');
            return;
        }

        // YouTube 会记住上一次的受众选择，预选好的那个再点一次是**取消**，
        // 不是"再选一次"。所以先看它是不是已经选中了。
        if (isControlChecked(hit)) {
            log('  受众：已经是「不是给小朋友看的」，不用再点', 'info');
            return;
        }

        hit.click();
        await sleep(CONFIG.step_pause);
        log('  受众：不是给小朋友看的', 'ok');
    }

    // ── 缩略图：从 YouTube 自动生成的视频截图里选一张 ──
    //
    // ★ 判据是"结构"，不是"名字"。跟受众声明同一个教训：
    //   写死的文案表追不上（语种多、简繁不同、文案会改）。
    //   这里只认两件事：
    //     ① 这一块自己（或近几层祖先）的 id / class / aria-label 提到
    //        thumbnail / 缩略图  —— id 和 class 是 DOM 自己的命名，
    //        比界面上给人看的文字稳得多
    //     ② 里面有一张 <img>（真截图一定有图）
    //
    // ★★ 一条硬规矩：**绝不能点到「上传缩略图」那个格子**。
    //   点它会弹**系统**文件选择器 —— 那是浏览器原生弹窗，脚本关不掉、
    //   也读不到，整条流程就吊死在那一句上，后面每一步都不执行，
    //   而且日志停在"正在上传第 N 个"这种看起来正常的地方，极难排查。
    //   所以候选里必须排掉"自己文字提到上传 / Upload"的格子。
    const THUMB_HINT = /thumbnail|缩略图/;
    const THUMB_UPLOAD_WORDS = /上传|upload|选择文件|choose file/;

    /** 一个节点的"身份线索"：id + class + aria-label，全小写。 */
    function hintOf(node) {
        if (!node) return '';
        const ga = function (k) {
            return String((node.getAttribute && node.getAttribute(k)) || '');
        };
        return (String(node.id || '') + ' ' + ga('class') + ' ' + ga('aria-label'))
            .toLowerCase();
    }

    /**
     * 一张 `<img>` 的地址。
     *
     * ★ 必须**只在这一个地方**读 —— 原来有三处各写各的，两处带 `|| node.src`
     *   兜底、一处不带。真机快照上这一点点不一致的表现是：
     *   同一个节点在「那一排」里列了出来，在下面的「图片」总表里**却找不到**
     *   （一处读到地址、一处读到空串）。诊断快照自相矛盾，
     *   读的人会以为"页面上有两张不同的图"，凭空多出一轮排查。
     */
    function srcOf(node) {
        if (!node) return '';
        return String((node.getAttribute && node.getAttribute('src')) || node.src || '');
    }

    /** 「标签#id.class」这种短写法，给日志和结构快照用。 */
    function tagOf(node) {
        if (!node) return '(空)';
        const cls = String((node.getAttribute && node.getAttribute('class')) || '');
        return String(node.tagName || '').toLowerCase()
            + (node.id ? '#' + node.id : '')
            + (cls ? '.' + cls.split(/\s+/).slice(0, 2).join('.') : '');
    }

    /**
     * 缩略图那一排：**装着至少两张图**、而且自己带着 thumbnail / 缩略图 名字的容器。
     *
     * ★★ 「至少两张图」这条不能省 —— 真机快照把这个不设它的后果暴露得很干净。
     *
     *   原来的写法是"从 <img> 往上找，谁的名字里有 thumbnail 就算在缩略图区"。
     *   在没有真 DOM 的时候看着挺合理，一上真页面就错了两处：
     *
     *     ① 左侧抽屉里的**频道头像**被判成 [缩略图区] ——
     *        Studio 给头像外面那层包的名字里就带 thumbnail。
     *        而它是候选里的**第一张**（页面上第一个 <img>），
     *        index=0 就会去点它 → 把导航抽屉点开 / 页面跳走，上传流程当场断掉。
     *     ② 内容列表页的「暂无内容」插图、对话框里的**报错插图**
     *        被判成 [上传入口!]（它们外层容器的文字里带「上传」）。
     *
     *   这两类误判合起来的意思是：**脚本会去点一个跟缩略图毫无关系的图** ——
     *   比"找不到缩略图"严重得多（找不到只是退回 YouTube 自己挑一张）。
     *
     *   "一排若干个"是缩略图**选择器**天然的结构，所以"至少两张图"
     *   是个又便宜又准的信号：单个头像、单张插图全被它挡掉。
     *
     * ★ 另外两条边界：
     *   · **只在对话框里找**（传 scope 就用 scope，否则用 dialogRoot）。
     *     对话框不在 → 一个都不给。页面别处的图（抽屉、页头、列表插图）
     *     全部出局，不需要再靠名字去分辨它们。
     *   · 排掉我们自己面板里的图（isOurs）。
     */
    function thumbnailRows(scope) {
        const root = scope || dialogRoot();
        if (!root) return [];
        let all = [];
        try { all = deepQueryAll('*', root); } catch (e) { all = []; }

        const rows = [];
        for (const n of all) {
            if (!n || isOurs(n)) continue;
            if (!THUMB_HINT.test(hintOf(n))) continue;
            let imgs = [];
            try { imgs = n.querySelectorAll('img'); } catch (e) { imgs = []; }
            // ★ 只数**真有 src** 的图：占位图 / 懒加载的空壳不算。
            const real = [];
            for (const im of imgs) {
                if (srcOf(im)) real.push(im);
            }
            if (real.length < 2) continue;
            rows.push({ node: n, imgs: real });
        }
        return rows;
    }

    /**
     * 截图的"格子"：从 <img> 往上走，走到"里面还只有这一张图"的那个祖先为止，
     * 而且**不许越出那一排**。
     *
     * ★ 为什么要这么绕，而不是直接拿 img.parentElement：
     *   判"是不是上传入口"得读格子自己的文字，而**读哪一层是有讲究的**。
     *   往外多走一层，就会把兄弟节点「上传缩略图」那几个字一起读进来
     *   （容器的 textContent = 自己 + 所有子孙），
     *   一句话把所有真截图全排除掉，表现成"这个功能没做" ——
     *   和受众声明那次"文案表不是子串"是同一类静默失效。
     *
     * ★ 真机快照补上的另一半：光有"只有一张图"这条还不够 ——
     *   页面上图少的时候（比如内容列表页、报错对话框），
     *   往上走好几层都只遇到这一张图，于是格子会一路涨到**整页容器**上，
     *   而它的文字里当然有「上传」（页面上到处是）。
     *   所以再加一道硬边界：`stopAt`（那一排）就是天花板。
     */
    function thumbTileOf(img, stopAt) {
        let cur = img;
        let hops = 0;
        while (cur.parentElement && hops < 6) {
            const up = cur.parentElement;
            if (stopAt && up === stopAt) break;      // 不许越出那一排
            let imgs = [];
            try { imgs = up.querySelectorAll('img'); } catch (e) { imgs = []; }
            if (imgs.length > 1) break;
            cur = up;
            hops += 1;
        }
        return cur;
    }

    /** 这个格子是不是「上传缩略图」入口（点它 = 弹系统文件选择器 = 吊死）。 */
    function looksLikeThumbUploader(tile) {
        if (!tile) return false;
        const text = String(tile.innerText || tile.textContent || '')
            .trim().replace(/\s+/g, ' ').slice(0, 40);
        if (text && THUMB_UPLOAD_WORDS.test(text)) return true;
        return THUMB_UPLOAD_WORDS.test(hintOf(tile));
    }

    /** 这一张当前是不是已经选中的（外圈高亮 / aria 状态）。 */
    function isThumbSelected(img) {
        let cur = img;
        let hops = 0;
        while (cur && hops < 4) {
            if (isControlChecked(cur)) return true;
            const g = function (k) { return cur.getAttribute && cur.getAttribute(k); };
            if (g('aria-selected') === 'true') return true;
            const sel = g('selected');
            if (sel !== null && sel !== undefined) return true;
            cur = ancestorOf(cur);
            hops += 1;
        }
        return false;
    }

    /**
     * 候选截图，按页面上的先后顺序。
     *
     * 只在**缩略图那一排**里取（见 thumbnailRows），所以页面别处的图
     * ——抽屉里的频道头像、页头头像、列表插图、报错插图——一个都进不来。
     * 返回的是 <img> 本身：点它就行，真截图外面那层的点击处理会冒泡上来，
     * 而且点"最深的那个节点"不会误点到整块容器
     * （跟 findControl 取最深是同一个道理）。
     *
     * ★★★ 一张缩略图 = 一个 **`select` 格子** —— 这是被**两份**真机快照连着纠正出来的。
     *
     *   第一份快照（3.2.2 的依据）显示一张截图是两个节点：
     *       <div class="select">  … <img src="…AOn4CLAE_jtlo…">
     *       <div class="preview"> … <img src="…AOn4CLAE_jtlo…">   ← 当时**地址一样**
     *   于是按"图片地址"去重就够了。
     *
     *   第二份快照（3.2.3 的依据）打脸了：
     *       <div class="select">  … <img src="…AOn4CLC5BN…X7A">
     *       <div class="preview"> … <img src="…n4CLBNhJt…&retry=2">  ← **地址不一样**
     *   两个节点地址不同 → 按地址去重**失效** → 一张缩略图照样算成两个候选。
     *   （`&retry=2` 那个地址还说明预览图是另一条渲染路径。）
     *
     *   ● 结论：**地址不是"一张缩略图"的判据，`select` 格子才是。**
     *     每个选项一个 `select`，`preview` 是它的附图。
     *     所以：**能认出 `select` 就只认 `select`**；
     *     一个 `select` 都认不出来，才退回"按格子 + 按地址"去重。
     *     —— 认不出来时退回宽松，是为了别的版本还能用；
     *        而它错的方向是"多数一张"，`index=0` 照样对，不会点错东西。
     */
    function isThumbSelectSlot(node) {
        const cls = String((node.getAttribute && node.getAttribute('class')) || '');
        return /(^|\s)select(\s|$)/.test(cls);
    }

    function thumbnailCandidates(scope) {
        const kept = [];
        for (const row of thumbnailRows(scope)) {
            for (const img of row.imgs) {
                const tile = thumbTileOf(img, row.node);
                if (looksLikeThumbUploader(tile)) continue;
                kept.push({ img: img, tile: tile });
            }
        }

        // ★ 有 select 格子 → 只认它（这才是"一张缩略图"）
        const sel = kept.filter(function (k) { return isThumbSelectSlot(k.tile); });
        const use = sel.length ? sel : kept;

        const out = [];
        const seenTile = [];
        const seenSrc = [];
        for (const k of use) {
            if (seenTile.indexOf(k.tile) >= 0) continue;      // 同一个格子只算一张
            const src = srcOf(k.img);
            if (src && seenSrc.indexOf(src) >= 0) continue;   // 同一个地址也只算一张
            seenTile.push(k.tile);
            if (src) seenSrc.push(src);
            out.push(k.img);
        }
        return out;
    }

    // 「缩略图没找到」的结构快照一次运行里只打一遍。
    // 72 个视频 × 一份几十行的快照 = 日志直接没法看，而真要看的就是第一遍。
    let thumbDumpDone = false;

    /**
     * 选缩略图：从自动生成的视频截图里选第 thumbnail_index 张（0 起）。
     *
     * ★ 三步走，每一步都是"失败也不影响别的事"：
     *     ① 直接找（可能已经渲染好了）
     *     ② 找不到就拨滚动区再找（这一块常在下半部分）
     *     ③ 还找不到就**等一会儿** —— 自动截图是视频**处理完之后**才生成的，
     *        刚投进去时这一块常常还是空的。等 thumbnail_wait_ms 还等不到就放弃
     *
     * ★ 最后一定会"放弃"，不会抛。缩略图是选填的：
     *   YouTube 会用它自己挑的那张，视频照样可用 ——
     *   也就是说**这一步最坏的结果 = 跟没做这个功能一样**，
     *   而不是让视频卡住。拿这个去换"让整批停下"是不划算的。
     */
    async function pickThumbnail() {
        const idx = Math.max(0, Math.floor(Number(CONFIG.yt.thumbnail_index) || 0));

        const findIt = function () {
            const sel = CONFIG.selectors.yt.thumbnailOption;
            if (sel) {
                const node = deepQueryOne(String(sel).replace(/\{i\}/g, String(idx)));
                if (node) return node;
            }
            const list = thumbnailCandidates();
            return list.length > idx ? list[idx] : null;
        };

        let hit = await withScrollSweep(findIt, '缩略图');

        // ★★ 等，而且是**边等边报进度**地等。
        //
        //   运营的原话：「缩略图那个是要系统生成需要一点时间，可以等一下再选择」。
        //   所以这里不是"重试一次"，是**值得等**：
        //   这个对话框此刻正挂着上传（元数据是在上传过程中填的），
        //   等一下不占额外时间；而截图一多，`thumbnail_index` 才真的能选第 2、第 3 张。
        //
        //   ★ 为什么不用 waitFor：它只有"等到/没等到"两种结局，
        //     中间一片空白。等了 60 秒什么都不说的话，用户只会以为脚本卡住了。
        //     现在每 10 秒报一次"已等 N 秒、目前看到几张" ——
        //     这个数正好回答"到底是没生成，还是我只认出来一部分"。
        if (!hit) {
            const limit = Math.max(0, Number(CONFIG.yt.thumbnail_wait_ms) || 0);
            log('  缩略图：还没生成好（截图是 YouTube 系统生成的，要一点时间），'
                + '等一会儿再选…', 'info');
            const t0 = Date.now();
            let lastSaid = 0;
            for (;;) {
                hit = findIt();
                if (hit) break;
                const waited = Date.now() - t0;
                if (waited >= limit) break;
                if (waited - lastSaid >= 10000) {
                    lastSaid = waited;
                    log('    还在等截图…（已等 ' + Math.round(waited / 1000)
                        + ' 秒，目前认得出 ' + thumbnailCandidates().length + ' 张）', 'info');
                }
                await sleep(500);
            }
            if (hit) {
                log('  缩略图：等到了（等了 ' + Math.round((Date.now() - t0) / 1000)
                    + ' 秒，现在有 ' + thumbnailCandidates().length + ' 张可选）', 'ok');
            }
        }

        if (!hit) {
            log('  ⚠ 等了 ' + Math.round(Math.max(0, Number(CONFIG.yt.thumbnail_wait_ms) || 0) / 1000)
                + ' 秒，还是没等到可选的视频截图，跳过缩略图。这是选填项 —— '
                + 'YouTube 会用它自己挑的那张，视频照样可用。', 'warn');
            log('  （两种可能：① 这一步本来就没有缩略图 —— 它在「详细信息」'
                + '那一步；② 截图还没生成好。两种情况都不用管。'
                + '要等更久就把 CONFIG.yt.thumbnail_wait_ms 调大。）', 'info');
            if (!thumbDumpDone) {
                thumbDumpDone = true;
                dumpDialog('缩略图没找到');
            }
            return;
        }

        if (isThumbSelected(hit)) {
            log('  缩略图：第 ' + (idx + 1) + ' 张本来就是选中的，不用再点', 'info');
            return;
        }

        hit.click();
        await sleep(CONFIG.step_pause);
        log('  缩略图：选了第 ' + (idx + 1) + ' 张视频截图', 'ok');
    }

    /**
     * 受众声明当前的实际状态：那一对 radio 里，哪一个被选中了。
     *
     * ★ 存在的理由：「找不到控件」和「这一项没选对」是两个完全不同的问题，
     *   但上一版的日志把它们混成一句「没找到」，看不出实际状态是好是坏。
     */
    function audienceState() {
        const out = { found: 0, notKidsChecked: false, kidsChecked: false };
        let nodes = [];
        try {
            nodes = deepQueryAll('tp-yt-paper-radio-button, ytcp-radio-button, '
                + '[role="radio"], input[type="radio"], tp-yt-paper-checkbox');
        } catch (e) { nodes = []; }

        for (const n of nodes) {
            const label = String(
                (n.getAttribute && n.getAttribute('aria-label')) || ''
            ) + ' ' + String(n.innerText || n.textContent || '');
            if (!KIDS_WORDS.test(label.toLowerCase())) continue;
            out.found += 1;
            if (!isControlChecked(n)) continue;
            if (isNotForKidsLabel(label)) out.notKidsChecked = true;
            else out.kidsChecked = true;
        }
        return out;
    }

    /** 对话框当前的步骤指纹，用来判断"下一步"到底有没有生效。 */
    function dialogStepMark() {
        const dlg = dialogRoot();
        if (!dlg) return '';

        // 优先用步骤指示条里高亮的那一格（详情 / 视频元素 / 检查 / 可见性）
        let tabs = [];
        try { tabs = dlg.querySelectorAll('[aria-selected="true"], [selected]'); } catch (e) { tabs = []; }
        if (tabs.length) {
            const t = Array.prototype.slice.call(tabs, 0, 3).map(function (n) {
                return String(n.textContent || '').trim().replace(/\s+/g, ' ');
            }).join('|');
            if (t) return t.slice(0, 120);
        }

        // 拿不到步骤条就用内容长度当指纹 —— 粗糙，但足以区分"变了"和"没变"
        const text = String(dlg.textContent || '');
        return text.length + ':' + text.slice(0, 60);
    }

    /**
     * ══════════════════════════════════════════════════════════════════
     * 对话框结构快照 —— 找不到东西时，把"页面上到底有什么"原样报出来。
     * ══════════════════════════════════════════════════════════════════
     *
     * ★ 为什么必须有这个东西。
     *
     *   这个脚本两次真机试跑的失败，根因都是**靠猜**：
     *     · 第一次：以为选择器错了 → 改选择器
     *     · 第二次：受众声明「找不到」→ 以为是没滚动 → 加了滚动
     *   滚动加完了还是找不到。真正的原因是**文案对不上**（见 isNotForKidsLabel），
     *   但当时手上一份真实 DOM 都没有，只能继续猜。
     *
     *   每次猜都要付一次代价：一次上传 = 一份配额，扣了不返还。
     *   **猜的轮数就是烧掉的配额数。** 所以把"猜"这一步干掉，
     *   比修任何一个具体 bug 都值钱。
     *
     *   有了这个快照，失败就自带答案：按钮叫什么、radio 的文案是什么、
     *   哪一项是选中的、有几个能滚的区域 —— 全在日志里，不用再跑一次。
     */
    function dumpDialog(tag) {
        const lines = [];
        lines.push('── 对话框结构快照（' + (tag || '手动') + '）──');

        const dlg = dialogRoot();
        lines.push('对话框根：' + (dlg
            ? dlg.tagName.toLowerCase() + (dlg.id ? '#' + dlg.id : '')
            : '★ 一个候选标签名都没匹配到'));

        if (dlg) {
            let marks = [];
            try { marks = dlg.querySelectorAll('[aria-selected="true"], [selected]'); } catch (e) { marks = []; }
            const step = Array.prototype.slice.call(marks, 0, 3).map(function (n) {
                return String(n.textContent || '').trim().replace(/\s+/g, ' ').slice(0, 30);
            }).filter(Boolean).join(' | ');
            lines.push('当前步骤：' + (step || '（读不到步骤条）'));
        }

        // ── 按钮：文字 + id + aria-label + 可见性 ──
        //    id 尤其值钱：拿到它就能把 finishButton 配成稳定选择器，
        //    以后再也不用按文字猜。
        const btns = [];
        const btnSeen = [];
        for (const n of safeDeepAll('button, ytcp-button, paper-button, '
            + 'tp-yt-paper-button, a, div[role="button"]')) {
            // ★★ 排掉**我们自己面板**上的按钮。
            //
            //   真机快照打脸打得很直接：一共 36 个按钮，前 30 条里
            //   有 6 条是面板自己的（选择视频目录 / 全选 / 全不选 / 反选 /
            //   开始上传 / 诊断对话框），而**被截掉的那 6 条里就有「下一步」**——
            //   这份快照存在的唯一目的就是告诉我们页面上有什么，
            //   结果它把自己家的按钮排在前面，把答案挤出去了。
            if (isOurs(n)) continue;
            const t = String(n.innerText || n.textContent || '').trim().replace(/\s+/g, ' ');
            if (!t || t.length > 40) continue;
            if (btnSeen.indexOf(t) >= 0) continue;
            btnSeen.push(t);
            btns.push('    ' + (isVisible(n) ? '·' : '×')
                + (isDisabled(n) ? '[禁用]' : '')
                + ' 「' + t + '」'
                + (n.id ? '  #' + n.id : '')
                + (n.getAttribute && n.getAttribute('aria-label')
                    ? '  aria-label="' + n.getAttribute('aria-label') + '"' : ''));
        }
        // ★ 截断要说出来。真机上一次就是"正好截在答案前面"而看不出来 ——
        //   只列 30 条却只写"按钮（36）"，读的人会以为下面就是全部。
        lines.push('按钮（' + btns.length + '，· 可见 / × 不可见）：'
            + (btns.length ? '' : ' 一个都没读到'));
        lines.push.apply(lines, btns.slice(0, 60));
        if (btns.length > 60) {
            lines.push('    …… 还有 ' + (btns.length - 60) + ' 个没列出来（太多了）');
        }

        // ── radio / checkbox：文案 + 是否选中 ──
        const radios = [];
        const radioSeen = [];
        for (const n of safeDeepAll('tp-yt-paper-radio-button, ytcp-radio-button, '
            + '[role="radio"], input[type="radio"], tp-yt-paper-checkbox, '
            + 'input[type="checkbox"], [role="checkbox"]')) {
            if (isOurs(n)) continue;         // 同样别把自己面板上的东西算进来
            const label = String((n.getAttribute && n.getAttribute('aria-label')) || '');
            const t = label + ' ' + String(n.innerText || n.textContent || '');
            const s = t.trim().replace(/\s+/g, ' ');
            if (!s || radioSeen.indexOf(s) >= 0) continue;
            radioSeen.push(s);
            // ★ 3.2.10：加 tag/id/class —— 光一句「[ ] 「公开」」看不出
            //   它是哪个节点、状态挂在哪一层。18:35 那次就是缺了这层结构，
            //   才只能靠猜"到底点在哪个东西上了"。
            const id = n.id ? '#' + n.id : '';
            const cls = String((n.getAttribute && n.getAttribute('class')) || '')
                .trim().split(/\s+/).filter(Boolean).slice(0, 2).join('.');
            const aria = String((n.getAttribute && n.getAttribute('aria-checked'))
                || (n.getAttribute && n.getAttribute('checked')) || '');
            radios.push('    [' + (isControlChecked(n) ? '✓' : ' ') + '] 「'
                + s.slice(0, 60) + '」  '
                + String(n.tagName || '').toLowerCase() + id
                + (cls ? '.' + cls : '')
                + (aria ? '  (' + aria + ')' : '  （无 aria-checked/checked）'));
        }
        lines.push('单/多选项（' + radios.length + '，[✓] = 已选中）：'
            + (radios.length ? '' : ' 一个都没读到'));
        lines.push.apply(lines, radios.slice(0, 20));

        // ── 含关键字的所有元素：受众这类靠文字找的东西，全在这 ──
        //
        // ★ 必须排掉**我们自己面板**里的元素。真机快照上这一段的命中是：
        //     「12:23:03 受众：不是给小朋友看的」
        //   ——那是面板日志框里我们自己写的一句话，
        //   它把"这一块到底渲没渲染"这个信息彻底搅浑了（看着像渲染了，其实没有）。
        //   诊断日志最忌讳把"自己说的话"当成"页面上的证据"。
        const hits = [];
        for (const n of safeDeepAll('*')) {
            if (isOurs(n)) continue;
            const t = String(n.innerText || n.textContent || '').trim().replace(/\s+/g, ' ');
            if (!t || t.length > 80) continue;
            if (!KIDS_WORDS.test(t.toLowerCase())) continue;
            const line = '    「' + t.slice(0, 60) + '」'
                + (n.getAttribute && n.getAttribute('aria-label')
                    ? '  aria-label="' + n.getAttribute('aria-label') + '"' : '')
                + (isControlChecked(n) ? '  [✓已选]' : '');
            if (hits.indexOf(line) >= 0) continue;
            hits.push(line);
        }
        lines.push('含「儿童 / kids」字样的元素（' + hits.length + '）：'
            + (hits.length ? '' : ' ★ 一个都没有 —— 说明这一块压根没渲染，不是文案问题'));
        lines.push.apply(lines, hits.slice(0, 15));

        // ── 可滚容器：确认"到底滚没滚得动" ──
        const boxes = findScrollContainers();
        lines.push('可滚容器（' + boxes.length + '）：' + (boxes.length ? '' : ' 0 个 —— 这就是没滚的原因'));
        boxes.slice(0, 8).forEach(function (b) {
            lines.push('    ' + b.tagName.toLowerCase()
                + (b.id ? '#' + b.id : '')
                + '  scrollHeight=' + Number(b.scrollHeight || 0)
                + ' clientHeight=' + Number(b.clientHeight || 0));
        });

        // ── 缩略图那一排 + 页面上所有的图 ──
        //
        // ★ 为什么单独一段：选缩略图靠的是"结构"（哪一排、哪几张是候选、
        //   哪个格子不能点），而这三件事**只有真页面上才看得出来**。
        //   有它才能把判据改对，而不是继续猜（猜错一次一份配额）。
        //
        // ★ 这段的第一版上了真机就被打脸了，所以现在长这样：
        //   第一版只列"每张图在不在缩略图区"，结果抽屉里的**频道头像**
        //   被标成 [缩略图区]（Studio 给头像包的类名里带 thumbnail），
        //   而它是页面上第一张图 —— 按 index=0 就会去点它。
        //   现在改成先认**那一排**（至少两张图 + 名字带 thumbnail），
        //   再在排里认候选，误判就没地方藏了。
        const rows = thumbnailRows();
        const cands = thumbnailCandidates();
        const inRows = [];
        lines.push('缩略图那一排（' + rows.length + '）：'
            + (rows.length ? '' : ' 0 排 —— ★ 要么这一步还没有缩略图'
                + '（缩略图在「详细信息」那一步），要么结构跟预期不一样'));
        // ★ 每排最多列 12 张 —— 而且**截断了要说出来**。
        //   真机快照上「上传缩略图」那个入口**恰好排在第 7 位**，
        //   被上一版的 slice(0, 6) 截掉了，于是整段少了一条
        //   `[排除][上传入口!]`，读的人以为"上传入口没被识别出来"。
        //   和"按钮只列 30 条、把「下一步」挤出去"是同一个毛病：
        //   **诊断报告的截断处，正好是答案所在的位置。**
        rows.slice(0, 4).forEach(function (r) {
            lines.push('    ' + tagOf(r.node) + '  里面 ' + r.imgs.length + ' 张图');
            r.imgs.slice(0, 12).forEach(function (im) {
                const tile = thumbTileOf(im, r.node);
                inRows.push(im);
                const isUp = looksLikeThumbUploader(tile);
                // ★ 三种状态分清楚：[候选] 会被点；[上传入口!] 是绝对不能点的那个；
                //   [重复] 是"跟前面某张同一张图"（Studio 里一张截图有
                //   select / preview 两个节点，地址一样）。
                //   不分的话，"同一张图的第二个节点"会被写成 [排除]，
                //   读的人会以为"这一张因为别的原因没选中"，白查一轮。
                const how = cands.indexOf(im) >= 0 ? '[候选]'
                    : (isUp ? '[排除]' : '[重复]');
                lines.push('        · ' + how
                    + (isUp ? '[上传入口!]' : '')
                    + (isThumbSelected(im) ? '[✓已选]' : '')
                    + ' 格子=' + tagOf(tile)
                    + ' …' + srcOf(im).slice(-40));
            });
            if (r.imgs.length > 12) {
                lines.push('        …… 这一排还有 ' + (r.imgs.length - 12) + ' 张没列出来');
            }
        });

        const thumbs = [];
        for (const im of safeDeepAll('img')) {
            const src = srcOf(im);
            if (!src) continue;
            thumbs.push('    ' + (inRows.indexOf(im) >= 0 ? '[排内]' : '[别处]')
                + ' …' + src.slice(-40)
                + '  格子=' + tagOf(thumbTileOf(im)));
        }
        lines.push('图片（' + thumbs.length + '）：'
            + (thumbs.length ? '' : ' 一张都没有'));
        lines.push.apply(lines, thumbs.slice(0, 15));
        if (thumbs.length > 15) {
            lines.push('    …… 还有 ' + (thumbs.length - 15) + ' 张没列出来');
        }

        // ── 「视频还在处理」回执对话框（3.2.18 新增）──
        //
        //   ★ 为什么必须单列一节：12:12:35 那份快照里，这个对话框的按钮
        //     **一个都没出现** —— 因为它不是 `dialogRoot()` 认得的那几个标签，
        //     而上面整段按钮扫描只扫 `dialogRoot()` 里那一坨。
        //     于是现场是"页面上明明有个「关闭」按钮，快照里却查无此物"，
        //     而这份快照存在的唯一目的就是告诉我们页面上有什么。
        //
        //   ★ 它现在的身份是**成功回执**（见到它 = YouTube 已受理这次发布），
        //     不是"卡住的东西"。回执当然也得能照出来 ——
        //     下次它换个标签名出现时，我们还得靠这份快照，不能靠猜。
        const sp = stillProcessingDialog();
        lines.push('「视频还在处理」回执对话框：'
            + (sp ? '**在**（' + tagOf(sp) + '）' : '不在'));
        if (sp) {
            const inSp = function (node) {
                let cur = node;
                let d = 0;
                while (cur && d < 200) {
                    if (cur === sp) return true;
                    cur = ancestorOf(cur);
                    d += 1;
                }
                return false;
            };
            const spSeen = [];
            const spBtns = [];
            for (const n of safeDeepAll('button, ytcp-button, paper-button, '
                + 'tp-yt-paper-button, a, div[role="button"]')) {
                if (isOurs(n)) continue;
                if (!inSp(n)) continue;          // ★ 只要**它内部**的
                const t = String(n.innerText || n.textContent || '')
                    .trim().replace(/\s+/g, ' ');
                if (!t || t.length > 40 || spSeen.indexOf(t) >= 0) continue;
                spSeen.push(t);
                spBtns.push('    ' + (isVisible(n) ? '·' : '×')
                    + (isDisabled(n) ? '[禁用]' : '')
                    + ' 「' + t + '」'
                    + (n.id ? '  #' + n.id : ''));
            }
            lines.push('  它里面的按钮（' + spBtns.length + '）：'
                + (spBtns.length ? '' : ' 一个都没读到'));
            lines.push.apply(lines, spBtns.slice(0, 20));
            lines.push('  ★ 按 3.2.18 的判据：见到它就是**发布已受理**，'
                + '点它的「关闭」→ 回「内容」页 → 传下一条。'
                + '快照里没读到「关闭」的话，看下一行的实情。');
        }

        for (const line of lines) log(line, 'info');
        return lines.join('\n');
    }

    /** deepQueryAll 的不会抛版本（dump 时页面状态可能很怪）。 */
    function safeDeepAll(selector) {
        try { return deepQueryAll(selector); } catch (e) { return []; }
    }

    /**
     * 把一段文本放进剪贴板。返回一句"是怎么放进去的"，用来打日志。
     *
     * ★ 为什么不用 GM_setClipboard：那要新加一条 @grant。改 @grant 会让
     *   油猴在更新时弹出权限提示、甚至需要重新授权 —— 为了复制一段文本
     *   去打扰用户不值得。navigator.clipboard 在**用户点击**的回调里
     *   属于"有手势"的场景，浏览器允许，够用了。
     *
     * ★ 失败必须说出来。剪贴板写入是**静默失败**的典型：
     *   没权限就直接 reject，或者 execCommand 返回 false，
     *   而用户面对的是一个"看起来点了、但粘出来还是旧内容"的按钮 ——
     *   那比报错更难查。所以返回 true/false，由调用方如实报。
     */
    function copyText(text) {
        const s = String(text || '');
        const fallback = function () {
            // 老办法：造一个看不见的 textarea，选中，execCommand('copy')。
            // 在这个场景里它有效，而且不需要任何权限声明。
            return new Promise(function (resolve, reject) {
                try {
                    const ta = document.createElement('textarea');
                    ta.value = s;
                    ta.setAttribute('readonly', '');
                    ta.style.position = 'fixed';
                    ta.style.top = '-1000px';
                    ta.style.opacity = '0';
                    document.body.appendChild(ta);
                    ta.select();
                    ta.setSelectionRange(0, s.length);
                    const ok = document.execCommand('copy');
                    document.body.removeChild(ta);
                    ok ? resolve(true) : reject(new Error('execCommand 返回 false'));
                } catch (e) {
                    reject(e);
                }
            });
        };

        if (navigator.clipboard && navigator.clipboard.writeText) {
            return navigator.clipboard.writeText(s)
                .then(function () { return true; })
                .catch(fallback)
                .catch(function () { return false; });
        }
        return fallback().catch(function () { return false; });
    }

    /**
     * 中间几步没有要填的，一路「下一步」过去。次数不写死，点不动了就停。
     *
     * ★ 加"卡住了"的判断，是因为上一版在这里**沉默**：
     *   受众没选上时 YouTube 会拒绝前进，但脚本照点不误，然后下一步
     *   报"等不到可见性选项"—— 日志把真正的原因（上一步没填完）盖掉了，
     *   看起来像"可见性文字配错了"，容易往错的方向查。
     */
    async function clickNextUntilDone() {
        let hops = 0;
        let stuck = 0;
        let lastMark = dialogStepMark();

        for (let i = 0; i < 6; i += 1) {
            const next = findByText(CONFIG.yt.next_texts);
            if (!next) break;

            next.click();
            hops += 1;
            await sleep(CONFIG.step_pause * 2);

            const mark = dialogStepMark();
            if (mark && mark === lastMark) {
                stuck += 1;
                if (stuck >= 2) {
                    throw StepError(
                        '连点两次「下一步」对话框都没动 —— 这一步有必填项没填。'
                        + '最常见的是受众声明（「不是给小朋友看的」）。'
                        + '看一眼页面上那行红色提示写的是什么，照着改，'
                        + '或者先手动把这一步走完。',
                        'blocked'
                    );
                }
            } else {
                stuck = 0;
                lastMark = mark;
            }
        }
        if (hops) log(`  点了 ${hops} 次「下一步」`, 'ok');
        return hops;
    }

    async function setVisibility(visibility) {
        const texts = CONFIG.yt.visibility_texts[visibility] || [];
        if (!texts.length) throw StepError('不认识的可见性：' + visibility, 'precheck');

        const hit = await waitFor(function () {
            const node = findControl(texts);
            if (!node) return null;
            const ctl = enclosingControlStrict(node);
            // ★★ 只有能落到**控件**的命中才算数。
            //   18:35 真机：findControl 命中了 `p#visibility-title`（块标题，
            //   文字里含「公开」），而它周围没有任何 radio —— 于是"找到了"
            //   变成了"点在标题上"，四个选项一个都没勾，日志却写「可见性：public」。
            return ctl ? { node: node, control: ctl } : null;
        }, CONFIG.wait_timeout);

        if (!hit) {
            // 再探一次，把"找不到"和"找到但不是控件"分开报 —— 这两种原因的
            // 修法完全不同，混成一句话等于没说。
            const loose = findControl(texts);
            if (loose) {
                log('  ✕ 找到了「' + texts.join(' / ') + '」的文字，但它不是可点的控件：'
                    + describeNode(loose), 'error');
                dumpDialog('可见性命中了非控件');
                throw StepError(
                    '可见性「' + visibility + '」只匹配到了非控件节点（'
                    + describeNode(loose) + '）—— 它多半是这一块的标题或说明文字，'
                    + '点上去不会有任何选项被选中。真正的单选项在页面上另有其节点，'
                    + '上面那份快照的「单/多选项」一段列出了它们。',
                    'verify'
                );
            }
            throw StepError(
                `等不到可见性选项「${visibility}」（找的是：${texts.join(' / ')}）。`
                + '改 CONFIG.yt.visibility_texts。',
                'notfound'
            );
        }
        // ★★ 点完**必须回读**。真机上这里是静默失败的重灾区：
        //    点了、日志写了「可见性：unlisted」，而快照里四个选项一个都没勾
        //    （`[ ] 「私享」 [ ] 「不公开列出」 [ ] 「公开」`）。
        //    后果不止是"没选上"：后面点「保存」会被 YouTube 拒绝（这一项必填），
        //    对话框停在原地 —— 而脚本已经写下「✓ 完成」。
        // ★★ 先往上找到**控件本体**再动手：拿文字节点去点、去读状态，
        //    两件事都不成立（见 enclosingControl 的注释）。
        const control = hit.control;
        log('  可见性选项命中的是 ' + describeNode(hit.node) + '（控件：'
            + describeNode(control) + '）');
        const st = await clickControlUntilChecked(control);
        const tried = triedList(control);

        if (st === false) {
            log('  ✕ 点了「' + texts.join(' / ') + '」但一直没选中，点的是 '
                + tagOf(control), 'error');
            log('    试过的手法（都失败了）：' + tried, 'error');
            dumpDialog('可见性点了没选中');
            throw StepError(
                '点了可见性「' + visibility + '」但选项一直没变成选中状态 —— '
                + 'YouTube 没认这次点击。'
                + '试过的手法全失败了：' + tried + '。'
                + '★ 这说明"触发方式"这条路走到头了 —— 下一步该看的是：'
                + '① 这个 radio 是不是被别的元素盖住/被禁用；'
                + '② 单选组是不是另有一个真正接管的父节点；'
                + '③ 有没有 iframe / 跨文档的边界。'
                + '快照的「单/多选项」一段能看到它们当前的结构。',
                'verify'
            );
        }
        if (st === null) {
            log('  ⚠ 可见性点过了，但读不到选中状态（这个版本没写 aria-checked），'
                + '没法回读确认。', 'warn');
        }
        log('  可见性：' + visibility, 'ok');

        // 可见性选完，YouTube 会多出一个可展开的「排期」区。
        // 不碰它的话，选了公开之后视频其实还停在待排期状态。
        await settleSchedule();
    }

    /**
     * 把「排期」设成最近 / 立即。
     *
     * ★ 找不到就静默跳过，**不报错** —— 排期是选填的，而且它长什么样
     *   各家账号的界面不完全一样（有的账号直接没有这个区）。
     *   为了一个选填项让整批停下，代价比收益大。
     */
    /**
     * 这条视频是不是 **Short**？（看对话框里那个链接锚点）
     *
     * ★★★ 3.2.17 新增。理由：11:19 真机快照里
     *
     *     · 「https://youtube.com/shorts/r9-1c8lahSc」  #video-link
     *
     *   `scanAnchoredVideoUrl` 早就认这个锚点了，只是没人拿它问过
     *   "这是不是 Short"。
     *
     * ★ 为什么这件事要紧：**YouTube 不给 Shorts 提供排期。**
     *   于是"公开范围"这一步**根本没有排期那一组 radio** ——
     *   而脚本连着两次（10:35、11:05）把"找不到排期选项"当成**故障**报出来，
     *   还把它写进了"这一步之前没做干净的地方"。等于**拿一个不存在的选项
     *   当失败原因**，把排查方向指到了页面上不存在的东西上。
     *
     * ★ 返回三态，别用真假两态：
     *     true  = 确认是 Short
     *     false = 确认不是 Short（读到 /watch?v= 或长短链接）
     *     null  = **读不到**（链接还没渲染出来）—— 这时**不许**下任何结论，
     *             只能按"没看到排期选项"如实说，不能说"因为它是 Short"。
     *   ★ 三态的理由：`null` 被当成 `false` 时会去点不存在的东西，
     *     被当成 `true` 时会**静默跳过**一个本该设的排期 —— 两边都错。
     */
    function detectShortVideo() {
        // ★★ 这里**故意不包 try/catch**。
        //
        //   我第一版写成了：
        //       try { hit = scanAnchoredVideoUrl(dialogRoot()); } catch (e) { hit = null; }
        //   结果测试里它一直返回 null，查了半天 —— 真因是测试环境**少挂了**
        //   `scanAnchoredVideoUrl`，ReferenceError 被那个 catch 吞掉，
        //   变成了"读不到链接"这个**看起来完全合理**的返回值。
        //
        //   ★ 这正是本项目反复栽的那个坑：**把"我出错了"伪装成"页面上没有"**。
        //     被吞掉的异常永远不会出现在日志里，而返回值还讲得通。
        //
        //   ★ 而且这里根本不需要那道 catch：`scanAnchoredVideoUrl` 和
        //     `scanForVideoUrl` 自己内部已经把 DOM 访问包好了
        //     （`try { all = deepQueryAll(...) } catch (e) { return null; }`），
        //     `dialogRoot()` 全程别处也在直接调。**重复的防御只会掩盖 bug。**
        let hit = scanAnchoredVideoUrl(dialogRoot());
        if (!hit) hit = scanForVideoUrl(dialogRoot());
        if (!hit) return null;

        // ★ 用**链接原文**判，不用 id —— /shorts/ 和 /watch?v= 的区别
        //   只在 URL 形态里。拿不到原文就返回 null（不猜）。
        const raw = String(hit.raw || hit.url || hit.href || '');
        if (!raw) return null;
        if (/\/shorts\//i.test(raw)) return true;
        if (/\/watch\?/i.test(raw) || /youtu\.be\//i.test(raw)) return false;
        return null;
    }

    /**
     * 排期（发布时间）那一组选项。
     *
     * ★★★ 3.2.17 的**重大修正**：找不到它**不再是错误**。
     *
     *   11:19 真机快照里，「公开范围」这一步的"单/多选项"**一共只有 4 个**：
     *       全选 / 私享 / 不公开列出 / 公开
     *   —— 排期那一组**压根不在 DOM 里**，受众那组也不在。
     *   而脚本连着两次把这件事报成 ⚠，还写进了"没做干净"清单。
     *
     *   真正的原因（用户确认 + 快照佐证）：**这是 Short**，
     *   YouTube **不给 Shorts 排期** —— 默认就是立即发布，本来就不需要选。
     *
     *   ★ 所以现在的行为：
     *     · 是 Short（或读不到是不是、但确实没有这组选项）→ **info 说一句就跳过**
     *     · 有这组选项 → 点「立即发布」（找不到就点「安排时间」兜底）
     *     · 点了但没选中 → **这才是 warn**（真的没做干净）
     *
     *   ★ 为什么必须把它从 warn 降下来：`troublesSince` 是靠扫 warn/error
     *     行来回答"这一步之前哪儿没做干净"的。留着 warn，
     *     就是在**用自己的无能为力伪造失败原因** —— 那 4 条里 3 条是排期，
     *     而排期根本不是问题所在。**错误信息比没有信息更糟。**
     *
     * ★ 另一个必须保留的语义：**「安排时间」不是"要排期"的意思**。
     *   选完可见性后，这一组按钮**不点的话底部「发布」就是禁用的**
     *   （运营 2026-09-16 原话）。所以只要**有**这组选项，就必须点一个 ——
     *   「立即发布」优先（我们要的就是立即发布），「安排时间」只做兜底。
     */
    async function settleSchedule() {
        const texts = CONFIG.yt.schedule_texts || [];
        if (!texts.length) return;

        // ★ 先把滚动区拨一遍再等。
        //   排期区常常在对话框滚动区的下半部分，不滚到那儿**根本不渲染**。
        //   （真机 10:35 快照里「可滚容器：0 个」，所以这一次多半是空转 ——
        //    但它是另一类页面结构的兜底，成本只有一轮，而且 "0 个可滚容器"
        //    这句诊断本身就是有用的信息。）
        //   传 `() => null` 是为了**强制**它滚一遍：withScrollSweep 只在
        //   "一个都没找到"时才滚，而我这里要的就是"无论找不找得到都滚"。
        //   ★ 3.2.17：第三参 'info' —— 排期这一区在 Short 上本来就不存在，
        //     滚不到容器是**预期**，不是故障。见 withScrollSweep 的注释。
        await withScrollSweep(function () { return null; }, '排期', 'info');

        // ★★★ 3.2.15：这里必须**等**，不能只查一次。
        //
        //   10:35 真机：选完「公开」到点「发布」之间只隔了 **1 秒**，
        //   而排期区是**异步渲染**的 —— 那一刻页面上还只有标题
        //   `p#visibility-title`（「…可以立即发布或安排时间」），
        //   真正的「立即发布 / 安排时间」两个 radio 还没出来。
        //
        //   旧写法只查一次（withScrollSweep），命中标题就放弃了 ——
        //   然后立刻去点「发布」，而排期没选 → `#done-button` 是**禁用**的
        //   → 点了毫无反应 → 报"YouTube 拒绝了这次保存"。
        //
        //   ★ 这一串的因果是**一条链**，但在日志里被拆成了三句看着无关的话：
        //       ⚠ 排期：…不是控件——跳过            （以为只是"没设排期"）
        //       ✕ 点了「发布」但对话框没动            （以为 YouTube 拒绝）
        //       （最可能是必填项没选上：公开范围/受众声明）  ← **这两项其实都成功了**
        //   真相是：**排期没点上 = 发布按钮禁用 = 点了当然没动**。
        //
        //   ★ 判据和 `setVisibility` 用同一套：等一个"能**落到真控件**"的命中。
        //     "命中了但不是控件"不算数 —— 那种命中在排期区渲染出来之前必然出现。
        //
        // ★★★ 3.2.18：**先判一次是不是 Short，是就把等待窗口压到 2 秒。**
        //
        //   运营真机实测：Short 上排期这一组**永远不出现**，
        //   而这里无条件等 `wait_timeout`（15 秒）——
        //   18 条 × 15 秒 ≈ **4.5 分钟纯白等**，而且每条都要等满才继续。
        //
        //   ★ 但不能"确认是 Short 就一秒不等、直接 return"：
        //     `detectShortVideo()` 只证明了"链接是 /shorts/ 形态"，
        //     万一这次 YouTube 真给了排期区，跳过的后果是
        //     **完成按钮禁用 → 点了没反应 → 整条失败**。
        //     所以是**缩短窗口**，不是取消等待：
        //     渲染出来了就照点（`hit` 有值，下面走的还是原来那条路），
        //     出不来才跳过。省时间，但一点风险都不多担。
        //
        //   ★ 只在 `=== true` 时缩窗口。`null`（链接还没渲染出来）
        //     必须按原样等满 —— 那是"读不到"，不是"是 Short"。
        const isShort = detectShortVideo() === true;
        const probeMs = isShort
            ? (Number(CONFIG.yt.short_schedule_probe_ms) || 2000)
            : CONFIG.wait_timeout;

        if (isShort) {
            log('  排期：这条是 **Short**（对话框里的链接是 /shorts/ 形态）—— '
                + 'YouTube 不给 Shorts 排期，所以把等待窗口从 '
                + ((Number(CONFIG.wait_timeout) || 0) / 1000).toFixed(1) + ' 秒压到 '
                + (probeMs / 1000).toFixed(1) + ' 秒'
                + '（万一这次真有这组选项，也还来得及点上）。', 'info');
        }

        const hit = await waitFor(function () {
            const node = findControl(texts);
            if (!node) return null;
            const ctl = enclosingControlStrict(node);
            return ctl ? { node: node, control: ctl } : null;
        }, probeMs);

        // ★ 三条分支都必须**留下话**。原来这里是两句 `return` ——
        //   "没找到"和"已经是了"都不打日志，调用方根本看不出排期到底设没设，
        //   而真机上「排期：没找到任何能滚的容器」后面就是一片空白，
        //   读日志的人只会以为"滚过了、大概设好了"。
        if (!hit) {
            // ★★★ 3.2.17：这里从 **warn 降成 info** —— 而且必须说清是"没有这组选项"
            //   还是"有但我们没找到"。原因见函数头那段大注释：
            //   **排期选项在 Short 上压根不存在**，把它报成 ⚠ 会顺手写进
            //   "这一步之前没做干净的地方"，等于拿一个不存在的选项当失败原因。
            //
            //   ★ 但也不能"干脆不打日志" —— 那会退回到"看不出排期到底设没设"
            //     的老毛病。所以照打，只是**如实**打，且降级。
            const short = detectShortVideo();
            const loose = findControl(texts);

            if (loose) {
                // "找到了但落不到控件上" —— Short 的标题里同样含
                //   「可以立即发布或安排时间」，所以命中标题在 Short 上是
                //   **预期现象**。这里照实说，但级别跟着下面一起定。
                log('  排期：命中的 ' + describeNode(loose) + ' 是标题/说明文字，'
                    + '不是能点的控件 —— 跳过（不点它）。', 'info');
            }

            // ★★ 三种情况**级别不同**，不能一锅端：
            //
            //   · 是 Short      → **info**。YouTube 不给 Shorts 排期，默认立即发布。
            //                     报 ⚠ 就是拿一个不存在的选项当失败原因。
            //   · 读不到链接    → **info**。没证据，不许下结论（见 detectShortVideo 三态）。
            //   · 是普通视频    → **warn**。它有排期区，该渲染却没渲染，
            //                     而且**后果真实存在**：排期没设 → 发布按钮禁用 →
            //                     点它不会有任何反应。这一档必须留着 ——
            //                     它是"两道门"里的第一道。
            if (short === false) {
                log('  ⚠ 排期：这一步**没有排期选项**（找的是：' + texts.join(' / ') + '）'
                    + ' —— 这条是普通视频（链接是 /watch），正常应该有两组选项；'
                    + '没渲染出来多半是页面还没就绪。'
                    + '★★ 排期没设的话，最下面那个保存/发布按钮是**禁用**的，'
                    + '点它不会有任何反应。', 'warn');
                return;
            }

            log('  排期：这一步**没有排期选项**（找的是：' + texts.join(' / ') + '）'
                + (short === true
                    ? (isShort
                        // ★ 上面那条已经把"是 Short、为什么没有排期"说过了，
                        //   这里就不再复述一遍 —— 同一件事说两次，
                        //   只会让真正的信息埋进重复里。
                        ? ' —— 和上面那条判断一致：**是 Short，跳过是对的**。'
                        : ' —— **这条是 Short，YouTube 本来就不给 Shorts 排期**，'
                          + '默认就是立即发布，跳过是对的。')
                    : ' —— 读不到视频链接，**没法确认**它是不是 Short；'
                      + '但页面上确实没有这组选项，按"没有"处理。')
                + ' ★ 跳过它**不是**失败，也不会进"没做干净"清单。', 'info');
            return;
        }

        const control = hit.control;
        log('  排期选项命中的是 ' + describeNode(hit.node) + '（控件：'
            + describeNode(control) + '）');

        if (checkedState(control) === true) {
            log('  排期：已经选好了（' + tagOf(control) + '），不用再动', 'info');
            return;
        }

        // ★★ 命中的如果不是**真控件**（而是标题、说明文字之类），就别点 ——
        //    真机上正是在这里点到了「公开范围」那一块的**标题** `p#visibility-title`
        //    （标题里含「不公开列出」），点完什么也没发生，
        //    而日志写的是「排期：选上了（p#visibility-title…）」。
        //    ★ 3.2.15：这里现在理论上到不了了（waitFor 那个判据已经要求
        //      能落到 enclosingControlStrict），但**保留**它 ——
        //      判据是两层，任何一层单独失守都不该让脚本去点标题。
        if (!looksLikeControl(control)) {
            log('  ⚠ 排期：文字命中了 ' + tagOf(control) + '，但它**不是控件**'
                + '（多半是标题/说明文字）—— 不点它，跳过。', 'warn');
            return;
        }

        const st = await clickControlUntilChecked(control);
        if (st === true) {
            log('  排期：选上了（' + tagOf(control) + '）—— 时间用默认的，不碰。', 'ok');
            return;
        }
        if (st === false) {
            log('  ⚠ 排期选项点了但没选中（点的是 ' + tagOf(control) + '）—— **没设排期**。'
                + '这一步不设的话，最下面那个保存/发布按钮是**禁用**的。', 'warn');
            return;
        }
        // ★★ null = 读不到状态。**不能**当成成功 ——
        //    这正是上一版写「排期：选上了（p#visibility-title…）」的地方：
        //    null 从 false 那条判断旁边溜过去了，直接落到"成功"那句。
        log('  ⚠ 排期点过了（' + tagOf(control) + '），但读不到选中状态，'
            + '**没法确认设上了**。后面靠"完成按钮是不是禁用的"来兜底。', 'warn');
    }

    /**
     * 拿 videoId。三条路，从最可靠到最不可靠。
     */
    /**
     * 已知锚点：优先按"那个链接元素自己的名字"去找。
     *
     * 真机快照（2026-09-16，中文界面）里那个链接元素长这样：
     *
     *     · 「https://youtube.com/shorts/2Tm6_KCvdrI」  #video-link
     *
     * ★ 这是**实测到的 id**，不是猜的。所以这里可以比通用扫描**宽松**：
     *   允许"链接：https://…"这种文字里带标签字的写法
     *   （通用扫描那一路必须卡死成"整段就是 URL"，理由见 scanForVideoUrl）。
     *
     * ★ 为什么明知道通用扫描能读到它、还要多这一路：
     *   运营说「链接和地址栏可以在发布后弹出框里复制」——
     *   也就是**发布之后那个弹框里还会再出现一次**。那个弹框的文案
     *   大概率是「链接：https://…」这种带前缀的写法，
     *   而"整段就是 URL"的判据在那时会不命中。
     *   锚点这一路把范围收在"名字里带 video-link 的元素"上，就敢宽松读。
     */
    const VIDEO_LINK_HINTS = /video-link|video-url/;

    function scanAnchoredVideoUrl(scope) {
        const root = scope || dialogRoot() || document;
        let all = [];
        try { all = deepQueryAll('*', root); } catch (e) { return null; }
        for (const n of all) {
            if (!n) continue;
            const hint = (String(n.id || '') + ' '
                + String((n.getAttribute && n.getAttribute('class')) || '')).toLowerCase();
            if (!VIDEO_LINK_HINTS.test(hint)) continue;
            const raw = String((n.href || n.value || n.textContent || '')).trim();
            if (!raw) continue;
            const id = extractVideoId(raw);       // ★ 这一路允许"文字里含链接"
            if (id) return { id: id, how: '链接锚点', raw: raw };
        }
        return null;
    }

    /**
     * 在一个范围里找视频链接。返回 { id, how, raw } 或 null。
     *
     * ★★ 这个函数存在的理由，是一次真机失败：脚本报
     *   「视频已经传上去了，但页面上找不到视频 id」——
     *   **而快照里那条链接就明摆着**：
     *       · 「https://youtube.com/shorts/2Tm6_KCvdrI」  #video-link
     *
     *   原因很朴素：原来的扫描只读 `n.href || n.value`，**从来不读文字**。
     *   而 Studio 把一个按钮样的元素当链接用，**文字就是那条 URL** ——
     *   它不是带 `href` 的 `<a>`，于是 `a[href]` 抓不到、`span/div` 那两路
     *   又因为只读 href 而空手而归。链接在页面上，代码看不见它。
     *
     * ★ 所以两种载体都读：
     *     · **属性**：`<a href>`、`<input value>`（"复制链接"那种只读输入框）
     *     · **文字**：整段文字本身就是一条 URL 的节点
     *
     * ★★ 文字这一路的判据必须**很紧**：`^https?://…youtu` ——
     *   整段文字本身就得是 URL。不这么卡的话，随便一层容器 div 的文字里
     *   都能"包含"一条链接，而**内容列表就在对话框后面**，
     *   那里每条视频都有自己的地址 —— 会稳稳地抓到**别的视频**的 id，
     *   然后一路顺利地把 CSL 建到错的视频上。
     *   这是"宁可找不到"和"找到了但是错的"之间的区别。
     */
    function scanForVideoUrl(scope) {
        const roots = scope ? collectRoots(scope) : cachedRoots();
        for (const root of roots) {
            let nodes;
            try {
                // ★ 这个清单必须覆盖 `#video-link` 可能的**每一种**外壳。
                //   真机快照里它被归在「按钮」那一类，而按钮那一类是
                //   `button / ytcp-button / paper-button / tp-yt-paper-button /
                //   a / div[role=button]` —— 少写一个，就是"链接在页面上、
                //   代码看不见它"的翻版。（第一版只写了 `a[href], input,
                //   span, div`，测试立刻抓出来了：`ytcp-button` 不在里面。）
                nodes = root.querySelectorAll('a[href], input, button, '
                    + 'ytcp-button, paper-button, tp-yt-paper-button, '
                    + '[role="button"], span, div');
            } catch (e) { continue; }
            for (const n of nodes) {
                const attr = String((n.href || n.value || '')).trim();
                if (attr && /youtu/i.test(attr)) {
                    const id = extractVideoId(attr);
                    if (id) return { id: id, how: '链接属性', raw: attr };
                }

                // ★ 用 `textContent` 而**不是** `innerText`：后者每次读都会
                //   触发布局计算，在这个循环里（几百上千个节点）会明显卡页面。
                //   代价是 textContent 会把隐藏文字也算进来 —— 但下一行的
                //   判据把这条路卡得很死，多出来的字只是让这一条**不命中**，
                //   不会误命中。
                const text = String((n.textContent || '')).trim();
                if (!text || text.length > 120) continue;   // URL 很短，长文字直接放掉
                if (!/^https?:\/\/\S*youtu/i.test(text)) continue;
                const id2 = extractVideoId(text);
                if (id2) return { id: id2, how: '页面上的文字', raw: text };
            }
        }
        return null;
    }

    /**
     * 自己把 Studio 的上传对话框打开。
     *
     * ★★ 真机上第二次点「开始上传」就是这个情况：上一轮的对话框已经关了，
     *    页面上只剩一个"缩略图用的" file input（`accept=image/jpeg,image/png`）。
     *    而「上传视频」那个按钮**就在页面上** —— 真机快照里明明白白一行：
     *        · 「上传视频」  #upload-button
     *    脚本自己能点，原来却只报一句"先手动打开 Studio 的上传页"，把一件
     *    自己能做的事推给用户，然后停下。手动步骤越少，重试越可能成功。
     *
     * ★ 只在"确实没找到上传 input"时才调；点完由调用方再等一轮。
     *   找不到按钮就返回 null，调用方照旧报那句"先手动打开"。
     */
    function openUploadDialog() {
        // ① 实测见过的 id
        //
        // ★ 必须**在这里就把可见性判掉**，不能"先赋值、不可见再去按文字找" ——
        //   后者忘了把 btn 清空的话，兜底那一路找不到时 btn 仍然指着
        //   那个隐藏节点，最后还是点了它。
        //   （这个漏洞是测试抓出来的：一条"按钮不可见时不许点"的用例红了。）
        let btn = null;
        try {
            const byId = deepQueryOne('#upload-button');
            if (byId && isVisible(byId) && !isOurs(byId)) btn = byId;
        } catch (e) { btn = null; }

        // ② 按文字找（中英文都认）
        if (!btn) {
            const hit = findByTextInfo(['上传视频', '上传 video', 'Upload video', 'Upload']);
            if (hit && hit.node && isVisible(hit.node) && !isOurs(hit.node)) btn = hit.node;
        }

        // ★ 找不到就返回 null —— 绝不瞎点页面上别的按钮。
        if (!btn) return null;
        const label = String((btn.innerText || btn.textContent || ''))
            .trim().slice(0, 20) || '上传视频';
        btn.click();
        return label;
    }

    /**
     * 每一条开始之前，先把页面**复位到"干净的待上传状态"**。
     *
     * ★★★ 3.2.17 新增。这条的存在理由是一次真机失败（11:19 那批的第 2 条）：
     *
     *     11:19:41  [1/18] …
     *     11:19:56    没找到上传 input → 点了「上传视频」，等对话框起来再找一轮…
     *     11:20:11    页面上的 file input：页面上一个 input[type=file] 都没有
     *
     *   原因很朴素：**上一条的上传对话框没关掉**（它一直开着、是个模态），
     *   残留下来的它挡在「上传视频」上 —— 点下去当然没反应，
     *   新对话框起不来，于是页面上一个 file input 都没有。
     *
     *   ★ 上一版只做了**一半**：`uploadOneVideo` 里"找不到 input 就去点上传视频"
     *     是**补救**（事后），而这里是**预防**（事前）。批量跑的时候，
     *     补救是来不及的 —— 模态只要还在，点几次都一样。
     *
     * ★ 三步，顺序不能换：
     *     ① 关掉残留的上传对话框（等到它**真的消失**）
     *     ② 回到频道内容页（Studio 视频列表）
     *     ③ 让调用方那边的 `findFileInput` 再找一次（找不到自然去点「上传视频」）
     *
     * ★ 为什么"关掉"要**等**：点「关闭」到它真的从 DOM 里消失之间，
     *   有一个动画+卸载的过程。立刻去点「上传视频」会被那层正在淡出的
     *   遮罩吃掉点击 —— 表现就是"点了没反应"，和没关一模一样。
     *
     * ★ 失败不抛错：复位没做干净时，后面的 `openUploadDialog` 兜底还在。
     *   这里报一句 warn 让它出现在"没做干净"清单里，比直接停整批划算。
     */
    /**
     * 那个「视频还在处理」对话框 —— 返回**节点**（不是标签名）。
     *
     * ★★★★ 3.2.18：它的语义在 12:11 真机上**整个反转了**。
     *
     *   3.2.17 把它当成"忙，继续等"的证据，于是等满 30 秒后报
     *   「YouTube 没接受这次保存」。**又错了** ——
     *   用户 12:13:48 的确认是：
     *     · 那条视频在内容列表里显示 **「已发布」**
     *     · 这个对话框上有一个 **「关闭」**
     *     · 关掉它之后**回内容页，接着传下一条**
     *
     *   → 所以它**不是障碍，是回执**：
     *
     *       点「发布」→ Studio 弹「视频还在处理」→ **发布已提交**
     *       → 点「关闭」→ 回内容页 → 传下一条
     *
     *   ★ 这个区别决定了一切：
     *     · 当"障碍" → 死等它自己消失 → 白等 30 秒、然后**误报失败**
     *     · 当"回执" → **看到它就认定成功**，点关闭、立刻进下一条
     *   转码/送审在**服务端**继续，根本不需要我们在这儿等。
     *
     *   ★ 为什么误报的代价更大：报失败 → 用户去重跑这一条 →
     *     而它**已经发布出去了** → **重复投稿**。
     *     反过来（万一其实没发成）留的是草稿，用户手动点一下就行，不亏。
     */
    function stillProcessingDialog() {
        const tags = ['ytcp-uploads-still-processing-dialog',
            'ytcp-uploads-processing-dialog',
            'ytcp-uploads-progress-dialog'];
        for (const t of tags) {
            let n = null;
            try { n = deepQueryOne(t); } catch (e) { n = null; }
            if (n && isVisible(n)) return n;
        }
        return null;
    }

    /** 只报"在不在 + 是哪个标签"，给日志用。 */
    function stillProcessingVisible() {
        const d = stillProcessingDialog();
        return d ? tagOf(d) : null;
    }

    /**
     * 关掉「视频还在处理」这个回执对话框。
     *
     * 返回 true = 关掉了（或本来就没有）。
     * ★ 失败**不抛错** —— 关不掉最多留个挡路的模态，
     *   下一步 `ensureCleanUploadState` 还会再试一次，
     *   而且「上传视频」按钮也可能照样点得动。
     */
    async function closeStillProcessing() {
        const dlg = stillProcessingDialog();
        if (!dlg) return true;

        const label = closeUploadDialog(dlg);
        const gone = await waitFor(function () {
            return stillProcessingDialog() ? null : true;
        }, 8000);

        if (gone) {
            log('  已关掉「视频还在处理」对话框（点了「' + label + '」）。', 'ok');
            return true;
        }
        log('  ⚠ 点了「' + label + '」，但「视频还在处理」对话框还在 —— '
            + '它挡着的话下一条会点不动「上传视频」。', 'warn');
        return false;
    }

    /**
     * 现在是不是在「内容」（视频列表）页？
     *
     * ★ 判据用**内容列表那一块在不在**，不用 URL：
     *   Studio 是 SPA，URL 变了好几段内容还是同一个页面，
     *   按 URL 判会得到"已经在了"但实际没渲染出来。
     */
    function onContentPage() {
        try { return !!deepQueryOne('ytcp-video-section-content'); } catch (e) { return false; }
    }

    /**
     * 回到「内容」页 —— 批量每一条开始之前要做的事。
     *
     * ★★★★ 3.2.18 新增。运营原话：
     *   「然后你应该**跳转到视频那个界面**接着自动上传下一个视频」
     *
     * ★★ 必须点**侧边栏的「内容」**，绝不能用 `location.href = …`：
     *   这是一个 UserScript，**整页重载会把脚本整个重启** ——
     *   `ytState.running` / 队列 / 这一次的进度**全部丢失**，
     *   表现是"跑到第 3 条页面刷新了一下，然后就再也没动静了"。
     *   点侧边栏走的是 SPA 路由，**不重载**。
     *
     * ★ 找不到导航按钮时**只 warn、不抛错**：回不去内容页多半不影响
     *   下一条上传（`#upload-button` 在顶栏一直在），
     *   为了一个"更干净的状态"把整批停掉不划算。
     */
    async function gotoContentPage() {
        if (onContentPage()) return true;

        // ① 实测过的导航项：`#menu-item-1` = 「内容」（两份真机快照里都是它）
        let btn = null;
        try { btn = deepQueryOne('#menu-item-1'); } catch (e) { btn = null; }

        // ② 兜底：在导航抽屉里按文字找（别扫整页，整页有好几个「内容」）
        if (!btn || !isVisible(btn)) {
            let drawer = null;
            try { drawer = deepQueryOne('ytcp-navigation-drawer'); } catch (e) { drawer = null; }
            const hit = findByTextInfo(['内容', 'Content', 'Videos'], drawer || undefined);
            if (hit && hit.node && isVisible(hit.node) && !isOurs(hit.node)) btn = hit.node;
        }

        if (!btn || !isVisible(btn)) {
            log('  想回「内容」页但找不到侧边栏那项 —— 跳过。'
                + '（不影响继续上传；「上传视频」按钮在顶栏一直在）', 'warn');
            return false;
        }

        btn.click();
        const ok = await waitFor(function () {
            return onContentPage() ? true : null;
        }, 10000);

        if (ok) {
            log('  已回到「内容」页。', 'ok');
            return true;
        }
        log('  ⚠ 点了「内容」但内容列表没出现 —— 先继续（多半只是渲染慢）。', 'warn');
        return false;
    }

    async function ensureCleanUploadState() {
        // ① 「视频还在处理」回执 —— 上一条发布完留下的那个
        //    ★ 3.2.18：它是个模态，不关掉会挡住「上传视频」。
        await closeStillProcessing();

        // ② 残留的上传对话框
        let dlg = null;
        try { dlg = deepQueryOne('ytcp-uploads-dialog'); } catch (e) { dlg = null; }
        if (!dlg) try { dlg = deepQueryOne('ytcp-upload-dialog'); } catch (e) { dlg = null; }

        if (dlg && isVisible(dlg)) {
            log('  上一条的上传对话框还开着 —— 先关掉它（它是个模态，'
                + '不关掉的话会挡着「上传视频」，点了没反应）', 'info');

            const closed = closeUploadDialog(dlg);
            const gone = await waitFor(function () {
                const d = deepQueryOne('ytcp-uploads-dialog')
                    || deepQueryOne('ytcp-upload-dialog');
                return (!d || !isVisible(d)) ? true : null;
            }, 10000);

            if (gone) {
                log('  已关掉残留对话框，页面复位。', 'ok');
            } else {
                log('  ⚠ 点了关闭但对话框还在 —— 没法确认复位干净。'
                    + '后面找不到 file input 的话就是它。', 'warn');
            }
        } else {
            log('  页面是干净的（没有残留的上传对话框）。', 'info');
        }

        // ③ 回「内容」页 —— 运营要求的批量流程里这一步在"传下一条"之前
        await gotoContentPage();
    }

    /**
     * 关掉一个上传对话框。返回点了哪个（拿不到就返回 null）。
     *
     * ★ 三档，从最可靠到最兜底：
     *   ① 实测过的 id `#close-button`
     *   ② 按文字找（关闭 / 取消 / Close / Cancel）
     *   ③ **按 ESC** —— 这是最后一道，因为前两档都依赖"按钮还在/文字对得上"
     *
     * ★ 必须排除我们自己的面板：`isOurs` 挡一下，
     *   否则会去点面板上的按钮（真有这一档：`findByTextInfo` 是整页扫的）。
     */
    function closeUploadDialog(dlg) {
        // ① 实测 id
        let btn = null;
        try {
            const byId = deepQueryOne('#close-button');
            if (byId && isVisible(byId) && !isOurs(byId)) btn = byId;
        } catch (e) { btn = null; }

        // ② 按文字（限定在对话框里找，别扫整页）
        if (!btn && dlg) {
            const hit = findByTextInfo(['关闭', '取消', 'Close', 'Cancel', 'Dismiss'], dlg);
            if (hit && hit.node && isVisible(hit.node) && !isOurs(hit.node)) btn = hit.node;
        }

        if (btn) {
            const label = String(btn.innerText || btn.textContent || '')
                .trim().slice(0, 12) || 'close';
            try { btn.click(); } catch (e) { /* 下面还有 ESC 兜底 */ }
            return label;
        }

        // ③ ESC 兜底
        //
        // ★ 派到**对话框节点**上而不是 document：Studio 的对话框监听在
        //   它自己的节点上，扔给 document 有不少场景收不到。
        //   两个都发一遍，成本忽略不计。
        //   ★ 两个事件对象要**分开建**：同一个事件对象被派发两次时，
        //     `target` 还指着上一次的节点，有些实现会因此丢掉第二次。
        const sendEsc = function (node) {
            try {
                node.dispatchEvent(new KeyboardEvent('keydown', {
                    key: 'Escape', code: 'Escape', keyCode: 27, which: 27,
                    bubbles: true, composed: true,
                }));
            } catch (e) { /* 发不出去就只能靠调用方超时 */ }
        };
        if (dlg) sendEsc(dlg);
        sendEsc(document);
        return 'ESC';
    }

    /**
     * 顺手把这一条的视频 id 记在 item 上（尽力而为：不阻塞、不报错、不抛）。
     *
     * ★★ 为什么必须在**「详细信息」这一步**记：
     *
     *   1. 真机快照显示，链接在「详细信息」这一步就有值（`#video-link` =
     *      `https://youtube.com/shorts/…`）；而走到后面几步
     *      （视频元素 / 检查 / 公开范围）它**已经从 DOM 里消失**了 ——
     *      两份快照一对比就能看出来。
     *   2. 第 10 步读它的时机**最差**：刚点完「完成」，对话框正在关。
     *
     *   ★ 真机日志就是这么栽的：
     *       14:10:38  已点「继续」，可见性 unlisted
     *       14:10:55  ✕ 视频已经传上去了，但页面上找不到视频 id
     *     中间那 17 秒 = 对话框里等满 15 秒 + 整页再等 2 秒，一个都没读到。
     *     而 14:10:34 那一刻，链接就在对话框里。
     *
     * ★ 位置必须在标题回读**通过之后**：得先确认这个对话框是**这条**视频的。
     *   更早去抓有可能抓到上一轮残留的链接 —— 那是"找到但记错了"，
     *   比找不到危险得多。
     *
     * ★ 要在「详细信息」这一步之内**多调几次**：链接是随上传进度出现的，
     *   标题填完那一刻不一定就有。所以调用方在点「继续」之前会再来一次。
     */
    function rememberVideoId(item) {
        if (!item) return null;
        // ★ 已经记下了就不再读 —— 后来读到的可能已经不是这一条的了
        //   （对话框换视频、或者链接元素被复用）。
        if (item.videoId) return item.videoId;

        const hit = scanAnchoredVideoUrl(dialogRoot()) || scanForVideoUrl(dialogRoot());
        if (hit && hit.id) {
            item.videoId = hit.id;
            log('  顺手记下视频 id：' + hit.id + '（来自' + hit.how
                + '）—— 发布后如果读不到，用这个兜底', 'info');
            return hit.id;
        }
        return null;
    }

    async function resolveVideoId(item) {
        // ① 上传对话框里的链接 —— YouTube 自己生成的，最准。
        //    要**等**：链接是上传/发布完成后异步渲染出来的。
        //
        // ★ 先在**对话框里**找，找不到再退到整页。
        //   顺序有讲究：内容列表就在对话框后面，那里有别的视频的地址，
        //   缩到对话框里能先把这批干扰排除掉。
        // ★ 边跑边读，四条路，从最准到最宽：
        //   ① 名字里带 video-link 的元素（实测过的锚点，允许文字带标签）
        //   ② 对话框里按属性/文字通用扫描（文字必须"整段就是 URL"）
        //   ③ 整页同样扫一遍 —— 有些版本会把链接挂到对话框外面
        //   ④ 上传时顺手记在 item 上的那一份（见 uploadOneVideo 的 4b）
        const dlg = dialogRoot();

        let found = dlg ? await waitFor(function () {
            return scanAnchoredVideoUrl(dlg) || scanForVideoUrl(dlg);
        }, CONFIG.wait_timeout) : null;

        if (!found) {
            found = await waitFor(function () {
                return scanAnchoredVideoUrl(null) || scanForVideoUrl(null);
            }, 2000);
        }

        if (found) {
            log(`  视频 id：${found.id}（来自${found.how}：${found.raw.slice(0, 70)}）`, 'ok');
            return found.id;
        }

        // ④ 上传时顺手记在 item 上的那一份（见 uploadOneVideo 的 4b）
        //
        // ★ 放在地址栏**前面**：它是"这条视频在上传对话框里写着的"，
        //   比地址栏可靠 —— 地址栏在草稿态根本没有 id。
        // ★ 过一遍 extractVideoId 再收：这一份要陪着这条视频记进记录里，
        //   宁可这里认不出来、走下面那条路（抛错停下），
        //   也不要往记录里写一个形状不对的东西。
        const rawStash = item && item.videoId;
        const stashed = rawStash ? extractVideoId(rawStash) : null;
        if (stashed) {
            log(`  视频 id：${stashed}（来自上传时顺手记下的那一份）`, 'ok');
            return stashed;
        }
        // ★ 3.2.57：读到了、但**形状不对** —— 不报错（报错就不记账了，见下），
        //   但也**别默默扔掉**：说一句，否则"为什么没用上顺手记的那份"没人知道。
        if (rawStash && !stashed) {
            log('  · 上传时顺手记下的那份不像 id（'
                + String(rawStash).slice(0, 40) + '）—— 跳过它，继续往下找。', 'warn');
        }

        // ⑤ 地址栏。放在最后是因为它最不可靠 ——
        //    停在草稿上时地址栏是 /videos/upload，里面根本没有 id。
        const id = extractVideoId(location.href);
        if (id) {
            log(`  视频 id：${id}（来自地址栏）`, 'ok');
            return id;
        }

        // ★ 拿不到 id 不等于失败：视频其实已经传上去了，只是停在草稿里。
        //   记成 failed 会造成两件坏事：用户以为视频丢了；下次跑的时候
        //   会把这条当成"没传过"而重复上传，白扣一遍配额。
        if (!item.autoPublish) {
            log('  没发布 → 页面上没有链接。视频在草稿箱里，这是预期的。', 'warn');
            return null;
        }

        // ★★★★★ 3.2.57：**自动发布开着、却读不到 id 时，也返回 null —— 不再抛错。**
        //
        //   ★ 上面那段注释（"拿不到 id 不等于失败…记成 failed 会…重复上传"）
        //     **一直是对的**，而这段代码恰恰做成了它说要避免的事：
        //     `autoPublish` 开着时 `throw StepError` → 整条流程判失败
        //     → `runYtQueue` 的 catch **不记账** → 下次跑**再传一份**。
        //
        //   ★★ 真机 2026-09-21 的实证（这个毛病终于咬到人）：
        //     18:32 那条视频**标题和描述都填对了、也确实发布成功了**
        //     （频道 RSS 里能看到它，描述正好 758 字符 = 模板长度），
        //     但脚本在"取链接"这一步读不到 id → 抛错 → 不记账。
        //     代价三条：
        //       ① 面板上不显示"已上传"
        //       ② Play 侧不给它建 CSL（记录里根本没有它 —— 用户看到"11 个视频只建了 10 个"）
        //       ③ **下次跑会再传一份**，频道上多一条几乎一样的
        //     ★ 同一个故障 2026-09-18 也发生过（日志里就有），当时只记录没修。
        //
        //   ★★★ 判据：**"视频已经发出去了"这件事，比"有没有拿到链接"更重要。**
        //     · 没有链接  = 这条记录**不完整**（Play 侧会跳过它，而且会明说是哪几条）
        //     · 不记账    = 它下次会被**重传** —— 而这是**不可逆**的
        //     两个都是坏的，但后者更坏。所以这里选前者。
        log('  ⚠ 视频**已经传上去了**，但页面上读不到视频 id —— '
            + '**照常记账**（链接留空）。', 'warn');
        log('    ★ 为什么不报错停下：报错就**不记账**，而它已经在频道上了 —— '
            + '下次跑会把它**再传一份**（那不可逆）。', 'warn');
        log('    ★ 代价：这一条在 Play 侧**建不了 CSL**'
            + '（那边会把它列进"勾了、但没有视频链接"那一条里说清楚）。'
            + '\n    → 想要它的链接：去 Studio 打开这条视频，'
            + '用面板上的「补录」把它补进来。', 'warn');
        return null;
    }

    async function runYtQueue() {
        if (ytState.running) { log('正在跑，别重复点', 'warn'); return; }

        // ★ 3.2.53：装上"切走了/切回来"的监听（幂等，全局只装一次）。
        //   之后日志里就能看到**是哪一刻切的** —— 今天的失败日志里没有这一行，
        //   所以事后无法判定"是不是后台造成的"（见那段长注释）。
        installVisibilityWatch();

        // ★ 开工时也记一行可见性：上面那个监听只在**变化时**出声，
        //   而"一开始就是后台"（点完开始立刻切走）不会触发它。
        if (pageHiddenNow()) {
            log('★ 开工时这个标签页就在**后台** —— 整批都会在浏览器的'
                + '定时器节流下跑，容易把"慢"误报成"失败"。建议先切到前台。', 'warn');
        }


        const autoPublishRaw = UI.yt.autoPublish ? UI.yt.autoPublish.checked : true;
        const form = buildYtForm({
            visibility: UI.yt.visibility ? UI.yt.visibility.value : CONFIG.yt.default_visibility,
            autoPublish: autoPublishRaw,
        });

        const picked = pickedYtEntries();

        if (!picked.length) {
            log('一个视频都没勾。先选目录，再在上面勾要传的。', 'error');
            return;
        }

        // ── 预检：File 必须在 ──
        // 一次报完所有坏项，而不是遇到第一个才说
        const split = splitByFile(picked);
        if (split.bad.length) {
            log(`有 ${split.bad.length} 个文件的 File 对象没了，不能继续：`, 'error');
            split.bad.forEach(function (b) {
                log('  · ' + (b.item.relPath || '?') + ' —— ' + b.why, 'error');
            });
            log('  重新选一次目录再试（选目录后不要重新打开页面）。', 'error');
            return;
        }

        ytState.dryRun = UI.yt.dryRun ? UI.yt.dryRun.checked : true;

        let todo = split.good;

        // ★★★ 2026-09-20（3.2.51）：**跳过以前传过的**。
        //
        //   ★ 位置是**承重的**：必须在下面那个"超过上限"检查**之前** ——
        //     否则"勾了 189 个、其中 20 个传过了"会**先**被上限拦下，
        //     而真正要传的其实只有 169 个。先跳再判，
        //     报出来的数字才是**这一趟真正要做的事**。
        //
        //   ★★ 判据用"有没有记录"，不看有没有拿到链接 ——
        //     见 `uploadedIndex` 上面那段：宁可漏传，不可重传。
        if (ytState.skipUploaded !== false) {
            const idx = uploadedIndex();
            const up = uploadedInEntries(todo, idx);
            if (up.length) {
                todo = todo.filter(function (e) { return !isUploadedEntry(e, idx); });
                log('★ 跳过 ' + up.length + ' 个**以前传过的**'
                    + '（面板上「跳过已上传的」开着）—— 剩下 '
                    + todo.length + ' 个要传。', 'warn');
                up.slice(0, 5).forEach(function (e) {
                    const r = idx[String(e.fileName)] || {};
                    log('  · ' + e.fileName
                        + (r.url ? '   →  ' + r.url : '   （这条没拿到链接）'), 'info');
                });
                if (up.length > 5) log('  · …… 另有 ' + (up.length - 5) + ' 个', 'info');
            }
            if (!todo.length) {
                log('★ 勾上的这些**全都传过了** —— 这一趟没有要传的东西，先停下。'
                    + '\n    → 想重传：把面板上「跳过已上传的」**取消勾选**。'
                    + '\n    → 想传别的：换一批（「只勾未上传」/ 筛选框）。', 'warn');
                return;
            }
        } else if (split.good.length) {
            log('★★ 「跳过已上传的」**是关着的** —— 这次会重传以前传过的文件。'
                + '\n    ★ 重传会在频道上多出一份，而上传额度不回收。'
                + '不打算重传的话，现在把它勾回去。', 'warn');
        }

        if (ytState.dryRun) {
            todo = todo.slice(0, 1);
            log('试运行：只传队列第 1 条（面板上「试运行」还勾着）。'
                + '上传会真实占用配额，扣了不返还。', 'warn');
            log('  ★ 要跑满这一批（' + split.good.length + ' 条），'
                + '把面板上的「试运行」**取消勾选**再点开始。', 'warn');
        } else if (CONFIG.yt.max_per_run > 0
            && todo.length > CONFIG.yt.max_per_run) {
            // ★ 3.2.52：只在**明确配了上限**（> 0）时才拦。默认是 0 = 不限。
            //   报错里要给出**改哪一行**，不然读的人只能猜。
            log(`一次 ${todo.length} 个超过上限 ${CONFIG.yt.max_per_run} 个。`
                + '\n    ★ 上限是配置里 `CONFIG.yt.max_per_run` —— 改成 0 就是不限。'
                + '\n    ★ 默认（0）是**不拦**的：YouTube 自己的限额才是真闸门，'
                + '我们这边再拦一道只是多一次手动筛。'
                + '\n    → 想去掉：把那个值改成 0。', 'error');
            return;
        } else if (todo.length > 20) {
            // ★ 3.2.52：不限了，但**规模要说出来** ——
            //   189 条 × 每条 15~40 秒 = 要跑一两个小时。
            //   不说的话，人会以为卡住了。
            //   ★★ 顺便告诉他**怎么中途收手**（中止按钮就在旁边）。
            log('★ 这一趟要传 **' + todo.length + ' 个**（不限量）。'
                + '\n    一条一条来，中途随时可以按「中止」—— '
                + '它是**做完当前这条就停**，不会半路劈开。'
                + '\n    ★ 连着失败 ' + CONFIG.yt.max_fail_streak
                + ' 条会自动停下（偶发失败会跳过去继续）。', 'warn');
        }

        if (CONFIG.yt.auto_publish === false) {
            log('自动发布已被 CONFIG.yt.auto_publish = false 强制关掉 —— '
                + '这一轮不会产出 YouTube 链接。', 'warn');
        }

        // ── ★★★★★ 文案哨兵：这一批视频会挂着**哪个产品**的名发出去 ──
        //
        // ★ 为什么必须在这里（开工日志里）而不只是在测试里：
        //   文案串台是**完全静默**的 —— 不报错、照传、照扣配额，
        //   等你在频道上看到一堆挂着别家产品名的视频才发觉（已经发出去几十条）。
        //   而运营**不会跑测试**：他改完文案就点开始了。
        //   → 判据要放在**会被执行的那条路径**上（本项目的老规矩）。
        //   ★ 3.2.48 就是这么差点出事的：脚本里躺着 SLOT-02 的文案，
        //     而那天要传的是 SLOT-01 的视频。
        // ★★ 3.2.54 又反向来了一次（换回 prod-b）—— 说明这不是一次性风险，
        //   是**每次换产品都会重现**的。所以它值得一行常驻的日志。
        logCopyProduct();

        ytState.running = true;
        ytState.stop = false;
        setRunningUI(true);

        const records = loadVideos();

        // ★ 3.2.52：连着失败几条了（成功一条就清零），以及失败过哪些。
        //   ★ 后者必须在**批次结束时汇总说出来** —— 那些条目处在
        //     "可能已经传上去了、但没记账"的模糊状态，而它们是
        //     整批跑完之后**唯一需要人工看一眼**的东西。
        let failStreak = 0;
        const failedList = [];

        try {
            for (let i = 0; i < todo.length; i += 1) {
                if (ytState.stop) {
                    log('已手动停止。', 'warn');
                    break;
                }

                const item = buildQueue([todo[i]], form)[0];
                log(`[${i + 1}/${todo.length}] ${item.relPath}`, 'info');

                // ★★★ 3.2.17：每条开始之前先**复位页面**。
                //
                //   11:19 那批的第 2 条就是这么栽的：第 1 条失败后上传对话框
                //   没关掉，残留的模态挡着「上传视频」→ 点下去没反应 →
                //   新对话框起不来 → 「页面上一个 input[type=file] 都没有」。
                //   （见 ensureCleanUploadState 的注释。）
                //
                // ★ 第 1 条也走一遍：用户可能是从前一轮的残留状态点开始的。
                //   成本只有一次可见性判断，没有对话框时几乎不花时间。
                if (ytState.stop) break;
                await ensureCleanUploadState();

                try {
                    const videoId = await uploadOneVideo(item);

                    records.push({
                        relPath: item.relPath,
                        fileName: item.fileName,
                        size: item.size,
                        title: item.title,
                        videoId: videoId || null,
                        url: videoId ? canonicalVideoUrl(videoId) : null,
                        // ★ 没链接记 draft，不是 failed —— 见 resolveVideoId 的注释
                        state: videoId ? 'published' : 'draft',
                        at: new Date().toISOString(),
                    });
                    saveVideos(records);
                    // ★ 3.2.51：刚写进一条新记录 → 让"已上传"索引的缓存立刻失效。
                    //   不失效的话，面板上那条**要等 300ms 之后**才会变成"已上传"，
                    //   而人在这 300ms 里点刷新会看到旧状态 ——
                    //   然后就会怀疑"到底记上没有"。
                    forgetUploadedIndex();

                    log(videoId
                        ? `  ✓ 完成：${canonicalVideoUrl(videoId)}`
                        : `  ✓ 已上传，停在草稿（没有链接）`, 'ok');
                    // ★ 成功一条 → 连续失败计数**清零**。
                    //   不清零的话，"中间隔了 50 条成功、偶尔失败 3 次"
                    //   会被误判成"连着失败 3 条"而停下整批。
                    failStreak = 0;

                    // ★ 3.2.56：这一条**以前失败过、现在传成了** → 从待补名单划掉。
                    //   （同一批里重跑、或者上次失败这次补上的情况。）
                    //   ★ 只在这条**真的在名单里**时才出声 —— 正常情况下
                    //     它压根不在名单里，那时多打一行只会稀释日志。
                    if (removePending([item.fileName]) > 0) {
                        log('  · 已从「待补传」名单里划掉这一条（补齐了）。', 'info');
                    }

                } catch (e) {
                    failStreak += 1;
                    failedList.push(item.fileName);

                    // ★★★★★ 3.2.56：**把这条记进「待补传」名单**。
                    //
                    //   ★ 为什么要持久化（而不是像原来那样只 push 进内存数组）：
                    //     运营原话是「**记得把舍弃的那个上传**」。
                    //     而失败清单原来只在内存里 —— 批次跑完、页面一关就没了，
                    //     他手里只剩"好像有一条没传"这种印象，
                    //     既不知道是哪个文件，也不知道下次要不要特意去勾它。
                    //
                    //   ★★ 记的是**文件名**（跟"已上传"判据同一个键）——
                    //     这样面板上那个「只勾待补的」能直接按它配对。
                    //     记 relPath 没用：下次重新选目录，路径可能不一样。
                    //
                    //   ★★★ `hidden` 这一项是关键：失败时标签页在不在前台。
                    //     它不是装饰 —— 后台造成的"失败"**大概率是误判**
                    //     （页面其实好了、脚本还睡着），这两种失败的处置不同：
                    //     误判 → 切回前台重跑就行；真失败 → 得看页面。
                    //     而**这个信息在事件发生的那一刻才能采到**，
                    //     事后（比如现在补跑）标签页早切回来了，采不到。
                    const wasHidden = notePendingFailure(item, e);

                    log(`  ✕ ${e.message}`, 'error');
                    if (e && e.stack) console.error('[CSL Helper] 堆栈', e.stack);

                    // ★★★ 3.2.56：**切后台造成的失败，话要说得不一样。**
                    //
                    //   原来的文案是「它可能已经传上去了 —— 回头去 Studio 搜一下」。
                    //   那句在**前台失败**时是对的（文件早投进去了，服务端可能
                    //   已经在处理），但在**后台失败**时会把方向带偏：
                    //   后台的失败多半是脚本没看见页面好了，而不是页面没动，
                    //   让人白跑一趟 Studio。
                    if (wasHidden) {
                        log('  ★★ 这一条失败时，**标签页在后台** —— 后台会把定时器'
                            + '压到最慢 1 分钟一次，所以这**大概率是误判**'
                            + '（页面其实好了，只是脚本没轮到看一眼）。'
                            + '\n    → 先切回前台，看那个上传对话框还在不在：'
                            + '\n        · 还在 → 它可能已经传完了（停在草稿）。'
                            + '手动填个标题发布，或者点「舍弃」放弃它'
                            + '\n        · 不在 → 这条**没传成**，重跑会补上'
                            + '（它没记账，不会被"跳过已上传的"拦住）'
                            + '\n    ★ 以后跑的时候把这个标签页留在前台，'
                            + '或者用「并排窗口」让它露一部分（最小化也算后台）。', 'warn');
                    }

                    // ★★★ 3.2.52：**跳过去继续**，而不是一条失败就停整批。
                    //
                    //   ★ 旧行为（一条就停）在"链路没跑通"的时期是对的：
                    //     那时失败多半意味着**根本性的问题**，接着跑等于
                    //     拿 N 份配额去试一条没证明能用的链路。
                    //   ★★ 但真机 2026-09-20 18:10 那次证明它**现在会误伤**：
                    //     第 13 条只是**页面被拖慢**（连传 12 条之后），
                    //     前 12 条全成 —— 那种失败跳过去继续跑才对，
                    //     而旧行为让整批停在 12/189 上。
                    //
                    //   ★ 但"永不放弃"同样不行：选择器真变了的话，
                    //     **每一条都会失败**，那是把 189 条一条条试完
                    //     （每条 15~40 秒）而一条都传不上去。
                    //   → 所以判据是**连续**失败 `max_fail_streak` 次：
                    //     偶发 → 跳过继续；系统性 → 连撞几次就停。
                    const lim = CONFIG.yt.max_fail_streak;
                    if (lim > 0 && failStreak >= lim) {
                        log('★★ **连着失败 ' + failStreak + ' 条** → 停下整批。'
                            + '\n    ★ 连着失败多半不是偶发（页面慢那种是一次性的），'
                            + '而是**页面结构变了 / 登录掉了 / 权限出问题**这类'
                            + '系统性原因 —— 接着一条条试下去，每条要 15~40 秒，'
                            + '试完也一条都传不上去。'
                            + '\n    → 先去看一眼页面（或者点「诊断对话框」把结构发出来）。', 'error');
                        break;
                    }
                    log('  · 这一条**跳过去，接着传下一条**'
                        + '（连着失败 ' + failStreak + ' 条就自动停下，'
                        + '现在 ' + failStreak + '/' + lim + '）。'
                        + '\n    ★ 它已经记进**「待补传」名单**了（面板上能看到）——'
                        + '下次跑的时候点一下「只勾待补的」就能把它带上。', 'warn');
                }
            }
        } catch (e) {
            log(e.message, 'error');
            if (e && e.stack) console.error('[CSL Helper] 堆栈', e.stack);
        } finally {
            ytState.running = false;
            setRunningUI(false);
            renderYtList();
            if (typeof renderPlayList === 'function') renderPlayList();
        }

        // ★★★ 3.2.52：**失败清单必须汇总说出来**。
        //
        //   ★ 因为"跳过继续"之后，日志里那几条 `✕` 会被后面成功的淹没 ——
        //     189 条的日志翻上去找 3 条失败，实际上没人会翻。
        //   ★★ 而这几条是**整批跑完之后唯一需要人工看一眼的东西**：
        //     它们处在"可能已经传上去了、但没记账"的模糊状态 ——
        //     去 Studio 搜一下文件名，传上去了就没事（下次会自动跳过），
        //     没传上去下次跑会补上。
        reportFailures(failedList);

        log('—— 结束 ——', 'info');
    }

    /**
     * 把这一趟失败的条目汇总报出来。返回报了几条。
     *
     * ★★★★★ 抽成**独立函数**是为了**能测** —— 这不是洁癖，是被变异测试逼的。
     *
     *   第一版这段是内联在 `runYtQueue` 里的，测试只能靠"源码里有没有那段字符串"
     *   来断言。而变异把 `if (failedList.length)` 改成 `if (false)` 之后，
     *   **字符串一个字都没少** → 那条断言照样绿 → 变异没被抓住。
     *   ★ 也就是说：**那条断言是假的** —— 它测的是"我写了这段话"，
     *     而不是"这段话真的会打出来"。
     *
     *   → 抽出来之后就可以**真的调它**：喂一个假清单，看日志里有没有。
     *     变异无论怎么改（删 if、掏空函数体、不调用它），都会被抓住。
     *
     * ★ 内容上必须说三件事，缺一件这条日志就白打：
     *   · 失败的是**哪几条**（文件名 —— 用户要去 Studio 搜的就是它）
     *   · **为什么需要人工看**（文件早就投进去了，可能已经在服务端传着）
     *   · **怎么办**（传上去了不用管、没传下次会自动补 —— 别重传）
     */
    function reportFailures(list) {
        const names = (list || []).filter(Boolean);
        if (!names.length) return 0;

        log('—— 这一趟有 ' + names.length + ' 条失败 ——', 'warn');
        names.forEach(function (n) { log('  · ' + n, 'warn'); });

        // ★★★★★ 3.2.56：告诉用户"这件事**已经记下来了**"，并且给出**下次怎么带上它们**。
        //
        //   ★ 原来这里只说「去 Studio 按文件名搜一下」—— 那是**要他手工核对**：
        //     一条条搜、一条条对，然后自己记住要补哪几个。
        //     而记进待补名单之后，他有一条**不用动脑的路**：点「只勾待补的」。
        //   ★★ 措辞上不能承诺"重跑一定会补上" —— 那不是事实。
        //     这几条的状态是**未知**（文件确实投进去过），
        //     所以"带上它们之前先扫一眼"这句必须留着。
        const pend = loadPending().length;
        if (pend > 0) {
            log('  ★ 这些已经记进**「待补传」名单**（现在共 ' + pend + ' 条）。', 'ok');
            log('  ★ 下次跑的时候：**重新选目录 → 点「只勾待补的」→ 开始**。'
                + '\n      那几条**不会被「跳过已上传的」拦住**（它们没记账）。'
                + '\n    ★ 但传之前**先扫一眼**：万一上次其实传成了，'
                + '再传一遍会在频道上多一份（标题都一样，不好认）。', 'warn');
        }

        log('  ★ 它们**可能已经传上去了**（文件早就投进去了）：'
            + '\n      · 传上去了 → 不用管，下次跑会自动跳过它'
            + '\n      · 没传上去 → 按上面那条路把它们补上', 'warn');
        return names.length;
    }

    /**
     * auto_publish 三态。
     *
     *   false → 硬闸：面板上勾了也不发
     *   null  → 面板说了算
     *   true  → 面板说了算，默认勾上
     *
     * 硬闸做成硬闸而不是"只当默认值"的原因：这个值原来只喂给加载表单时的兜底。
     * 用户一旦动过面板，存储里就存下了 true，之后 CONFIG 改什么都看不见 ——
     * "测试阶段已经关掉自动发布"会变成自我安慰。
     *
     * 挡的时候日志会明说（静默改用户的选择比不改更糟）。
     */
    function resolveAutoPublish(checked) {
        // 硬闸：不管面板上勾没勾，一律不发
        if (CONFIG.yt.auto_publish === false) return false;
        // 其余两态都听面板的（true 的"默认勾上"体现在面板初始化时）
        return !!checked;
    }

    // ════════════════════════════════════════════════════════════════════
    // 7. PLAY
    // ════════════════════════════════════════════════════════════════════

    let playState = {
        running: false,
        stop: false,
        picked: {},   // relPath -> true
        names: {},    // relPath -> 面板上手改的 CSL 名（留空 = 用文件名）
        // ★ 3.2.60：原来这里还有 `urlsText`（受众网址清单）和 `audience`
        //   （面板上选的 'url' / 'ads'）。受众固定走广告流量之后两个都没了 ——
        //   受众现在**只有一个来源**：`CONFIG.play.audience`。
    };

    // ════════════════════════════════════════════════════════════════════
    // 7a. Play 侧"算得出来的部分"
    //
    // ★★ 为什么要单独拆出这一层：
    //   这一节里全是**纯函数** —— 给同样的输入，出同样的输出，
    //   不碰 DOM、不碰存储、不点任何东西。
    //   而它们决定的是**最容易出错、错了最贵**的东西：
    //     发哪几条（去重）、叫什么名。
    //   CSL 配额 50 个、不可回收 —— 这里算错一次就白烧一个。
    //   所以这一层必须**能被单独测**，不能埋在 runPlaySteps 的 DOM 操作里。
    // ════════════════════════════════════════════════════════════════════

    /**
     * 一条视频记录的**去重键**：文件名去扩展名、折空白、转小写。
     *
     * ★ 为什么不直接用 name：name 会**截断到 60 字符**。
     *   两个长文件名如果前 60 字一样，截断后名字相同 —— 但它们是**两条
     *   不同的视频**，不该互相顶掉。所以"去重"用完整键，"取名"才截断。
     *   这两件事必须分开，混在一起会出现"明明不一样却被跳过"。
     *
     * ★ 为什么不直接用 relPath：运营的原话是「拿视频文件名字来命名名称，
     *   一样的你就跳过」。判"一样"的**依据是文件名**，不是路径 ——
     *   同一批文件换个文件夹再传一遍，relPath 就变了，文件名没变。
     */
    function cslKeyOf(record) {
        const raw = record || {};
        let k = String(raw.fileName || '').trim();
        k = k.replace(/\.[^.]+$/, '');              // 去扩展名
        k = k.replace(/\s+/g, ' ').trim().toLowerCase();  // 折空白 + 转小写
        if (!k) {
            // 没文件名就只能退回路径 —— 但这是**兜底**，不是常态。
            // 两条都没文件名时它会退化成空串，上层会当错误报出来。
            k = String(raw.relPath || '').trim().toLowerCase();
        }
        return k;
    }

    /** 这个按钮文字**是不是「保存为草稿」**。是的话绝对不能点。 */
    function isDraftSaveText(text, draftTexts) {
        // ★ 用**包含**而不是相等：真按钮上常带括号后缀
        //   （「保存为草稿（不发布）」），完全匹配会漏掉它，
        //   而漏掉的后果是**把草稿当成品点了**。
        return textHitsAny(text, draftTexts || CONFIG.selectors.play.draft_texts);
    }

    /**
     * 这个按钮文字**是不是那个最终要点的「保存」**。
     *
     * ★★ 这里有个非常容易写错的地方：**「保存」是「保存为草稿」的子串**。
     *   所以判断顺序必须是"**先排草稿，再看保存**"，反过来就会把
     *   「保存为草稿」认成「保存」。这条顺序是承重的，不是风格问题。
     */
    function isFinalSaveText(text, saveTexts, draftTexts) {
        if (isDraftSaveText(text, draftTexts)) return false;
        return textHitsAny(text, saveTexts || CONFIG.selectors.play.save_texts);
    }

    /**
     * 这一批要把「发布比例」设成多少。返回 **null = 不碰这一项**。
     *
     * ★★ 为什么值得单独写成一个函数（而不是把 `if (CONFIG.play...)` 写在流程里）：
     *
     *   直接写在流程里的话，这个功能最可能的死法是 `if (false)` ——
     *   而源码护栏查 `playSetPercent(` **照样通过**：名字还在，
     *   只是那一步永远不执行了。真机上的后果是**每条 CSL 都只发一半流量**，
     *   页面不报错、流程也走完了，只有结果不对（静默失真）。
     *
     *   抽成纯函数之后，"设多少"这件事就能被单独断言 ——
     *   变异测试可以把它改成"永远返回 null"，用例当场变红。
     */
    function percentToSet(cfg) {
        const p = Number((cfg || {}).publish_percent);
        // ★ NaN 必须在这里挡掉：NaN 一旦流进输入框，那一格会变成空的，
        //   而"发布比例是空的"在页面上看起来跟"没填"一样，
        //   最后可能变成一个 0% 的 CSL（谁都不投）。
        if (!isFinite(p) || p <= 0) return null;
        return p;
    }

    /**
     * **执行前预检查**：这一趟真正需要的选择器，缺了哪几个？
     *
     * 返回 `[{ key, why }, …]` —— 空数组 = 齐了，可以开工。
     *
     * ★★★★ 为什么必须有（2026-09-18 加）：
     *
     *   原来的形态是"**跑到哪一步才发现哪个没配**"：
     *     点开入口 → 走到第 2 步 → 发现 `previewVideo` 没配 → 停。
     *   而这时**入口已经点开了**：向导停在那儿，人也搞不清建没建出来。
     *   ★ 更坏的是这**每一条都要重来一遍** —— 配一个选择器就要真机跑一次，
     *     而每次真机跑都要占一份 CSL 配额的风险。
     *
     *   → 改成"**开工前一次问完**"：把这一轮真正需要的选择器全查一遍，
     *     **缺哪些一次列全**，然后"一条 CSL 都不建"。见 `playPrecheck`。
     *
     * ★ "本轮真正需要"是**跟着模式变的**，不是一张固定清单 ——
     *   写死清单的话，切成其它模式就会漏查或多查：
     *     · `ai_declaration=false` → **不要** `aiDeclaration`（这一版就是）
     *     · 模板名为空       → 连 `templateSelect` 都不该查（另有专门报错）
     *   ★ 这也是它值得做成**纯函数**的理由：上面每一种组合都能单独断言，
     *     不用真机、不用 DOM。变异测试把某个分支改坏，用例当场变红。
     *   ★★ 3.2.60 之后"跟模式变"的只剩下面这两条 —— 受众那条
     *     （`url` 要 `audienceUrl*`、`ads` 要 `audienceAds`）跟着
     *     「网址」那条路一起删了，现在**固定只要 `audienceAds`**。
     *
     * ★ `nextBtn` / `save` **不在这个清单里**，见 `playConfigSoftGaps`。
     */
    function playConfigGaps(sel, cfg, opts) {
        const S = sel || {};
        const c = cfg || {};
        const o = opts || {};
        const need = [];
        const add = function (key, why) {
            if (!S[key]) need.push({ key: key, why: why });
        };

        // ── 第 1 步「设置」──
        add('createCsl', '列表页的「创建自定义商品详情」入口');
        add('copyExisting', '第 1 步「复制现有商品详情」这个单选'
            + '（★ 它是 `input[type=radio]`，只能用 `label=` 定位，不能用 `text=`）');
        if (o.templateName) {
            add('templateSelect', '第 1 步「选择商品详情」下拉的触发按钮'
                + '（要选「' + o.templateName + '」）');
        }

        // ── 第 2 步「详细信息」──
        add('name', '第 2 步「自定义商品详情的名称」输入框');
        if (o.publishPercent !== null && o.publishPercent !== undefined) {
            add('publishPercent', '第 2 步「发布比例」下拉的触发按钮'
                + '（要设成 ' + o.publishPercent + '%—— 页面默认 50%，只发一半流量）');
        }
        // ★ 3.2.60：这里原来有条 `if (o.audience === 'url')` 的分支
        //   （走网址时要 `audienceUrl` / `audienceUrlInput`）。
        //   「受众网址」那个功能删掉之后，受众**只有广告流量一条路**，
        //   于是它退化成一句无条件添加 —— 留着一个永远走同一侧的
        //   `if/else` 会让下一个人以为"还可以切"。
        add('audienceAds', '第 2 步「选择受众群体」下拉的触发按钮'
            + '（要选「' + (c.audience_ads_text || '广告流量') + '」）');

        // ── 第 3 步「资源」──
        add('previewVideo', '第 3 步的 YouTube 链接输入框');

        // ── 第 4 步「评价」──
        // ★ 这两个是"配置里开着才需要"。★ 注意它们是**同一个单选组**，
        //   正常情况下只有一个为 true（见 CONFIG.play 那段订正）。
        if (c.ai_declaration) {
            add('aiDeclaration', '第 4 步「AI 资源声明」'
                + '（`CONFIG.play.ai_declaration` 开着）');
        }
        if (c.no_resource_tag) {
            add('noResourceTag', '第 4 步「不为资源添加标签」'
                + '（`CONFIG.play.no_resource_tag` 开着）');
        }
        return need;
    }

    /**
     * 靠**文字兜底**的那两项：选择器可以空，但兜底的文字表**必须有内容**。
     *
     * 返回 `[{ key, why }, …]` —— 这些不是"缺选择器"，是"**兜底也没了**"。
     *
     * ★ 为什么单列一层：`nextBtn` 和 `save` 都有"按文字找"的第二条路
     *   （`playClickNext` / `playClickFinalSave`）。选择器空着是**允许的**，
     *   但前提是那条路真的在 —— 而"文字表被清空"这件事**在页面上一眼看不出来**，
     *   它只会在跑的时候变成"找不到下一步"。
     * ★ 第 9 条对这两项的要求就是这一句：「必须确认文字兜底存在」。
     */
    function playConfigSoftGaps(sel, cfg) {
        const S = sel || {};
        const out = [];
        if (!S.nextBtn && !(S.next_texts && S.next_texts.length)) {
            out.push({
                key: 'nextBtn',
                why: '「下一步」既没配选择器，文字兜底表（`next_texts`）也是空的'
                    + ' —— 两条路都没有，走不到第 2 步',
            });
        }
        if (!S.save && !(S.save_texts && S.save_texts.length)) {
            out.push({
                key: 'save',
                why: '最后那个「保存」既没配选择器，文字兜底表（`save_texts`）'
                    + '也是空的 —— 走到第 4 步会卡在找不到保存按钮',
            });
        }
        return out;
    }

    // ★★ 3.2.60 删掉了三个函数：`remainingUrls` / `pickNextUrl` / `parseUrlList`。
    //   它们只服务「受众网址」那一条路（"依次填不要重复"的队列语义）。
    //   运营 2026-09-22 说「受众网址这个功能可以删除了」→ 整条路没了，
    //   三个函数**没有任何调用点**。留着它们的代价不是几行代码，
    //   而是下一个人会以为"还能切回网址"—— 于是去补一个已经删掉的
    //   输入框、再踩一次那个"一次都不点就整条失败"的坑。

    /**
     * 把「勾了哪些视频 + 各自叫什么」算成**这一批要建哪几个 CSL**。
     *
     * 纯函数。**不点页面、不写存储**。返回的东西面板和 runPlayQueue 都读它。
     *
     * ★★ 这里承担运营 2026-09-17 明确要求的**两条去重**：
     *   ① 同批去重 —— 「一样的你就跳过不要发重复的」。
     *      真机上的样子：一个 buffalo 文件在存储里有 **4 条记录**
     *      （4 个不同 videoId，因为之前误判重跑过）。不去重就是建 4 个
     *      同名 CSL，白烧 3 个配额。
     *   ② 历史去重 —— 已经建过的（跨批次）不再建。
     *
     * @returns {{plans:Array, skippedDone:Array, skippedDup:Array,
     *            errors:Array, warnings:Array}}
     */
    function buildPlayPlans(records, opts) {
        const o = opts || {};
        const picked = o.picked || {};
        const names = o.names || {};
        const done = o.done || [];
        const maxPerRun = (typeof o.maxPerRun === 'number')
            ? o.maxPerRun : CONFIG.play.max_per_run;

        const errors = [];
        const warnings = [];
        const skippedDone = [];
        const skippedDup = [];
        const plans = [];

        const doneSet = {};
        done.forEach(function (k) { doneSet[String(k)] = true; });

        const src = (records || []).filter(function (r) {
            return r && r.videoId && picked[r.relPath];
        });

        // ★★★★★ 3.2.44：**勾了、但没有视频链接的那几条，必须单独报出来。**
        //
        //   起因是用户一句解释：「之前是那个视频没有上传，因为我们只上传了 17 个」。
        //   ★ 上面那个 filter 会把 `!r.videoId` 的记录**直接筛掉** ——
        //     筛得对（没上传成功就不该建 CSL：建出来是个没有 Preview video 的空壳，
        //     而配额一样扣），但它是**一声不响**筛掉的。
        //   ★ 同一份报告里，别的原因都有话说：
        //       · 同名重复 → 「同批里有 N 个文件名重复…取最新上传的那条」
        //       · 已建过   → 「有 N 条之前已经建过，跳过：…」
        //     唯独"没上传成功"**一个字都不说** ——
        //     于是"勾了 20 个、这一批只建 16 条"这种事，
        //     读的人只能自己一条条数，而**数不出来的那个差额没有任何线索**。
        //   ★ 这跟本项目那条老规矩是同一条：
        //     **被跳过的必须说出来 —— "没有"和"我没看"不能长得一样。**
        const noVideo = [];
        (records || []).forEach(function (r) {
            if (!r || !picked[r.relPath]) return;      // 没勾的不算，不是跳过
            if (r.videoId) return;                     // 有链接的正常进流程
            noVideo.push({
                relPath: r.relPath,
                fileName: r.fileName || r.relPath,
                state: r.state || '（没记状态）',
            });
        });

        // ★ 网址是先按"这一批实际要发几条"分配，还是先按记录顺序分配？
        //   必须是**先定下要发哪几条、再分配网址**。反过来的话，被去重跳过
        //   的那几条也会各吃掉一个网址 —— 网址就白白消耗了，而且下一条
        //   视频会配到一个"本该属于别人"的网址（运营说的"混淆"）。
        //
        // ★★ 同批同名只留 **1 条**，留哪一条？—— **留最后一条**。
        //
        //   为什么不是第一条（3.2.21 改）：
        //   存储是**追加写**的，同一个文件被重复上传时，**最后一条 = 最近一次上传**。
        //   运营清理重复投稿时删的是**旧的**、留的是**新的**。
        //
        //   2026-09-17 **实测**（`tools/check-video-links.py` 拉缩略图）：
        //   4 条 buffalo 记录里 `EDXdoyDid5E` / `od0VfGrKg8o` / `7s-pRzzMapA`
        //   全返回 **404（视频已删）**，只有最后一条 `wcSR9BnZsOQ` 是 200。
        //   —— 留第一条会**稳定地**建出一个指向已删视频的 CSL，白烧一份配额，
        //   而且页面不报错（Play 不会替我们验这个链接活不活）。
        //
        //   所以分两遍：先按 key 归组（**后到的顶掉先到的**），
        //   再按**首次出现的顺序**输出 —— 顺序仍然可预测，只是取的那条变了。
        const order = [];
        const byKey = {};
        const dropped = {};

        src.forEach(function (r) {
            const key = cslKeyOf(r);

            if (!key) {
                errors.push('有一条记录既没有文件名也没有路径，认不出是什么，停。'
                    + '（videoId=' + r.videoId + '）');
                return;
            }

            if (!byKey[key]) {
                order.push(key);          // ① 首次出现 → 定下它的位置
                dropped[key] = [];
            } else {
                dropped[key].push(byKey[key]);   // 旧的攒起来，一会儿报"跳过"
            }
            byKey[key] = r;               // ★ 后到的顶掉先到的 = 留最新那条
        });

        order.forEach(function (key) {
            const r = byKey[key];

            // ② 历史去重
            if (doneSet[key]) {
                skippedDone.push({ key: key, fileName: r.fileName, videoId: r.videoId });
                return;
            }

            const custom = String(names[r.relPath] || '').trim();
            plans.push({
                key: key,
                relPath: r.relPath,
                fileName: r.fileName,
                videoId: r.videoId,
                videoUrl: r.url || canonicalVideoUrl(r.videoId),
                useVideo: true,
                // ★ 面板上手改过就用他改的，没改过就用文件名。
                name: custom || defaultCslName(r),
                // ★ 这个文件在存储里有几条记录。> 1 说明传过多次，
                //   面板上要提醒运营"用的是最新那条" —— 之前实测出现过
                //   "留下来的那条 404、被顶掉的反而活着"的相反情况，
                //   这种时候得让人一眼看见有得选。
                dupCount: dropped[key].length + 1,
            });
        });

        order.forEach(function (key) {
            dropped[key].forEach(function (old) {
                skippedDup.push({
                    key: key,
                    fileName: old.fileName,
                    videoId: old.videoId,
                    keptVideoId: byKey[key].videoId,
                });
            });
        });

        // ★★ 3.2.60 删掉了一整段「网址够不够」的校验 + 分配
        //   （`urlPool` / `remainingUrls` / 逐条 `p.audienceUrl = left[i]`）。
        //   受众固定走广告流量之后，"这一批要几条网址、够不够"这个问题
        //   不存在了 —— 于是它也从"能拦住错误"退化成一段死代码。
        //   ★ 顺手也去掉了 `maxPerRun` 之外唯一一处会**因为受众配置而整体停下**
        //     的地方：那个错误信息本身就是个坑（它教人去改面板下拉切换路线，
        //     而那条路线现在没有了）。

        if (plans.length > maxPerRun) {
            errors.push('这一批算下来有 ' + plans.length + ' 条，超过上限 '
                + maxPerRun + ' 条。先分批来 —— 配额建出来就占着，不可回收。');
        }

        if (skippedDup.length) {
            // ★ 按文件名归并再报，别把同一个名字打 3 遍。
            const dupKeys = [];
            skippedDup.forEach(function (s) {
                if (dupKeys.indexOf(s.key) < 0) dupKeys.push(s.key);
            });
            warnings.push('同批里有 ' + dupKeys.length + ' 个文件名重复（共多出 '
                + skippedDup.length + ' 条记录），每个只建 1 条、**取最新上传的那条**：'
                + dupKeys.join('、'));
        }
        if (skippedDone.length) {
            warnings.push('有 ' + skippedDone.length + ' 条之前已经建过，跳过：'
                + skippedDone.map(function (s) { return s.fileName; }).join('、'));
        }
        if (noVideo.length) {
            warnings.push('★ 有 ' + noVideo.length + ' 条**勾了、但没有视频链接**'
                + '（没上传成功 / 还在处理）—— 这一批**不含它们**：'
                + noVideo.map(function (s) { return s.fileName; }).join('、')
                + '　→ 实际会比勾选数少 ' + noVideo.length + ' 条。'
                + '（没上传成功就不建：建出来是个没有 Preview video 的空壳，'
                + '而配额一样扣、不回收。）');
        }

        return {
            plans: plans,
            skippedDone: skippedDone,
            skippedDup: skippedDup,
            noVideo: noVideo,
            errors: errors,
            warnings: warnings,
        };
    }

    // ════════════════════════════════════════════════════════════════════
    // 7b. Play 侧「找按钮 / 点按钮 / 等页面」
    //
    // ★ 这一节存在的理由，是把 runPlaySteps 里最容易点错的东西**收成一处**。
    //   真机流程是 4 步向导 + 最后一下「保存」，而"点错按钮"在这个页面上
    //   的代价是**不可逆**的（CSL 配额建出来就占着）。
    // ════════════════════════════════════════════════════════════════════

    /** 文字里含清单里的任一个就算命中（两边都折掉空白）。 */
    function textHitsAny(text, list) {
        const t = String(text || '').replace(/\s+/g, '');
        if (!t) return false;
        const arr = list || [];
        for (let i = 0; i < arr.length; i++) {
            const w = String(arr[i] || '').replace(/\s+/g, '');
            if (w && t.indexOf(w) >= 0) return true;
        }
        return false;
    }

    /**
     * 这个节点"**点得动**吗" —— 只给 `playFindAllByText` 当准入用。
     *
     * ★★★★ 2026-09-18 新增。这是本项目**同一类 bug 的第三次**，值得把来龙去脉写全：
     *
     *   `playFindAllByText` 原来的准入只有一句 `if (!looksLikeControl(n)) continue;`。
     *   而 `looksLikeControl` 的判据是"**有状态属性**"
     *   （radio / checkbox / aria-checked / checked）—— 它是给
     *   "读得懂状态的控件"用的谓词。**普通 `<button>` 一条都不满足**。
     *
     *   实测（临时脚本搭最小假 DOM 跑真源码）：
     *
     *     <button class="mdc-button">下一步</button>
     *       looksLikeControl = false  →  playFindAllByText 命中 **0**
     *       playFindByText   = null
     *     <button><span>保存</span></button>
     *       命中 **0** / null
     *     <div role="menuitem" class="menu-item">广告流量</div>
     *       命中 **0**
     *
     *   → 也就是说，**"按文字找按钮"这条路整条是死的**：
     *      · `playClickNext` 的兜底（`P.nextBtn` 没配）永远抛「找不到『下一步』按钮」
     *      · `playClickFinalSave` 的兜底永远抛「找不到可以点的『保存』按钮」
     *      · 下拉选项（`role=menuitem` / `.menu-item`）也一样
     *   而这三条**恰好是向导里唯一能往下走的三个动作**。
     *
     * ★★ 前两次的形状（都是这一条谓词太窄）：
     *     ① 「选择商品详情」下拉展开后的 `.menu-item` 被滤掉 →
     *        模板那一步恒抛（见 `runPlaySteps` 第 1 步那段注释）
     *     ② 这次：普通 `<button>` 被滤掉 → 「下一步」「保存」恒抛
     *
     * ★★★ 为什么**不直接改 `looksLikeControl`**：
     *   它还被 YouTube 侧一堆地方用着（`findControl` 那一族），
     *   那些地方要的正是"读得懂状态"，放宽了会把整块容器也放进来 ——
     *   那是**为了修一个问题而制造一批新问题**。
     *   所以这里**只给这条路**加一条并集判据。
     *
     * ★ 标签/角色清单是照着**真机快照**列的，不是想当然：
     *   button / a  —— 「下一步」「保存」「选择商品详情」
     *   role=menuitem / role=option / .menu-item —— 下拉展开后的项
     *   .mdc-button / .mat-option / .mat-menu-item —— MDC / Material 那套壳
     */
    function looksClickable(n) {
        if (!n) return false;
        const tag = String(n.tagName || '').toLowerCase();
        if (tag === 'button' || tag === 'a') return true;

        const g = function (k) { return n.getAttribute && n.getAttribute(k); };
        const role = String(g('role') || '').toLowerCase();
        if (role === 'button' || role === 'link' || role === 'menuitem'
            || role === 'option' || role === 'tab' || role === 'radio'
            || role === 'checkbox') {
            return true;
        }

        const cls = String(g('class') || '');
        // ★ 按**整词**比，不用 `indexOf` —— `menu-itemized` 这种东西
        //   不该被当成菜单项（选择器那边的教训：子串匹配会咬到不该咬的）。
        const toks = cls ? cls.split(/\s+/) : [];
        for (const t of toks) {
            if (t === 'menu-item' || t === 'mdc-button' || t === 'mat-option'
                || t === 'mat-menu-item') {
                return true;
            }
        }
        return false;
    }

    /**
     * 在页面上找**文字命中 judge 而且真像个控件**的东西，返回**全部**候选。
     *
     * ★ 为什么要返回"全部"而不是第一个：
     *   出错时最需要的信息是"**页面上到底有什么**"。只返回一个的话，
     *   报错只能写"没找到"，而实际可能是"找到了 5 个，全都不是我想要的那种"。
     *   这两种情况的修法完全不同。
     *
     * ★ 为什么不用 findControl：
     *   findControl 只能表达"接受什么"，表达不了"**排除**什么"。
     *   而最后点保存那一步恰恰靠排除来保命 —— 见 playClickFinalSave。
     *
     * ★ 性能：先做**最便宜的判断**（textContent 长度、文字命中），
     *   再去调 isVisible（它会强制布局）。反过来写的话，几千个节点每个
     *   都来一次 reflow，页面会卡到像死机。
     */
    function playFindAllByText(judge, opts) {
        const o = opts || {};
        const maxLen = o.maxLen || 40;
        const roots = o.scope ? collectRoots(o.scope) : cachedRoots();
        const out = [];

        for (const root of roots) {
            let nodes;
            try { nodes = root.querySelectorAll('*'); } catch (e) { continue; }
            for (const n of nodes) {
                let raw = '';
                try { raw = String(n.textContent || ''); } catch (e) { continue; }
                // 便宜的长度预筛：祖先容器会在这里被整片刷掉。
                if (!raw || raw.length > maxLen) continue;

                const text = raw.replace(/\s+/g, ' ').trim();
                if (!text) continue;
                if (!judge(text)) continue;

                if (!n.isConnected || !isVisible(n) || isOurs(n)) continue;
                // ★★★★ 2026-09-18：**并集** —— "读得懂状态的控件" 或 "点得动的元素"。
                //   只有前者的话，`<button>` 会被整片滤掉，"按文字找按钮"这条路
                //   整条是死的。详见 `looksClickable` 上面那段。
                if (!looksLikeControl(n) && !looksClickable(n)) continue;

                const tag = String(n.tagName || '').toLowerCase();
                const role = String((n.getAttribute && n.getAttribute('role')) || '');
                out.push({
                    node: n,
                    text: text,
                    // 「这就是个按钮标签」优先于「文字最深的那个」——
                    // 真点击的 target 更可能是前者。
                    isRealBtn: (tag === 'button' || tag === 'a' || role === 'button'),

                    depth: depthOf(n),
                });
            }
        }
        return out;
    }

    /** 同上，但只要一个（真按钮标签优先，其次取最深的）。 */
    function playFindByText(judge, opts) {
        const all = playFindAllByText(judge, opts);
        if (!all.length) return null;
        for (let i = 0; i < all.length; i++) {
            if (all[i].isRealBtn) return all[i];
        }
        let best = all[0];
        for (let i = 1; i < all.length; i++) {
            if (all[i].depth > best.depth) best = all[i];
        }
        return best;
    }

    /** 候选项文字列表，用来写进错误里。 */
    function textListOf(hits) {
        return hits.map(function (h) { return '「' + h.text + '」'; }).join('、');
    }

    /**
     * 读**步骤条**，把四步各自的样子列出来。
     *
     * ★★★★ 2026-09-18 新增。真机证据（运营抓回来的第 1 屏快照）：
     *
     *     ·    「1 设置」      class="stepper-step _ngcontent-eir-22"
     *     ·[禁用]「2 详细信息」 class="stepper-step … is-disabled"
     *     ·[禁用]「3 资源」     class="stepper-step … is-disabled"
     *     ·[禁用]「4 评价」     class="stepper-step … last is-disabled"
     *
     *   每一条自己带 `aria-label="第 N 步，共 4 步，<名字>"` ——
     *   **序号、总数、名字全在一条属性里**，不用去数按钮、也不用猜。
     *
     * ★★ 为什么"读得出序号"是**准入条件**（读不出就整条丢掉）：
     *   序号是后面对比"翻页了没"的**唯一可比项**。
     *   一条读不出序号的记录混进来，会让"当前步"变成一个没法用的值 ——
     *   而它看起来又像"读到了东西"，比空手而归更坏。
     */
    /**
     * 材质图标（Material Icons）的**文字名**。
     *
     * ★★★★ 为什么值得单独有一条：`expand_more` / `check` / `arrow_right`
     *   这些东西是**图标字体的文字** —— 它们在 DOM 里就是普通的文本节点，
     *   会跟着 `textContent` / `innerText` 一起被读出来，于是"一个按钮叫
     *   `check`"这种事会真的发生。
     *
     *   真机证据（3.2.27 抓回来的三屏）：
     *     · 按钮段的正文里有「`notifications_unread` 未读通知」
     *       「`keyboard_backspace` 商品详情」「`expand_less`」
     *       「`选择商品详情 arrow_drop_down`」—— 图标名和真名粘在一起；
     *     · 屏 C 的诊断里，一个资源卡片 `button.asset-card.pc-flex`
     *       被当成单选项列了出来，**名字是「check」**。
     *
     * ★★ 后果不是"多一行噪声"，是**把读的人引到错的地方**：
     *   拿着「check」去配 `copyExisting`，怎么配都对不上，
     *   而真正的问题（那个控件本来就没什么可读的名字）被这句话盖住了。
     *
     * ★ 掐掉之后如果**什么都不剩**，那就是"这个名字读不出来" ——
     *   上层会把它计进"读不出选项文字"，**如实说看不清**，
     *   而不是**找一个图标名冒充选项名**。
     */
    const ICON_WORDS = 'expand_more|expand_less|check|done|edit|lock|close|add|'
        + 'delete|arrow_drop_down|arrow_drop_up|arrow_right|arrow_left|'
        + 'keyboard_backspace|keyboard_arrow_down|keyboard_arrow_up|'
        + 'notifications_unread|menu|search|star|info|warning|more_vert';

    /** 把句子里的图标名整词掐掉，再把空白压平。 */
    function stripIconWords(s) {
        // ★ 用 `\b` 而不是 `(?:^|\s)…(?=\s|$)`：后者会把**前导空格也吃掉**，
        //   于是连着两个图标名时第二个漏网（`check expand_more`）。
        // ★ 代价是英文界面下「add」这种普通词也会被掐 —— 可接受：
        //   本项目的界面是中文，而中文选项名里不会长出 `add` 这个词。
        return String(s || '')
            .replace(new RegExp('\\b(?:' + ICON_WORDS + ')\\b', 'g'), ' ')
            .replace(/\s+/g, ' ')
            .trim();
    }

    function playStepperItems() {
        const P = CONFIG.selectors.play;
        // ★ 默认值给真机那两条：Play 自己的 `stepper-step`（真机实测）
        //   和 Angular Material 的 `mat-step-header`（同类控件的通称）。
        const sel = P.stepper || '[class*="stepper-step"], mat-step-header';

        let nodes = [];
        try { nodes = safeDeepAll(sel); } catch (e) { return []; }

        const out = [];
        for (const n of nodes) {
            try {
                if (!n.isConnected || isOurs(n)) continue;
                if (!isVisible(n)) continue;

                const attr = function (k) {
                    return String((n.getAttribute && n.getAttribute(k)) || '');
                };
                const aria = attr('aria-label');
                const txt = String(n.textContent || '').replace(/\s+/g, ' ').trim();

                // ── 序号 / 总数 / 名字 ──
                // 优先从 `aria-label` 里取（真机上那里最完整、最稳定）；
                // 取不到再退回"可见文字里开头那个数字"。
                let index = 0;
                let total = 0;
                let name = '';
                const mIdx = /第\s*([0-9]+)\s*步/.exec(aria)
                    || /第\s*([0-9]+)\s*步/.exec(txt);
                if (mIdx) index = parseInt(mIdx[1], 10);
                const mTot = /共\s*([0-9]+)\s*步/.exec(aria)
                    || /共\s*([0-9]+)\s*步/.exec(txt);
                if (mTot) total = parseInt(mTot[1], 10);
                const mName = /第\s*[0-9]+\s*步[，,、]\s*共\s*[0-9]+\s*步[，,、]\s*(.+)$/.exec(aria);
                if (mName) name = mName[1].trim();
                if (!name) {
                    // 兜底：掐掉开头的序号，再去掉材质图标名。
                    // ★ 2026-09-18：词表抽成了 `ICON_WORDS` —— 原来这里有一份
                    //   内联的、而「单/多选项」那段没有，于是同一个问题
                    //   在那一段上照样发作（真机屏 C 的「check」就是这么来的）。
                    name = stripIconWords(txt.replace(/^[0-9]+\s*/, ''));
                }

                // ★ 读不出序号 → 整条丢掉。见函数头那段。
                if (!index) continue;

                const cls = attr('class');
                const toks = cls ? cls.split(/\s+/).filter(Boolean) : [];

                // ── "禁用"的两条判据，**两条都要认** ──
                //   ① 类名 `is-disabled`：真机快照里**看得见**的那一条
                //   ② `isDisabled()`：aria-disabled / disabled 属性
                //
                // ★★ 为什么类名不能省：`isDisabled` **不认类名**，
                //   而"快照说 `[禁用]`"证明它当时确实读到了 aria/disabled 里的
                //   某一个 —— 但**读不到是哪一个**（快照只打印 aria-label 和 class）。
                //   在不确定是哪一个的情况下，两条都认 = 拿到的是**并集**，
                //   漏判的风险最小。而多判的代价只是"当前步读成 null"，
                //   上层会降级成"这次不验翻页"，不会抛错。
                const disCls = toks.some(function (t) {
                    return t === 'is-disabled' || t === 'disabled'
                        || t === 'mat-step-disabled';
                });
                let disAria = false;
                try { disAria = isDisabled(n); } catch (e) { disAria = false; }

                // ── "当前步"的三条**明示**判据 —— 有就用它，没有才靠"没被禁用"去推 ──
                const curAria = attr('aria-current');
                const selAria = attr('aria-selected');
                const curCls = toks.some(function (t) {
                    // `is-active` / `active` / `mat-step-current` 都归到同一处。
                    const s = t.replace(/^is-/, '').replace(/^mat-step-/, '');
                    return s === 'active' || s === 'current' || s === 'selected';
                });

                out.push({
                    node: n,
                    index: index,
                    total: total,
                    name: name,
                    dis: disCls || disAria,
                    curAria: !!curAria && curAria !== 'false',
                    curSel: selAria === 'true',
                    curCls: curCls,
                });
            } catch (e) { continue; }
        }

        out.sort(function (a, b) { return a.index - b.index; });
        return out;
    }

    /** 「第 3 步（资源）」这种给人看的写法。 */
    function playStepText(step) {
        if (!step) return '(读不出第几步)';
        return '第 ' + step.index + ' 步'
            + (step.name ? '（' + step.name + '）' : '');
    }

    /**
     * 现在停在向导的**第几步**？
     *
     * 返回 `null` = 读不出来（不在向导里 / 结构不认识）。
     * 返回 `{ index, total, name, how, sure, seen, openIdx }`：
     *   · `how`     —— 判据是什么（出错时要说出来，不然没法判断该不该信）
     *   · `sure`    —— ★★★ 这一条是**承重**的，见下面
     *   · `seen`    —— 一共读到了几条步骤条
     *   · `openIdx` —— 没被禁用的那几条的序号
     *
     * ★★★★ `sure` 为什么必须存在：
     *   不是所有判据都一样硬。"`aria-current` 指着它"是页面**自己说的**；
     *   而"第一条没被禁用的"是**我推的** —— 推的那条在"从第 2 步往第 3 步走"
     *   的时候会**系统性地说错**（走过来的第 1 步通常也还是可点的，
     *   于是"第一条没被禁用"永远是第 1 步）。
     *   → 拿它去断言"没翻页"就会**假报失败**，而假报失败会让人去改
     *     一段本来是对的代码。所以：`sure` 为假时**只当线索，不当判据**。
     *
     * ★★ 判据顺序是按**可信度**排的，不是按好写程度：
     *   ① `aria-current` / `aria-selected` / active 类 —— 页面明说的
     *   ② **只有一条没被禁用** —— 前向向导停在第 1 步时正是这个样子
     *   ③ 第一条没被禁用的 —— 只当线索（`sure = false`）
     */
    function playCurrentStep() {
        const items = playStepperItems();
        if (!items.length) return null;

        const open = items.filter(function (it) { return !it.dis; });
        const openIdx = open.map(function (it) { return it.index; });

        const build = function (it, how, sure) {
            return {
                index: it.index,
                total: it.total,
                name: it.name,
                how: how,
                sure: sure,
                seen: items.length,
                openIdx: openIdx,
            };
        };

        // ① 页面**自己说的** —— 三条里任一条只有一个命中，就采信它。
        const pickOne = function (list) {
            return list.length === 1 ? list[0] : null;
        };
        const byAria = pickOne(items.filter(function (it) { return it.curAria; }));
        if (byAria) return build(byAria, 'aria-current 指着它', true);

        const bySel = pickOne(items.filter(function (it) { return it.curSel; }));
        if (bySel) return build(bySel, 'aria-selected="true"', true);

        const byCls = pickOne(items.filter(function (it) { return it.curCls; }));
        if (byCls) return build(byCls, '类名里有 active / current', true);

        // ② 只有一条没被禁用。真机上停在第 1 步时就是这个样子
        //    （第 2/3/4 步全是 `is-disabled`）。
        if (open.length === 1) {
            return build(open[0], '只有这一条没被禁用', true);
        }

        // ③ 兜底：**只给线索**。
        //
        // ★★★★ 2026-09-18 改：取**最后一条**开放的，不是第一条。
        //
        //   原来取 `open[0]`，那是**最坏**的一个值 —— 向导是**前向**走的，
        //   而"能回头"的那几步永远排在最前面（第 1 步永远能回）。
        //   于是 `open[0]` **几乎恒等于第 1 步**，跟真正走到哪儿无关。
        //
        //   ★ 后果不是"报错个数字"，是**翻页验证整个失效**：
        //     `playClickNext` 点完拿 `after.index !== before.index` 判翻页，
        //     而两边都会被算成"第 1 步" → 永远判不出"翻了" →
        //     只剩一句 warn。**一次都验不成功**的验证，和没有验证是一样的。
        //
        //   ★ 为什么"最后一条"更接近真相：走到哪一步，**那一步一定开放**；
        //     还没走到的地方是禁用的。所以**开放区间的右端 = 走到的最远处**。
        //     往回退也成立（退到第 2 步，第 3/4 步就该重新禁用）。
        //
        //   ★★ 但仍然**只当线索**（`sure = false`）：有的 stepper 是非 linear
        //     的（四步全解锁），那时"最后一格"恒等于第 4 步。这个反例在 DOM 里
        //     证伪不了 —— 所以不许拿它下结论，只许拿它写日志。
        if (open.length) {
            return build(open[open.length - 1],
                '最后一条没被禁用的（这是**猜的**）', false);
        }

        // 全都被禁用了 —— 这不是"当前步"，这是"没在向导里"。
        return null;
    }

    /**
     * 说清"它为什么被判成禁用" —— **只用于报错文案**。
     *
     * ★★ 必须跟 `isDisabledDeep` **同源**：不然会出现
     *   "报错说它禁用、可路径里一条禁用标记都看不到"这种自相矛盾，
     *   而这个形状本项目已经吃过好几次（快照说 `[禁用]`、代码说没禁用）。
     */
    function disabledWhy(node) {
        if (!node) return '(没有节点)';
        if (isDisabled(node)) return disabledTrace(node);

        let kids = [];
        try {
            kids = node.querySelectorAll
                ? node.querySelectorAll('button, [role="button"], a')
                : [];
        } catch (e) { kids = []; }
        for (const k of kids) {
            try {
                if (!k.isConnected || !isVisible(k)) continue;
                if (isDisabled(k)) {
                    return '外层没有，在内层 ' + tagOf(k) + ' 上：' + disabledTrace(k);
                }
            } catch (e) { continue; }
        }
        return '往上 12 层、往下那层可点元素里都没找到禁用标记'
            + '（判据可能读得不完整）';
    }

    /**
     * 点「下一步」。四步向导每步都有，所以**一个选择器够用**。
     * 点不到就抛 —— 绝不"往前凑合点一个别的"。
     *
     * ★★★★ 2026-09-18 加了两道闸，起因是**真机上的一个静默跑偏**：
     *
     *   `runPlaySteps` 第 1 步里，只要「选择商品详情」的选择器没配，
     *   那一步就**没做** —— 而此时页面上的「下一步」是
     *   `·[禁用] 「下一步」`（真机快照原话）。原来这里只有
     *   `clickHard(node); await sleep(...)`，于是：
     *
     *     · **禁用按钮点下去，浏览器自己就不响应** —— 不抛错、控制台干净
     *     · 脚本 `sleep` 完**无条件**报了「点了」
     *     · 后面每一步于是**全在错误的屏上执行**
     *
     *   关键认识：**"点了没反应"必须当成失败**。
     *   降级（某一步没做）的后果不是"少做一步"，而是"整条流程走偏"。
     *
     *   闸 ①：点之前查禁用（`isDisabledDeep`），禁用就抛，
     *         并把**禁用标记在第几层**一起报出来（`disabledWhy`）。
     *   闸 ②：点之后比对"第几步"，没变就说明翻页没发生。
     */
    async function playClickNext(stepLabel) {
        const P = CONFIG.selectors.play;

        // ★ 读"点之前在几步"。读不出来（null）不算错 —— 只是后面没法验翻页。
        const before = playCurrentStep();

        // 找按钮这一段要**能被重复调**（下面等它变亮时会重来一遍：
        // Angular 重新渲染之后旧节点会脱离文档，拿着旧节点判状态等于白判）。
        //
        // ★★ 2026-09-18：`locate` 改成 `async` —— `findOne` 现在会**等**控件出现
        //   （见它自己的注释：真机 15:19 那次"还没渲染出来"被报成了"配置错"）。
        //   ★ 这里重复调它**不会**累积等待：`locate` 找不到时会直接抛错，
        //     根本进不了下面那个 `while`；而循环里那次重调的前提是
        //     "节点刚刚还在、只是脱离了文档"，`findOne` 会立刻命中。
        const locate = async function () {
            if (P.nextBtn) {
                const node = await findOne(P.nextBtn, stepLabel + ' 的「下一步」');
                return {
                    node: node,
                    text: String(node.textContent || '').replace(/\s+/g, ' ').trim(),
                };
            }
            const hit = playFindByText(function (t) {
                // ★ 排除"保存"类：万一有人把 next_texts 配成含"保存"的词，
                //   那就在第 1 步把整条 CSL 直接发出去了。
                if (isFinalSaveText(t) || isDraftSaveText(t)) return false;
                return textHitsAny(t, P.next_texts);
            });
            if (!hit) {
                const see = playFindAllByText(function (t) {
                    return textHitsAny(t, P.next_texts);
                }, { maxLen: 60 });
                throw StepError('在' + stepLabel + '找不到「下一步」按钮。'
                    + (see.length
                        ? '页面上跟"下一步"有关的候选：' + textListOf(see)
                        : '（一个候选都没有 —— 页面可能还没加载完，或者已经不在向导里了）')
                    + '。★ 脚本不会随便点别的按钮往前凑。'
                    + '可以自己在页面上点，或者把 CONFIG.selectors.play.nextBtn 配上。',
                    'notfound');
            }
            return { node: hit.node, text: hit.text };
        };

        let found = await locate();

        // ── 闸 ①：点之前先问"它禁没禁用" ──
        //
        // ★★ 但**先给它一点时间**：选完某个控件之后，Play 那边可能还在做
        //   异步校验，「下一步」会晚一点才亮。直接判死会得到一个
        //   "看着没道理的失败"，而没道理的失败会让人不再信这个检查。
        //
        // ★ 预算按 `step_pause` 缩放，不是写死毫秒 —— 用例里惯用
        //   `CONFIG.step_pause = 1` 那种临时改法把等待压掉。
        const budget = Math.max(0, CONFIG.step_pause * 6);
        const gap = Math.max(1, Math.round(CONFIG.step_pause / 5));
        let waited = 0;
        while (isDisabledDeep(found.node) && waited < budget) {
            await sleep(gap);
            waited += gap;
            if (!found.node.isConnected) found = await locate();
        }

        if (isDisabledDeep(found.node)) {
            throw StepError(stepLabel + ' 的「' + found.text + '」是**禁用的**'
                + '（等了 ' + waited + 'ms 也没亮）。'
                + '\n    禁用标记在这儿：' + disabledWhy(found.node)
                + '\n    ★ 脚本不去点禁用按钮 —— **禁用按钮点下去浏览器自己就不响应**：'
                + '不抛错、控制台干干净净，然后后面每一步都会在**错误的屏**上执行，'
                + '最后建出一个内容不对的 CSL（配额不回收）。'
                + '\n    ★ 最常见的原因是**这一步该做的事没做成**（必填项没填 / 没选）。'
                + '往上翻日志，找有没有「选择器还没配 —— 这一步没做」那几条 —— '
                + '它们就是"上一步没做成"的证据。',
                'verify');
        }

        const tNext = Date.now();
        clickHard(found.node);
        log('  → 点了「' + found.text + '」', 'info');

        // ── 闸 ②：翻页了吗？ ──
        //
        // ★ 判据不是"页面上有没有变化"，而是**步骤条上的序号变没变** ——
        //   前者会被任何一点异步渲染骗过（真机上第 1 屏本来就是异步渲染的）。
        //
        // ★★★★★ 2026-09-18 改：原来这里是 `await sleep(CONFIG.step_pause * 2)`
        //   （真机 = **1000ms**）然后读一次 —— 这跟 15:19:16 那个坑**一模一样**：
        //   **赌一个数字够用**。
        //
        //   真机 00:47:00 那次就是被它坑的：
        //     00:47:00 → 点了「下一步」
        //     00:47:00 → ✕ 但**还停在第 1 步（设置）** —— 没翻页
        //     00:47:09 → 用户抓的快照：URL 已经是 `…/custom/create`，
        //                页面**已经在第 2 步（详细信息）**了
        //   ★ **页面明明翻了，是脚本读早了。** 而这条报错把人引向
        //     "是不是有弹窗/必填项挡着" —— 方向完全相反。
        //   ★ 这一类错误的共同形状：**用一个固定等待，去回答一个"有没有发生"的问题。**
        //
        //   → 改成**等它变**：判据明确（序号变了 / 又放开了一步），就等这个判据。
        const budgetNext = Math.max(2000, CONFIG.step_pause * 20);
        let after = null;
        try {
            after = await waitFor(function () {
                const now = playCurrentStep();
                if (!now || !before) return null;
                const moved = (now.index !== before.index)
                    || (now.openIdx.length > before.openIdx.length);
                return moved ? now : null;
            }, budgetNext);
        } catch (e) { after = null; }
        const waitedNext = Date.now() - tNext;
        // ★ 等不到就取最后一次读到的 —— 后面的判死逻辑要用它。
        //   而报错里会把"等了多久"写出来，免得又变成一句没有时间的断言。
        if (!after) after = playCurrentStep();

        if (!before || !after) {
            log('  · 翻页验证没做成（' + stepLabel + '：'
                + (before ? '' : '点之前就读不出第几步，')
                + (after ? '' : '点之后也读不出第几步，')
                + '可能是步骤条的选择器没配，或者这一屏结构不一样）—— '
                + '★ 这不代表翻页了，只代表**没验**。', 'warn');
        } else if (after.openIdx.length > before.openIdx.length) {
            // 新解锁了一步 —— 这是"真的往前走了"的**强证据**，
            // 哪怕序号读不准也够用（比序号还硬：禁用集缩小是不可逆的）。
            log('  ✓ 翻页：' + playStepText(before) + ' → ' + playStepText(after)
                + '（新放开了 ' + (after.openIdx.length - before.openIdx.length)
                + ' 步）', 'ok');
        } else if (after.index !== before.index) {
            log('  ✓ 翻页：' + playStepText(before) + ' → ' + playStepText(after), 'ok');
        } else if (before.sure && after.sure && Math.max(before.seen, after.seen) >= 2) {
            // ★ 只有**两边都有明确证据**、而且确实读到过多条步骤条时，
            //   才敢判死。少任何一条都退化成下面的 warn —— 见 playCurrentStep
            //   那段关于 `sure` 的注释（"假报失败"的代价）。
            throw StepError('点了「' + found.text + '」，等了 ' + waitedNext
                + 'ms **也没翻页**（还停在第 '
                + after.index + ' 步' + (after.name ? '（' + after.name + '）' : '')
                + '）。'
                + '\n    ★ 这次是**一直等着的**（最多 ' + Math.round(budgetNext / 1000)
                + ' 秒），不是固定睡 1 秒就读 —— 所以基本可以排除"读早了"。'
                + '\n    步骤条读出来是：' + before.how
                + '（第 ' + before.index + ' 步）→ ' + after.how
                + '（第 ' + after.index + ' 步）'
                + '\n    ★ 停在这里，别往下走：继续跑的话后面每一步都会在'
                + '**错误的屏**上执行，最后建出一个内容不对的 CSL，'
                + '而配额不可回收。'
                + '\n    先看一眼页面上是不是有东西挡着（弹窗 / 校验红字 / 某个必填项）。',
                'verify');
        } else {
            log('  · 翻页验证：序号没变（' + playStepText(before) + '），'
                + '但这次的步骤条读得**不够准**（' + before.how + ' / ' + after.how
                + '），所以没当失败。★ 自己扫一眼页面确认真的翻页了。', 'warn');
        }

        return found.text;
    }

    /**
     * 点最后那一下「保存」。
     *
     * ★★★ 这是**整个 Play 侧最危险的一次点击**，判断必须写得很死。
     *
     *   运营 2026-09-17 的原话：「最后点击保存就完成了，**不要选择保存为草稿**」。
     *   为什么不能存草稿，他也说了：「发布之后我们还需要去后台检查一次」——
     *   存成草稿等于这一趟白跑，而**配额已经花掉了**（不像 YouTube 删了能重传）。
     *
     *   两个陷阱叠在一起：
     *     ① 「保存」是「保存为草稿」的**子串** —— 子串匹配会两个都命中；
     *     ② 两个按钮**同时存在于页面上**，"先找到哪个"全看 DOM 顺序，
     *        而 DOM 顺序这种事在不同版本之间会变。
     *
     *   做法：**先把所有候选收集起来 → 排除草稿 → 再挑**。
     *   而且**不信任手配的选择器**：就算 P.save 指了地方，也要先过一遍草稿检查。
     */
    async function playClickFinalSave() {
        const P = CONFIG.selectors.play;

        // ★★★★ 2026-09-18 加：**点之前先问它禁没禁用**。
        //
        //   跟 `playClickNext` 是同一个失效形态，但后果重一层：
        //   「下一步」点不动 → 后面在错误的屏上跑；
        //   「保存」点不动 → 脚本报"点了保存"，而**一条都没建出来**，
        //   然后 `playConfirmSaved` 因为没配 `savedSignal` 只会 warn
        //   （"存没存上不知道"）→ 整批跑完，日志看着像成功。
        //
        //   ★ YouTube 侧已经吃过一次同形的亏（「保存」是灰的、对话框一动不动，
        //     只能靠"点了完成但对话框没动"这条**事后**检查发现 —— 见
        //     `finishDisabledProblem` 那段注释）。这里把那道闸**搬到点之前**。
        const guardDisabled = function (node, text) {
            if (!isDisabledDeep(node)) return;
            throw StepError('「' + text + '」是**禁用的**（灰的），点了也不会响应。'
                + '\n    禁用标记在这儿：' + disabledWhy(node)
                + '\n    ★ 脚本不去点禁用按钮：点了不报错、什么都不发生，'
                + '而日志会写着"点了保存" —— 于是这一整批**一条都没建出来**，'
                + '看起来却像跑成功了。'
                + '\n    ★ 「保存」什么时候才亮：**必填项齐了**才亮'
                + '（第 4 步的评价那两个选项、以及前面三步的必填项）。'
                + '往上翻日志，找有没有「选择器还没配 —— 这一步没做」那几条。',
                'verify');
        };

        if (P.save) {
            const node = await findOne(P.save, '「保存」按钮');
            const text = String(node.textContent || '').replace(/\s+/g, ' ').trim();
            if (isDraftSaveText(text)) {
                throw StepError('CONFIG.selectors.play.save 指的是「' + text + '」'
                    + ' —— 那是**保存为草稿**，不是要点的那个。已拒绝点击。'
                    + '把 save 改到真正的「保存」上。', 'safety');
            }
            guardDisabled(node, text);
            clickHard(node);
            await sleep(CONFIG.step_pause * 2);
            log('  → 点了「' + text + '」', 'info');
            return text;
        }

        const hit = playFindByText(function (t) { return isFinalSaveText(t); });
        if (!hit) {
            const see = playFindAllByText(function (t) {
                return isDraftSaveText(t) || textHitsAny(t, P.save_texts);
            }, { maxLen: 60 });
            throw StepError('找不到可以点的「保存」按钮。'
                + (see.length
                    ? '页面上跟"保存"有关的候选：' + textListOf(see)
                    : '（一个候选都没有 —— 向导可能还没走到第 4 步）')
                + '。★ 脚本**不会**去点「保存为草稿」：'
                + '存成草稿等于这一趟白跑，而配额照样花掉、不可回收。'
                + '把 CONFIG.selectors.play.save 指到真正的「保存」上。',
                'notfound');
        }
        // ★ 草稿那道闸在上面找按钮**之前**（`isFinalSaveText` 已排除草稿），
        //   这里补的是"禁用"那道。两条互为独立判据，都要过。
        guardDisabled(hit.node, hit.text);
        clickHard(hit.node);
        await sleep(CONFIG.step_pause * 2);
        log('  → 点了「' + hit.text + '」', 'info');
        return hit.text;
    }

    /**
     * 把一个输入框设成目标值，并**回读确认**。
     * 对不上就抛 —— 因为"填了但没吃进去"在后续步骤里看不出来，
     * 只会在最后变成一个内容不对的 CSL。
     */
    async function playSetVerified(sel, value, what) {
        if (!sel) {
            log('  · ' + what + '：选择器还没配 —— **这一步没做**。'
                + '★ 别当成填好了。', 'warn');
            return false;
        }
        const node = await findOne(sel, what);
        setValue(node, value);
        await sleep(CONFIG.step_pause);

        const back = String(readValue(node) || '').trim();
        if (back !== String(value).trim()) {
            throw StepError(what + '回读对不上：填的是「' + value + '」，'
                + '读回来是「' + back + '」。字段可能没吃进去，'
                + '或者页面把它格式化过了。', 'verify');
        }
        log('  ✓ ' + what + '：' + value, 'ok');
        return true;
    }

    /**
     * 把当前**展开着**的下拉里的选项文字列出来 —— 只用于报错。
     *
     * ★ 为什么必须有：选项没找到时，唯一有用的信息是"**列表里到底有什么**"。
     *   没有它的话，报错只能写"没找到「广告流量」"，
     *   而读的人分不清是"文案变了"、"下拉没展开"、还是"这个选项压根不在这一屏" ——
     *   三种情况的修法完全不同。
     *
     * ★ 上限 12 条 + 报出剩余个数：真机上「选择商品详情」那个下拉有 **18 项**，
     *   全列出来会把报错冲得没法读；而只列前 12 个不说还有多少，
     *   又会让人以为列表就这么长（"截断不报数"的老毛病）。
     */
    /**
     * 采集循环 —— `listMenuOptions` 和 `listControlish` 的**同一段实现**。
     *
     * ★ 2026-09-20 精简：这两个函数原来是**两份一模一样的循环体**，
     *   只有选择器不同（11 行 × 2，其中 9 行逐字相同）。
     *   合并成一个之后，"上限 12 条 + 报出剩余个数"这类规矩**只在一处**，
     *   不会再出现"改了 A 忘了改 B"。
     *
     * ★★ 两条**刻意保持**的行为，别顺手"优化"掉：
     *   · 上限 12 条 + 末尾补一句"另有 N 项" ——
     *     只列前 12 个不说还有多少，会让人以为列表就这么长。
     *   · 文字短于 60 字符才算 —— 长的是外层容器，不是选项。
     */
    function collectTexts(sel) {
        const out = [];
        let total = 0;
        for (const n of safeDeepAll(sel)) {
            try {
                if (!n.isConnected || !isVisible(n) || isOurs(n)) continue;
                const t = String(n.innerText || n.textContent || '')
                    .replace(/\s+/g, ' ').trim();
                if (!t || t.length > 60) continue;
                total += 1;
                if (out.indexOf(t) < 0 && out.length < 12) out.push(t);
            } catch (e) { continue; }
        }
        if (total > out.length) out.push('…… 另有 ' + (total - out.length) + ' 项');
        return out;
    }

    function listMenuOptions() {
        return collectTexts('.menu-item, [role="menuitem"], [role="option"], mat-option');
    }

    /**
     * 用一套**更宽**的选择器，把页面上"像选项/像控件"的东西列出来 —— **只在失败路径用**。
     *
     * ★ 为什么要有它（3.2.38 真机：点开「选择受众群体」读到 0 个选项）：
     *   `listMenuOptions` 只认 `.menu-item` / `[role=menuitem]` / `[role=option]` /
     *   `mat-option` —— 那是"下拉菜单"的形状。而"读不到"有**两种**可能：
     *     ① 菜单没开（时序 / 触发按钮点错了）
     *     ② 菜单开了，但**页面用的根本不是下拉菜单**（比如一排复选框、
     *        一个对话框里的列表项）→ 它一个标记都不在名单里，于是永远读不到
     *   ★ 这两种的修法完全不同：① 是等久一点 / 修触发按钮；
     *     ② 是**换个读法**，等多久都没用。光报"读到 0 个"分不出来，
     *     所以这里用更宽的名单再读一遍 —— 目标要是出现在这一份里，
     *     就等于当场告诉读的人"是 ②"。
     *
     * ★ 它**不参与判定**，只进报错文本：名单宽 = 噪声多，
     *   拿它当判据会把别的东西当成选项。**诊断可以吵，判据必须准。**
     */
    function listControlish() {
        return collectTexts(
            '.mdc-list-item, .mat-mdc-menu-item, mat-list-item, mat-option,'
            + ' [role="option"], [role="menuitem"], [role="checkbox"], [role="radio"],'
            + ' [role="listbox"], [role="dialog"], [role="listitem"],'
            + ' mat-checkbox, mat-radio-button, .mdc-menu-surface, .mat-mdc-menu-panel,'
            + ' .cdk-overlay-pane'
        );
    }

    /**
     * 找页面上**浮层类**的容器（下拉面板 / 菜单面板 / 弹窗），**连不可见的也报**。
     *
     * ★★★★ 为什么"连不可见的也要报"是重点（3.2.39，真机 16:26:57 逼出来的）：
     *   点开下拉之后"读不到选项"至少有**两种**完全不同的情况：
     *     ① 菜单**压根没被创建**（点击没被认成"打开"）
     *     ② 菜单**创建了**，但我们的读法 / 可见性判断把它过滤掉了
     *        （动画期间 `visibility:hidden`、或选项在浮层里但不在我们认的标记上）
     *   ★ 这两种的修法相反：① 换**点击打法**，② 改**读法**。
     *   而"按选项选择器读到 0 个"这两种**长得一模一样** ——
     *   所以这里换一个**更硬的事实**去问：浮层容器**到底有没有出现在 DOM 里**。
     *     有 = 菜单确实被创建了 → 问题在读法；
     *     一个都没有 = 压根没打开 → 问题在点击打法。
     */
    /**
     * 查 Angular Material 的**浮层容器**到底在不在文档里。
     *
     * ★★★★★ 3.2.46 新增，来自真机 2026-09-20 10:47:51。
     *
     *   那天第 2 条 CSL 卡在第 1 步：「选择商品详情」下拉**三种打法全试过、
     *   一个都没开**，而 `listOverlayish()` 报的是「**一个都没有**」。
     *   脚本据此下了结论：「菜单**压根没被创建**，所以问题在**点击**」。
     *
     *   ★★ 这个推论**不成立** —— 它把两件修法完全相反的事混成了一句：
     *
     *     · `.cdk-overlay-pane`（菜单本体）是**挂在 `.cdk-overlay-container`
     *       里面**的。容器不在文档里，pane 当然也读不到，
     *       而那**跟点击没有任何关系** —— 菜单**连"该挂到哪儿"都没有**，
     *       点一百次也创建不出来。
     *     · 而 `.cdk-overlay-container` 是 Angular Material
     *       **应用启动时创建、之后常驻**的单例（哪怕里面是空的）。
     *       它**不在文档里**这件事本身就是异常 —— 说明**页面状态坏了**。
     *
     *   → 所以「浮层 0 个」必须再拆一层，拆成两种：
     *     · 容器**在**、里面没 pane → 点击没被认成"打开"（或开了又被关）→ **改打法**
     *     · 容器**不在文档里**       → **页面状态坏了** → **刷新页面**，改打法没用
     *
     *   ★ 判据全部来自同一个 `deepQueryAll`：`listOverlayish()` 的选择器表
     *     第一项就是 `.cdk-overlay-container`，所以它返回 0 条这件事，
     *     本来就已经等价于"容器不在文档里"—— 只是**当时没人这么读**。
     *     这里把它单独问一次，是为了让那句结论**写在日志/报错里**，
     *     而不是留给读的人自己去推。
     */
    function overlayRootCheck() {
        const SEL = '.cdk-overlay-container';
        let nodes = [];
        try { nodes = deepQueryAll(SEL); } catch (e) { nodes = []; }
        let visible = 0;
        for (const n of nodes) {
            try { if (isVisible(n)) visible += 1; } catch (e) { /* 读不出可见性不算 */ }
        }
        return { count: nodes.length, visible: visible };
    }

    /**
     * 把 `overlayRootCheck()` 的结果说成**一句能直接指导下一步**的话。
     *
     * ★ 两种"不在"要分开：`{count:0, visible:0}` 和 `{count:2, visible:0}`
     *   是**两件不同的事**（后者是"容器在、只是不可见"）——
     *   合并成一句"没有浮层"，读的人又要自己猜。
     */
    function overlayRootSay() {
        const r = overlayRootCheck();
        if (!r.count) {
            return '**不在文档里**（一个都没读到）';
        }
        return '在文档里（' + r.count + ' 个，其中可见 ' + r.visible + ' 个）';
    }

    function listOverlayish() {
        const out = [];
        const SEL = '.cdk-overlay-container, .cdk-overlay-pane, .mdc-menu-surface,'
            + ' .mat-mdc-menu-panel, .mat-mdc-select-panel, .mat-menu-panel, mat-select-panel,'
            + ' [role="menu"], [role="listbox"], [role="dialog"], [role="tooltip"]';
        for (const n of safeDeepAll(SEL)) {
            try {
                if (n.isConnected === false) continue;
                if (isOurs(n)) continue;
                const cls = String((n.getAttribute && n.getAttribute('class')) || '')
                    .trim().split(/\s+/).filter(Boolean)[0] || '';
                const t = String(n.innerText || n.textContent || '')
                    .replace(/\s+/g, ' ').trim();
                out.push('<' + String(n.tagName || '').toLowerCase()
                    + (cls ? '.' + cls : '') + '> 可见='
                    + (isVisible(n) ? '是' : '**否**')
                    + (t ? ' 文字=「' + t.slice(0, 40) + '」' : '（没文字）'));
                if (out.length >= 6) break;
            } catch (e) { continue; }
        }
        return out;
    }

    /**
     * 打开一个**下拉**，并在展开的列表里按文字选中一项。
     *
     * ★★★★ 2026-09-18 新增。真机上「选择商品详情」「50%」「选择受众群体」
     *   全是**下拉按钮 + 选项列表**，而代码里原来只有两种处理方式
     *   （填输入框 / 勾选控件）—— 于是同一个错误假设长出两种坏法：
     *
     *     · `publishPercent` 走了"填输入框"→ `setValue` →
     *       元素既不是 input 也不是 contenteditable →
     *       落到兜底那句 `el.textContent = text`，**把按钮文字改成了「100」**，
     *       而回读又正好读到刚写进去的那个假值 → **判定成功**。
     *       页面上下拉根本没打开、值还是 50%，日志报 ✓。**静默失真。**
     *     · `audienceAds` 走了"勾选"→ `checkedState` 读不出来 → null →
     *       "读不出来也点一次试试" → 点完还是 null → **抛错**。
     *
     *   ★ 抛错的那个反而安全 —— 它停住了。静默的那个才致命：
     *     它会让整批 CSL 都按 50% 发出去，而**配额已经花掉、不可回收**。
     *
     * ★ 为什么选项要按**文字**找、而不是去设按钮的值：
     *   下拉按钮的可见文字**就是当前值**（没选时是「选择受众群体」，
     *   选过之后变成「广告流量」）—— 拿它当判据会在"第二次跑"时失效。
     *   而**列表里那一项的文字是稳定的**（真机上是 `class="menu-item …"`，
     *   且 aria-label 和 innerText 一致），那才是能钉住的东西。
     *
     * ★★ 最后一定要**回读按钮文字确认选上了**。
     *   这一步才是对上面那个静默失真的正面回应 ——
     *   没有它，"点了没选上"和"点了选上了"在日志里长得一模一样。
     *
     * @param {string} sel        下拉按钮的选择器
     * @param {string} optionText 选项的可见文字（精确匹配）
     * @param {string} what       日志/报错里的人话名字
     */
    /**
     * 有些选择**之后会弹一个确认框** —— 把「是」点上。
     *
     * ★★★★★ 2026-09-18 新增。真机 00:58:05：把发布比例拉到 **100%** 之后，
     *   页面弹了一个「是 / 否」（旁边还有个「关闭」）。
     *   ★ 不点「是」的话那一步**根本不生效**：下拉仍然显示「50%」，
     *     而页面**一声不响** —— 脚本会一路跑到最后，建出一个值不对的 CSL。
     *   ★ 用户原话：「选择了100%但是还要点是」。
     *
     * ★★ 只在**真的看到「是」和「否」成对出现**时才点 ——
     *   拿一个孤零零的「是」去猜，猜错就点在别的东西上了。
     *   没弹框就老实返回 false，调用方照旧走回读（回读才是真正的判据）。
     *
     * ★ 这一条跟本项目别处是同一条规矩：**改值之后必须回读**。
     *   点「是」只是把"确认"这件事做掉，生效与否由调用方的回读说了算。
     */
    async function playAcceptYesNo(what) {
        let hits = [];
        try {
            hits = playFindAllByText(function (t) {
                const s = String(t || '').replace(/\s+/g, ' ').trim();
                return s === '是' || s === '否';
            }, { maxLen: 10 });
        } catch (e) {
            // ★★★★★ 抓到的异常**必须说出来**。
            //   第一版这里是光秃秃的 `return false`，于是"环境缺函数"
            //   （`looksLikeControl is not defined`）被吞成了一句
            //   "没有确认框" —— 断言只看到 false，真因完全不可见。
            //   ★ 这正是本项目反复栽的那个形状：**静默的失败看起来像正常的否**。
            //   ★ "没有确认框"是**正常的否**（不该刷屏），所以这里用 warn 而不是抛 ——
            //     但必须留下痕迹，否则下次还是查不出来。
            log('  · 找确认框时出错了（' + (e && e.message ? e.message : e)
                + '）—— 当成"没有确认框"继续，但**这不是正常的否**，'
                + '多半是环境/代码有问题。', 'warn');
            return false;
        }

        let yes = null;
        let no = null;
        for (const h of hits) {
            const s = String(h.text || '').replace(/\s+/g, ' ').trim();
            if (s === '是' && !yes) yes = h;
            if (s === '否' && !no) no = h;
        }
        if (!yes || !no) return false;

        log('  · ' + what + ' 之后弹出了确认框（是 / 否）→ 点「是」', 'info');
        clickHard(yes.node);
        return true;
    }

    async function playPickDropdown(sel, optionText, what) {
        if (!sel) {
            // ★★★★★ 2026-09-18：这里原来是 `log(… warn); return false;` ——
            //   也就是说**没配就跳过、还接着往下跑**。现在改成**抛错停下**。
            //
            //   为什么要改（不是洁癖，是这套方案最怕的那种翻车）：
            //   这个函数的契约是"**把这一项选成 optionText**"。跳过 = 页面
            //   保持**原值**往下走 —— 而它的三个调用点，原值全都是错的：
            //     · 发布比例：页面默认 **50%** → 只发一半流量
            //     · 受众：默认**不是**「广告流量」→ 投给错的人群
            //     · 选择商品详情：不选就等于没挑模板
            //   ★★ 更坏的是它**不报错**：`playPickDropdown` 里那道"回读确认"
            //     （`after.indexOf(want) < 0` 就抛）是**配了才走得到**的，
            //     没了选择器就直接 return 了 —— 于是日志里只有一行 warn，
            //     整批照跑完、照报成功，而建出来的是 50% 的 CSL。
            //     源码上面那段自己就写着这句：**"这一步不生效是静默的"**。
            //
            //   ★ 为什么 `playEnsureChecked` 保持"警告 + 跳过"不动：
            //     它的契约是"**确认**某个控件是勾上的"，跳过 = 没碰它；
            //     而它三个门都由 `CONFIG.play.*` 的开关控制，语义是
            //     "要的话就去勾"。**改值是必须发生的事，确认是可以没发生的事**
            //     —— 两者后果不对称，所以处理方式也不该一样。
            throw StepError(what + '：选择器还没配 —— **停在这里**。'
                + 'CONFIG.selectors.play 里这一项是空的。'
                + '\n    ★ 不是"跳过就算了"：这一步的页面**默认值跟我们要的不是一个**'
                + '（发布比例默认 50%、受众默认不是「广告流量」），'
                + '跳过会安安静静建出一个值不对的 CSL，而配额照扣、不回收。'
                + '\n    → 去 `CONFIG.selectors.play` 把对应的那个下拉（触发按钮）配上。',
                'unconfigured');
        }
        const want = String(optionText || '').trim();
        if (!want) {
            throw StepError(what + '：没给要选的选项文字 —— 配置里那项是空的。',
                'unconfigured');
        }

        const node = await findOne(sel, what);
        // ★ 3.2.39：先把这个触发按钮**长什么样**记下来。
        //   真机上「发布比例」和「受众」是同一个 class 的两个下拉、一个开一个不开 ——
        //   没有这行身份信息，两份日志在纸面上长得一模一样，**没法比**。
        //   （哪天真机上换成"点到的是内层图标"这种，也全靠这行才看得出来。）
        log('  · 下拉触发按钮：' + describeNode(node), 'info');

        // ★★★★★ 3.2.46：**动手之前**先把"浮层容器在不在文档里"记一行。
        //
        //   为什么这一行必须存在：真机 2026-09-20 10:47:52 那次，
        //   报错里写的是「浮层容器探测：**一个都没有** → 问题在**点击**」——
        //   而"容器在不在"这件事，**从头到尾没有任何一行日志直接写过**，
        //   它是从"浮层 0 个"**推断**出来的，而且推错了方向
        //   （菜单挂在容器里，容器不在 → 读不到 pane **跟点击无关**）。
        //   → 把这一句提到**动手之前**：这一条的**成因**在点之前就定型了，
        //     点完之后再补一句"现在不在"是分不清"本来就不在"和"点坏的"。
        const rootBefore = overlayRootSay();
        log('  · 浮层容器（`.cdk-overlay-container`）：' + rootBefore
            + (rootBefore.indexOf('不在') >= 0
                ? '　★ 这一行是**警报**：菜单必须挂进这个容器，它不在文档里的话，'
                  + '下面几级打法全都注定开不了 —— 该做的是**刷新页面**，不是换打法。'
                : ''), rootBefore.indexOf('不在') >= 0 ? 'warn' : 'info');

        // ★ 3.2.39：三种打法按顺序试，见上面那段长注释。
        //   ★ 3.2.46：新增第 4 级 `noBubble`（**诊断级**，见 `MOUSE_SEQ.noBubble`）。
        const openAttempts = [
            { name: '整条鼠标链（pointer→mouse→click）',
                fn: function () { clickHard(node); } },
            { name: '只按下（pointerdown+mousedown，**不补** click）',
                fn: function () { clickDownOnly(node); } },
            { name: '只派一次 click',
                fn: function () { clickOnce(node); } },
            { name: '★ **不冒泡**的一枪（mousedown+mouseup+click，都不冒泡）',
                fn: function () { clickNoBubble(node); } },
        ];

        // ★★★★★ 2026-09-18（3.2.38）：点开下拉之后**要等菜单真的出现**，
        //   不能再"固定睡一下、然后只读一次"。
        //
        //   ★ 同一个形状**第三次**了：
        //     ① 3.2.35 点「下一步」后 `sleep(step_pause*2)` 读一次 → 判"没翻页"
        //        （而页面 1 秒后就翻了）
        //     ② 3.2.36 选「100%」后没等确认框 → 判"没选上"（而框就在那儿）
        //     ③ 这次（3.2.37 真机 12:48:27）：点开「选择受众群体」→
        //        固定等 1000ms → 读一次 → 读到 **0 个选项** → 报"下拉可能没真的展开"
        //   ★ 三次的写法是同一句：**用一个固定等待，去回答一个"有没有发生"的问题。**
        //     而固定等待的时长和页面的渲染速度**没有任何关系** ——
        //     它决定的只是"这次运气好不好"。
        //
        //   ★★ 这次的证据特别干净，值得记下来：**同一份日志、同一段代码、
        //     同一个等待时长**，发布比例那个下拉在 1000ms 内展开了（✓ 12:48:26），
        //     受众这个没有（✗ 12:48:27）。**两个结果** ——
        //     这恰恰证明那个时长**不是判据**，是掷骰子。
        //
        //   → 改成**一直等**（轮询到目标出现为止），预算 `max(3000, step_pause*6)`；
        //     判"没出现"时把**等了多久**说出来（跟 `playClickNext` 同一条规矩）。
        //
        //   ★★★ 出口有**三个**，这是故意的：把"没等到"和"等到了、但里面没这一项"
        //     分开报 —— 因为它们的修法**相反**（一个去查时序/触发按钮，
        //     一个去改配置里的文案）。而"菜单已经开了却不在里面"时
        //     **立刻停**、不把预算耗完：再等下去它也不会自己冒出来。
        //
        //   ★★★★ 2026-09-19（3.2.39）：**点开这个动作本身改成"分级尝试"**。
        //     真机 16:26:57 的现场（3.2.38 的兜底清单交出来的答案）：
        //       · 目标文字「广告流量」整页任何地方都不存在
        //       · 兜底清单列出来的全是**导航项** → 它确实扫了全页
        //     → 菜单**从来没开过**。而同一屏上「发布比例」那个下拉**点得开**，
        //       快照里两个是**一模一样的 class** —— 长得一样、一个开一个不开，
        //       差别只可能在**事件序列**上（详见 `MOUSE_SEQ` 上面那段）。
        //     ★ 但那是**假设**。所以这里做成三级打法**逐个试**，并**记下哪一级生效** ——
        //       "哪一级生效"本身就是证据，下一轮日志会直接告诉我们是哪回事。
        const probeMs = Math.max(700, Math.min(1200, Math.round(CONFIG.step_pause * 2)));
        // ★★★★★ 3.2.46：预算必须**保证每一级都至少能试一次**。
        //
        //   真机 2026-09-20 10:47:52 的报错里写着「**三种打法都试过了**」，
        //   而同一行还写着「等了 **3184ms**」—— 而当时的预算是
        //   `max(3000, step_pause*6) = 3000ms`、每级上限 `probeMs = 1000ms`。
        //   **3 × 1000 正好等于 3000** → 第三级大概率**压根没跑满**。
        //
        //   ★ 也就是说那句"都试过了"**跟事实不符** —— 而它恰恰是
        //     「问题在点击（事件没被页面认成打开）」这个结论的**唯一依据**。
        //     依据不成立，结论就是悬空的：读的人会去改事件序列，
        //     而真相可能只是"**没试完**"。
        //   → 预算按**级数**算，而不是拍一个数：
        const menuBudget = Math.max(3000, CONFIG.step_pause * 6,
            probeMs * openAttempts.length);
        const tMenu = Date.now();
        let opt = null;
        let opened = [];
        let winAt = -1;
        // ★ 3.2.46：记下**真的跑过哪几级**。报错里必须列这个，
        //   不能再说"三种都试过了"这种**没有代码保证**的话。
        const tried = [];
        for (let attempt = 0; attempt < openAttempts.length; attempt += 1) {
            // ★ 最后一级之前先看预算还剩多少 —— 别为了"把几种都试一遍"
            //   把等待时间翻好几倍（真机上每一步都变慢，是要还的）。
            if (attempt > 0 && Date.now() - tMenu >= menuBudget) break;
            tried.push(attempt);
            openAttempts[attempt].fn();
            const tTry = Date.now();
            for (;;) {
                opt = findOneByText(want) || null;
                if (opt) break;                                     // 出口①：等到了
                opened = listMenuOptions();
                if (opened.length) break;                           // 出口②：开了，里面没它
                if (Date.now() - tTry >= probeMs) break;            // 这一级没开 → 换下一级
                if (Date.now() - tMenu >= menuBudget) break;        // 出口③：等满了
                await sleep(200);
            }
            if (opt || opened.length) { winAt = attempt; break; }
        }
        if (opt && winAt > 0) {
            log('  · 第 ' + (winAt + 1) + ' 种打法才点开：' + openAttempts[winAt].name
                + '（★ 这条是**证据**：说明前一种事件序列被页面当成了别的东西，'
                + '不是"没点到按钮"）', 'warn');
            // ★ 3.2.46：第 4 级（不冒泡）生效的**含义**和别的不一样，要单独说。
            //   它成立等于**确证**："菜单其实开过、又被那记冒泡到 document 的
            //   click 关掉了" —— 这是一条**可以直接固化成修法**的结论，
            //   所以不能只当"第四种点法碰巧灵了"。
            if (openAttempts[winAt].name.indexOf('不冒泡') >= 0) {
                log('  · ★★ 这一级的意义不只是"点开了"：说明前三级失败的原因是'
                    + '**菜单开过、又被同一串里那记冒泡到 document 的 click 关掉了**'
                    + '（CDK 的"点到外面就关"）。→ 修法是把这一级**提到最前面**，'
                    + '别让它每次都白等前三级。', 'warn');
            }
        }

        if (!opt) {
            const waited = Math.round(Date.now() - tMenu);
            // ★★ 必须**分情况说**，因为修法完全不同 ——
            //   原来只有一句「下拉打开后没找到…（列表里一个可选项都没读到）」，
            //   把"菜单没开"和"菜单开了但没这一项"混成一句，读的人只能猜，
            //   而这两件事的修法**相反**：一个去修触发按钮/时序，
            //   一个去改配置里的文案。
            let why;
            if (opened.length) {
                why = '菜单**开了**，里面有：' + opened.join(' / ')
                    + ' —— 里面没有「' + want + '」。★ 这是**文案/配置**问题，'
                    + '不是没等够（等了 ' + waited + 'ms）。';
            } else {
                const loose = listControlish();
                const overlays = listOverlayish();
                // ★★★★★ 3.2.46：**换一个更硬的事实**去问。
                //
                //   真机 2026-09-20 10:47:52 那次，脚本从"浮层 0 个"
                //   直接推出了「问题在**点击**」—— 这个推论**不成立**：
                //   菜单是挂在 `.cdk-overlay-container` **里面**的，
                //   容器不在文档里，pane 当然也读不到，
                //   而那**跟点击没关系**（菜单连"该挂到哪儿"都没有）。
                //   ★ 更要命的是这两条的修法**相反**：
                //     一个是"换事件序列"，一个是"刷新页面"。
                //   → 所以这里把它单独问一次，按结果**分两条完全不同的路**报。
                const rootNow = overlayRootCheck();
                const rootMissing = (rootNow.count === 0);
                const triedNames = tried.map(function (i) {
                    return openAttempts[i].name;
                });
                const notTried = openAttempts.length - tried.length;

                why = '菜单**一直没开**：等了 ' + waited + 'ms，'
                    // ★ 3.2.46：报"试过哪几种"必须**以实际跑过的为准** ——
                    //   原来那句"三种打法都试过了"是**写死的**，
                    //   而这个预算（3×probeMs=3000ms）下第三级很可能没跑满。
                    + '实际试过 ' + tried.length + ' 种打法（' + triedNames.join(' / ') + '）'
                    + (notTried
                        ? '。★★ **还有 ' + notTried + ' 种没试** —— 预算 '
                          + menuBudget + 'ms 用完了。'
                          + '**别把这一条读成"都试过了"**，先把预算调大再跑一次，'
                          + '否则「点击没生效」这个结论是悬空的。'
                        : '（' + openAttempts.length + ' 种**全都真的跑过**了）。')
                    + '按选项的选择器读到的还是 0 个。'
                    + '\n    ★ 浮层容器探测（**连不可见的也报** —— 这条是分水岭）：'
                    + (overlays.length
                        ? '找到了 ' + overlays.length + ' 个 —— ' + overlays.join(' ｜ ')
                          + '\n    → 浮层**被创建出来了**，所以问题在**我们的读法/可见性判断**，'
                          + '不在点击。照着上面那句"可见=否"或那串文字去改读法。'
                        : (rootMissing
                            ? '**一个都没有**，而且浮层容器本身**不在文档里**'
                              + '（`overlayRootCheck`：' + rootNow.count + ' 个'
                              + '；点击前那一次也是 ' + rootBefore + '）。'
                              + '\n    → ★★ 所以**这不是"点击打法"的问题，'
                              + '也不是选择器配错了**：菜单是**挂在那个容器里**的，'
                              + '容器不在文档里，菜单**连该挂到哪儿都没有** —— '
                              + '点多少次都创建不出来。'
                              + '\n    → 修法只有一个：**刷新页面（F5）**，然后重跑这一条。'
                              + '（★ 这条 CSL **没建出来**，也不算在 `PLAY_DONE` 里，'
                              + '刷新后重跑不会重复建。）'
                            : '**一个都没有**，但浮层容器**在文档里**（'
                              + rootBefore + '）→ 容器在、里面没 pane，'
                              + '所以问题确实在**点击**（事件没被页面认成"打开"，'
                              + '或者开了又被立刻关掉）—— 去换打法，不是去刷新页面。'))
                    // ★ 3.2.46：第 4 级跑没跑过，是"开出即关"这条路的**判据**。
                    + (tried.indexOf(3) >= 0
                        ? '\n    ★ 第 4 级（**不冒泡**的一枪）也跑过了、也没开 —— '
                          + '所以"菜单开了、又被同一串里那记冒泡到 document 的 click '
                          + '关掉"这条路**已经排除**。'
                        : '\n    ★ 第 4 级（**不冒泡**的一枪）**还没跑过**（预算不够）—— '
                          + '它专门用来排除"开了又被冒泡的 click 关掉"那条路，'
                          + '先把它跑上，再谈别的。')
                    + (loose.length
                        ? '\n    页面上**像选项的东西**（用更宽的选择器兜底读的）：'
                          + loose.join(' / ')
                          + '\n    → 如果目标就在这里面，说明**页面用的不是下拉菜单**，'
                          + '或者它的选项不在 `listMenuOptions` 认的那几个标记里'
                          + '（现在只认 `.menu-item` / `[role=menuitem]` /'
                          + ' `[role=option]` / `mat-option`）—— 那就不是"等久一点"能解决的。'
                        : '\n    用更宽的选择器也没读到"像选项的东西" —— '
                          + '那多半是**触发按钮点错了**（点到的不是真正会展开菜单的元素）。');
            }
            throw StepError(what + '：下拉打开后没找到「' + want + '」这一项。'
                + why + '\n    ★ 按文字**精确**匹配，页面文案变了就要改配置。', 'notfound');
        }
        clickHard(opt);
        await sleep(CONFIG.step_pause);

        // ★★★★★ 2026-09-18：选完可能弹出确认框（真机 00:58:05 发布比例 100%
        //   那次就弹了「是 / 否」）。**不点「是」，这一步根本不生效** ——
        //   而页面不报错，于是下面的回读会拿到旧值、抛"没选上"。
        //   ★ 顺序很重要：先确认，再回读 —— 反过来就会得到一句
        //     "点了但没选上"的报错，而真相是"没点确认"。
        await playAcceptYesNo(what + ' 选「' + want + '」');
        await sleep(CONFIG.step_pause);

        // ★★★ 回读：按钮上现在应该显示着刚选的那一项。
        //   「点了没选上」如果不在这里拦住，页面会安安静静地按旧值继续
        //   （比如发布比例停在 50%），而流程照样跑到最后、照样报成功。
        const after = String(node.textContent || '').replace(/\s+/g, ' ').trim();
        if (after.indexOf(want) < 0) {
            throw StepError(what + '：点了「' + want + '」，'
                + '但下拉上显示的还是「' + after + '」—— **没选上**。'
                + '停在这里，别往下走：这一步不生效是静默的，'
                + '会一路跑到最后再建出一个值不对的 CSL（配额不回收）。', 'verify');
        }
        log('  ✓ ' + what + '：已选「' + want + '」（下拉现在显示「' + after + '」）', 'ok');
        return true;
    }

    /**
     * 确保某个单/复选是**勾上**的。
     *
     * ★ 三态：读不出来时**如实说读不出来**，然后照样试着点一次。
     *   不能因为"读不出来"就当成"没勾上"（那是把不知道说成知道），
     *   也不能当成"已经勾上"就跳过（那会让这一步静默不做）。
     */
    async function playEnsureChecked(sel, what) {
        if (!sel) {
            log('  · ' + what + '：选择器还没配 —— **这一步没做**。'
                + '★ 别当成勾上了。', 'warn');
            return false;
        }
        const node = await findOne(sel, what);

        let now = null;
        try { now = checkedState(node); } catch (e) { now = null; }

        // ★★★ 3.2.41：和下拉那边同一条规矩 —— **先说清"动的是哪个元素"**。
        //   真机上一轮就是靠这行身份信息（`label` vs `div.button`）才把
        //   "点错元素"从"事件序列"里摘出来的。这里同理：
        //   勾选类控件在外层读状态、在内层点，日志里不写清**是哪个**，
        //   出了"点了没勾上"就只能猜。
        log('  · 勾选项元素：' + describeNode(node), 'info');

        if (now === true) {
            log('  ✓ ' + what + '：本来就是勾上的', 'ok');
            return true;
        }
        if (now === false) log('  · ' + what + '：当前没勾上，点它', 'info');
        else log('  · ' + what + '：状态读不出来，还是点一次试试', 'warn');

        await clickControlUntilChecked(node);

        let after = null;
        try { after = checkedState(node); } catch (e) { after = null; }
        if (after !== true) {
            // ★★★★★ 3.2.41：**失败必须自带答案** —— 这一步在真机上连卡两轮，
            //   而"点了没勾上"这一个说法底下藏着**至少四种**完全不同的情况：
            //     ① 点击压根没生效
            //     ② 点击生效了，但状态挂在**我们读不到的地方**（外层 aria 陈旧）
            //     ③ 页面把这一段**重新渲染换掉了** → 我们一直盯着一个**已经不在页面上**的旧节点
            //     ④ 手里这个元素从一开始就**挑错了**（比如挑到了字段标签）
            //   ★ 而这四种的修法完全不同。所以把现场拆开打出来：
            //     · 手里这个元素是谁、还在不在文档里
            //     · 它自己怎么说（aria/checked 属性）、里面的原生框怎么说
            //     · **按同一个选择器现在重新找一个**、它又怎么说
            //       —— "两个不是同一个元素"就当场把 ③ 摘出来。
            const anatomy = function (n) {
                if (!n) return '（没有）';
                const out = [describeNode(n)];
                try { out.push('在文档里=' + (n.isConnected ? '是' : '**否**')); } catch (e) { /* 忽略 */ }
                try {
                    out.push('自带 aria-checked='
                        + JSON.stringify(n.getAttribute && n.getAttribute('aria-checked')));
                } catch (e) { /* 忽略 */ }
                try {
                    if (typeof n.checked === 'boolean') out.push('自带 checked=' + String(n.checked));
                } catch (e) { /* 忽略 */ }
                const nf = nativeFieldOf(n);
                try {
                    out.push('里面的原生框：' + (nf
                        ? (describeNode(nf) + ' checked=' + String(nf.checked))
                        : '（没有，或不止一个）'));
                } catch (e) { /* 忽略 */ }
                return '\n        · ' + out.join('\n          ');
            };
            let again = null;
            try { again = await findOne(sel, what); } catch (e) { again = null; }
            const same = (!!again && again === node);
            throw StepError(what + '：点了但没勾上（读出来是 '
                + (after === null ? '读不出来' : String(after)) + '）。'
                + '停在这里 —— 没勾上就往下走，最后会建出一个选项不对的 CSL。'
                + '\n    ★ 现场（我们手里这个）：' + anatomy(node)
                + '\n    ★ 现场（现在按同一选择器重新找到的）：' + anatomy(again)
                + (same
                    ? '\n    → 是**同一个**元素。那这个 false 就是它自己的状态 —— '
                      + '要么点击没生效，要么状态写在**它读不到的地方**'
                      + '（往上 6 层之外，或者压根没写 aria / checked）。'
                    : '\n    ★★ **两个不是同一个元素** —— 页面把这一段**重新渲染换掉了**，'
                      + '我们一直在读一个**已经不在页面上**的旧节点（它的状态当然永远不变）。'
                      + '→ 修法不是"多点几次"，是**每次读之前重新找一次**。'),
                'verify');
        }
        log('  ✓ ' + what + '：已勾上', 'ok');
        return true;
    }

    /**
     * 扫一遍页面，报出"保存之后那一屏才该有"的按钮文字（`save_hints`）。
     *
     * ★ 只返回**文字**，不返回节点。理由：这个函数要在**保存前**和**保存后**
     *   各调一次，而中间隔着一次点击 —— Angular 会把 DOM 整个重建，
     *   **跨调用拿着旧节点去读，读到的是已经不在页面上的东西**
     *   （本项目为这个形态栽过一次：拿陈旧节点判勾选状态，
     *     读出来永远是同一个值）。每次现扫，前后两次才可比。
     *
     * ★ 同名去重：一个按钮和它里面的 `<span>` 会各命中一次，
     *   不去重的话"保存前有 / 保存后没有"这种比较会因为层数不同而误判。
     */
    function playSavedHintScan() {
        const P = CONFIG.selectors.play;
        const words = P.save_hints || [];
        if (!words.length) return [];
        const hits = playFindAllByText(function (t) {
            return textHitsAny(t, words);
        }, { maxLen: 30 });
        const out = [];
        hits.forEach(function (h) {
            const t = String(h.text || '').trim();
            if (t && out.indexOf(t) < 0) out.push(t);
        });
        return out;
    }

    /**
     * 确认"真的存上了"，并把保存后那一屏收尾掉。
     *
     * ★ 没配 savedSignal 时**不能说成功** —— 那是"没检查"，不是"检查通过了"。
     *   本项目在这上面栽过：把"没看到信号"当成失败 → 用户重跑 → 重复投稿。
     *   所以这里的话术是**反过来**的：先劝住手，再让人去看。
     *
     * ★★★★★ 3.2.45：判据从"用户必须自己配一个 savedSignal"扩成**三档**，
     *   按证据强度排：
     *
     *     ① `savedSignal`（人配的，最硬：配了就是明确的契约）
     *     ② `save_hints` 里**保存后才出现**的按钮（自证过的，见下）
     *     ③ 已经离开向导 —— 判据是 `playPageShape()` 报出一个**非空、
     *        且不含"向导"**的形状（= 看到了别的东西，**不是**"没看到向导"）
     *
     *   ★★ ③ 的写法是刻意的，别简化成 `!playCurrentStep()`：
     *     "读不到步骤条"里混着两种情况 —— 真的离开了，和**还没渲染出来**。
     *     拿后者当成功就是把"没看"记成"有了"，而这一笔记错了的后果
     *     正是本项目最怕的那种：`PLAY_DONE` 里有了它，**这条就永远补不上**。
     *     所以 ③ 要求的是**正面证据**（读到了一个不是向导的形状），不是缺省。
     *
     * ★ 自证（`before` 参数）：保存前扫到的那些文字**一律不能当信号** ——
     *   它们保存前就在，说明"出现"这个动作不是保存造成的，也就证不了什么。
     *   这一步的结果会打进日志，第一次真机跑就能确认 ② 到底成不成立。
     */
    async function playConfirmSaved(opts) {
        const o = opts || {};
        const before = o.before || [];
        const P = CONFIG.selectors.play;
        const sel = P.savedSignal;

        const hintWords = P.save_hints || [];

        // ★ 保存前就有、因而**不能**当信号的那些，先挑出来说清楚。
        const unusable = hintWords.filter(function (w) {
            return before.some(function (b) { return b.indexOf(w) >= 0; });
        });

        // ★★★★★ `hintWords.length &&` 这半句是**必须的**，不是防御性写法。
        //   没有它的话，`save_hints` 没配（空数组）时会算出 `0 === 0` → 成立，
        //   于是打印「手上的候选判据保存前就已经在页面上了**（）**」——
        //   **一个空清单**，读的人根本不知道在说什么。
        //   这是测试当场抓到的（第 943/946 那轮的 3 条 FAIL 之一）。
        //   ★ 它跟本项目那条老规矩是同一件事：
        //     **"没有"和"我没看"不能长得一样** ——
        //     空清单该走"什么都没配"那条路，不该走"全都不能用"这条。
        // ★ 三态里"没检查"的那一态，有**两种**成因，措辞必须分开 ——
        //   它们给读的人的下一步动作不一样：
        //     ① 什么都没配（就是下面这条）：去配一个
        //     ② 配了但全都用不上（再下面那条）：换一个**保存后才出现**的
        //   ★ 合并成一句"没检查"看起来省事，但读的人不知道该去改哪儿。
        if (!sel && !hintWords.length) {
            log('  · 没配 savedSignal —— **存没存上不知道**（这不是"成功"，是"没检查"）。'
                + '去页面上确认一眼再跑下一条。', 'warn');
            return false;
        }

        if (!sel && hintWords.length && unusable.length === hintWords.length) {
            // 候选**全都**在保存前就存在 —— 没有一个能自证。
            // 这跟"没配 savedSignal"是同一种状态：**没检查**，不是"检查通过了"。
            log('  · 手上的候选判据**保存前就已经在页面上了**（'
                + unusable.join('、') + '）——'
                + '它们在保存前就在，所以**证不了"保存成功"**，本轮一个都没用上。'
                + '★ 这不是"成功"，是**没检查**。', 'warn');
            log('    ★ 要修的话：找那个**保存成功之后才会冒出来**的东西'
                + '（成功提示 / 跳转后的页面特征），填进 '
                + '`CONFIG.selectors.play.savedSignal`。', 'info');
            return false;
        }

        const hit = await waitFor(function () {
            // ① 人配的
            if (sel) {
                let n = null;
                try { n = deepQueryOne(sel); } catch (e) { n = null; }
                if (n) return { how: '配置的 savedSignal 命中了「' + sel + '」' };
            }
            // ② 自证过的按钮：**保存前没有、现在有**
            const now = playSavedHintScan();
            for (let i = 0; i < now.length; i++) {
                const t = now[i];
                if (before.indexOf(t) >= 0) continue;      // 保存前就有 → 不算
                return { how: '「' + t + '」出现了（保存前页面上没有它）' };
            }
            // ③ 正面证据：读到了一个**不是向导**的页面形状
            let shape = '';
            try { shape = String(playPageShape() || ''); } catch (e) { shape = ''; }
            if (shape && !/向导/.test(shape)) {
                return { how: '已经离开向导（当前页面形状：' + shape + '）' };
            }
            return null;
        }, CONFIG.wait_timeout);

        if (!hit) {
            throw StepError('点了保存，但**没有任何一条判据成立** ——'
                + '所以**不知道**这一条建没建出来。'
                + '\n    ★ 这不是"保存失败了"：保存很可能真的成功了。'
                + '\n    ★★ 先别重跑 —— 重跑会再建一个，而配额不回收。'
                + '\n    这一次试过的判据：'
                + (sel ? '\n      · savedSignal：' + sel + '（没命中）'
                       : '\n      · savedSignal：**没配**')
                + '\n      · 保存后才出现的按钮：'
                + ((P.save_hints || []).join('、') || '（没配）')
                + (unusable.length ? '（其中 ' + unusable.join('、')
                    + ' **保存前就有**，本轮主动弃用）' : '')
                + '\n    → 去页面上看一眼这一条建出来没有，再决定补记还是重跑。',
                'timeout');
        }

        log('  ✓ 保存已受理：' + hit.how, 'ok');

        // ── 保存后那一屏的收尾：点掉提示框 ──
        //
        // ★ 为什么要管它：那个提示框挡在页面上，而**下一条 CSL 要先回列表页**
        //   再点创建入口（`runPlaySteps` 起点那一段会判"现在在哪一屏"）。
        //   不收尾的话，第二条一开工就会撞上"已经在向导里了"那道闸。
        await playDismissSavedScreen();

        return true;
    }

    /**
     * 保存之后那一屏的收尾：点掉提示框（`save_dismiss`），然后等页面回列表页。
     *
     * ★★ 收尾失败**不抛错** —— 保存已经确认了（调用方只有在 `hit` 成立时才走到这），
     *   这时候抛错会让整批停下，而"提示框还开着"是可以人工点一下的小事。
     *   但它必须**说出来**，因为下一条会因此撞上"已经在向导里"那道闸 ——
     *   那句报错看着像"选择器配错了"，根因却在这里，不说清楚就白查一轮。
     */
    async function playDismissSavedScreen() {
        const P = CONFIG.selectors.play;
        const words = P.save_dismiss || [];
        let clicked = '';

        if (words.length) {
            const hit = playFindByText(function (t) {
                return textHitsAny(t, words);
            });
            if (hit) {
                clickHard(hit.node);
                clicked = hit.text;
                await sleep(CONFIG.step_pause * 2);
                log('  → 点了「' + hit.text + '」收尾', 'info');
            }
        }
        if (!clicked) {
            log('  · 没找到收尾按钮（' + (words.join('、') || '没配') + '）——'
                + '提示框可能还开着。下一条开工时若报"已经在向导里了"，'
                + '就是它挡着，手动点掉即可。', 'warn');
        }

        // ── 等回列表页 ──
        //
        // ★ 判据跟 ③ 同款：要**正面证据**（读到一个不是向导的形状），
        //   不是"没读到向导"。这里失败只 warn —— 因为回没回列表页
        //   不影响这一条的结论（它已经建出来了），只影响下一条能不能自动开工。
        const back = await waitFor(function () {
            let shape = '';
            try { shape = String(playPageShape() || ''); } catch (e) { shape = ''; }
            if (shape && !/向导/.test(shape)) return shape;
            return null;
        }, CONFIG.wait_timeout);

        if (back) {
            log('  ✓ 已经回到列表页（' + back + '），下一条可以从头走', 'ok');
        } else {
            log('  · 收尾后**还停在向导里** —— 这一条已经建出来了，'
                + '但下一条会被"已经在向导里了"那道闸拦下。'
                + '先手动把页面拨回 CSL 列表页再继续。', 'warn');
        }
    }

    /**
     * 建一条 CSL。**按运营 2026-09-17 口述的真实 4 步流程**。
     *
     * 原话：「在谷歌后台的商品详情里点击创建自定义商品详情，然后第一步设置，
     *        设置选择复制现有商品详情……要在选择商品详情里选择默认商品详情，
     *        然后点击页面右下角下一步；第二步填写默认商品需求，首先填参考名称……
     *        直接 100% 发布不要 50%……还需要选择目标受众群体，我们选择网址……
     *        再下一步是资源，其他全部默认就是在视频这里填上我们 YouTube 的视频链接……
     *        再下一步第 4 步，我们在评价这步只要选择 AI 资源声明、不为资源添加标签，
     *        最后点击保存就完成了，不要选择保存为草稿。」
     *
     * ★ 每一步的注释里都留了原话出处 —— 因为这些步骤**不是从页面上看出来的**，
     *   是运营口述的。将来页面改版时，"哪一句对不上"比"哪一行代码不对"更好定位。
     */
    async function runPlaySteps(task) {
        const P = CONFIG.selectors.play;

        // ★ 面板上改了要**立刻生效** —— 不读 playState 的话，
        //   用户在框里改了模板名却还是按 CONFIG 跑，而面板上明明显示着新名字。
        //   这种"显示的和用的不是一回事"是最难发现的一类问题。
        const templateName = String(
            playState.templateName || CONFIG.play.template_name || ''
        ).trim();

        // ════════════════ 起点：页面到底在哪一屏？════════════════
        //
        // ★★★★ 2026-09-18 加。加的理由是当天真机上的四连败：
        //
        //   15:04:34 那一次（run #1）**点到了入口**，页面随之进了向导；
        //   接下来它卡在第二步（`copyExisting` 找不到），**没有退回去**。
        //   于是 15:04:55 / :57 / :58 三次（run #2~#4）看到的
        //   **已经是向导第 1 步**，而不是列表页 —— 入口当然找不到，
        //   于是三条一模一样地报「「创建自定义商品详情」入口」在页面上找不到」。
        //
        //   ★★ 这个报错**把人指向了错的方向**：它读起来像"选择器配错了"，
        //     而真实原因是"**页面还停在上一次没走完的向导里**"，
        //     修法完全不同（一个是改配置，一个是回列表页/把向导收尾）。
        //   ★ 而且它**每跑一次就重复一次** —— 用户看到的就是"一点用都没有"。
        //
        //   → 所以先问一句"现在在哪一屏"，分三种情况：
        //     · 已经在向导里 → **停下**，并告诉他先去处理那一条
        //       （★ 不能顺手接着走：那个向导是**上一条**开的，
        //         接着走会把这一条的数据填进上一条的 CSL —— 建出来的东西是错的）
        //     · 读不出形状   → **停下**，并把页面形状原样打出来（自诊断）
        //     · 在列表页     → 正常往下走
        //
        //   ★ 为什么不直接找入口、找不到再说：因为"找不到"这个结果
        //     没法区分上面三种情况，而**用户拿到的那句话必须能指向修法**。
        let shape = '';
        try { shape = String(playPageShape() || ''); } catch (e) { shape = ''; }
        const inWizard = /向导/.test(shape);
        log('  · 页面形状：' + (shape || '（读不出）'), 'info');
        // ★ 3.2.46：顺手记一下**浮层容器**的状态 —— 一行，但这次真机就缺它。
        //
        //   真机 2026-09-20 的现场是"**第 1 条的下拉开得了、第 2 条开不了**"，
        //   而容器状态**只在第 2 条失败的那一刻**被观测到。
        //   → 分不清两种成因：**本来就没有** vs **被上一条的收尾带走了**。
        //   而这两条的修法不同（前者要另找容器，后者只要在收尾后等一下）。
        //
        //   ★ 这一行**单独看没有意义**（列表页本来就可能没这个容器，懒创建），
        //     它的价值在于跟"第 1 条开工时""下拉点之前"放在一起比 ——
        //     三条一排，就能看出是**哪个动作**把它弄没的。
        log('  · 浮层容器（`.cdk-overlay-container`）：' + overlayRootSay(), 'info');

        if (inWizard) {
            throw StepError('页面**已经停在创建向导里了** —— 不是列表页。'
                + '这一次没动任何东西。'
                + '\n    ★ 多半是**上一条没走完**留下的（脚本失败时不会自动退出向导）。'
                + '\n    ★★ **别让脚本接着往下走**：那个向导是上一条开的，'
                + '接着填会把**这一条**的数据填进**上一条**的 CSL ——'
                + '建出来的东西名字和视频对不上，而配额照样扣。'
                + '\n    → 先手动把那个向导处理掉（建完 / 点「舍弃」），回到列表页再跑。'
                + '\n    当前：' + shape, 'wrongpage');
        }
        if (!shape) {
            throw StepError('**读不出当前页面是什么形状** —— 这一趟不能开始。'
                + '\n    ★ 这不是"页面不对"，是**没法判断**。'
                + '本项目的规矩：没法判断的时候停下，不挑一个结论往下走。'
                + '\n    → 确认当前标签页是 Play Console 的商品详情页，再跑一次。',
                'wrongpage');
        }

        // ════════════════ 第 1 步「设置」════════════════
        log('  ① 设置：创建 → 复制现有 → 选「' + templateName + '」', 'info');

        // ★★★★★ 2026-09-18：这句 history 留在下面一段注释里。
        //   原来前一句是直接 `findOne` 完就 `clickHard`，真机上**点了没反应**；
        //   现在这两个动作连同"回读"一起挪进了 `playClickCreateEntry()`
        //   —— 见那个函数上面的排雷顺序。

        // ★★★★ 2026-09-18 改：这里原来是 `await sleep(CONFIG.step_pause * 2);`
        //   —— **1000ms 的固定等待**，然后直接去找第 1 步的控件。
        //
        //   真机 15:19:16 那次就是被这 1000ms 坑的：点完入口，向导还在渲染，
        //   脚本已经去 `findOne('label=复制现有商品详情')` 了 → 找不到 →
        //   报「按标注文字没找到对应的输入框」——**读起来像选择器配错了**，
        //   而 4 秒后的手动快照显示页面**还在列表页**。
        //
        //   ★ 固定 sleep 的问题不是"设小了"，而是**它本来就不该是固定值**：
        //     这一步的成功条件是明确的（"页面进了向导"），判得出来就该等它，
        //     而不是赌一个数字。网络快时白等，慢时照样不够。
        //   ★ 这也是本项目在 YouTube 侧定过的规矩 —— **点完必须回读**。
        //     这里缺的正是那一半：只点、不等、不验。
        //
        // ★★★★★ 2026-09-18 第二版：点 + 回读这两件事**合成一个函数**
        //   （`playClickCreateEntry`）。为什么要合：
        //   18:10 / 18:40 两次证明"点一下就完事"不够 —— 可能点到的不是真按钮、
        //   也可能该点的是另一个同名入口。这两个嫌疑**都只能靠回读区分**，
        //   所以"点"必须长回"点→验→再点别的"这一整个循环。
        //   ★ 留在这句上面的那一版虽好，但它验完只会甩锅（报"没进向导"），
        //     不会自己去找第二个答案 —— 而现在这份区别由线索决定，由证据纠正。
        await playClickCreateEntry();

        // 「复制现有商品详情」
        // ★ 运营说"一般默认就是它"，但这**不能当成已经选好** ——
        //   默认值会跟着别的开关变，而选错底子的后果是整条 CSL 都不对，
        //   且建出来不可回收。
        await playEnsureChecked(P.copyExisting, '「复制现有商品详情」');
        await sleep(CONFIG.step_pause);

        // 「选择商品详情」→「默认商品详情」
        //
        // ★★★ 2026-09-18 改：原来这里自己写了一遍"点开→按文字找→点"，
        //   而它**在真机上根本不工作**：那条路走的是 `playFindByText`
        //   → 过 `looksLikeControl` → 而 `looksLikeControl` **不认 `menu-item`**
        //   （它只认 radio/checkbox/role/aria-checked）→ 选项全被滤掉 →
        //   `hit` 恒为 null → 每一次都抛「下拉打开后没找到…」。
        //   改走 `playPickDropdown`（用 `findOneByText`，它的标签清单里
        //   **有** `.menu-item`），三处下拉共用同一条路。
        //
        // ★ 这个 bug 藏得很深：那段代码读起来完全正确，
        //   测试也过（夹具里造的是"看起来像控件"的东西）——
        //   直到真机上 `looksLikeControl` 把它滤干净为止。
        // ★★★★★ 2026-09-18 修：原来这里没配选择器时是
        //       log('… 这一步没做。★ 别当成选好了…) // warn
        //   然后**照样点「下一步」往下走** —— 而"复制模板"这一步**不是可选的**：
        //   整套方案**靠它**继承默认商品详情的图片和文案（我们不上传 Play 图片、
        //   也不改 Play 文案，见文件头那几条硬约束）。
        //   ★ 没选模板就往下走，建出来的是一个**没有图、没有文案**的空壳 CSL ——
        //     而它**照样占一个配额**，且名称建出来就不可改。
        //   ★ 所以这里必须**抛错停下**（第 14 条：模板未选择成功 → 抛 StepError）。
        if (!templateName) {
            throw StepError('模板名是空的 —— 不知道该复制哪一个商品详情。'
                + '\n    ★ 面板上的「模板名」那个框、或者 `CONFIG.play.template_name`'
                + '得有一个值（真机上是「默认商品详情」）。'
                + '\n    ★ 不能"随便选一个"：复制哪个模板决定了整条 CSL 的底子。',
                'unconfigured');
        }
        if (!P.templateSelect) {
            throw StepError('「选择商品详情」的选择器还没配 —— **停在这里**。'
                + 'CONFIG.selectors.play.templateSelect 是空的。'
                + '\n    ★ 复制模板**不是可选步骤**：整套方案靠它继承'
                + '默认商品详情的**图片和文案**（我们不上传 Play 图片、也不改文案）。'
                + '\n    ★ 跳过它建出来的是一个**没有图、没有文案的空壳 CSL**，'
                + '而配额照扣、名称建出来就不可改。'
                + '\n    → 回列表页/第 1 步确认那个下拉的触发按钮，把它配上。',
                'unconfigured');
        }
        await playPickDropdown(P.templateSelect, templateName, '「选择商品详情」');

        await playClickNext('第 1 步');

        // ════════════════ 第 2 步「填写默认商品需求」════════════════
        log('  ② 需求：参考名称 / ' + CONFIG.play.publish_percent
            + '% 发布 / 受众', 'info');

        await playSetVerified(P.name, task.name, '参考名称');

        // ★ 原话：「直接 100% 发布不要 50%，他默认 50%」。
        //   不主动拉就只发一半流量 —— 这是**静默失真**：页面不报错、
        //   流程也走完了，只有结果不对。
        //
        // ★ 判据走 percentToSet（纯函数，能被单独测）。
        //   直接在这里写 `if (CONFIG.play.publish_percent > 0)` 的话，
        //   把它改成 `if (false)` 源码护栏查不出来 —— 见那个函数的注释。
        const pct = percentToSet(CONFIG.play);
        if (pct !== null) {
            // ★★ 这是**下拉**，不是输入框 —— 见 playPickDropdown 那段。
            //   真机上它的选项是「100% / 90% / … / 10%」，文字稳定。
            await playPickDropdown(P.publishPercent, pct + '%', '发布比例');
        }

        // ★★ 受众**固定走「广告流量」**（3.2.60）。
        //
        //   ★ 这一段原来是个 `if (audience === 'url') … else …`，
        //     里面还有一条 `if (!task.audienceUrl) throw StepError(…)` ——
        //     那条错误的实际触发条件是"面板上把下拉切到了「网址」、
        //     而网址框是空的"，也就是**一次都不点就整条失败**，
        //     而且错误信息把人指向一个"我们根本不打算填"的框。
        //   ★ 运营 2026-09-22 说「受众网址这个功能可以删除了」→
        //     那条路连同那个状态**在面板上已经无法表达**，于是整段删掉。
        //     现在这里是**无条件**的：走广告流量是唯一可能。
        //   ★ 文案仍然是**配置来的**（页面文案会变，改一处就够）。
        await playPickDropdown(P.audienceAds,
            CONFIG.play.audience_ads_text, '受众 = 广告流量');
        log('  · 受众走「广告流量」，不填网址', 'info');

        await playClickNext('第 2 步');

        // ════════════════ 第 3 步「资源」════════════════
        log('  ③ 资源：只填视频链接，其余保持默认', 'info');

        if (!task.useVideo) {
            throw StepError('这条任务没有视频。Play 侧的 CSL 现在只走"填视频"'
                + '这条路（无视频对照是 YouTube 侧 A/B 用的，现在不做了）。',
                'precheck');
        }
        if (!task.videoUrl) {
            throw StepError('任务的视频链接是空的：' + task.name, 'precheck');
        }
        await playSetVerified(P.previewVideo, task.videoUrl, '视频链接');

        await playClickNext('第 3 步');

        // ════════════════ 第 4 步「评价」════════════════
        log('  ④ 评价：AI 资源声明 + 不为资源添加标签', 'info');

        if (CONFIG.play.ai_declaration) {
            await playEnsureChecked(P.aiDeclaration, '「AI 资源声明」');
        } else {
            log('  · 「AI 资源声明」按配置**不动**（CONFIG.play.ai_declaration=false）', 'info');
        }
        if (CONFIG.play.no_resource_tag) {
            await playEnsureChecked(P.noResourceTag, '「不为资源添加标签」');
        } else {
            log('  · 「不为资源添加标签」按配置**不动**（CONFIG.play.no_resource_tag=false）', 'info');
        }

        // ── 收尾：点「保存」，**绝不点「保存为草稿」** ──
        //
        // ★★★★★ 3.2.45：**点之前**先扫一遍基线 —— 记下"保存之后才该有"的那些按钮
        //   现在在不在页面上。这是判据的**自证**：
        //     保存前没有、保存后有 → 那是保存带来的，可以当成功信号
        //     保存前就有           → 它证不了保存成功，本轮主动弃用
        //
        //   ★ 扫描时机是承重的：必须在**第 4 步的表单已经填完、但还没点保存**这一刻。
        //     早一点（比如刚进第 4 步）扫，基线会把第 4 步自己的东西算进去；
        //     晚一点（点完之后）扫，那已经不叫基线了。
        const hintsBefore = playSavedHintScan();
        const hintWords = (CONFIG.selectors.play.save_hints || []);
        log('  · 保存前先记基线：页面上' + (hintsBefore.length
            ? '**已经有了** ' + hintsBefore.join('、')
              + ' → 这几个本轮**不能**当成功信号（它们不是保存带来的）'
            : '没有「' + hintWords.join('」「') + '」'
              + ' → 它们一旦冒出来，就是保存带来的'), 'info');

        await playClickFinalSave();

        // ── 确认真的存上了 ──
        //
        // ★★★★★ 2026-09-18 修**真 bug**。这里原来是**一句话**：
        //       await playConfirmSaved();
        //   —— 而 `playConfirmSaved` 在**没配 `savedSignal`** 时的返回值是
        //   `false`（它不抛错，只 warn 一句"存没存上不知道"）。
        //   **返回值被丢掉了**，于是调用方认为"这一步过了"：
        //       没配 savedSignal
        //         → 其实**没做任何确认**
        //         → 照样写 STORE.PLAY_DONE
        //         → 日志打「✓ 完成」
        //   ★ 这是最坏的一种谎报：**"没检查"被当成了"检查通过了"**。
        //     后果是运营按日志以为建好了，而下一条会跳过这个 key ——
        //     真没建出来的话就**永远补不上**。
        //
        // ★ 三态（这是本项目的定案）：
        //     SUCCESS（读到成功信号）   → 写 PLAY_DONE
        //     FAILED（waitFor 超时）    → `playConfirmSaved` 里已经抛了，走不到这
        //     UNKNOWN（没配 savedSignal）→ **停下，不写 PLAY_DONE**
        //   ★★ UNKNOWN **不是** SUCCESS。不确定就停下来让人看一眼 ——
        //     这比"赌它成功、继续往下建"安全得多（CSL 配额不可回收，
        //     赌错的代价是多建一个错的，而停下来的代价只是人看一眼）。
        //
        // ★ 为什么敢让它在没配 savedSignal 时**卡住整批**：
        //   因为这才是事实 —— 没配的时候脚本**确实不知道存没存上**。
        //   让它继续跑，等于用"不知道"当"知道"。
        //   → 配 `savedSignal` 的办法见那条报错文案。
        const saved = await playConfirmSaved({ before: hintsBefore });
        if (!saved) {
            throw StepError('**无法确认保存成功** —— 当前状态是 UNKNOWN，'
                + '**不记录 PLAY_DONE**，这一批停在这里。'
                + '\n    ★ 这不是"保存失败了"：保存很可能真的成功了，'
                + '只是脚本手上**没有一条能自证的判据**，所以**不知道**。'
                + '\n    ★★ UNKNOWN 不等于 SUCCESS：把"不知道"当成"成功"，'
                + '下一条就会跳过这一条（`PLAY_DONE` 里有了），'
                + '万一其实没建出来，**就永远补不上了**。'
                + '\n    → 去页面上看一眼这一条建出来没有：'
                + '\n        · 建出来了 → 可以手动补记，或者配好 `savedSignal` 再跑'
                + '\n        · 没建出来 → 处理掉那个向导，回到列表页重跑'
                + '\n    → 配置办法：`CONFIG.selectors.play.savedSignal` 填一个'
                + '**只在保存成功后才会出现**的元素'
                + '（`playConfirmSaved` 里那份报错会列出本次试过哪几条判据、'
                + '各自为什么没成立）。',
                'unverified');
        }
    }

    /**
     * **开工前**把这一趟真正需要的选择器查一遍，缺了就不开工。
     *
     * 返回 `true` = 可以开工；`false` = 有缺失，**一条都不要建**。
     *
     * ★★★★ 为什么必须在"建第一条"**之前**（而不是每条开始前）：
     *   每建一条都要点开向导、占一份配额风险。缺项要在**还没碰页面**的时候
     *   就全找出来，这样"缺 3 个选择器"是**一次**报完，而不是
     *   "跑一条 → 发现缺一个 → 配 → 再跑一条 → 又发现缺一个"，把配额和
     *   真机联调的时间都耗在发现同一类问题上。
     *
     * ★ 报错形态是**一次列全**：`✕ name（第 2 步「…」输入框）` 一行一个，
     *   而不是只说"缺少必需的选择器"——后者用户还得回去一个个比。
     */
    function playPrecheck() {
        const P = CONFIG.selectors.play;
        const templateName = String(
            playState.templateName || CONFIG.play.template_name || ''
        ).trim();

        // ★ 这里的入参就是上面 `playConfigGaps` 说的"模式" ——
        //   它们决定"本轮真正需要哪些"，而不是一张固定清单。
        //   ★★ 3.2.60：`audience` 这个入参还在（`playConfigGaps` 用它决定
        //     要不要查 `audienceAds`），但来源**只剩 `CONFIG.play.audience`** ——
        //     面板上没有能改它的控件了。
        const gaps = playConfigGaps(P, CONFIG.play, {
            templateName: templateName,
            publishPercent: percentToSet(CONFIG.play),
            audience: CONFIG.play.audience,
        });
        const soft = playConfigSoftGaps(P, CONFIG.play);

        if (!gaps.length && !soft.length) {
            log('  ✓ Play 预检查通过：这一趟要用的选择器都配齐了', 'ok');
            return true;
        }

        if (gaps.length) {
            log('Play 预检查**没通过** —— 缺 ' + gaps.length + ' 项选择器：', 'error');
            gaps.forEach(function (g) {
                log('  ✕ ' + g.key + '（' + g.why + '）', 'error');
            });
        }
        soft.forEach(function (s) {
            log('  ✕ ' + s.key + '（' + s.why + '）', 'error');
        });

        log('★ **本次没有创建任何 CSL** —— 在点开入口之前就拦下来了。'
            + '\n    → 在 Play Console 里对着上面缺的那几项抓一次快照，'
            + '填进 `CONFIG.selectors.play`（填法见每一项的注释），再跑。'
            + '\n    ★ 为什么不"先跑起来看看"：跑到一半才发现缺项时，'
            + '入口**已经被点开**、向导停在半路 —— 那时不但白占一份配额风险，'
            + '还得先手工收拾页面才能重跑。', 'error');
        return false;
    }

    async function runPlayQueue() {
        if (playState.running) { log('正在跑，别重复点', 'warn'); return; }

        // ★ 3.2.53：Play 侧同样是"一堆 waitFor 撑着"的流程，后台一样会被拖慢。
        //   而它比 YouTube 侧更要紧：CSL 建一半停下的代价是**留一个没走完的向导**
        //   （下一条开工时会撞"已经在向导里了"那道闸）。
        installVisibilityWatch();
        if (pageHiddenNow()) {
            log('★ 开工时这个标签页就在**后台** —— Play Console 的每一步都在等'
                + '页面响应，后台节流会让它明显变慢，甚至误报失败。'
                + '\n  → 建议把这一页切到前台再跑。', 'warn');
        }

        // ── 先把"这一批要建哪几个"算清楚，再动页面 ──
        //
        // ★★ 顺序是**承重**的：这一步是纯计算，不点任何东西，算错了还能回头；
        //   而一旦开始点，配额就没了。所以宁可在这里多停一次。
        const built = buildPlayPlans(loadVideos(), {
            picked: playState.picked,
            names: playState.names,
            done: storeGet(STORE.PLAY_DONE, []),
            maxPerRun: CONFIG.play.max_per_run,
        });

        built.warnings.forEach(function (w) { log(w, 'warn'); });

        if (built.errors.length) {
            built.errors.forEach(function (e) { log(e, 'error'); });
            log('先解决上面的问题 —— 这一趟**一条都不会建**。', 'error');
            return;
        }
        if (!built.plans.length) {
            log('没有要建的任务。先勾视频；要是都勾了，多半是之前都建过了。', 'warn');
            return;
        }

        // ★ 把"要建什么"原样报一遍再动手。
        //   这是**最后一道人眼防线** —— 清单摆在日志里，不对还能按停止。
        //   之前吃过一次"以为在补跑、其实在重复投稿"的亏，就是因为
        //   动手之前没有任何地方把"这一趟要干什么"完整说出来。
        //
        // ★★★★★ 2026-09-19（3.2.42）：**还要报出脚本自己的版本号。**
        //   起因是实打实的一轮浪费：用户装没装上新版，日志里**一个字都不说**。
        //   那一轮我判断"跑的还是旧版"全靠对比代码特征（新版会多打一行
        //   `勾选项元素：`、失败信息里会多一段"现场"）—— 这是**靠旁证推断**，
        //   而旁证会错（比如新版正好没走到那一行）。用户白等一轮，我也白分析一轮。
        //   ★ 这跟本项目那条老规矩是同一条：
        //     **发版必须升 `@version`（同版本号分不出装的是哪一份）** ——
        //     但升了版本号还不够，**得让它出现在用户看得到的地方**（这行日志）。
        //   ★ 读不到（测试环境、或某些管理器不给 `GM_info`）时如实说"版本读不到"，
        //     不假装知道。
        log('这一批要建 ' + built.plans.length + ' 条：　（脚本 v'
            + scriptVersion() + '）', 'info');
        built.plans.forEach(function (p, i) {
            log('  ' + (i + 1) + '. ' + p.name, 'info');
        });

        // ★★★★ 执行前预检查（2026-09-18 加）。
        //
        //   位置是**承重**的：必须在 `playState.running = true` 之前、
        //   更要在**任何一次点击之前** —— 这一句不通过就 `return`，
        //   整批**一条 CSL 都不会建**，页面一毫未动。
        //
        //   ★ 放在"要建哪几条"报完之后：这样日志里的顺序是
        //      1) 这一趟打算建什么  →  2) 能不能建 → 3) 开始建
        //     缺项时人看到的是"我本来要建这 17 条，但因为缺 3 个选择器一条没建"，
        //     而不是"报了个错，不知道本来要干什么"。
        if (!playPrecheck()) {
            return;
        }

        playState.running = true;
        playState.stop = false;
        setRunningUI(true);

        try {
            for (let i = 0; i < built.plans.length; i += 1) {
                if (playState.stop) {
                    log('收到停止，这一批停在 ' + (i + 1) + '/' + built.plans.length
                        + '（还没开始的那几条没建）。', 'warn');
                    break;
                }

                const task = built.plans[i];
                log(`[${i + 1}/${built.plans.length}] ${task.name}`, 'info');

                try {
                    await runPlaySteps(task);

                    // ★ 只有**走完整条流程**才记账。
                    //
                    //   失败时不记 —— 因为失败可能发生在"其实已经建出来了、
                    //   只是没看到成功信号"之后。那时记不记账都各有一个坑：
                    //   记了会漏建（下次跳过），不记会重跑建两个。
                    //   这里选**不记**，因为重跑建两个的代价更大（配额不可回收），
                    //   而漏建可以人工补 —— 所以日志里要明确让人去看一眼。
                    const list = storeGet(STORE.PLAY_DONE, []);
                    if (list.indexOf(task.key) < 0) {
                        list.push(task.key);
                        storeSet(STORE.PLAY_DONE, list.slice(-2000));
                    }
                    log('  ✓ 完成', 'ok');
                } catch (e) {
                    log('  ✕ ' + e.message, 'error');
                    if (e && e.stack) console.error('[CSL Helper] 堆栈', e.stack);
                    log('这一批停在这里。★ **先去页面上确认这一条到底建没建出来** ——'
                        + '建了的话，重跑会再建一个，配额不回收。', 'error');
                    break;
                }
            }
        } catch (e) {
            log(e.message, 'error');
            if (e && e.stack) console.error('[CSL Helper] 堆栈', e.stack);
        } finally {
            playState.running = false;
            setRunningUI(false);
        }

        log('—— 结束 ——', 'info');
    }

    // ════════════════════════════════════════════════════════════════════
    // 8. UI
    // ════════════════════════════════════════════════════════════════════

    // UI 里各控件的引用。因为只有两个面板，直接放一个对象里，不做抽象。
    const UI = { yt: {}, play: {} };

    function el(tag, props, children) {
        const node = document.createElement(tag);
        if (props) {
            Object.keys(props).forEach(function (k) {
                if (k === 'style') node.style.cssText = props[k];
                else if (k === 'text') node.textContent = props[k];
                // checked / value / disabled 要设**属性**（property）而不是标签属性
                // （attribute）。设 attribute 只是"初始状态"，之后读 .checked
                // 拿到的可能不是你要的那个值。
                else if (k === 'checked' || k === 'value' || k === 'disabled') node[k] = props[k];
                else if (k.indexOf('on') === 0) node.addEventListener(k.slice(2), props[k]);
                else if (props[k] !== null && props[k] !== undefined) node.setAttribute(k, props[k]);
            });
        }
        (children || []).forEach(function (c) { if (c) node.appendChild(c); });
        return node;
    }

    const CSS = [
        '.cslh-panel{position:fixed;top:12px;right:12px;width:340px;max-height:88vh;',
        'overflow:auto;background:#fff;color:#202124;border:1px solid #dadce0;',
        'border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.18);',
        'font:12px/1.5 -apple-system,"Segoe UI",Roboto,"Microsoft YaHei",sans-serif;z-index:2147483646;}',
        '.cslh-head{display:flex;align-items:center;justify-content:space-between;',
        'padding:8px 10px;background:#1a73e8;color:#fff;border-radius:9px 9px 0 0;font-weight:600;',
        // ★ `cursor:move` 是**唯一**能让人知道"这里能拖"的信号。
        //   没有它，用户只会以为面板是钉死的 —— 他本来就是这么以为的，
        //   所以这一条不是装饰，是"这个功能存不存在"的可发现性。
        'cursor:move;user-select:none;}',
        '.cslh-head button{background:none;border:0;color:#fff;cursor:pointer;font-size:14px;}',
        '.cslh-body{padding:10px;}',
        '.cslh-sec{margin-bottom:10px;}',
        '.cslh-label{font-weight:600;margin-bottom:4px;color:#3c4043;}',
        '.cslh-btn{background:#1a73e8;color:#fff;border:0;border-radius:6px;padding:7px 12px;',
        'cursor:pointer;font-size:12px;font-weight:600;}',
        '.cslh-btn:disabled{background:#9aa0a6;cursor:not-allowed;}',
        '.cslh-btn.sec{background:#f1f3f4;color:#3c4043;}',
        // ★ 3.2.57：面板上的文本输入框（补录用）。
        '.cslh-input{border:1px solid #dadce0;border-radius:4px;padding:5px 7px;',
        'font-size:12px;background:#fff;color:#3c4043;box-sizing:border-box;}',
        '.cslh-row{display:flex;align-items:center;gap:6px;margin:5px 0;}',
        '.cslh-list{max-height:210px;overflow:auto;border:1px solid #e8eaed;border-radius:6px;padding:5px;}',
        '.cslh-item{display:flex;align-items:flex-start;gap:6px;padding:3px 2px;}',
        '.cslh-item input[type=text]{flex:1;min-width:0;border:1px solid #dadce0;',
        'border-radius:4px;padding:3px 6px;font-size:11px;}',
        '.cslh-name{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}',
        // ★ 2026-09-20：「已上传」这个标记。
        //   绿色底 + 小字 —— 目的是**扫一眼就能分出来**。
        //   189 个文件里，"哪些传过了"必须一眼可见，不能靠逐个读文件名。
        '.cslh-tag{background:#e6f4ea;color:#137333;border-radius:3px;',
        'padding:0 4px;font-size:10px;white-space:nowrap;}',
        // 会被跳过的那一条：**整体压暗**。
        // ★ 压暗比"加个灰字说明"更直接 —— 用户看到的就是"这条不会发生"。
        '.cslh-item-dim{opacity:.55;}',
        '.cslh-log{margin-top:6px;max-height:190px;overflow:auto;background:#202124;color:#e8eaed;',
        'border-radius:6px;padding:7px;font:11px/1.5 ui-monospace,Consolas,monospace;white-space:pre-wrap;}',
        '.cslh-log .e{color:#f28b82;}',
        '.cslh-log .w{color:#fdd663;}',
        '.cslh-log .o{color:#81c995;}',
        '.cslh-hint{color:#5f6368;font-size:11px;}',
        'select,input[type=text]{border:1px solid #dadce0;border-radius:4px;padding:3px 6px;font-size:12px;}',
    ].join('');

    function installStyle() {
        if (document.getElementById('cslh-style')) return;
        const s = document.createElement('style');
        s.id = 'cslh-style';
        s.textContent = CSS;
        document.head.appendChild(s);
    }

    // ── 面板可以拖着走 ──────────────────────────────────────────────────
    //
    // ★ 为什么要做：面板是 `position:fixed` 贴在右上角，而 Play Console 的
    //   CSL 创建向导里**右下角是「下一步」、右上角也压着东西**
    //   （还有步骤条）。面板盖上去就点不着了 ——
    //   对一个"替人点按钮"的工具来说，**挡住要点的按钮**是最要命的缺陷：
    //   它不但不帮忙，还得先绕过它。
    //
    // ★★ 位置必须**存盘**。Play Console 虽然是 SPA，但整页刷新真的会发生
    //   （F5、或者从列表点进某个 CSL 时偶尔走完整导航）。不存的话，
    //   脚本一重跑面板就弹回右上角 —— 用户每刷一次拖一次，等于没做。
    //
    // ★★★ 恢复位置时**必须夹回视口内**。这是个很容易漏、后果又很唬人的坑：
    //   用户可能在 2560 宽的屏上把面板拖到最右边，然后换到笔记本（1366）打开
    //   —— 存下来的 `left=2400` 会让面板**完全飘在屏幕外**，
    //   表现是"脚本坏了，面板不见了"，而它其实好好地在视口右边外头。
    //   → 夹取逻辑抽成**纯函数**（不读 window、只算），这样能直接测。

    // 面板至少要有这么多像素留在视口里，否则人就够不着它了
    const PANEL_MIN_VISIBLE = 48;

    /**
     * 把一个存下来的坐标夹回"看得见"的范围。**纯函数**，便于直接测。
     *
     * ★ 规则：**能整个放下就整个放下**，放不下才允许只露一角。
     *   为什么不一律"留 48px 就算数"：那样在宽屏上可以把面板推到
     *   只剩一条边，而用户以为它还在原地 —— 不如让它永远完整可点。
     *
     * @param {{left:number, top:number}} pos 存下来的（或正在拖的）坐标
     * @param {{w:number, h:number, pw:number, ph:number}} view 视口与面板尺寸
     * @returns {{left:number, top:number}} 一定在视口内的坐标
     */
    function clampPanelPos(pos, view) {
        const v = view || {};
        const w = Number(v.w) > 0 ? Number(v.w) : 1200;
        const h = Number(v.h) > 0 ? Number(v.h) : 800;
        const pw = Number(v.pw) > 0 ? Number(v.pw) : 340;
        const ph = Number(v.ph) > 0 ? Number(v.ph) : 240;

        // 面板比视口还宽/还高时，"整个放下"做不到 —— 退回"至少留一角"。
        const maxLeft = (w >= pw) ? (w - pw) : Math.max(0, w - PANEL_MIN_VISIBLE);
        const maxTop = (h >= ph) ? (h - ph) : Math.max(0, h - PANEL_MIN_VISIBLE);

        // ★ 读不出来/不是数就当 0 —— 存盘内容是可以被人手改坏的，
        //   而 NaN 一旦流进 style.left，面板会**静默消失**
        //   （`left:NaNpx` 是无效值，浏览器直接丢掉整条声明）。
        let left = Number(pos && pos.left);
        let top = Number(pos && pos.top);
        if (!isFinite(left)) left = 0;
        if (!isFinite(top)) top = 0;

        return {
            left: Math.max(0, Math.min(left, maxLeft)),
            top: Math.max(0, Math.min(top, maxTop)),
        };
    }

    /** 面板挪到哪就记哪。按站点分开存，互不干扰。 */
    function savePanelPos(key, pos) {
        if (!key) return;
        const all = storeGet(STORE.PANEL_POS, {});
        all[key] = { left: Math.round(pos.left), top: Math.round(pos.top) };
        storeSet(STORE.PANEL_POS, all);
    }

    function loadPanelPos(key) {
        if (!key) return null;
        const all = storeGet(STORE.PANEL_POS, {});
        const p = all && all[key];
        return (p && typeof p === 'object') ? p : null;
    }

    /**
     * 把面板做成可以按着标题栏拖。
     *
     * ★ 三个必须做对的地方：
     *   ① **别让拖拽吃掉按钮的点击**。标题栏里有一个「×」（收起/展开）。
     *      如果 mousedown 落在按钮上还照常开始拖，那个按钮就时灵时不灵
     *      —— 表现是"点了没反应"，而且只在手抖了一下的时候才复现。
     *   ② **移动/松开必须挂在 document 上**，不能挂在面板上：
     *      鼠标拖快了会跑到面板外面，挂在面板上的话那一刻就断了，
     *      表现为"拖到一半突然掉下来"。
     *   ③ **拖的时候禁止选中文字**，否则会拖出一片蓝色高亮，
     *      而且日志框里的文字被选走后面板看着很脏。
     */
    function makeDraggable(panel, key) {
        const head = panel.querySelector('.cslh-head');
        if (!head) return;

        const view = function () {
            return {
                w: window.innerWidth || 1200,
                h: window.innerHeight || 800,
                pw: panel.offsetWidth || 340,
                ph: panel.offsetHeight || 240,
            };
        };

        // ── 恢复上次的位置 ──
        const saved = loadPanelPos(key);
        if (saved) {
            const c = clampPanelPos(saved, view());
            panel.style.left = c.left + 'px';
            panel.style.top = c.top + 'px';
            panel.style.right = 'auto';
        }

        let dragging = false;
        let offX = 0;
        let offY = 0;

        const onMove = function (e) {
            if (!dragging) return;
            const c = clampPanelPos(
                { left: e.clientX - offX, top: e.clientY - offY },
                view()
            );
            panel.style.left = c.left + 'px';
            panel.style.top = c.top + 'px';
            panel.style.right = 'auto';
            // 拖拽期间别让浏览器顺手去滚页面
            if (e.cancelable) e.preventDefault();
        };

        const onUp = function () {
            if (!dragging) return;
            dragging = false;
            document.removeEventListener('mousemove', onMove, true);
            document.removeEventListener('mouseup', onUp, true);
            document.body.style.userSelect = '';
            // ★ 存盘放在**松开**的时候，不是每次 mousemove ——
            //   一次拖拽会触发几十上百次移动，每次都写一遍
            //   GM_setValue 是在 LevelDB 上落盘的，会明显卡手。
            savePanelPos(key, {
                left: parseFloat(panel.style.left) || 0,
                top: parseFloat(panel.style.top) || 0,
            });
        };

        head.addEventListener('mousedown', function (e) {
            // ① 点在标题栏的按钮上时**不拖** —— 那是要用的按钮
            let t = e.target;
            let guard = 0;
            while (t && t !== head && guard < 20) {
                if (String(t.tagName || '').toLowerCase() === 'button') return;
                t = t.parentElement;
                guard += 1;
            }
            if (e.button !== 0) return;          // 只认左键

            const r = panel.getBoundingClientRect();
            offX = e.clientX - r.left;
            offY = e.clientY - r.top;
            dragging = true;

            document.body.style.userSelect = 'none';
            // ② 挂在 document 上，而且要**捕获阶段**：
            //   否则页面自己的 mousemove 处理器可能先 stopPropagation，
            //   拖拽就在某些页面上时断时续。
            document.addEventListener('mousemove', onMove, true);
            document.addEventListener('mouseup', onUp, true);
            if (e.cancelable) e.preventDefault();
        });
    }

    function buildShell(title, key) {
        installStyle();

        const logBox = el('div', { class: 'cslh-log' });
        logSink = function (line) {
            const cls = line.level === 'error' ? 'e' : line.level === 'warn' ? 'w' : line.level === 'ok' ? 'o' : '';
            const time = line.at.toTimeString().slice(0, 8);
            const div = el('div', { class: cls, text: time + '  ' + line.text });
            logBox.appendChild(div);
            logBox.scrollTop = logBox.scrollHeight;
        };
        // 把之前已经记下的日志补上
        LOG_LINES.forEach(logSink);

        const body = el('div', { class: 'cslh-body' });
        const panel = el('div', { class: 'cslh-panel' }, [
            el('div', { class: 'cslh-head' }, [
                el('span', { text: title }),
                el('button', {
                    text: '×',
                    title: '收起 / 展开（按住蓝色标题栏可以拖动面板）',
                    onclick: function () {
                        body.style.display = body.style.display === 'none' ? '' : 'none';
                    },
                }),
            ]),
            body,
        ]);

        document.body.appendChild(panel);
        makeDraggable(panel, key);
        return { panel: panel, body: body, logBox: logBox };
    }

    /**
     * 开工 / 收工时切换面板上那几个按钮的可用状态。
     *
     * ★★★★★ 3.2.47：加"中止"按钮。
     *
     * ── 为什么必须有它（这不是"锦上添花"）──
     *
     *   改之前，两个大循环里**早就有**中止的出口：
     *       if (ytState.stop) { log('已手动停止。'); break; }
     *       if (playState.stop) { log('收到停止，这一批停在 …'); break; }
     *   而 `stop` 这个标志**从头到尾没有任何地方把它设成 true**。
     *   也就是说：那两条出口是**死的** —— 代码里写着"可以停"，
     *   而人**没有任何办法停**。这比不写更坏：
     *   读代码的人会以为这个能力存在。
     *
     *   ★ 真机上这很具体：这一批要建 17 条 CSL，每条要烧一份不可回收的配额。
     *     中途发现"网址填错了""模板选错了"，**唯一的办法是关掉标签页** ——
     *     而关标签页会留下一个没走完的向导（那个向导里可能已经点了保存）。
     *
     * ── 两条刻意的设计 ──
     *
     *   ① **中止是"做完当前这条再停"，不是"立刻打断"。**
     *      半路劈开会同时坏两件事：
     *        · 页面上留一个没走完的创建向导 → 下一条一开工就撞上
     *          「页面已经停在创建向导里了」那道闸（而那句报错像"选择器配错了"）
     *        · 更糟的是**已经点下去的保存可能已经生效了** ——
     *          这一条就处在"建了、但没记账"的模糊状态。
     *          它不在 `PLAY_DONE` 里 → 重跑会**再建一个**（配额不回收）；
     *          记上呢，又可能在没建出来时**永远补不上**。
     *      ★ 所以"停在一条的边界上"是**唯一安全的中止点**，
     *        而这件事必须**在日志里说清楚** —— 用户按下去之后要等一会儿，
     *        不解释的话他会以为按钮没生效，然后再按几次、甚至去关标签页。
     *
     *   ② **按过之后按钮不置灰**，只把文字改成"正在停…"。
     *      置灰会让人分不清"按上了"和"按了没反应"；
     *      而重复按是**无害**的（第二下只会再打一句"已经在停了"）。
     *      ★ 这一点跟"开始"按钮正相反：开始按钮运行中必须置灰
     *        （重复点会开两批），中止按钮必须让人能一直按。
     */
    function setRunningUI(running) {
        ['yt', 'play'].forEach(function (k) {
            const b = UI[k] && UI[k].startBtn;
            if (b) {
                b.disabled = running;
                b.textContent = running ? '运行中…' : (k === 'yt' ? '开始上传' : '生成 CSL');
            }
            // ★ 中止按钮：**只有运行时**才可用（平时一片灰，避免误点）。
            //   文字每次都复位 —— 上一轮停在"正在停…"的话，下一轮开工会
            //   带着这个字样开始，而那时它已经没在停了。
            const a = UI[k] && UI[k].abortBtn;
            if (a) {
                a.disabled = !running;
                a.textContent = '中止';
            }
        });
    }

    /**
     * 请求中止。`which` 是 `'yt'` / `'play'`。
     *
     * ★ 三种情况的措辞**必须分开** —— 它们的修法完全不同：
     *   · 没在跑     → 什么都不用做（不是错误，别吓人）
     *   · 已经在停了 → 让人**安心**（"已经在停了"），他多半是等急了又按了一下
     *   · 第一次按    → 说清"停在哪"、"要等多久"、"现在已经建出来的那些算数"
     *
     * ★★ 合并成一句"已请求停止"是最省事的写法，但它对第二种人（等急了）
     *   什么忙都帮不上 —— 而那种时刻恰恰是最需要一句准话的时刻。
     */
    function requestStop(which) {
        const st = which === 'yt' ? ytState : playState;
        const who = which === 'yt' ? '上传' : 'CSL';

        if (!st.running) {
            log('[' + who + '] 现在没有在跑的任务 —— 不用中止。', 'warn');
            return;
        }
        if (st.stop) {
            log('[' + who + '] **已经在停了** —— 收到过一次了，'
                + '会在当前这条做完之后停。再按多少次都是这个结果。',
                'warn');
            return;
        }

        st.stop = true;
        const ab = UI[which] && UI[which].abortBtn;
        if (ab) ab.textContent = '正在停…';

        log('[' + who + '] ⏹ 收到**中止**。'
            + '\n    ★ 停法是：**当前这条做完就停**，不会半路劈开 —— '
            + '因为半路停会留下一个没走完的流程，'
            + '而更麻烦的是**已经点下去的保存可能已经生效**，'
            + '那一条就处在"建了、但没记账"的模糊状态（重跑会再建一个，'
            + '而配额不回收）。'
            + '\n    ★ 所以要等**当前这条**走完，可能还要十几秒 —— '
            + '按钮文字已经变成「正在停…」，那表示收到了，不用再按。'
            + '\n    ★ 已经建出来的那些**照常记账**（不会被这个中止撤掉）。'
            + '剩下没开工的一条都不建。', 'warn');
    }

    /**
     * 把"上传记录有多少条 / 上次备份是什么时候多少条"画到面板上。
     *
     * ★★★ 为什么这两个数字**必须显示**，不能只放在日志里：
     *
     *   `清理上传记录` 是一个**不可逆**的动作（清完 Play 侧就没有视频列表了）。
     *   人在按它之前想知道的是两件事：
     *     ① 我**要清掉多少条**？       → 清 0 条和清 20 条，按下去的手感完全不同
     *     ② 万一清错了，**还能找回来吗**？→ 这就是"上次备份"那一行存在的全部理由
     *   ★ 只写"已备份"是不够的 —— 那句话无法证伪。
     *     写出**时间和条数**才能证：条数是清之前那一刻的数、时间就是那一刻。
     *     （同一条规矩：本项目别处也要求"动作之后要能回读"，这里回读的是备份本身。）
     */
    function renderRecHint() {
        if (!UI.yt.recHint) return;
        const n = videoRecordCount();
        const b = loadVideoBackup();

        let s = '上传记录：' + n + ' 条'
            + (n ? '' : '（还没有记录 —— 传完视频才会有）');
        // ★ 3.2.49：归档是**栈**，所以要把"有几份"一起说出来 ——
        //   只说"上次归档"的话，用户不知道前面还有没有更早的几批，
        //   而"只留最新一份"正是 3.2.47 那个会被第二次归档覆盖掉的毛病。
        const st = loadVideoArchiveStack();
        if (b) {
            s += '\n上次归档：' + b.list.length + ' 条，' + fmtWhen(b.at);
            if (st.length > 1) {
                s += '（一共存着 ' + st.length + ' 批，取回时给**最近**那批）';
            }
        } else {
            s += '\n上次归档：**还没有过**（第一次归档时会自动存）';
        }

        // ★ 3.2.56：待补传 —— 上次没传成的那些。
        //   ★ 数字**必须显示**：这是"要不要再跑一趟"的唯一依据。
        //     不显示的话，用户对上一批的印象只剩"好像有一条没传"，
        //     而他会因此把整批重跑一遍 —— 那才是真的浪费。
        const pend = loadPending();
        if (pend.length) {
            s += '\n待补传：**' + pend.length + ' 条**（上次没传成的）';
            // 只列前 3 个：面板这一行是**提示**，完整清单靠按钮点出来。
            pend.slice(-3).forEach(function (x) {
                s += '\n  · ' + String(x.fileName);
            });
            if (pend.length > 3) s += '\n  · ……还有 ' + (pend.length - 3) + ' 条';
        }

        UI.yt.recHint.textContent = s;

        // ★ 没有备份时，"恢复"按钮**禁用**而不是"点了报错" ——
        //   一个按下去只会报错的按钮，比一个灰着的按钮更让人困惑。
        if (UI.yt.restoreRecords) UI.yt.restoreRecords.disabled = !b;
        if (UI.yt.clearRecords) UI.yt.clearRecords.disabled = !n;
        // ★ 3.2.56：待补名单空着的时候，"只勾待补的"和"清空"都禁用 ——
        //   点下去只会打一句"名单是空的"，那是没意义的交互。
        //   （"选目录之前"也一样：队列是空的，勾不了任何东西。）
        if (UI.yt.onlyPending) {
            UI.yt.onlyPending.disabled = !pend.length || !ytState.entries.length;
        }
        if (UI.yt.clearPending) UI.yt.clearPending.disabled = !pend.length;
    }

    /** 把 ISO 时间说成一句人话。读不出来就原样吐回去 —— 不假装知道。 */
    function fmtWhen(iso) {
        if (!iso) return '（时间读不到）';
        const d = new Date(iso);
        if (isNaN(d.getTime())) return String(iso);
        const pad = function (v) { return (v < 10 ? '0' : '') + v; };
        return d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate())
            + ' ' + pad(d.getHours()) + ':' + pad(d.getMinutes());
    }

    /**
     * 清理上传记录 —— 先问清楚，再清。
     *
     * ★★★★★ 三条硬要求：
     *
     *   ① **正在跑的时候不许清**。这一条比看起来重要：
     *      `runYtQueue` 开头有 `const records = loadVideos();`，
     *      然后每传完一条就 `records.push(…)` + `saveVideos(records)`。
     *      也就是说循环**手里捏着一份内存副本** ——
     *      中途清空存储的话，下一条传完那记 `saveVideos(records)`
     *      会把**清掉的内容原样写回来**，记录**复活**。
     *      而用户看到的是"我明明清了、它又回来了"，像见了鬼。
     *   ② **先把要归档什么说出来**，再问确认。只说"确定吗"是没用的 ——
     *      人不知道自己在对什么点头。
     *   ③ **归档没落地就不能清**（`clearVideoRecords` 返回 -1 时）。
     *      这时候要**把原因说出来**，因为"清不掉"这件事本身也需要解释。
     *
     *   ★★ 3.2.49：这个动作的**名字是"归档"，不是"删除"**。
     *     运营那句「之前的视频记录不显示」要的是"换一批"，
     *     不是"这批不要了"。所以措辞里必须说清两件事：
     *       · 面板上**看不见了**（这是他要的效果）
     *       · 但**还在**，能取回 —— 而且**在导出成 md 之前建议先导出**
     *         （见 `tools/export-video-records.py`）。
     *     ★ 只说"清空"会让人以为数据没了，于是不敢点；
     *       只说"归档"又会让人以为脚本里还能翻到 —— **两个都要说**。
     */
    function askClearVideoRecords() {
        if (ytState.running || playState.running) {
            log('现在有任务在跑 —— **先中止、等它停稳**再清记录。'
                + '\n    ★ 这不是小心过头：跑的过程中脚本手里捏着一份'
                + '内存里的记录副本，中途清掉的话，下一条传完会把它'
                + '**原样写回来** —— 记录会"复活"，看着像没清掉。', 'error');
            return;
        }

        const list = loadVideos();
        const n = Array.isArray(list) ? list.length : 0;
        if (!n) {
            log('存储里本来就没有上传记录，不用清。', 'warn');
            renderRecHint();
            return;
        }

        // ② 把"要归档什么"摆出来 —— 条目多的时候只报个数
        const withLink = list.filter(function (r) { return r && r.videoId; }).length;
        log('准备**归档**上传记录：**' + n + ' 条**（其中 ' + withLink + ' 条有 YouTube 链接，'
            + (n - withLink) + ' 条没拿到链接）。', 'info');
        log('  ★ 归档之后 **Play 侧的视频列表就空了** —— 那个列表就是从这份记录读的，'
            + '而它推不回来（YouTube 那边只看得到"传过什么"，'
            + '对应不到本地是哪个文件）。', 'warn');
        log('  ★ 这是**归档**，不是删除：面板上看不见了，但**还留着**，'
            + '随时可以「取回上次归档」。', 'info');
        // ★ 3.2.49：这一句是今天才加的 —— 归档**只存在浏览器里**，
        //   清缓存/换电脑就没了。而 md 存档在视频文件夹里，不会跟着没。
        //   ★ 不说的话，用户会以为"归档了 = 安全了"。
        log('  ★★ 归档**只存在浏览器里**（清缓存、换电脑就没了）。'
            + '\n     要长期留着，先跑一次：`python tools/export-video-records.py`'
            + '\n     （它会把这份对应关系写成 md，放进视频素材文件夹。）', 'warn');

        const okGo = typeof confirm === 'function'
            ? confirm('归档这 ' + n + ' 条上传记录（不再显示）？\n\n'
                + '· 会先自动存一份，之后可以用「取回上次归档」拿回来\n'
                + '· 归档之后 Play 侧的视频列表会变成空的\n'
                + '· ★ 归档只存在浏览器里 —— 要长期留，先导出成 md\n\n'
                + '确定继续吗？')
            : true;   // 没有 confirm 的环境（测试/某些管理器）→ 视为确认
        // ★ 没有 `confirm` 时**不假装问过了**：日志里要留一句，
        //   否则读日志的人以为有人确认过。
        if (typeof confirm !== 'function') {
            log('  · （这个环境没有确认框，直接往下走 —— 归档已经做了）', 'warn');
        }
        if (!okGo) {
            log('已取消，什么都没动。', 'info');
            return;
        }

        const cleared = clearVideoRecords();
        if (cleared === -1) {
            // ③ 归档没落地 → 没有清
            log('**归档没成功，所以没有清** —— 记录一条都没动。', 'error');
            log('  ★ 为什么不"清完再说"：这个动作的退路就是那份归档，'
                + '退路没铺好就不该迈这一步。'
                + '\n  ★ 可能的成因：油猴存储写不进去（配额满 / 管理器限制）。'
                + '可以先在管理器的存储面板里看看 `csl_helper_videos` 有多大。', 'error');
            renderRecHint();
            return;
        }

        const st = loadVideoArchiveStack();
        log('✓ 已归档 ' + cleared.cleared + ' 条（面板上看不见了，但**还留着** —— '
            + '点「取回上次归档」就能回来）。', 'ok');
        if (st.length > 1) {
            log('  · 归档栈里现在存着 ' + st.length + ' 批（取回时给**最近**那批）。', 'info');
        }

        // ★★★★★ 3.2.53：把"归档之后还认不认得这批"**说出来**。
        //   这是归档留下的一个**看不见的后果**：清空的是"这一批传了什么"，
        //   而这批文件名已经进了永久名单 —— **下次扫目录时它们照样显示"已上传"**。
        //   ★ 不说的话，用户会以为"归档 = 这批当没传过"，然后准备去重传一遍。
        reportArchiveEver(cleared);

        log('  ★ **Play 那一页需要刷新一下** —— 它的列表是渲染时读的，'
            + '不刷新的话面板上还显示着旧的几条。', 'warn');
        renderRecHint();
    }

    /**
     * 归档之后，把「这批还认不认得」说出来。
     *
     * ★ 为什么抽成独立函数（而不是内联在 `doClearVideoRecords` 里）：
     *   **"源码里有这句话"和"这句话会被说出来"是两件事** ——
     *   内联的话只能靠 `slice + 正则` 验"我写了没"，
     *   而把 `if` 条件改成 `if (false)` 那种坏法是验不出来的。
     *   抽出来就能**真的调一遍**（还自带反向断言：没问题时不许出声）。
     */
    function reportArchiveEver(cleared) {
        log('  · 「已上传」的标记**不受归档影响** —— 这 ' + cleared.cleared
            + ' 个文件下次扫目录时照样显示已上传（永久名单里共 '
            + cleared.everTotal + ' 个）。', 'info');
        if (cleared.everMissing > 0) {
            // 名单是"归档之后还认不认得这批"的唯一依据，没进去就是**真的没有依据**了
            log('  ★★ 有 ' + cleared.everMissing + ' 个**没能进永久名单**'
                + '（存储写不进去）—— 下次扫目录时它们会被当成"没传过"。'
                + '\n     → 想重传之前先看一眼存档 md，别直接整批跑。', 'error');
        }
    }

    /** 把上次归档写回去。同样：先把要取回什么说出来。 */
    function doRestoreVideoRecords() {
        if (ytState.running || playState.running) {
            log('现在有任务在跑 —— 先中止、等它停稳再取回记录。', 'error');
            return;
        }
        const b = loadVideoBackup();
        if (!b) {
            log('没有归档可以取回（从来没归档过，或者被管理器清掉了）。', 'warn');
            renderRecHint();
            return;
        }

        const before = videoRecordCount();
        log('准备取回上次归档：' + b.list.length + ' 条（' + fmtWhen(b.at) + ' 那时候存的）',
            'info');
        // ★ 覆盖语义要**主动说出来**。合并听起来更"安全"，
        //   但它会让"现在这份是怎么来的"说不清（谁也没见过的混合体）。
        log('  ★ 这是**覆盖**，不是合并：当前这 ' + before + ' 条会被整份换掉。', 'warn');

        const okGo = typeof confirm === 'function'
            ? confirm('用 ' + fmtWhen(b.at) + ' 那份归档（' + b.list.length + ' 条）'
                + '覆盖当前的 ' + before + ' 条记录？')
            : true;
        if (!okGo) {
            log('已取消，什么都没动。', 'info');
            return;
        }

        const n = restoreVideoRecords();
        log('✓ 已取回 ' + n + ' 条（来自 ' + fmtWhen(b.at) + ' 那份归档）。', 'ok');
        // ★ 3.2.49：取回**不弹出**归档 —— 归档是历史，取回是复制回来。
        //   弹出的话，取回一次就少一批，而"我只是想看看"也会损失一份。
        log('  · 那份归档**还在栈里**（取回是复制，不是搬走）—— '
            + '再取一次还是同一份。', 'info');
        log('  ★ 同样地，**Play 那一页刷新一下**才会看到。', 'warn');
        renderRecHint();
    }

    // ── 外部上传记录导入（3.2.61 新增） ──
    //
    // 背景：这套脚本自己传的视频，记录是它自己写的。但从 2026-09 起多了一条路 ——
    // 用 YouTube Data API 在脚本外部批量传（Python 工具，见 youtube-api-upload skill）。
    // 那些视频在 YouTube 上真实存在、有 videoId，可 `csl_helper_videos` 里没有它们，
    // Play 侧就找不到链接、建不出对应的 CSL。
    //
    // 之前只能靠人把链接一条条抄进面板 —— 那是手滑的来源，条数一多就没人愿意做。
    // 这里开一个口子：读一份 JSON，把「文件名 → videoId」并进现有记录。
    //
    // ★ 为什么不直接写油猴的 LevelDB：
    //   那要关掉浏览器、格式脆弱，而且写失败**还是静默的**。
    //   面板导入是唯一"写在同一个进程里、写完能立刻回读"的路。

    /**
     * 解析外部导入的上传记录。**纯函数**：不碰 DOM、不碰存储。
     *
     * 认两种形状（都是实际会遇到的）：
     *   · 数组  `[{fileName|file, videoId, url?, title?, at?}, ...]`
     *     —— `tools/export-video-records.py` 和 API 批量上传工具导出的都是这个
     *   · 字典  `{fileName: {videoId, url?, at?}, ...}`
     *     —— API 工具的台账 `uploaded.json`
     *
     * 返回 `{records, skipped}`。
     *
     * ★ 为什么"多认一种形状"值得写：导出来源不止一个，
     *   而让人先手工转一遍格式，他会在转的过程中顺手改错东西 ——
     *   那比多写十行解析代码贵得多。
     */
    function parseImportedRecords(text) {
        let data;
        try {
            data = JSON.parse(String(text || ''));
        } catch (e) {
            throw new Error('不是合法的 JSON（' + String(e && e.message || e) + '）');
        }

        const raw = [];
        if (Array.isArray(data)) {
            data.forEach(function (r) { if (r && typeof r === 'object') raw.push(r); });
        } else if (data && typeof data === 'object') {
            Object.keys(data).forEach(function (k) {
                const v = data[k];
                if (!v || typeof v !== 'object') return;
                const rec = {};
                Object.keys(v).forEach(function (f) { rec[f] = v[f]; });
                // 字典形状里，键本身就是文件名 —— 记录里没有就补上
                if (!rec.fileName && !rec.file) rec.fileName = k;
                raw.push(rec);
            });
        } else {
            throw new Error('顶层既不是数组也不是对象，看不出是什么格式');
        }

        const skipped = { noName: 0, noId: 0, dup: 0, notOk: 0, privateVid: 0 };
        const byName = {};
        const order = [];

        raw.forEach(function (r) {
            const name = String(r.fileName || r.file || r.name || '').trim();
            // videoId 三种来源都试：直接给的 id、url、或者 `id` 字段
            const vid = extractVideoId(r.videoId || r.url || r.id || '');

            if (!name) { skipped.noName += 1; return; }
            if (!vid) { skipped.noId += 1; return; }

            // ★★ 显式 `ok: false` 的不收。
            //   API 工具的失败记录里**是有 videoId 的** —— 可见性校验没过那条，
            //   就带着一个 videoId 和一句 problem。只按 videoId 收，会得到一条
            //   "看起来正常、实际用不了"的记录，而下游拿它建 CSL 必然失败 ——
            //   失败还发生在**烧掉一份不可回收的配额之后**。
            //   ★ 必须写成 `=== false` 严格比较：字典台账里根本没有 `ok` 字段，
            //     `undefined !== false` 才放行。写成 `!r.ok` 会把它整批杀掉。
            if (r.ok === false) { skipped.notOk += 1; return; }

            // ★★ `private` 的不收：Play 的 Preview Video 只接受 public / unlisted。
            //   收进来只是让下游白跑一趟，而且报错点离得很远（点「保存」的时候）。
            const privacy = String(r.privacy || '');
            if (privacy === 'private') { skipped.privateVid += 1; return; }

            if (Object.prototype.hasOwnProperty.call(byName, name)) {
                // ★ 同名多条：**留最后一条**，位置仍按首次出现。
                //   跟 3.2.21 那条教训一致 —— 运营清重复投稿时删的是旧的、留的是新的，
                //   而存储是追加写，所以"最后一条 = 最近一次上传"。
                skipped.dup += 1;
            } else {
                order.push(name);
            }

            byName[name] = {
                relPath: String(r.relPath || name),
                fileName: name,
                size: Number(r.size) > 0 ? Number(r.size) : 0,
                title: String(r.title || ''),
                videoId: vid,
                url: canonicalVideoUrl(vid),
                state: 'published',
                at: String(r.at || r.uploadedAt || '') || new Date().toISOString(),
            };
        });

        return {
            records: order.map(function (n) { return byName[n]; }),
            skipped: skipped,
        };
    }

    /**
     * 把导入的记录并进现有记录。**纯函数**。
     *
     * ★ 只补「还没有链接」的，**不覆盖**已有的：
     *   现有记录是本脚本自己传的，videoId 是页面回读拿到的；导入的是外部来源。
     *   同名时谁更可信无法判断，而覆盖错了的表现是
     *   **"CSL 指向一条别的视频"** —— 页面不报错、流程也走完，只有结果不对。
     *   `overwrite` 参数留着是为以后的显式场景，面板上不给这个选项。
     *
     * 返回 `{list, added, filled, kept}`，四个都在日志里报出来 ——
     * 只说"导入了 N 条"会让"到底改了什么"说不清。
     */
    function mergeVideoRecords(existing, incoming, overwrite) {
        const out = (existing || []).slice();
        const idx = {};
        out.forEach(function (r, i) { if (r && r.fileName) idx[r.fileName] = i; });

        const added = [];
        const filled = [];
        const kept = [];

        (incoming || []).forEach(function (r) {
            if (!r || !r.fileName) return;

            if (!Object.prototype.hasOwnProperty.call(idx, r.fileName)) {
                idx[r.fileName] = out.length;
                out.push(r);
                added.push(r.fileName);
                return;
            }

            const i = idx[r.fileName];
            const cur = out[i];
            if (cur && cur.videoId && !overwrite) {
                kept.push(r.fileName);
                return;
            }

            // 补链接：本地那条的 relPath / size 更准（它扫的是真目录），保留
            out[i] = Object.assign({}, cur || {}, r, {
                relPath: (cur && cur.relPath) || r.relPath,
                size: (cur && cur.size) || r.size,
            });
            filled.push(r.fileName);
        });

        return { list: out, added: added, filled: filled, kept: kept };
    }

    /** 弹文件选择框，读进来交给 `importRecordsFromText`。 */
    function doImportVideoRecords() {
        if (ytState.running || playState.running) {
            log('现在有任务在跑 —— 先中止、等它停稳再导入。', 'error');
            return;
        }

        const input = el('input', {
            type: 'file',
            accept: '.json,application/json',
            style: 'display:none',
        });
        document.body.appendChild(input);

        input.addEventListener('change', function () {
            const file = input.files && input.files[0];
            if (!file) { input.remove(); return; }

            const reader = new FileReader();
            reader.onload = function () {
                try {
                    importRecordsFromText(String(reader.result || ''), file.name);
                } catch (e) {
                    log('✕ 导入失败：' + String(e && e.message || e), 'error');
                } finally {
                    input.remove();
                }
            };
            reader.onerror = function () {
                log('✕ 读文件失败：'
                    + String(reader.error && reader.error.message || '未知原因'), 'error');
                input.remove();
            };
            reader.readAsText(file, 'utf-8');
        });

        input.click();
    }

    /**
     * 解析 → 合并 → 存 → **回读确认**。
     *
     * ★ 回读不是保险，是必需：`storeSet` 内部 try/catch 吞错（写失败不抛），
     *   不回读的话，"已经导进去了"就是一句没有依据的话 ——
     *   而下游（Play 侧建 CSL）会拿这份记录去找链接，找不到就静默少建一条。
     */
    function importRecordsFromText(text, sourceName) {
        const parsed = parseImportedRecords(text);

        if (!parsed.records.length) {
            log('这个文件里没有可导入的记录：'
                + '缺文件名 ' + parsed.skipped.noName + ' 条、'
                + '缺/认不出 videoId ' + parsed.skipped.noId + ' 条。', 'warn');
            return { added: 0, filled: 0, kept: 0, missing: [] };
        }

        const before = loadVideos();
        const merged = mergeVideoRecords(before, parsed.records, false);
        saveVideos(merged.list);

        // 回读
        const after = loadVideos();
        const stored = {};
        after.forEach(function (r) { if (r && r.fileName && r.videoId) stored[r.fileName] = r.videoId; });
        const touched = merged.added.concat(merged.filled);
        const missing = touched.filter(function (n) { return !stored[n]; });

        // ★ 丢弃原因要分组报出来 —— 只说"导入 N 条"，
        //   运营就没法判断"少的那些是为什么少的"，而这正是他要核的东西。
        const sk = parsed.skipped;
        const drops = [];
        let dropTotal = 0;
        if (sk.noId) { drops.push('认不出 videoId ' + sk.noId); dropTotal += sk.noId; }
        if (sk.notOk) { drops.push('标记失败 ' + sk.notOk); dropTotal += sk.notOk; }
        if (sk.privateVid) { drops.push('private 用不了 ' + sk.privateVid); dropTotal += sk.privateVid; }
        if (sk.dup) { drops.push('同名取最新 ' + sk.dup); dropTotal += sk.dup; }

        log('✓ 导入 ' + sourceName + '：新增 ' + merged.added.length
            + ' 条、补上链接 ' + merged.filled.length
            + ' 条、跳过（已有链接）' + merged.kept.length + ' 条'
            + (drops.length ? '；丢弃 ' + dropTotal + ' 条（' + drops.join('、') + '）' : ''),
            missing.length ? 'warn' : 'ok');

        if (missing.length) {
            log('⚠ 有 ' + missing.length + ' 条写进去后读不回来（油猴存储可能满了）：'
                + missing.slice(0, 3).join('、')
                + (missing.length > 3 ? ' …' : ''), 'error');
        }

        log('  ★ **Play 那一页要刷新一下**才会看到这批。', 'warn');

        renderYtList();
        renderRecHint();

        return {
            added: merged.added.length,
            filled: merged.filled.length,
            kept: merged.kept.length,
            missing: missing,
        };
    }

    // ── YouTube 面板 ──

    function buildYtPanel() {
        const shell = buildShell('CSL Helper · YouTube', 'yt');
        const body = shell.body;

        // 选择目录
        const dirBtn = el('button', {
            class: 'cslh-btn',
            text: '选择视频目录',
            onclick: async function () {
                try {
                    const handle = await pickVideoDirectory();
                    const entries = await scanVideoDir(handle, CONFIG.yt);
                    ytState.entries = entries;

                    log(`目录里找到 ${entries.length} 个视频，共 `
                        + fmtBytes(entries.reduce(function (s, e) { return s + e.size; }, 0)), 'ok');
                    renderYtList();
                } catch (e) {
                    log(e.message, 'error');
                }
            },
        });

        const listBox = el('div', { class: 'cslh-list' });

        // ── 筛选框 ──
        // ★ 72 个视频靠滚动找，逐个点勾，本来就不现实。
        //   所以这里同时给两条路：**筛**（留下要传的）和**批量勾**
        //   （全选 / 全不选 / 反选）。
        UI.yt.filter = el('input', {
            type: 'text',
            placeholder: '筛选：文件名 / 目录名，空格分隔多个词',
            value: ytState.filter || '',
            oninput: function (ev) {
                ytState.filter = ev.target.value;
                renderYtList();
            },
        });

        UI.yt.countHint = el('div', { class: 'cslh-hint' });

        // ★ 只作用于**当前筛选出来的**那些 —— 逻辑在 bulkSetSkip 里，
        //   这里只负责"改完状态重画一遍"。
        function bulk(mode) {
            const n = bulkSetSkip(mode);
            log(({ all: '全选', none: '全不选', invert: '反选' }[mode] || mode)
                + '：动了 ' + n + ' 个（当前筛选出来的）', 'info');
            renderYtList();
        }

        UI.yt.selectAll = el('button', {
            class: 'cslh-btn sec', text: '全选',
            onclick: function () { bulk('all'); },
        });
        UI.yt.selectNone = el('button', {
            class: 'cslh-btn sec', text: '全不选',
            onclick: function () { bulk('none'); },
        });
        UI.yt.invert = el('button', {
            class: 'cslh-btn sec', text: '反选',
            onclick: function () { bulk('invert'); },
        });

        // ── 「只勾待补的」（3.2.56）──
        //
        // ★ 它解决的是运营那句话：「**我不小心切后台导致失败…记得把舍弃的那个上传**」。
        //   待补名单记着"上次没传成的"，而这个按钮把它们**一键勾上**。
        //
        // ★ 为什么不能靠「反选」凑合：待补的通常就一两条，
        //   而他手里这批可能上百个文件 —— 一条条翻出来再勾，
        //   正是他想省掉的事。
        UI.yt.onlyPending = el('button', {
            class: 'cslh-btn sec',
            text: '只勾待补的',
            onclick: function () {
                const r = selectPendingOnly();
                if (r.hit > 0) {
                    log('✓ 已勾上 ' + r.hit + ' 条待补传的'
                        + '（其余**全部取消勾选**）。', 'ok');
                } else {
                    log('待补传名单里没有一条能在当前这批文件里找到。', 'warn');
                    log('  ★ 多半是**目录选错了**（要选当初传那批素材的目录），'
                        + '或者文件被改名 / 移走了。', 'warn');
                }
                if (r.missed.length) {
                    log('  · 有 ' + r.missed.length + ' 条**没找到**：', 'warn');
                    r.missed.slice(0, 8).forEach(function (n) { log('      ' + n, 'warn'); });
                    if (r.missed.length > 8) {
                        log('      …… 还有 ' + (r.missed.length - 8) + ' 条', 'warn');
                    }
                }
                renderYtList();
            },
        });

        // ★ 3.2.56：清空待补名单。
        //   ★ 为什么这件事**不需要二次确认**（跟"归档上传记录"不一样）：
        //     归档清掉的是**推不回来的东西**（文件名 ↔ 链接的对应关系），
        //     而待补名单只是**待办提示** —— 那些文件本来就没记账，
        //     清掉名单**不会**让它们被跳过（"跳过已上传的"读的是成功记录）。
        //   ★★ 所以日志里要把这一点说出来，否则用户会以为"清掉 = 放弃补传"。
        UI.yt.clearPending = el('button', {
            class: 'cslh-btn sec',
            text: '清空待补名单',
            onclick: function () {
                const n = clearPending();
                if (!n) { log('待补名单本来就是空的。', 'info'); return; }
                log('✓ 已清空待补名单（' + n + ' 条）。', 'ok');
                log('  ★ 这只是把**提醒**去掉了 —— 那些文件照样没传成；'
                    + '它们没记账，下次勾上照样会传。', 'info');
                renderRecHint();
            },
        });

        // ── 「已上传」相关的三个控件（3.2.51）──
        //
        // ★ 运营原话：「上传过的视频标注 + 上传过的不上传的选项，
        //   视频一多就筛选不来了」。
        //   ★ 背景：这一批 **189 个**，一次最多 20 个 → 要跑 9 批多，
        //     中途还可能失败停下。**每次接着跑之前都得知道哪些传过了。**
        //
        // ★★ 三个控件的分工是刻意分开的（显示 / 勾选 / 执行是三层）：
        //     · 「只看未上传」 —— 只管**看得见什么**
        //     · 「只勾未上传」 —— 一次把已上传的取消勾选（**看得见效果**）
        //     · 「跳过已上传」 —— 兜底保险，只管**真正会传哪些**（默认开）
        //   ★ 为什么"显示"和"执行"不能合成一个：
        //     合成的话，用户取消勾「只看未上传」的瞬间，
        //     那些"看不见但还勾着"的已上传项会被**重新计入要传的**，
        //     而他完全不会注意到 —— 点开始就重传了。
        UI.yt.hideUploaded = el('input', {
            type: 'checkbox',
            checked: !!ytState.hideUploaded,
            onchange: function (ev) {
                ytState.hideUploaded = !!ev.target.checked;
                renderYtList();
            },
        });
        UI.yt.skipUploaded = el('input', {
            type: 'checkbox',
            checked: ytState.skipUploaded !== false,
            onchange: function (ev) {
                const on = !!ev.target.checked;
                ytState.skipUploaded = on;
                if (!on) {
                    // ★ 关掉保险必须**出声**：这是唯一会让脚本去重传的开关，
                    //   而重传 = 频道上多一份 + 额度不回收。
                    log('★★ 「跳过已上传」**已经关掉** —— 接下来会**重传**'
                        + '以前传过的文件。\n'
                        + '    ★ 这是刻意的（你要重传就关它），但请确认一下：'
                        + '重传会在频道上多出一份，而 YouTube 的上传额度不回收。\n'
                        + '    → 不打算重传的话，现在把它勾回去。', 'warn');
                }
                renderYtList();
            },
        });
        UI.yt.pickUnuploaded = el('button', {
            class: 'cslh-btn sec',
            text: '只勾未上传',
            onclick: function () {
                // ★ 只作用于**当前筛选出来的**那些（跟全选/全不选一个规矩）：
                //   不然"筛出 5 个 → 点它"会把另外 184 个的状态也改了，
                //   而那些根本看不见。
                let off = 0;
                let left = 0;
                ytState.entries.forEach(function (e) {
                    if (!matchYtFilter(e)) return;
                    if (isUploadedEntry(e)) {
                        if (!e.skip) off += 1;
                        e.skip = true;            // 已上传的 → 取消勾选
                    } else {
                        left += 1;
                    }
                });
                log('只勾未上传：取消勾选 ' + off + ' 个已上传的，'
                    + '留下 ' + left + ' 个没传过的勾着（当前筛选范围内）。', 'info');
                // ★ 缓存要失效 —— 否则刚取消勾选完，列表读的还是旧索引。
                forgetUploadedIndex();
                renderYtList();
            },
        });

        UI.yt.visibility = el('select', {}, Object.keys(CONFIG.yt.visibility_texts).map(function (v) {
            return el('option', { value: v, text: v });
        }));
        // ★ 必须显式设一次。select 的默认值是**第一个 option**，
        //   而 visibility_texts 的第一个是 private —— 不设的话
        //   面板上显示的会是"private"，跟 CONFIG 里的默认值（unlisted）不一致，
        //   而且 Play 那边会因为这个校验不过。
        UI.yt.visibility.value = CONFIG.yt.default_visibility;

        UI.yt.autoPublish = el('input', {
            type: 'checkbox',
            checked: CONFIG.yt.auto_publish !== false,
            disabled: CONFIG.yt.auto_publish === false,
        });

        UI.yt.dryRun = el('input', { type: 'checkbox', checked: true });

        UI.yt.startBtn = el('button', {
            class: 'cslh-btn',
            text: '开始上传',
            onclick: function () { runYtQueue(); },
        });

        // ★ 3.2.47：中止按钮。初始**禁用**（没在跑的时候按它没有意义），
        //   真正的可用状态由 `setRunningUI` 统一管。
        UI.yt.abortBtn = el('button', {
            class: 'cslh-btn sec',
            text: '中止',
            disabled: true,
            onclick: function () { requestStop('yt'); },
        });

        // ── 上传记录：显示条数 + 清理 + 恢复 ──
        //
        // ★ 3.2.47。这一块是"数据"区，不是"操作"区，所以放在最下面。
        UI.yt.recHint = el('div', { class: 'cslh-hint' });

        // ── 补录（3.2.57）──
        //
        // ★ 用途：把**已经在频道上、但脚本没记上账**的视频补进记录。
        //   这种视频真的存在（2026-09-21 就丢了一条，见 `manualAddRecord`）。
        //   不补的话：面板显示"没传过"、Play 侧建不了 CSL、**下次跑还会重传**。
        //
        // ★ 它同时是"手动传的片子"的入口 —— 以后在 Studio 里手工传的，
        //   也能补进来，Play 侧照样能给它建 CSL。
        //
        // ★ 两个输入框都**故意不做自动纠错**（比如自动补全 `https://`）：
        //   认不出来时 `extractVideoId` 会明说"认不出"，比悄悄改一下
        //   然后存进去一个错的 id 好 —— 后者会在 Play 侧建出一个坏 CSL。
        UI.yt.manualName = el('input', {
            type: 'text', class: 'cslh-input', placeholder: '文件名',
            style: 'flex:1.2;min-width:0;',
        });
        UI.yt.manualLink = el('input', {
            type: 'text', class: 'cslh-input', placeholder: '视频链接 或 id',
            style: 'flex:1.6;min-width:0;',
        });
        UI.yt.manualAdd = el('button', {
            class: 'cslh-btn sec', text: '补录',
            onclick: function () {
                doManualAdd(UI.yt.manualName, UI.yt.manualLink);
                renderRecHint();
                renderYtList();       // "已上传"标记要立刻出现在列表里
            },
        });
        UI.yt.clearRecords = el('button', {
            class: 'cslh-btn sec',
            // ★ 3.2.49：文案从「清理」改成「**归档（不再显示）**」。
            //   "清理"听起来像"删掉"，而实际它是**留着的** ——
            //   运营今天那句「之前的记录不显示」要的正是这个：
            //   旧的搁一边、新的一批从零开始，以后还能取回来。
            //   ★ 名字错了会让人不敢点（以为点了就没了），
            //     或者点完以为彻底没了（不再去看 md 存档）。
            text: '归档（不再显示）',
            onclick: function () { askClearVideoRecords(); },
        });
        UI.yt.restoreRecords = el('button', {
            class: 'cslh-btn sec',
            text: '取回上次归档',
            onclick: function () { doRestoreVideoRecords(); },
        });

        // ★ 3.2.61：给"脚本外传的视频"留一个入口。
        //   文案里点名「API」，因为"导入 JSON"听起来像给技术人员用的，
        //   而运营要的是"把用另一种方式传的那些接上"这个意思。
        UI.yt.importBtn = el('button', {
            class: 'cslh-btn sec',
            text: '导入外部上传记录（JSON）',
            onclick: function () { doImportVideoRecords(); },
        });

        body.appendChild(el('div', { class: 'cslh-sec' }, [
            dirBtn,
            el('div', { class: 'cslh-row' }, [UI.yt.importBtn]),
            el('div', { class: 'cslh-hint', text: 'API 在外部传完的视频，用这个把链接接进来' }),
        ]));
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-label', text: '视频：' }),
            el('div', { class: 'cslh-row' }, [UI.yt.filter]),
            el('div', { class: 'cslh-row' }, [
                UI.yt.selectAll, UI.yt.selectNone, UI.yt.invert, UI.yt.pickUnuploaded,
            ]),
            // ★ 3.2.56：补传的那一下。单独一行 —— 它跟上面那排
            //   "改一堆状态"的按钮**语义不同**（那是批量改，这是"挑出漏的"），
            //   混在一行里会让人以为它是第四个批量按钮。
            el('div', { class: 'cslh-row' }, [
                UI.yt.onlyPending, UI.yt.clearPending,
            ]),
            // ★ 2026-09-20：这两个勾选框是"视频一多就筛选不过来"的正面回应。
            el('div', { class: 'cslh-row' }, [
                UI.yt.hideUploaded, el('span', { text: '只看未上传' }),
                UI.yt.skipUploaded, el('span', { text: '跳过已上传的' }),
            ]),
            UI.yt.countHint,
            listBox,
        ]));
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-row' }, [
                el('span', { text: '可见性：' }), UI.yt.visibility,
            ]),
            el('div', { class: 'cslh-row' }, [UI.yt.autoPublish, el('span', { text: '传完后自动发布' })]),
            el('div', { class: 'cslh-row' }, [UI.yt.dryRun, el('span', { text: '试运行（只传第 1 条）' })]),
            CONFIG.yt.auto_publish === false
                ? el('div', { class: 'cslh-hint', text: '★ 自动发布被 CONFIG 强制关掉了' })
                : null,
        ]));
        // 诊断：把对话框里"实际有什么"原样报出来，并复制到剪贴板。
        //
        // ★ 什么时候用：卡在某个步骤、又不想再跑一次的时候（跑一次 = 一份配额）。
        //   手动打开 Studio 的上传对话框，点这个按钮，然后 Ctrl+V 把结果发出来。
        //   比 F12 里手抄稳得多，也不用装任何东西。
        //
        // ★★ 最省事的用法是**根本不上传**：打开任意一个**已有视频**的编辑页
        //   （studio.youtube.com/video/<已有id>/edit），这一页用的是同一套
        //   元数据编辑器 —— 受众声明那对 radio、可见性选项、按钮全在，
        //   而且是同一个组件。在这儿点这个按钮，**一个配额都不花**。
        //   先把零成本能确认的确认掉，再去烧配额。
        //   （唯一验不了的是"unlisted 时完成按钮叫什么"，那只能在真机上传时看。）
        UI.yt.diagnose = el('button', {
            class: 'cslh-btn sec',
            text: '诊断对话框（复制结构）',
            onclick: function () {
                const text = dumpDialog('手动');
                copyText(text).then(function (ok) {
                    if (ok) log('  结构快照已复制到剪贴板，Ctrl+V 粘贴发出来就行。', 'ok');
                    else log('  ⚠ 没能自动复制 —— 请手动选中上面那份快照复制。', 'warn');
                });
            },
        });

        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-row' }, [UI.yt.startBtn, UI.yt.abortBtn]),
            el('div', { class: 'cslh-hint', text: '「中止」是**做完当前这条再停**，'
                + '不会半路劈开 —— 半路停会留下一个没走完的流程，'
                + '而且可能已经点了保存。按过之后按钮会变成「正在停…」。' }),
        ]));
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            UI.yt.diagnose,
            el('div', { class: 'cslh-hint', text: '卡住时点它 —— 会把当前对话框里所有的按钮、'
                + '选项（含哪一项已选中）和可滚区域列出来。'
                + '★ 不用真的上传：打开任意已有视频的编辑页点它，一个配额都不花。' }),
        ]));
        // ── 数据区：上传记录 ──
        //
        // ★ 3.2.47。放在**最下面、紧挨日志**：它是"万一要重来"用的，
        //   平时不该抢视线。但它必须**看得见** —— 藏进二级菜单的话，
        //   真需要它的时候（记录乱了、想重来）反而找不到。
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-label', text: '上传记录' }),
            UI.yt.recHint,
            el('div', { class: 'cslh-row' }, [UI.yt.clearRecords, UI.yt.restoreRecords]),
            el('div', { class: 'cslh-hint', text: '★ 这份记录是 **Play 侧唯一的来源**'
                + '（视频列表、文件名、YouTube 链接都从它读）。清掉之后推不回来 —— '
                + '所以清理**永远先自动备份**，随时可以恢复。' }),
            // ★ 3.2.57：补录 —— 把"发出去了但没记上账"的视频补回来。
            el('div', { class: 'cslh-label', text: '补录一条（视频已在频道上、但记录里没有）' }),
            el('div', { class: 'cslh-row' }, [
                UI.yt.manualName, UI.yt.manualLink, UI.yt.manualAdd,
            ]),
        ]));
        body.appendChild(el('div', { class: 'cslh-label', text: '日志' }));
        body.appendChild(shell.logBox);

        UI.yt.listBox = listBox;
        renderYtList();
        // ★ 初始化就要画一次 —— 否则面板刚打开时这一块是空白的，
        //   而"空"和"0 条"在用户眼里是两回事（前者像是坏了）。
        renderRecHint();
    }

    function renderYtList() {
        const box = UI.yt.listBox;
        if (!box) return;
        box.textContent = '';

        if (!ytState.entries.length) {
            if (UI.yt.countHint) UI.yt.countHint.textContent = '';
            box.appendChild(el('div', { class: 'cslh-hint', text: '（还没选目录）' }));
            return;
        }

        const idx = uploadedIndex();
        const visible = ytState.entries.filter(matchYtFilter);
        const picked = ytState.entries.filter(function (e) { return !e.skip; });

        // ★ 2026-09-20：真正会传的那批 = 勾上的 ∩ 看得见的 ∩（若开着跳过）未上传的。
        //   ★★ 这个数**必须**显示出来：它跟"已勾几个"可能不一样，
        //     而它才是点开始之后**真正会发生的事**。
        //     （不显示的话，用户勾了 20 个、以为要传 20 个，实际传了 13 个 ——
        //      而他只会在事后数链接的时候才发现。）
        const willSend = picked.filter(function (e) {
            if (!matchYtFilter(e)) return false;
            if (ytState.skipUploaded && isUploadedEntry(e, idx)) return false;
            return true;
        });
        const upAll = uploadedInEntries(ytState.entries, idx).length;

        if (UI.yt.countHint) {
            // ★ 把"总共多少 / 筛出来多少 / 勾了多少 / **实际会传多少**"一起摆出来。
            //   只显示"勾了 N 个"的话，筛了之后用户没法判断 N 是筛出来的那些
            //   还是全部 —— 而这个区别直接决定点开始会传几个视频。
            let s = `共 ${ytState.entries.length} 个`;
            if (visible.length !== ytState.entries.length) s += `，筛出 ${visible.length} 个`;
            s += `，已勾 ${picked.length} 个`;
            s += ` → **会传 ${willSend.length} 个**`;
            if (upAll) {
                s += `（其中 ${upAll} 个以前传过`;
                s += ytState.skipUploaded ? '，会跳过）' : '，★ 但「跳过已上传」关着，会重传）';
            }
            UI.yt.countHint.textContent = s;
        }

        if (!visible.length) {
            box.appendChild(el('div', {
                class: 'cslh-hint',
                text: ytState.hideUploaded && ytState.entries.length
                    ? '★ 筛完之后一个都不剩 —— 多半是「只看未上传」勾着，'
                      + '而这批全都传过了。取消它看全部。'
                    : '没有匹配「' + ytState.filter + '」的视频。清空筛选框看全部。',
            }));
            return;
        }

        visible.forEach(function (e) {
            const up = idx[String(e.fileName)] || null;
            const willSkip = !!(up && ytState.skipUploaded);

            const cb = el('input', {
                type: 'checkbox',
                checked: !e.skip,
                onchange: function (ev) { e.skip = !ev.target.checked; renderYtList(); },
            });

            // 把 File 是否还活着显示出来 —— 这是整条链上最容易静默断掉的地方
            const alive = fileProblem(e.file) ? '✗' : '✓';

            const nameRow = [el('div', {
                class: 'cslh-name', text: e.fileName, title: e.relPath,
            })];
            if (up) {
                // ★ 标出来"传过"，并且把**链接**放进来 ——
                //   这一条最常见的用途就是"这条传过了，我去看看它长什么样"。
                const when = up.at ? String(up.at).slice(0, 16).replace('T', ' ') : '';
                // ★ 3.2.53：`from === 'ever'` = 这条是从**永久名单**里认出来的
                //   （当前这批的记录已经归档清掉了）。它会**照常被跳过**，
                //   只是面板上拿不出链接了 —— 这一点必须说出来，
                //   否则用户按"已上传"去点开发觉没有链接，会以为标记是错的。
                const onlyEver = up.from === 'ever';
                nameRow.push(el('span', {
                    class: 'cslh-tag',
                    text: willSkip ? '✓ 已上传（会跳过）' : '✓ 已上传',
                    title: '传过 ' + (up.at ? when + '（UTC）' : '（时间读不到）')
                        + (up.url ? '\n' + up.url
                            : onlyEver
                                ? '\n★ 这批记录**已经归档**了，所以面板上拿不出链接。'
                                    + '\n   但"传过"这件事记着 —— 它照样会被跳过。'
                                    + '\n   要链接的话看视频文件夹里的存档 md。'
                                : '\n（这条没拿到链接，但记录在）'),
                    style: 'margin-left:6px;flex:none;',
                }));
            }

            box.appendChild(el('div', {
                class: 'cslh-item' + (willSkip ? ' cslh-item-dim' : ''),
            }, [
                cb,
                el('div', { style: 'flex:1;min-width:0;' }, [
                    el('div', { class: 'cslh-row', style: 'align-items:center;' }, nameRow),
                    el('div', {
                        class: 'cslh-hint',
                        text: fmtBytes(e.size) + '   File ' + alive
                            + (up && up.url ? '   ' + up.url : ''),
                    }),
                ]),
            ]));
        });
    }

    // ── Play 面板 ──

    // ── Play 侧的「已建记录」管理（3.2.58）────────────────────────────
    //
    // ★★★★★ 为什么需要它 —— 运营 2026-09-22 的实测：
    //   YouTube 上还有 29 条视频，而 Play 上只剩 **20 个 CSL**。
    //   原因：**他在 Play 里删过 CSL，而删的时候不会动脚本这份记录**。
    //   → 于是重跑时那些条目被当成"已经建过"**跳过**，
    //     永远补不回来。**这就是"为什么才 20 个"的答案。**
    //
    // ★ 脚本**看不到 Play 后台的列表**（没有 API —— 见方法论文档第 2 节），
    //   所以它没法自己知道"哪几个被删了"。
    //   唯一可行的办法是：**把记录清掉，让人重新挑一遍要建哪几个**。
    //
    // ★★ 为什么不是"自动检测哪些被删了然后只清那些"：
    //   做不到 —— 判据是 Play 后台的列表，而脚本拿不到。
    //   硬猜（比如"链接还活着就该有 CSL"）会在别的地方出错：
    //   一个人**故意**只给部分视频建 CSL 是完全正常的用法。

    /** 脚本认为"已经建过 CSL"的条数。 */
    function playDoneCount() {
        const l = storeGet(STORE.PLAY_DONE, []);
        return Array.isArray(l) ? l.length : 0;
    }

    /**
     * 清空「已建记录」。返回清掉了几个。
     *
     * ★ 只清这一份，**不碰任何别的数据**：
     *   上传记录（VIDEOS）和永久名单（UPLOADED_EVER）跟它没关系，
     *   动了它们会让「跳过已上传」失效 —— 那是另一件事。
     */
    function clearPlayDone() {
        const n = playDoneCount();
        if (n > 0) storeSet(STORE.PLAY_DONE, []);
        return n;
    }

    /**
     * 面板上「清空已建记录」的动作：**先说清后果，再问确认，然后清**。
     *
     * ★★ 后果里最要紧的一条是「**清完之后别全选**」——
     *   清空之后面板不再跳过任何条目，而 Play 上**已经建好的那些还在**。
     *   全选 = 把它们**重复建一遍**，白占配额（CSL 有上限，
     *   而且删出来的配额不会自动补回来）。
     *   ★ 所以这是一次"必须说清楚才不会做错"的操作 —— 不能只弹一句"确定吗"。
     */
    function askClearPlayDone() {
        if (playState.running) {
            log('现在有任务在跑 —— 先中止、等它停稳再动记录。', 'error');
            return 0;
        }

        const n = playDoneCount();
        if (!n) {
            log('「已建记录」本来就是空的 —— 面板现在**什么都不会跳过**。', 'info');
            return 0;
        }

        log('准备清空「已建记录」：**' + n + ' 条**。', 'info');
        log('  ★ 清完之后面板会**列出全部**视频 —— 之前被当成"已经建过"'
            + '而跳过的那些，都会重新出现在列表里。', 'warn');
        log('  ★★ **清完之后别全选**：Play 上已经建好的那些会被**重复建**，'
            + '白占配额（CSL 有上限，删出来的配额不会自动补回来）。'
            + '\n      → **只勾你确实缺的那几个**。', 'warn');

        const okGo = typeof confirm === 'function'
            ? confirm('清空「已建记录」（' + n + ' 条）？\n\n'
                + '· 清完之后面板不再跳过任何条目\n'
                + '· ★ 别全选 —— 已经建好的会被重复建、白占配额\n'
                + '· 只影响这份记录，不动上传记录\n\n'
                + '确定继续吗？')
            : true;
        if (typeof confirm !== 'function') {
            log('  · （这个环境没有确认框，直接往下走）', 'warn');
        }
        if (!okGo) {
            log('已取消，什么都没动。', 'info');
            return 0;
        }

        const cleared = clearPlayDone();

        // ★ 回读：`storeSet` 写失败**不抛错**，不回读的话"已清空"就是
        //   一句没有依据的话 —— 而用户会按它去重跑，然后发现还是被跳过。
        const back = playDoneCount();
        if (back !== 0) {
            log('**清空没成功** —— 记录里还剩 ' + back + ' 条。', 'error');
            log('  ★ 成因：油猴存储写不进去（配额满 / 管理器限制）。', 'error');
            return 0;
        }

        log('✓ 已清空「已建记录」（清掉 ' + cleared + ' 条）。', 'ok');
        log('  ★ 现在**重新挑一遍**要建哪几个，再点「生成 CSL」。'
            + '\n    ★ 上传记录和永久名单**都没动**，「跳过已上传的」照常生效。', 'info');
        return cleared;
    }

    /** 把「已建记录」的条数画到 Play 面板上。 */
    function renderDoneHint() {
        if (!UI.play || !UI.play.doneHint) return;
        const n = playDoneCount();
        UI.play.doneHint.textContent = n
            ? '已建记录：' + n + ' 个 —— 这些**在列表里会被跳过**'
            : '已建记录：**空**（面板不会跳过任何条目）';
        // ★ 空的时候禁用按钮：点下去只会打一句"本来就是空的"，
        //   那是没意义的交互。
        if (UI.play.clearDone) UI.play.clearDone.disabled = !n;
    }

    // ── 按 Play 清单**对齐**记录（3.2.59）──────────────────────────
    //
    // ★★★★★ 为什么 3.2.58 那个「清空」只解决了一半 ——
    //   清空之后面板**不再跳过任何条目**，Play 上已经建好的那些
    //   会重新出现在列表里。而他手上没有一份"Play 上到底有哪几个"的账，
    //   于是要么不敢全选（漏掉该建的），要么全选（把建过的**重复建一遍**，
    //   白占配额 —— 而 CSL 配额删出来不会自动补回来）。
    //
    // ★ 运营 2026-09-22 的原话把需求说得很准：
    //   「你把已经创建的标记，然后没有在这 29 个的记录删了
    //    （除了我刚刚上传到 YouTube 的）」
    //   → 他要的是**把记录对齐到 Play 上真实的样子**，三件事：
    //     ① 已经在 Play 上的      → 标成"已建"（下次别重复建）
    //     ② 视频已经没了的废记录  → 删掉（它们**永远建不出可用的 CSL**）
    //     ③ 刚传上去、还没建 CSL 的 → 留着（这就是接下来要干的活）
    //
    // ★★ 判据从哪来：**用户贴进来的 Play 名单**。
    //   脚本看不到 Play 后台的列表（没有 API，见方法论文档第 2 节），
    //   而"硬猜"会在别的地方出错 —— 一个人**故意**只给部分视频建 CSL
    //   是完全正常的用法。所以名单只能人给，脚本负责对账。
    //
    // ★★★ 为什么"视频还在不在"要**自己去问 YouTube**（而不是看记录里有什么）：
    //   记录里存的只是"当初传过"，视频后来有没有被删，本地**没有任何线索**。
    //   一条指向已删视频的记录：建不出可用的 CSL（页面会指向 404），
    //   也没有别的用途 —— 留着只会让面板越来越长、让人越来越不敢选。

    /**
     * 贴进来的 Play 名单 → 规范化 key 列表。
     *
     * ★ 规范化的规矩**必须和 `cslKeyOf` 一模一样**（去扩展名、折空白、转小写）——
     *   否则"从 Play 复制出来的名字"和"记录里的文件名"永远对不上，
     *   而症状是**整份名单一条都配不上**（会被当成"清单贴错了"）。
     * ★ `#` 开头的行当注释跳过：从文档里连标题一起复制是常事。
     */
    function parsePlayNameList(text) {
        const out = [];
        String(text === null || text === undefined ? '' : text)
            .split(/\r?\n/)
            .forEach(function (line) {
                const s = String(line).trim();
                if (!s || s.charAt(0) === '#') return;
                const k = cslKeyOf({ fileName: s });
                if (k && out.indexOf(k) < 0) out.push(k);
            });
        return out;
    }

    /**
     * 把 Play 名单配到记录的 key 上。返回 `{matched, missing, ambiguous}`。
     *
     * ★★ 允许"**名字是前缀**"：真机上 Play 那边的 CSL 名会**少一截后缀** ——
     *   实测有两条是 `prod-b260326_EMPRESS WU_duojitai_KT_1080`，
     *   而本地文件是 `prod-b260326_EMPRESS WU_duojitai_KT_1080_gqw.mp4`
     *   （人工建的时候名字被改短了）。死按全等匹配的话这两条会被判成
     *   "Play 上没有" → 于是被**重复建一遍**（白占配额）。
     *
     * ★★★ 但前缀匹配**必须唯一**才算数：一个 Play 名对上两个文件时，
     *   谁也说不清是哪一个 —— 这时候宁可**报出来让人看**，
     *   不能挑一个往下走（挑错的那条会被当成"Play 上有"，永远补不上）。
     */
    function matchPlayNames(names, keys) {
        const matched = [];
        const missing = [];
        const ambiguous = [];

        (names || []).forEach(function (n) {
            if (keys.indexOf(n) >= 0) {
                if (matched.indexOf(n) < 0) matched.push(n);
                return;
            }
            const hits = keys.filter(function (k) { return k.indexOf(n) === 0; });
            if (hits.length === 1) {
                if (matched.indexOf(hits[0]) < 0) matched.push(hits[0]);
                return;
            }
            if (hits.length > 1) {
                ambiguous.push({ name: n, hits: hits.slice(0, 4) });
                return;
            }
            missing.push(n);
        });

        return { matched: matched, missing: missing, ambiguous: ambiguous };
    }

    /** 缩略图地址。判据跟 `tools/check-video-links.py` 是同一个。 */
    const THUMB_URL = 'https://img.youtube.com/vi/%s/default.jpg';

    /**
     * 探针超时。★ 超时一律算「**没问到**」，绝不算「已失效」——
     *   这是本项目那条老规矩（"没法判断的时候要说没办法判断"）。
     */
    const PROBE_TIMEOUT_MS = 5000;

    /**
     * 对照组的视频 id。
     *
     * ★★★★★ 为什么必须有它 —— 这是这个功能里唯一会让"误判"变成"数据被删"
     *   的地方：`new Image()` 的 `onerror` **分不清"404"和"断网"**。
     *   （跨域读不到状态码：`no-cors` 拿到的是不透明响应，状态恒为 0；
     *     而 `onload/onerror` 不受 CORS 限制，代价就是丢掉了状态码。）
     *
     * ★ 一次断网（VPN 掉线、YouTube 被墙）会让**整张表**整齐地判成
     *   "视频全没了" → 31 条记录被一口气删光，而且**全程一个错都不报**。
     *
     * ★★ 所以先探一个**已知活着**的视频：它都失败，说明问题在网、不在视频。
     *   这是本项目"**同屏放一个已知答案的对照组**"那条规矩的又一次应用。
     */
    const CONTROL_VIDEO_ID = 'dQw4w9WgXcQ';

    /** 建一个 `<img>`。★ 抽出来是为了让测试能把它换掉（否则单测会真去请求 youtube）。 */
    function newThumbImage() { return new Image(); }

    /**
     * 问 YouTube：这条视频还在吗。返回 `'alive' | 'dead' | 'unknown'`。
     *
     * ★ 三态是刻意的：`onerror` 既可能是 404、也可能是断网/超时，
     *   **两者在浏览器里长得一模一样**。分不出来的那种就报 `unknown`，
     *   由上层决定怎么处置（现在是一律**保留**）。
     */
    function probeThumbAlive(videoId) {
        return new Promise(function (resolve) {
            // 记录里可能没有 videoId（"发出去了但没拿到链接"那条路）——
            // 没 id 就**问不了**，不是"已失效"。
            if (!videoId) { resolve('unknown'); return; }

            let done = false;
            const img = newThumbImage();
            const timer = setTimeout(function () {
                if (done) return;
                done = true;
                resolve('unknown');
            }, PROBE_TIMEOUT_MS);

            img.onload = function () {
                if (done) return;
                done = true;
                clearTimeout(timer);
                resolve('alive');
            };
            img.onerror = function () {
                if (done) return;
                done = true;
                clearTimeout(timer);
                resolve('dead');
            };

            try {
                img.src = THUMB_URL.replace('%s', encodeURIComponent(videoId));
            } catch (e) {
                clearTimeout(timer);
                done = true;
                resolve('unknown');
            }
        });
    }

    /**
     * 算一份"要怎么对齐"的报告，**不写任何东西**。
     *
     * ★ 拆成"算"和"写"两步是刻意的：删记录不可逆，所以必须能
     *   **先把后果原样说出来、等人点头**（跟「清空上传记录」同一条规矩）。
     *   算完直接写的话，"确认"就变成一句没有内容的形式。
     *
     * 返回 `{ok, reason, playCount, matched, missing, ambiguous, doomed, kept, unknown}`。
     */
    async function planAlign(text) {
        const rep = {
            ok: false, reason: '',
            playCount: 0, matched: [], missing: [], ambiguous: [],
            doomed: [], kept: 0, unknown: 0, total: 0,
        };

        // ── ① 解析名单 ──
        const names = parsePlayNameList(text);
        rep.playCount = names.length;
        if (!names.length) {
            rep.reason = '清单是空的（一行一个名字）';
            return rep;
        }

        // ── ② 配对 ──
        const recs = loadVideos();
        const keys = [];
        recs.forEach(function (r) {
            const k = cslKeyOf(r);
            if (k && keys.indexOf(k) < 0) keys.push(k);
        });

        const m = matchPlayNames(names, keys);
        rep.matched = m.matched;
        rep.missing = m.missing;
        rep.ambiguous = m.ambiguous;

        // ★★★★★ 一条都没配上 → **停在这里**。
        //   下一步是"删掉不在名单里的记录"，名单全空就等于**把记录删光**。
        //   这是整个功能里唯一一处"判据错了就不可逆"的地方，
        //   所以闸门要卡在**最前面**，而不是等算完再检查。
        //   （贴错表是常事：贴成别的产品、别的站、或者整份名字都被改过。）
        if (!m.matched.length) {
            rep.reason = '清单里**没有一条**能对上记录 —— 别急着按，先确认贴的是这个站的';
            return rep;
        }

        // ── ③ 圈出"可能该删的"：不在名单里的那些 ──
        //   ★ 名单里的**一律不动**（Play 上已经有 CSL 了，它就是有用的）。
        const groups = playGroups(recs);
        rep.total = groups.length;
        const candidates = groups.filter(function (g) {
            return rep.matched.indexOf(g.key) < 0;
        });

        // ── ④ 对照组：先确认"判据这次可信" ──
        const control = await probeThumbAlive(CONTROL_VIDEO_ID);
        if (control !== 'alive') {
            // ★★★★★ 整个停下，**不能**"那就不删了吧"往下走：
            //   半做等于没说 —— 用户看到一句"完成"，就会按它去理解记录，
            //   那是最容易出错的中间态。重跑是幂等的，"这次不做"没有代价。
            rep.reason = control === 'dead'
                ? '对照组（一个已知活着的视频）也探不到 —— 这次的存活判据不可信'
                : '对照组没问到（网络慢 / 不通）—— 这次的存活判据不可信';
            return rep;
        }

        // ── ⑤ 逐条问：还在吗 ──
        //   ★ 串行而不是并发：一次几十条、只在这一个动作里跑，
        //     而并发会让"哪一条超时了"变得说不清楚。
        for (let i = 0; i < candidates.length; i += 1) {
            const g = candidates[i];
            // eslint-disable-next-line no-await-in-loop
            const st = await probeThumbAlive(g.main && g.main.videoId);
            if (st === 'dead') rep.doomed.push(g);
            else if (st === 'unknown') rep.unknown += 1;
        }

        rep.kept = groups.length - rep.doomed.length;
        rep.ok = true;
        return rep;
    }

    /**
     * 把算好的报告落下去。返回 `{ok, removed, doneCount}`。
     *
     * ★ 顺序跟「清空上传记录」一样：**先归档、回读确认、再改**。
     *   删记录不可逆，而 `storeSet` 写失败**不抛错**（油猴存储配额满等），
     *   不回读的话"已经备份了"就是一句没有依据的话。
     * ★★ 归档和恢复用的是**同一套**（`pushVideoArchive` / `loadVideoBackup`），
     *   所以「恢复上传记录」照样能把这次删掉的找回来 —— 不另开一套。
     */
    function applyAlign(rep) {
        const recs = loadVideos();
        const doomed = {};
        (rep.doomed || []).forEach(function (g) { doomed[g.key] = true; });

        const keep = recs.filter(function (r) {
            const k = cslKeyOf(r);
            return !(k && doomed[k]);
        });

        // ── ① 先归档 ──
        pushVideoArchive(recs);
        const back = loadVideoBackup();
        if (!back || back.list.length !== recs.length) return { ok: false };

        // ── ② 再改上传记录（`saveVideos` 会顺手并进永久名单）──
        saveVideos(keep);

        // ── ③ 已建记录 = **整体替换**成名单里那些 ──
        //   ★ 不是"并进去"：这份名单是"Play 上现在真实有哪几个"，
        //     它天然就是全量。并的话，之前删掉的 CSL 会永远留在记录里
        //     —— 那正是 3.2.58 要解决的问题本身。
        storeSet(STORE.PLAY_DONE, (rep.matched || []).slice(-2000));

        // ── ④ 回读确认（`storeSet` 写失败不抛错）──
        const backVideos = loadVideos();
        const backDone = storeGet(STORE.PLAY_DONE, []);
        if (backVideos.length !== keep.length) return { ok: false };
        if (!Array.isArray(backDone) || backDone.length !== rep.matched.length) {
            return { ok: false };
        }

        return { ok: true, removed: recs.length - keep.length, doneCount: backDone.length };
    }

    /**
     * 面板上「按清单对齐」这个动作：**先算、把后果说清、问确认、再落**。
     *
     * ★ 一个都不删也要把结果说出来 —— "这次没有废记录"和"这个功能没生效"
     *   在界面上长得一样，而后者会让人以为记录对齐过了。
     */
    function askAlignRecords() {
        if (playState.running) {
            log('现在有任务在跑 —— 先中止、等它停稳再动记录。', 'error');
            return;
        }

        const box = UI.play && UI.play.alignBox;
        const text = box ? box.value : '';

        log('— 按 Play 清单对齐记录 —', 'info');
        // ★ 把这条链**返回出去**：面板那边照样是"点了就走"，
        //   但测试里能 await 到它做完 —— 否则用例只能靠 sleep 猜时机，
        //   而"猜时机"的用例会在快机器上绿、慢机器上红。
        return planAlign(text).then(function (rep) {
            if (!rep.ok) {
                log('✕ 不能往下走：' + rep.reason, 'error');
                if (rep.playCount) {
                    log('  · 你贴进来 ' + rep.playCount + ' 行', 'info');
                }
                log('  ★ **一条记录都没动**。', 'info');
                return;
            }

            log('贴进来 ' + rep.playCount + ' 行，配上 ' + rep.matched.length
                + ' 条记录（共 ' + rep.total + ' 条）。', 'info');
            if (rep.missing.length) {
                log('  · ⚠ 有 ' + rep.missing.length + ' 行在记录里找不到对得上的：'
                    + rep.missing.slice(0, 5).join(' / ')
                    + (rep.missing.length > 5 ? ' …' : ''), 'warn');
                log('    （可能是别的产品/别的站的，或者记录已经被清过 ——'
                    + '这些**不会**被标成"已建"）', 'info');
            }
            if (rep.ambiguous.length) {
                log('  · ⚠ 有 ' + rep.ambiguous.length + ' 行能对上**不止一个**文件'
                    + '（名字是前缀），不敢猜，跳过：', 'warn');
                rep.ambiguous.forEach(function (a) {
                    log('      ' + a.name + ' → ' + a.hits.join(' / '), 'warn');
                });
            }

            log('打算这么改：', 'info');
            log('  · 标记「已建」：**' + rep.matched.length + '** 条'
                + '（下次跑会跳过它们）', 'info');
            log('  · 删掉废记录：**' + rep.doomed.length + '** 条'
                + '（视频已经不在了 —— 建不出可用的 CSL）', rep.doomed.length ? 'warn' : 'info');
            if (rep.unknown > 0) {
                log('  · ★ 另有 ' + rep.unknown + ' 条**没问到**（超时/没有链接）——'
                    + ' **留着**。没问到不等于已失效。', 'warn');
            }
            if (!rep.doomed.length) {
                log('  · 这次没有要删的。', 'ok');
            }

            const okGo = typeof confirm === 'function'
                ? confirm('按 Play 清单对齐记录？\n\n'
                    + '· 标记「已建」' + rep.matched.length + ' 条\n'
                    + '· 删掉废记录 ' + rep.doomed.length + ' 条\n'
                    + '· 删之前会先归档一份，可用「恢复上传记录」找回\n\n'
                    + '确定继续吗？')
                : true;
            if (typeof confirm !== 'function') {
                log('  · （这个环境没有确认框，直接往下走）', 'warn');
            }
            if (!okGo) {
                log('已取消，什么都没动。', 'info');
                return;
            }

            const done = applyAlign(rep);
            if (!done.ok) {
                log('**没改成** —— 归档没落地，或者写回后回读对不上。', 'error');
                log('  ★ 成因一般是油猴存储写不进去（配额满 / 管理器限制）。', 'error');
                log('  ★ 记录**没有被改动**，可以重试。', 'info');
                return;
            }

            log('✓ 对齐完成：删掉 ' + done.removed + ' 条，'
                + '「已建」现在有 ' + done.doneCount + ' 条。', 'ok');
            log('  ★ 删掉的那些**不在**这一步里 —— 想找回来用「恢复上传记录」。', 'info');

            if (box) box.value = '';
            renderDoneHint();
            renderPlayList();
        }).catch(function (e) {
            log('✕ 对齐失败：' + (e && e.message ? e.message : e), 'error');
            if (e && e.stack) console.error('[CSL Helper] 堆栈', e.stack);
        });
    }

    function buildPlayPanel() {
        const shell = buildShell('CSL Helper · Play', 'play');
        const body = shell.body;

        // 模板名。默认就是「默认商品详情」—— 运营口述里第 1 步要选的那个。
        const templateInput = el('input', {
            type: 'text',
            placeholder: '选择商品详情（默认：默认商品详情）',
            value: CONFIG.play.template_name || '',
            onchange: function (e) { playState.templateName = e.target.value; },
        });
        playState.templateName = CONFIG.play.template_name || '';

        // ── 受众 ──
        //
        // ★★ 3.2.60：这里原来有一个「目标受众群体」下拉（网址 / 广告流量）
        //   加一个「受众网址」textarea，**两个都删了**。
        //   运营 2026-09-22：「受众网址这个功能可以删除了」。
        //
        //   ★ 为什么删掉比留着好 —— 留着这条路**不是中立的**：
        //     下拉一旦被切到「网址」，而网址框是空的，就会走到
        //     `if (!task.audienceUrl) throw StepError('这条任务的受众网址是空的…')`
        //     → **一次都不点就整条失败**。
        //   ★ 而 `playState.audience` 是**内存变量、不持久化**：
        //     刷新页面就跳回 `CONFIG.play.audience`。所以"这次记得选了广告流量"
        //     这件事**跨会话不成立**。
        //   → 删掉之后，受众**只有一个来源**：`CONFIG.play.audience`（= 'ads'），
        //     面板上再也表达不出"走网址"这个状态。

        // ── 批量勾选（2026-09-17 加，和 YouTube 侧一致）──
        //
        // ★ 为什么要：这批视频一多（运营那边现在 17 条、上限 6 条），
        //   逐个点勾选框点不过来；而且"要建哪几条"本来就是**一批一批**决定的。
        // ★ 只作用于**当前列出来的**那些 —— 面板上现在没有筛选框，
        //   所以就是全部。哪天加了筛选框，这里的语义要跟着改成
        //   "只动筛出来的"（YouTube 侧就是这么定的，见 pickedYtEntries）。
        function bulk(mode) {
            const n = playBulkPick(mode);
            log(({ all: '全选', none: '全不选', invert: '反选' }[mode] || mode)
                + '：动了 ' + n + ' 个', 'info');
            renderPlayList();
        }

        const pickAllBtn = el('button', {
            class: 'cslh-btn sec', text: '全选',
            onclick: function () { bulk('all'); },
        });
        const pickNoneBtn = el('button', {
            class: 'cslh-btn sec', text: '全不选',
            onclick: function () { bulk('none'); },
        });
        const pickInvertBtn = el('button', {
            class: 'cslh-btn sec', text: '反选',
            onclick: function () { bulk('invert'); },
        });

        const listBox = el('div', { class: 'cslh-list' });

        const refreshBtn = el('button', {
            class: 'cslh-btn sec',
            text: '刷新视频',
            onclick: function () { renderPlayList(); },
        });

        UI.play.startBtn = el('button', {
            class: 'cslh-btn',
            text: '生成 CSL',
            onclick: function () { runPlayQueue(); },
        });

        // ★ 3.2.47：中止按钮。★ 这一侧比 YouTube 侧**更需要**它 ——
        //   每建一条 CSL 都要烧一份**不可回收**的配额，
        //   而"发现配错了想停"这件事在 17 条一批的规模上一定会发生。
        //   在此之前唯一的办法是关标签页，而关标签页会留下一个
        //   没走完的向导（那里面可能已经点过保存了）。
        UI.play.abortBtn = el('button', {
            class: 'cslh-btn sec',
            text: '中止',
            disabled: true,
            onclick: function () { requestStop('play'); },
        });

        // 诊断：把**当前这一页**的结构原样报出来，并复制到剪贴板。
        //
        // ★ 为什么在上线选择器之前必须先有这个：
        //   Play 侧的选择器全是 null，一次真页面都没碰过；而 CSL 只有
        //   **50 个配额**，试错成本不可回收。所以顺序是**先看清、再配置、后跑**。
        //
        // ★★ 一个配额都不花的用法：
        //   不用真的新建 —— 打开**已有的** CSL 详情页、或者点开创建向导
        //   停在某一屏，点这个按钮就行。看看不要钱的部分先看完。
        UI.play.diagnose = el('button', {
            class: 'cslh-btn sec',
            text: '诊断页面（复制结构）',
            onclick: function () {
                const text = dumpPlayPage('手动');
                copyText(text).then(function (ok) {
                    if (ok) log('  结构快照已复制到剪贴板，Ctrl+V 粘贴发出来就行。', 'ok');
                    else log('  ⚠ 没能自动复制 —— 请手动选中上面那份快照复制。', 'warn');
                });
            },
        });

        // ── 「已建记录」区（3.2.58）──
        //
        // ★ 放在诊断按钮**后面**：它是"数据出问题时才用"的，
        //   平时不该抢视线，但必须能找得到。
        UI.play.doneHint = el('div', { class: 'cslh-hint' });
        UI.play.clearDone = el('button', {
            class: 'cslh-btn sec', text: '清空「已建记录」',
            onclick: function () {
                askClearPlayDone();
                renderDoneHint();
                renderPlayList();
            },
        });

        // ── 「按清单对齐」（3.2.59）──
        //
        // ★ 跟「清空」放在一起：它们是**同一件事的两个方向** ——
        //   清空是"我不知道 Play 上有哪些，先全忘掉"，
        //   对齐是"我知道 Play 上有哪些，按它改"。
        //   ★ 后者能用的场合就用后者：清空之后面板不再跳过任何条目，
        //     一不小心就会把建过的**重复建一遍**（配额不可逆）。
        UI.play.alignBox = el('textarea', {
            rows: '4',
            placeholder: '把 Play 后台「自定义商品详情」那页的名字复制进来，一行一个\n'
                + '（连着别的内容一起复制也行，# 开头的行会当注释跳过）',
        });
        UI.play.alignBtn = el('button', {
            class: 'cslh-btn sec', text: '按清单对齐记录',
            onclick: function () { askAlignRecords(); },
        });

        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-label', text: '选择商品详情（第 1 步用）：' }),
            templateInput,
        ]));
        // ★ 3.2.60：原来这里还有两块 ——「目标受众群体」下拉 和
        //   「受众网址（一行一个）」textarea。两个都删了，见 buildPlayPanel
        //   开头那段（受众固定走广告流量）。
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-row' }, [
                el('div', { class: 'cslh-label', text: '视频：', style: 'flex:1;margin:0;' }),
                pickAllBtn, pickNoneBtn, pickInvertBtn, refreshBtn,
            ]),
            listBox,
        ]));
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-row' }, [UI.play.startBtn, UI.play.abortBtn]),
            el('div', { class: 'cslh-hint', text: '★ 「中止」是**做完当前这条再停**：'
                + '每一份配额都不可回收，而半路劈开会留下一个没走完的向导'
                + '（那里面可能已经点过保存了）。按过之后按钮会变成「正在停…」。' }),
        ]));
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            UI.play.diagnose,
            el('div', { class: 'cslh-hint', text: '★ 第一次跑之前先点它 —— 会把当前这一页'
                + '所有的按钮、输入框（含认出来的 label 和当前值）、表格行数、'
                + '配额线索列出来，并复制到剪贴板。'
                + '★ 先在有把握的地方点（已有的 CSL 详情页 / 创建向导），'
                + '不花配额。' }),
        ]));
        // ── 数据区：已建记录（3.2.58）──
        //
        // ★ 为什么必须有这个入口：脚本**看不到 Play 后台的列表**，
        //   所以"某个 CSL 被人在后台删了"它**永远不知道** ——
        //   而那份记录会让它在重跑时跳过该条目，导致那条
        //   **永远建不出来**（运营实测：YouTube 29 条、Play 只剩 20 个）。
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-label', text: '已建记录' }),
            UI.play.doneHint,
            el('div', { class: 'cslh-row' }, [UI.play.clearDone]),
            el('div', { class: 'cslh-hint', text: '★ 这份记录管的是"**哪些已经建过、'
                + '下次别重复建**"。★ 它**看不到 Play 后台的实际状态** —— '
                + '如果你在 Play 里删过 CSL，这里**不会跟着更新**，'
                + '那些条目会被一直跳过、永远补不回来。'
                + '\n→ 遇到这种情况**优先用下面的「按清单对齐」**（能直接对上账）；'
                + '实在对不上再退回来把它**清空**，然后**只勾缺的那几个**重跑。' }),
        ]));

        // ── 数据区：按清单对齐（3.2.59）──
        //
        // ★★ 排在「清空」**后面**，而且文案要说清它比"清空"好在哪 ——
        //   否则人会本能地选那个更简单的按钮，然后全选、重复建、烧配额。
        body.appendChild(el('div', { class: 'cslh-sec' }, [
            el('div', { class: 'cslh-label', text: '按 Play 清单对齐记录' }),
            UI.play.alignBox,
            el('div', { class: 'cslh-row' }, [UI.play.alignBtn]),
            el('div', { class: 'cslh-hint', text: '★ 用途：你在 Play 后台删/建过 CSL 之后，'
                + '把那个列表**原样复制**进来 —— 脚本会'
                + '\n · 把清单里有的标成「已建」（下次跑跳过）'
                + '\n · 把**视频已经没了**的废记录删掉（它们建不出可用的 CSL）'
                + '\n · 刚传上去、还没建 CSL 的**留着**（这就是接下来要干的活）'
                + '\n\n★ 比「清空」好在：清空之后面板不再跳过任何条目，'
                + '一不小心就会把建过的**重复建一遍**（配额不可逆）。'
                + '\n★ 删之前会先归档一份，可用「恢复上传记录」找回。'
                + '\n★ 会先问一遍、把条数说清再动手；**一条都没配上时什么都不改**。' }),
        ]));
        body.appendChild(el('div', { class: 'cslh-label', text: '日志' }));
        body.appendChild(shell.logBox);

        UI.play.listBox = listBox;
        renderPlayList();
        // ★ 初始化画一次 —— 否则面板刚打开时这一块是空白，
        //   而"空白"和"0 条"在用户眼里是两回事（前者像是坏了）。
        renderDoneHint();
    }

    /**
     * 把存储里带链接的视频，按**文件名**分成"一个文件一条"。
     *
     * ★ 为什么要分组：真机上存储里躺着 4 条 buffalo 记录（4 个不同
     *   videoId，是之前误判重跑留下的）。不分组的话面板上会出现 4 个
     *   一模一样的条目，而它们其实只会建出 1 个 CSL ——
     *   "看到的"和"会发生的"对不上，而"对不上"正是要消灭的东西。
     *
     * ★★ 分组规则必须和 `buildPlayPlans` **一模一样：后到的顶掉先到的**。
     *   两边要是各有一套，勾选框（按 main.relPath 存）和真跑的那条
     *   就会指向不同的记录 —— 而这类不一致不会报错，只会静默跑偏。
     *
     * ★★★ 抽成一个函数（2026-09-17），是为了让**面板渲染**和
     *   「全选 / 全不选 / 反选」拿到**同一份清单**。
     *   批量勾选要是自己去遍历原始记录，同名多条会被算成多条，
     *   于是勾上的是**根本不会建的那条旧记录**的 key ——
     *   表现成"点了全选，勾选框一个都没动"，而且不报错。
     *
     * @param {Array=} records 已经取好的记录（省一次读存储）；不传就自己读
     */
    function playGroups(records) {
        const recs = records || loadVideos().filter(function (r) {
            return r && r.videoId;
        });
        const groups = [];
        const byKey = {};
        recs.forEach(function (r) {
            const k = cslKeyOf(r) || ('#' + groups.length);
            if (byKey[k]) {
                byKey[k].others.push(byKey[k].main);   // 旧的攒进 others
                byKey[k].main = r;                     // ★ 换成**最新**那条
                return;
            }
            byKey[k] = { key: k, main: r, others: [] };
            groups.push(byKey[k]);
        });
        return groups;
    }

    /**
     * 批量改 Play 侧的勾选。mode: 'all' | 'none' | 'invert'。
     *
     * 返回"**动了**几条"—— 和 YouTube 侧 `bulkSetSkip` 同一个语义：
     * 数是**参与操作的条数**，不是"值真的变了"的条数。
     * 两边的日志措辞也因此能对得上（都是「动了 N 个」）。
     */
    function playBulkPick(mode) {
        let n = 0;
        playGroups().forEach(function (g) {
            const p = g.main && g.main.relPath;
            if (!p) return;
            n += 1;
            // ★ 未设置 = 勾上（和 renderPlayList 里那句初始化的默认值一致）。
            //   不这么算的话，"从没渲染过就点全不选"会漏掉这些项。
            const before = playState.picked[p] !== false;
            if (mode === 'all') playState.picked[p] = true;
            else if (mode === 'none') playState.picked[p] = false;
            else playState.picked[p] = !before;
        });
        return n;
    }

    function renderPlayList() {
        const box = UI.play.listBox;
        if (!box) return;
        box.textContent = '';

        // 只列 YouTube 侧真的拿到 id 的
        const records = loadVideos().filter(function (r) { return r && r.videoId; });

        if (!records.length) {
            box.appendChild(el('div', {
                class: 'cslh-hint',
                text: '（存储里没有带链接的视频。先去 YouTube 那边传完再来。）',
            }));
            return;
        }

        // ① 按**文件名**分组 —— 一个文件就是一条，同名的是同一条。
        //    规则和理由都在 `playGroups` 上（面板渲染、批量勾选、
        //    以及 buildPlayPlans 用的是**同一条规则**）。
        const groups = playGroups(records);

        // ② 初始化勾选和名字（默认全勾、默认名 = 文件名）
        groups.forEach(function (g) {
            const p = g.main.relPath;
            if (playState.picked[p] === undefined) playState.picked[p] = true;
            if (playState.names[p] === undefined) {
                playState.names[p] = defaultCslName(g.main);
            }
        });

        // ③ 算这一批的账
        //
        // ★★ 面板显示的和真跑的，必须是**同一个函数**算出来的。
        //   面板要是自己另算一套，就会出现"面板显示 3 条、实际建 4 条"
        //   这种最坏的情况：看着没事，跑起来烧配额。
        const built = buildPlayPlans(records, {
            picked: playState.picked,
            names: playState.names,
            done: storeGet(STORE.PLAY_DONE, []),
            maxPerRun: CONFIG.play.max_per_run,
        });
        const planOf = {};
        built.plans.forEach(function (p, i) {
            planOf[p.relPath] = { plan: p, no: i + 1 };
        });
        const doneKeys = {};
        built.skippedDone.forEach(function (s) { doneKeys[s.key] = true; });

        // ④ 摘要 —— 让"这一批到底会建几条"在点按钮之前就看得见
        box.appendChild(el('div', {
            class: 'cslh-hint',
            text: '这一批会建 ' + built.plans.length + ' 条'
                + (built.skippedDup.length ? '，同名跳过 ' + built.skippedDup.length + ' 条' : '')
                + (built.skippedDone.length ? '，已建过跳过 ' + built.skippedDone.length + ' 条' : '')
                + (built.noVideo && built.noVideo.length
                    ? '，⚠ 没上传成功 ' + built.noVideo.length + ' 条' : '')
                + '。',
        }));

        // ⑤ 逐条渲染
        groups.forEach(function (g) {
            const r = g.main;
            const p = r.relPath;
            const hit = planOf[p];

            const cb = el('input', {
                type: 'checkbox',
                checked: !!playState.picked[p],
                onchange: function (e) {
                    playState.picked[p] = e.target.checked;
                    renderPlayList();
                },
            });

            // ★ oninput 里**不**重渲染：一重渲染这个输入框就被换掉了，
            //   用户正在打字会**丢焦点**（打一个字跳出去一次）。
            const nameInput = el('input', {
                type: 'text',
                value: playState.names[p] || '',
                placeholder: 'CSL Name（默认 = 文件名）',
                oninput: function (e) { playState.names[p] = e.target.value; },
            });

            const marks = [];
            if (hit) {
                marks.push('第 ' + hit.no + ' 条');
            }
            if (doneKeys[g.key]) marks.push('★ 已建过，会跳过');
            if (g.others.length) {
                // ★ 这里要**说清用的是哪一条**。
                //   2026-09-17 实测踩过：这一组的第 1 条 404（视频已删），
                //   只有最新那条活着 —— 只写"会跳过 N 条"的话，
                //   运营没法知道留下来的到底是不是那条活的。
                marks.push('★ 这个名字传过 ' + (g.others.length + 1)
                    + ' 次，用的是**最新那条** `' + r.videoId + '`');
            }

            box.appendChild(el('div', { class: 'cslh-item' }, [
                cb,
                el('div', { style: 'flex:1;min-width:0;' }, [
                    el('div', { class: 'cslh-name', text: r.fileName, title: r.url }),
                    nameInput,
                    marks.length
                        ? el('div', { class: 'cslh-hint', text: marks.join('  ') })
                        : null,
                ]),
            ]));
        });
    }

    /** 默认的 CSL 名：文件名去后缀，超长截断。用户可以在面板上改。 */
    function defaultCslName(record) {
        return String(record.fileName || '').replace(/\.[^.]+$/, '').slice(0, 60);
    }

    // ════════════════════════════════════════════════════════════════════
    // 8b. Play 侧「整页结构快照」
    //     先把页面看清楚，再去改选择器
    // ════════════════════════════════════════════════════════════════════

    /**
     * 猜这一页是 Play Console 的哪一种界面。
     *
     * ★ 为什么要把"这是哪一页"写在快照第一行：
     *   Play 侧的流程是**跨页**的 ——「创建」在列表页、「选模板」在向导里、
     *   「名称 / Preview video / 保存」在详情页。而选择器是**按页**配的。
     *   快照要是不说自己抓的是哪一页，读的人就得靠按钮文案反推，
     *   而"靠文案猜"正是这整件事要消灭的东西。
     *
     * ★★ 判据只用**页面自己的内容**，不看 URL。
     *   Play Console 是 SPA，路由形态会变；而且本项目已经吃过一次亏 ——
     *   「按内容判页面」比「按地址判页面」稳（见 gotoContentPage 的教训）。
     */
    function playPageShape() {
        const hasNode = function (sel) {
            const arr = safeDeepAll(sel);
            for (let i = 0; i < arr.length; i++) {
                if (!isOurs(arr[i])) return true;
            }
            return false;
        };

        let text = '';
        try {
            text = String((document.body && document.body.innerText) || '')
                .replace(/\s+/g, ' ');
        } catch (e) {
            text = '';
        }
        const hasText = function (re) { return re.test(text); };

        // ① 创建 / 复制向导
        //
        // ★★★★ 2026-09-18 改：判据从"页面上有没有步骤条"换成
        //   **"现在停在第几步"**。
        //
        //   原来那一句是 `hasText(复制现有的…) || hasNode('mat-stepper,
        //   [class*="stepper"]')`，而它在真机上是**恒真**的：
        //   步骤条在向导的**四步里都在**（它就是同一个向导的顶栏）。
        //   于是第 2/3/4 屏的快照抬头全都写着「选模板那一屏」——
        //   而抬头存在的唯一意义就是"告诉读的人这一屏是什么"。
        //   **一个恒真的判据，比没有判据更糟**（它让人以为自己知道）。
        //
        //   → 改用 `playCurrentStep()`：它读的是步骤条上
        //     专门表达状态的那个字段（`is-disabled` / `aria-current`），
        //     能说出"现在第 N 步（名字）"。
        let curStep = null;
        try { curStep = playCurrentStep(); } catch (e) { curStep = null; }
        if (curStep) {
            return '创建 / 复制向导（现在在' + playStepText(curStep)
                + '｜判据：' + curStep.how + '）';
        }
        // 步骤条读不出来时**不许硬猜**，但也要说清"是哪一个环节没读到" ——
        // 这两种情况的修法完全不一样（一个是配选择器，一个是结构变了）。
        if (hasText(/复制现有的|Duplicate existing|选择模板|Choose a template/)) {
            return '创建 / 复制向导（读到「复制现有」这类文案，'
                + '但**步骤条没读到** —— 多半是 stepper 的选择器还没配）';
        }
        if (hasNode('mat-stepper, [class*="stepper"]')) {
            return '创建 / 复制向导（页面上有步骤条，'
                + '但**读不出现在第几步** —— 这一屏的结构可能和真机快照不一样）';
        }

        // ② 屏 B「第 2 步 详细信息」：应用名称 + 说明 / 视频链接
        //
        // ★★★★ 2026-09-18 改。原来这一条是：
        //     hasText(/Preview video|预览视频/i) && hasText(/store listing name|商店页名称/i)
        //   两个毛病叠在一起，于是它**一次都没命中过**：
        //     · 运营的 Console 是**中文**界面，屏 B 上写的是「**应用名称**」，
        //       `store listing name` / `商店页名称` **一个都对不上**；
        //     · 那一屏上也没有「Preview video」这几个字 ——
        //       视频那一栏的 label 是 `https://www.youtube.com/watch?v=`。
        //   → 判据词全部换成**真机快照里出现过的原文**。
        //     这是本项目定过的规矩：判据要用页面上**真有的字**，
        //     不许用"应该会有的字"。（假 DOM 里两条都能满足，
        //     所以测试绿着、真机恒假 —— 典型的"绿在错的理由上"。）
        //
        // ★★ 措辞里必须带上"步骤条没读到"：
        //   屏 B 在**向导内部**，所以正常情况它会先被 ① 拦下。
        //   能走到这一条，说明步骤条**读不出来** —— 那就分不清
        //   "向导里的屏 B" 和 "主商品详情页"（两边的字段名几乎一样）。
        //   只报"这是 CSL 详细信息那一屏"就是**装作知道**。
        if (hasText(/应用名称|store listing name|商店页名称/)
            && (hasText(/youtube\.com\/watch|Preview video|预览视频/i)
                || hasText(/简短说明|完整说明|short description|full description/i))) {
            return '像 CSL 详细信息那一屏（应用名称 + 说明/视频字段）'
                + '—— ★ 但**步骤条没读到**，也可能只是主商品详情页';
        }
        // ③ 列表页：提到 CSL，而且页面里真有列表/表格结构
        //
        // ★★★ 2026-09-18：判据词加上「自定义商品详情」。
        //   真机上的入口路径是「商品详情 → 自定义商品详情」
        //   （运营自己的走查卡 `docs/走查操作卡-广告流量.md` 里就是这么写的），
        //   而原来只认 `Custom store listings / 自定义商店页` ——
        //   中文界面上一个都对不上，于是列表页会一路落到最后的
        //   「不像 CSL 相关页」那条兜底里，而那是**最容易被当成"没点对页面"**的一句。
        if (hasText(/Custom store listings|自定义商店页|自定义商品详情/)) {
            if (hasNode('table, mat-table, [role="table"], '
                + 'mat-list-item, [role="row"], mat-card')) {
                return 'CSL 列表页（创建入口应该在这一屏）';
            }
            return 'CSL 相关页（分不出是哪一屏）';
        }
        return '★ 不像 CSL 相关页 —— 先确认没点错页面';
    }

    /**
     * 把「创建自定义商品详情」这一击**真的**打下去。
     *
     * ★★★★★ 2026-09-18：原来这里只有两句 ——
     *     const createBtn = await findOne(P.createCsl, '…');
     *     clickHard(createBtn);
     *   而真机 **18:10 和 18:40 两次**都是：**点了没反应**，等满 15 秒页面
     *   纹丝没动（还在列表页），向导没打开。
     *
     *   ★ 排雷的顺序（每一步都由证据推进，没有一个靠猜）：
     *     ① 用户手工点同一个按钮**能打开**
     *        → 排掉"没权限 / 这个入口是死的"；
     *     ② 把合成点击事件补齐到真实鼠标的完整一条链
     *        （pointerover → … → pointerdown → mousedown → focus → … → click，
     *          加上点击前先滚进视野）
     *        → **仍然没反应**，排掉"事件序列不完整"；
     *     ③ 剩下的可能只有两个：
     *         (a) 命中的那个元素**不是真按钮** —— 外层 wrapper 也有可能带着
     *             同一个 `aria-label`，而 `deepQueryOne` 取的是文档里第一个；
     *         (b) 该点的是**另一个入口** —— 快照里一直有两个同名：
     *             顶部那个和工具栏里的 `add_2` 那个。
     *
     *   ★★ 这两个**都不押注**：把候选排成队，逐个点下去，
     *     **每点一次回读**页面有没有进向导。谁成功就用谁，并把"第几个候选生效"
     *     写进日志 —— 这样下一次取证时，日志里直接写着答案，不用再猜。
     *     （这跟"赌一个选择器是对的"是两条路：一个会被证据纠正，一个不会。）
     */
    async function playClickCreateEntry() {
        // ★ 这里不能写成 `P.createCsl` —— `P` 是在 runPlaySteps 里
        //   `const P = CONFIG.selectors.play;` 定义的局部变量，
        //   本函数在它外面，写 P 会当场 ReferenceError，
        //   而 `node --check` 只看语法、看不出来这一个。
        const P = CONFIG.selectors.play;
        const cands = [];
        const seen = [];
        const add = function (node, why) {
            if (!node) return;
            let key;
            try {
                key = String(node.tagName || '') + '|' + String(node.className || '')
                    + '|' + String(node.getAttribute
                        ? node.getAttribute('aria-label') : '');
            } catch (e) { key = 'unknown-' + String(Math.random()); }
            if (seen.indexOf(key) >= 0) return;
            seen.push(key);
            cands.push({ node: node, why: why });
        };

        // ── 候选来源 1 / 2：配置的选择器，以及它**内部**真正的按钮 ──
        //   为什么连内部一起试：`deepQueryAll` 按文档顺序返回，命中的第一个
        //   可能是外面那层容器；容器上没有处理函数，点了自然不动。
        safeDeepAll(P.createCsl).forEach(function (n) {
            add(n, '选择器 createCsl 命中的元素本体');
            try {
                deepQueryAll('button, a, [role=button]', n).forEach(function (b) {
                    add(b, '命中元素**内部**的 '
                        + String(b.tagName || '').toLowerCase());
                });
            } catch (e) { /* 查询失败就当这个候选不存在 */ }
        });

        // ── 候选来源 3：页面上"文字里有这几个字"的可点元素 ──
        //   这一条会把工具栏里那个 `add_2 创建自定义商品详情` 也捞进来 ——
        //   它没有 aria-label，靠选择器**永远**找不到它。
        try {
            playFindAllByText(function (t) { return t.indexOf('创建自定义商品详情') >= 0; })
                .forEach(function (hit) {
                    add(hit.node, '文字含「创建自定义商品详情」'
                        + '（' + (hit.isRealBtn ? '按钮标签' : '容器') + '）');
                });
        } catch (e) { /* 同上 */ }

        if (!cands.length) {
            throw StepError('一个「创建自定义商品详情」的候选都没找到 —— '
                + '选择器没命中，**按文字也捞不到**。'
                + '\n    → 抓一张当前页面的结构快照发我，'
                + '照着里面实际的标签改 `CONFIG.selectors.play.createCsl`。',
                'notfound');
        }

        // 每个候选给多久回读：够检出"向导开了"就行 ——
        // 候选可能有六七个，给太长会把整轮拖到不可接受。
        const probeMs = Math.max(1500, CONFIG.step_pause * 6);
        const tried = [];

        for (let i = 0; i < cands.length; i += 1) {
            // ★★★ 2026-09-18：把"点下去的到底是个什么"**说全**。
            //   原先只报 `tag.class`，而两个候选都是 `button.mdc-button`
            //   —— 从日志上**分不出谁是谁**，也就没法判断"是不是点错人"。
            //   ★ 缺的这四项正是能一次定性的：
            //     尺寸（0×0 = 根本没布局出来）、disabled、在不在 shadow 里、
            //     以及它的完整 class（用来区分顶部那个和工具栏 add_2 那个）。
            let desc = '（描述不出来）';
            let full = '';
            try {
                const n = cands[i].node;
                desc = String(n.tagName || '').toLowerCase()
                    + (n.className ? '.' + String(n.className).split(/\s+/)[0] : '');
                const bits = [];
                try {
                    const r = n.getBoundingClientRect();
                    bits.push('尺寸 ' + Math.round(r.width || 0) + '×' + Math.round(r.height || 0));
                } catch (e) { bits.push('尺寸读不到'); }
                bits.push('disabled=' + String(!!n.disabled));
                try {
                    const rn = n.getRootNode ? n.getRootNode() : null;
                    bits.push(rn && rn.host ? '在 shadow 里' : '在主文档');
                } catch (e) { bits.push('root 读不到'); }
                try {
                    full = String(n.className || '').replace(/\s+/g, ' ').trim();
                } catch (e) { full = ''; }
                desc = desc + '[' + bits.join('，') + ']';
                if (full) desc = desc + ' class=「' + full + '」';
            } catch (e) { /* 有些节点读属性会抛 */ }
            tried.push('第 ' + (i + 1) + ' 个 ' + desc + ' —— ' + cands[i].why);

            log('  · 试第 ' + (i + 1) + '/' + cands.length + ' 个入口候选：'
                + desc + '（' + cands[i].why + '）', 'info');
            clickHard(cands[i].node);
            if (await playWaitForWizard(probeMs, true)) {
                log('  ✓ 生效的是第 ' + (i + 1) + ' 个候选：' + desc + '。'
                    + '★ 下次可以直接把这个抄进 createCsl', 'ok');
                return true;
            }
        }

        const where = pageWhereNow();
        throw StepError('**试遍了 ' + cands.length + ' 个候选，页面都没进向导** —— '
            + '每个候选点完都回读了 ' + Math.round(probeMs / 1000) + ' 秒。'
            + '\n    ★ 当时页面在哪一屏：' + where
            + '\n    ★ 试过的候选（按顺序）：'
            + '\n      ' + tried.join('\n      ')
            + '\n    ★★ **别去动 `copyExisting` / `name` 那些选择器**：'
            + '向导没开的时候页面上当然没有那些控件，它们是**被冤枉的**。'
            + '\n    → 三种可能，按可能性排：'
            + '\n       ① **这个应用此刻真的不能建 CSL**'
            + '（手工点也没用 / 还欠着一份待审核的变更 —— '
            + '快照里出现过「正在审核中的更改」，那就是线索）；'
            + '\n       ② Google 不认**合成**事件（要真实鼠标才行）—— '
            + '那种情况下脚本这条路走到头了，得换真实输入那条路；'
            + '\n       ③ 入口在别的 tab / 别的层级里，这一屏上根本不成立。',
            'wrongpage');
    }

    /**
     * 点完「创建自定义商品详情」之后，**等向导真的出现**。
     *
     * ★★★★ 2026-09-18 加。这是真机 15:19:16 那一次的直接产物。
     *   那一次的顺序是：
     *     ① 找到入口、点下去            （走到这一步说明入口选择器是对的）
     *     ② `sleep(step_pause * 2)` = **1000ms** —— 就等这么点
     *     ③ `findOne('label=复制现有商品详情')` → 找不到 → 抛 notfound
     *   而 4 秒后的**手动快照显示页面还在列表页**：向导压根没打开。
     *
     *   ★ 于是那句报错说的是"按标注文字没找到对应的输入框"，
     *     读起来是**选择器配错了**（修法：改 CONFIG）；
     *     而真相是"**页面还没换屏**"（修法：等 / 查为什么没打开）。
     *     两者的修法完全相反 —— 跟 15:04 那次「入口找不到 /
     *     其实是停在向导里」是**同一个形状**。
     *
     * ★ 为什么"等"是对的解法，而不是"把那个 sleep 调大"：
     *   调大固定秒数是在**赌一个数字够用** —— 网络快时白等，慢时照样不够。
     *   而这一步的成功条件是**明确的**（"页面进了向导"）。
     *   既然判得出来，就该等它出现，而不是猜。
     *   ★ 这也正是本项目在 YouTube 侧定过的规矩：**点完必须回读**。
     *     这里缺的正是那一半 —— 只点，不等，也不验。
     *
     * ★ 超时之后**必须把矛头从 copyExisting 上挪开**：
     *   不挪的话，用户会跑去改一个**没配错**的选择器，然后重跑一次、
     *   再被同一句话拦住 —— 15:04 那次四连败就是这么来的。
     */
    async function playWaitForWizard(timeoutMs, quiet) {
        const t0 = Date.now();
        const hit = await waitFor(function () {
            try {
                const s = String(playPageShape() || '');
                return /向导/.test(s) ? s : null;
            } catch (e) {
                return null;   // 读形状出问题 ≠ 向导出现了，继续等
            }
        }, (timeoutMs === undefined || timeoutMs === null) ? CONFIG.wait_timeout : timeoutMs);

        if (hit) {
            log('  ✓ 向导已打开（等了 ' + (Date.now() - t0) + 'ms）', 'ok');
            log('  · 页面形状：' + hit, 'info');
            return true;
        }

        // ★ `quiet`：外面要"挨个试候选"的时候，**不能**让它抛 ——
        //   抛了第一个候选就等于整体失败，后面的候选根本没机会上场。
        //   安静模式返回 false，由调用方决定要不要换下一个。
        if (quiet) return false;

        const where = pageWhereNow();
        throw StepError('点了「创建自定义商品详情」，但等了 '
            + Math.round(CONFIG.wait_timeout / 1000)
            + ' 秒页面**还是没进向导**。'
            + '\n    ★ 当时页面在哪一屏：' + where
            + '\n    ★★ **别去动 `copyExisting` / `name` 那些选择器** ——'
            + '它们是**被冤枉的**：向导没打开的时候，页面上当然没有那些控件，'
            + '改了也没用。（真机 15:19 那一次就是报的 copyExisting 找不到，'
            + '而真正的问题是这一句。）'
            + '\n    → 三种可能，按可能性排：'
            + '\n       ① **点到的不是那个入口**。真机快照里常有两个同名的 ——'
            + '顶部的「创建自定义商品详情」和工具栏里的「add_2 创建自定义商品详情」；'
            + '脚本按 `aria-label` **精确匹配**，只会命中其中之一。'
            + '\n       ② 点下去了但页面没响应（这个应用没权限 /'
            + '这个入口需要先切到别的 tab）。'
            + '\n       ③ 确实只是慢（少见；可以把 `CONFIG.wait_timeout` 调大再试一次）。'
            + '\n    → 怎么查（**手动**，不要重跑脚本）：'
            + '\n       在页面上自己点一次那个入口，看向导开不开：'
            + '\n         · 开了 → 把那一刻的页面结构快照抓下来（面板上有按钮），'
            + '照里面第 1 步的**实际结构**配 `copyExisting`；'
            + '\n         · 没开 → 那不是脚本的问题，先去 Console 里搞清楚'
            + '这个入口为什么点不动。',
            'wrongpage');
    }

    /**
     * 尽量给一个输入框找出"页面上写给它看的名字"。
     *
     * ★ 选择器配不准的时候，这一行往往就是唯一能对上号的东西。
     *   所以宁可多列几个候选（aria-label / label / mat-label /
     *   formControlName / placeholder），由读的人去挑。
     *
     * ★ 不用 `CSS.escape`：它在老内核里可能是 undefined，而一个**诊断函数**
     *   因为拼选择器失败而少报一组信息，是最没必要的一种坏。
     *   改成遍历 label 比 for 属性，慢一点，但不会抛。
     */
    /**
     * 一个控件"页面上写给它看的名字"的**全部候选**。
     *
     * ★★★ 3.2.28：从 `labelOfControl` 里拆出来，因为要**反着用** ——
     *   见下面的 `findOneByLabel`。拆的理由是：
     *   "读出一个控件叫什么" 和 "按名字找一个控件" 必须是**同一份判据**，
     *   不然会出现"快照能报出名字、但按那个名字配选择器却找不到"这种
     *   最让人怀疑人生的现象。
     */
    function labelCandsOf(node) {
        if (!node) return [];
        const cands = [];
        const add = function (v) {
            const s = String(v || '').trim().replace(/\s+/g, ' ');
            if (s && s.length <= 60 && cands.indexOf(s) < 0) cands.push(s);
        };

        try {
            add(node.getAttribute && node.getAttribute('aria-label'));
            add(node.getAttribute && node.getAttribute('formcontrolname'));
            add(node.getAttribute && node.getAttribute('name'));
            add(node.getAttribute && node.getAttribute('placeholder'));

            // ① <label for="这个id">
            const id = node.id;
            if (id) {
                let labels = [];
                try { labels = document.querySelectorAll('label'); } catch (e) { labels = []; }
                for (let i = 0; i < labels.length; i++) {
                    if (labels[i].getAttribute
                        && labels[i].getAttribute('for') === id) {
                        add(labels[i].textContent);
                        break;
                    }
                }
            }

            // ② 往上找 mat-label / <label>（Angular Material 的常见结构）
            let cur = node;
            for (let hop = 0; cur && hop < 8; hop++) {
                let lab = null;
                try {
                    lab = cur.querySelector && cur.querySelector('label, mat-label');
                } catch (e) { lab = null; }
                if (lab && !isOurs(lab)) {
                    add(lab.textContent);
                    if (cands.length) break;
                }
                cur = cur.parentElement;
            }
        } catch (e) {
            // 诊断函数**不许抛** —— 它存在的意义就是在页面很怪的时候还能出声。
        }
        return cands;
    }

    function labelOfControl(node) {
        let cands = [];
        try { cands = labelCandsOf(node); } catch (e) { cands = []; }
        return cands.join(' / ');
    }

    /**
     * 一个节点"自己直接写的字"（不算后代贡献的那些）。
     *
     * ★ 为什么需要这一层：页面上到处是"祖先容器也**含有**这个字符串"——
     *   祖先的 `textContent` 等于它所有子孙文字拼起来。不加这层筛选，
     *   配额那一行会把整条链路的外层容器全列出来，几十条噪音里找不到答案。
     *
     * ★★ 判据是「**没有元素子节点**」—— 这种节点上 `textContent` 就等于
     *   它自己写的字，语义和"自己的文字"完全一致。
     *
     * ★★★ 这里**故意用 `children`（元素子节点）而不是 `childNodes`**：
     *   第一版写的是 `childNodes` + 只累加 `nodeType === 3` 的文字节点，
     *   那版在真实 DOM 里是对的，但在项目测试夹具里 `childNodes` **不存在** ——
     *   于是这个函数永远返回空串，上层 `if (t && …)` 静默跳过，
     *   "配额线索"那一条断言就**只可能匹配到它自己的标题文字**，
     *   变成一个永远绿的假断言（实测真的绿了，而且是靠标题里的
     *   `"3 / 50"` 这几个字绿的）。
     *   → 换成 `children` 之后，真实 DOM 和夹具语义一致，
     *     这条路径**真的被测到了**，也不会多出一个只有测试才走到的分支。
     */
    function ownText(node) {
        let s = '';
        try {
            const kids = node.children || [];
            if (!kids.length) s = node.textContent || '';
        } catch (e) {
            // 诊断函数**不许抛** —— 它存在的意义就是在页面很怪的时候还能出声。
        }
        return String(s).trim().replace(/\s+/g, ' ');
    }

    /**
     * 把**当前这一整页** Play Console 的结构原样报出来，并复制到剪贴板。
     *
     * ★ 为什么 Play 侧要一个「整页」版，而不是照抄 YouTube 的 dumpDialog：
     *   YouTube 那边所有要点的东西都在**一个对话框**里，所以作用域是对话框。
     *   Play 这边是**跨页**的：创建入口在列表页、模板向导在另一屏、
     *   名称 / Preview video / 保存在详情页。**你在哪一页点，它就该抓哪一页** ——
     *   所以作用域是 document，不是某个 root。
     *
     * ★★ 为什么非要有这个东西：
     *   CONFIG.selectors.play 里那 8 个选择器**全是 null**，一次真页面都没碰过，
     *   现在的 runPlaySteps 全是"按常见结构"推的。而 CSL 一共只有 **50 个配额**，
     *   试错一次的代价是一份**不可回收**的配额（不像 YouTube 删了能重传）。
     *   所以顺序必须是：**先看清页面 → 再改选择器 → 最后才跑**。
     *
     * ★★★ 为什么每个字段都带 id / aria-label / placeholder：
     *   配选择器最怕"按文字猜"。文字会随语言、A/B、版本变，id 和 aria-label
     *   稳得多。快照把这几样一起列出来，就是为了让下一次改配置是**抄**，
     *   而不是**猜** —— 这也是 dumpDialog 在 YouTube 侧已经证过一次的道理。
     */
    function dumpPlayPage(tag) {
        const lines = [];
        const push = function (s) { lines.push(s); };
        const seen = [];
        const uniq = function (s) {
            const t = String(s || '').trim().replace(/\s+/g, ' ');
            if (!t) return false;
            if (seen.indexOf(t) >= 0) return false;
            seen.push(t);
            return true;
        };
        // 本脚本面板自身被排掉了多少个 —— 要**说出来**。
        // YouTube 侧吃过一次：36 个按钮里 6 个是自家的，把「下一步」挤出了截断线，
        // 而快照上完全看不出来少了东西。计数写在抬头，读的人才知道这份快照"干净"。
        let oursCount = 0;

        // ★★★ 可见性**不包**，禁用**必须包** —— 这个区别是有依据的，不是随手的。
        //
        //   · `isVisible` 自己的实现就是"`getBoundingClientRect` 抛也只返回
        //     false"，它在结构上**不可能抛**。再给它包一层 try/catch，
        //     那个 catch 是**永远走不到**的分支 —— 而"够不着的防御比没有更糟"
        //     是本项目已经定过的规矩（它会让"测试很严"变成错觉）。
        //
        //   · `isDisabled` 不一样：它要往上走 12 层祖先，每一层都读
        //     `getAttribute('aria-disabled')`，**没有**兜底。第一版没包，
        //     实测就是一个陌生节点把它弄抛了，整份快照**从按钮那一段开始全没了** ——
        //     而快照存在的意义恰恰是"页面很怪的时候替我说话"。
        //     → 包，并且**如实报"读不出来"**（`[?]`），不能兜成 false ——
        //       那会把"不知道"说成"没禁用"，正是本项目反复踩的"看着对、其实错"。
        const dis = function (n) {
            try { return isDisabled(n); } catch (e) { return null; }
        };
        const disMark = function (v) {
            return v === null ? '[?]' : (v ? '[禁用]' : '');
        };

        // ★★★★ 2026-08-31-17-01-20：**id 是不是"渲染时生成的"**（GUID 形状）。
        //
        //   真机上 Play Console 的 id 长这样（运营抓回来的创建向导）：
        //     #aF1407E44-8667-47FA-9F7A-009884BC5F0E--29   ← 三个 radio
        //     #a16173DA9-9329-465C-87A8-95D18C830AF5--0    ← 模板下拉
        //   这种 id 跟着账号 / 实验分组 / 渲染次序变，**今天配明天就挂**。
        //   而挂的表现是"选择器没配"或者更糟 —— 点到别的元素上。
        //
        //   ★ 为什么在快照里就要标出来：用户拿着快照配选择器时，
        //     一眼看到 `#aF1407E44-…--30` 是最自然的填法，
        //     而它恰好是**最不能用**的填法。得在那一行当场拦住。
        const guidLike = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/i;

        /**
         * 从 `labelOfControl` 的结果里挑出**能当名字用**的那一段。
         *
         * ★★★ 为什么必须有这一层：`labelOfControl` 会把节点的 `name`
         *   **属性**也算进 label 候选，而且排得比 `<label for>` 还靠前。
         *   radio 组的 name 是**整组共用**的，于是三个单选项的"选项名"
         *   全长一个样：
         *     「radio-group-a64678140-5EFF-4382-8E90-38B8E69EFFB7--0」
         *   → 读快照的人**根本分不出哪个是哪个**。
         *   而 `copyExisting` 恰恰要靠这段区分「创建新商品详情 /
         *   复制现有商品详情 / 在群组中创建新的商品详情」。
         *   （实测：运营拿 3.2.24 抓回来的快照就是这样，三个名字一模一样。）
         *
         * ★★ 判据是**精确的，不是猜形状**：
         *   label 不可能恰好等于这个节点自己的 `name` 属性值 ——
         *   那只是属性回显。相等就否决。
         *   再叠一条 GUID 形状兜底（防它把 name 截断后混进别的候选）。
         *
         * ★ 不动 `labelOfControl` 本身：YouTube 侧也在用它，
         *   而"表单控件的 name"在那边是有意义的候选。改共用函数要重跑
         *   全量变异，收益不抵风险 —— 在调用点过滤。
         */
        const labelWords = function (n, raw) {
            const parts = String(raw || '').split(' / ');
            const nm = String((n.getAttribute && n.getAttribute('name')) || '');
            for (const p of parts) {
                const s = String(p).trim();
                if (!s) continue;
                if (nm && s === nm) continue;
                if (guidLike.test(s)) continue;
                return s;
            }
            return '';
        };

        try {
            push('── Play 页面结构快照（' + (tag || '手动') + '）──');
            push('URL：' + location.href);
            push('页面形状（脚本猜的）：' + playPageShape());

            // ── 按钮 / 可点元素 ──
            // ★★★★ 2026-09-17：**导航栏单独成桶** —— 这是真机快照逼出来的。
            //
            //   运营发回来的那份快照：写着「101 个按钮」，而列出来的
            //   前 60 条**全是左侧导航**（`class="item-link _ngcontent-inm-33"`
            //   加一个 `aria-label`）。真正要配的「下一步」被挤进了
            //   那 41 条**没显示出来**的里 —— 而这份快照存在的唯一目的，
            //   就是让人看清"向导这一页上到底有哪些可点的东西"。
            //
            //   ★ 这跟 YouTube 侧吃过的那个亏是同一件事的**第三张脸**：
            //     那边是**自家面板**的 6 个按钮挤掉了「下一步」，
            //     这边是**导航栏**挤掉了它。共同点是：
            //     **被截掉的正好是最关键的那一个。**
            //     所以只把 oursCount 报出来不够 —— 得让重要的东西**排在前面**。
            //
            //   ★★ 判据只有两条，都来自真机，宁可配不上也不多认：
            //     ① `<nav>` / `role="navigation"` 祖先（语义化 + ARIA，最稳）
            //     ② 自己是 `<a>` 且 class 里有 `item-link`（Play Console 左侧那排）
            //     再加上祖先 class 里有 `nav-drawer` / `sidenav` / `side-nav`。
            //
            //   ★★★ 特意**不**按 `_ngcontent-*` 判 —— 那是 Angular 的
            //     样式作用域标记，页面上**到处都是**（按钮、输入框、卡片
            //     全带），拿它当判据会把整页都算成导航，比不改还糟。
            //
            //   ★★★★ 而且导航项**不许静默扔掉** —— 单独成桶列在后面，
            //     并在抬头如实报出条数。理由跟「截断要说出来」是同一条：
            //     判据一旦配不上（Play 改版换个类名），用户得**看得出来**
            //     东西被挪走了，否则他会以为页面变了。
            const navWord = /(^|[\s_-])(item-link|navigation|nav-drawer|sidenav|side-nav)([\s_-]|$)/i;
            const inNav = function (n) {
                try {
                    let cur = n;
                    for (let hop = 0; cur && hop < 8; hop += 1) {
                        const tg = String(cur.tagName || '').toLowerCase();
                        const rl = String((cur.getAttribute && cur.getAttribute('role')) || '');
                        if (tg === 'nav' || rl === 'navigation') return true;
                        // ①/② 合并成一句：类名或标签名里带导航词（`ytcp-navigation-drawer`
                        //   这类是**标签名**里带的，所以两边都要看）
                        if (navWord.test(tg)) return true;
                        const cl = String((cur.getAttribute && cur.getAttribute('class')) || '');
                        if (navWord.test(cl)) return true;
                        cur = ancestorOf(cur);
                    }
                    return false;
                } catch (e) { return false; }
            };

            const btns = [];
            const btnSeen = [];
            const navBtns = [];      // 导航桶：**不参与正文的截断**
            const navSeen = [];
            // ★★★★ 2026-09-17：「跳过的」也得报出来。
            //   静默 `continue` 会让读的人以为「页面上没有这个东西」，
            //   于是反复去找一个根本不在快照里的按钮 —— 见下面 40 字那条。
            let btnLong = 0;          // 文字超过 40 字被跳过的
            let btnLongFirst = '';    // ★ 留第一条：让人判断"是不是误跳了正主"
            for (const n of safeDeepAll('button, a, [role="button"], '
                + '[role="tab"], [role="menuitem"], [role="option"]')) {
                // 一个节点读不出来，不该带走整份快照。
                try {
                    if (isOurs(n)) { oursCount += 1; continue; }
                    const t = String(n.innerText || n.textContent || '')
                        .trim().replace(/\s+/g, ' ');
                    if (!t) continue;
                    // ★ 文字太长的不列（下面正文还有 60 条上限），但**要报数**。
                    if (t.length > 40) {
                        btnLong += 1;
                        if (!btnLongFirst) {
                            btnLongFirst = t.slice(0, 60) + (t.length > 60 ? '…' : '');
                        }
                        continue;
                    }

                    const cls = String((n.getAttribute && n.getAttribute('class')) || '');
                    // ★★★★ 2026-09-17：类名原来是 `cls.slice(0, 40)` —— **按字符数切**。
                    //   真机上出事的方式（「下一步」那条）：
                    //     class="mdc-button mdc-button--unelevated primary…"
                    //     40 字符正好切在 `primar` **中间** → 快照里写成 `primar`
                    //     → 工具建议的选择器是 `.primar`，**匹配不到任何元素**。
                    //   ★ 而且**切的方向是反的**：MDC / Angular Material 把通用壳名
                    //     放前面、项目自己的类名放最后，按字符切**先丢掉的正是最有用的那个**。
                    //   → 改成按**类名个数**截：列出来的每个类名都是**完整的**，
                    //     截断了就留一个 `…` 当标记。读的人看得见"还有没列完的"，
                    //     工具也能把 `…` 当成"这不是个类名"直接跳过（而不是拿去拼选择器）。
                    //   为什么不是干脆不截：Play Console 的类名能到七八个，
                    //   全列会把每条撑成好几行，反而看不清 id 在哪。
                    const clsParts = cls ? cls.split(/\s+/).filter(Boolean) : [];
                    const clsShown = clsParts.slice(0, 4).join(' ')
                        + (clsParts.length > 4 ? ' …' : '');
                    const line = '    ' + (isVisible(n) ? '·' : '×')
                        + disMark(dis(n))
                        + ' 「' + t + '」'
                        + (n.id ? '  #' + n.id : '')
                        + (n.getAttribute && n.getAttribute('aria-label')
                            ? '  aria-label="' + n.getAttribute('aria-label') + '"' : '')
                        + (clsShown ? '  class="' + clsShown + '"' : '');

                    // ★ 判 inNav 放在**去重之前**：正文和导航各去各的重。
                    //   合成一次去重的话，导航里先出现的那个文字会把
                    //   正文里同名的按钮**整条吞掉**（比如两边都有「设置」），
                    //   于是正文桶里凭空少一个 —— 又是一次静默失真。
                    if (inNav(n)) {
                        if (navSeen.indexOf(t) >= 0) continue;
                        navSeen.push(t);
                        navBtns.push(line);
                        continue;
                    }

                    if (btnSeen.indexOf(t) >= 0) continue;
                    btnSeen.push(t);
                    btns.push(line);
                } catch (e) { continue; }
            }
            push('');
            push('按钮 / 可点元素（正文 ' + btns.length + ' 个'
                + (navBtns.length
                    ? ' + 导航栏 ' + navBtns.length + ' 个（单列在后面）' : '')
                + '，· 可见 / × 不可见 / [?] 禁用与否读不出来）：'
                + (btns.length ? '' : ' 正文里一个都没读到'));
            // ★★ 被跳过的**必须说出来**。不然读的人会把"没列出来"当成"没有"，
            //   然后花一整天去找一个其实存在、只是文字太长的按钮。
            if (btnLong) {
                push('    ★ 另有 ' + btnLong + ' 个可点元素**文字超过 40 字**没列出来'
                    + (btnLongFirst ? '（第一条：「' + btnLongFirst + '」）' : '')
                    + ' —— 这**不是"页面上没有"**，是这条诊断没显示。');
            }
            // ★★★ 这里必须是 `lines.push.apply`，**不能**是 `push.apply`。
            //   `push` 是我上面那个**只收一个参数**的包装（`function (s)`），
            //   而 `Function.prototype.apply` 是**按位置展开**传参的 ——
            //   `push.apply(lines, 60 条)` 只会把**第一条**塞进去，剩下 59 条丢掉；
            //   数组为空时更糟：`push()` 收到 `undefined`，于是快照里
            //   凭空多出一行字面量 `undefined`。
            //   而"只列出一条"看着完全正常，不会有人怀疑 —— 正是本项目
            //   最忌讳的那种静默失真。（实测被 20f/20h 两组断言逮到。）
            lines.push.apply(lines, btns.slice(0, 60));
            if (btns.length > 60) {
                push('    …… 正文还有 ' + (btns.length - 60)
                    + ' 个没列出来（太多了）—— ★ 这不是"没有"，是没显示完');
            }
            // 导航桶：**列在后面**，让正文那些先被看见。
            // ★ 上限 15 是故意的：导航项对"配选择器"几乎没用，列出来
            //   只是为了让人**确认它们没丢**。但它**必须有个上限** ——
            //   不封顶的话，导航一多又会把别的东西挤下去，等于没改。
            if (navBtns.length) {
                push('');
                push('  ── 导航栏里的可点项（' + navBtns.length
                    + ' 个）—— 配向导选择器基本用不上，列在这里只是让你确认'
                    + '"它们没丢"：');
                lines.push.apply(lines, navBtns.slice(0, 15));
                if (navBtns.length > 15) {
                    push('    …… 导航项还有 ' + (navBtns.length - 15)
                        + ' 个没列出来（都是导航，不影响向导）');
                }
            }

            // ── 输入框 / 可编辑字段 ──
            const fields = [];
            for (const n of safeDeepAll('input, textarea, select, '
                + '[contenteditable="true"], mat-select, [role="combobox"]')) {
                try {
                    if (isOurs(n)) { oursCount += 1; continue; }
                    const kind = n.tagName.toLowerCase();

                    // ★★★ 2026-09-17：radio / checkbox 的 `value` **恒为 "on"**，
                    //   打出来什么都不代表 —— 三个单选项会全部显示成
                    //   `当前值=「on」`，读起来像"三个都选中了"。
                    //   而它真正的选中状态在**另一处**（见下面「单/多选项」那段）。
                    //
                    //   实测代价：运营拿着这份快照，**判断不出**
                    //   「复制现有商品详情」到底是不是默认选中 ——
                    //   而这一项直接决定 `copyExisting` 怎么配。
                    const isPick = /^(radio|checkbox)$/.test(String(n.type || ''));

                    let val = '';
                    if (!isPick) {
                        try {
                            val = (n.value !== undefined && n.value !== null)
                                ? String(n.value) : ownText(n);
                        } catch (e) { val = ''; }
                        if (val.length > 60) val = val.slice(0, 60) + '…';
                    }

                    // ★ 只算一次。`labelOfControl` 内部要遍历一遍页面上的
                    //   所有 <label> 找一个 `for=` 对得上的 —— 一个字段算两遍
                    //   （一遍进去重键、一遍进显示）就是两倍的全页扫描，
                    //   页面上输入框一多就很明显。
                    //
                    // ★★ 再过一道 `labelWords`：单选/多选项的 `name` 是整组
                    //    共用的 GUID，直接印出来会让三个选项看着一模一样。
                    //    `labelWords` 过滤后可能为空（整个候选都是 name 回显），
                    //    那时保留原文 —— 有个信息总比空着强。
                    const labRaw = labelOfControl(n);
                    const lab = labelWords(n, labRaw) || labRaw;

                    const key = kind + '#' + (n.id || '') + '@' + (n.name || '')
                        + '|' + lab;
                    if (!uniq(key)) continue;
                    fields.push('    ' + (isVisible(n) ? '·' : '×')
                        + disMark(dis(n))
                        + ' ' + kind
                        + (n.type ? ' type=' + n.type : '')
                        + (n.id ? '  #' + n.id : '')
                        + (n.name ? '  name="' + n.name + '"' : '')
                        + '  label=「' + (lab || '（认不出来）') + '」'
                        // ★ 单选项不印「当前值」—— 那句 `on` 是误导，
                        //   它的选中状态由下面「单/多选项」那段负责。
                        + (isPick
                            ? '  ★ 选中状态见下面「单/多选项」那段'
                            : '  当前值=「' + (val || '（空）') + '」'));
                } catch (e) { continue; }
            }
            push('');
            push('输入框 / 可编辑字段（' + fields.length + '）：'
                + (fields.length ? '' : ' 一个都没读到'));
            lines.push.apply(lines, fields.slice(0, 40));
            if (fields.length > 40) {
                push('    …… 还有 ' + (fields.length - 40) + ' 个没列出来');
            }

            // ── 单/多选项（radio / checkbox）──
            //
            // ★★★ 为什么必须**单独**有这么一段（2026-09-17 补）：
            //
            //   ① 上面「输入框」那段对单选项印的是 `当前值=「on」` ——
            //      那是 radio 的 `value` 属性，**恒为 on**，什么都不代表。
            //      三个单选项全都印成"on"，读起来像"三个都选中了"。
            //   ② Play 侧有**三项配置**都直接依赖"哪个选项是选中的"：
            //      · `copyExisting`   —— 默认选的是不是「复制现有商品详情」
            //      · `aiDeclaration`  —— AI 声明要不要勾
            //      · `noResourceTag`  —— 「不为资源添加标签」要不要勾
            //      这三项以前只能靠人用眼睛看，而"看选中状态"恰好是
            //      最会看错的一件事：Angular 把选中态挂在**外层**节点上，
            //      里面那个 input 的 checked 可能一直是 false。
            //   ③ 三态上报：`[✓]` 选中 / `[ ]` 没选中 / `[?]` **读不到**。
            //      "读不到"绝不能写成"没选中"—— 拿 null 当 false 报错，
            //      这正是本项目反复栽过的那个坑（见 checkedState 的注释）。
            //      这里直接复用 `checkedState`，它本来就会往上找 6 层。
            const picks = [];
            const pickSeen = [];
            // ★★★ 2026-09-17 补：**跳掉了几个必须说出来**。
            //   原来"读不出选项文字"是 `continue` 掉的 —— 于是抬头只会写
            //   「单/多选项（0）：一个都没读到」，而它**分不清**
            //   这两种完全不同的情况：
            //     · 页面上真的没有单选项      → 不用管
            //     · 页面上有 8 个，但我一个文字都读不出来 → **得去 F12 看一眼**
            //   这正是刚写进 ops-userscript 技能那条「噪声不许静默扔掉」
            //   的翻版 —— 只不过这次扔的是"我要找的东西本身"。
            let pickCand = 0;     // 命中选择器的候选数（不含自家面板的）
            let pickNoText = 0;   // 有候选、但选项文字一个都读不出来
            let pickErr = 0;      // 读的时候抛了
            // ★★★ 光报"出错了几条"不够用 —— 用户拿到的还是一句
            //   "有 2 个读取时出错"，然后不知道该干嘛。
            //   留**第一条错误消息**，它通常直接就是答案。
            //   实测（写这条时正好撞上）：`checkedState is not defined` ——
            //   一眼就能看出是"名字不存在"，而不是"页面结构怪"。
            let pickErrFirst = '';
            for (const n of safeDeepAll('input[type="radio"], input[type="checkbox"], '
                + '[role="radio"], [role="checkbox"], '
                + 'mat-radio-button, mat-checkbox')) {
                try {
                    if (isOurs(n)) { oursCount += 1; continue; }
                    pickCand += 1;

                    // 这一项**自己**的文字。
                    // ★ 不能用 labelOfControl 的结果当选项名 —— 它会把
                    //   `name` 一起算进候选，于是单选项的"label"变成
                    //   「radio-group-a6B11B6F7…--1 / 创建新商品详情」。
                    //   前半截是**整组共用的 name**，当成选项名会误导。
                    let t = '';
                    let cur = n;
                    for (let hop = 0; cur && hop < 5; hop += 1) {
                        const tag = String(cur.tagName || '').toLowerCase();
                        const role = (cur.getAttribute && cur.getAttribute('role')) || '';
                        if (tag === 'mat-radio-button' || tag === 'mat-checkbox'
                            || role === 'radio' || role === 'checkbox'
                            || tag === 'label') {
                            // ★★★★ 2026-09-18：**掐掉材质图标名**。
                            //   真机屏 C 的诊断里有一条
                            //     [ ] 「check」  button.asset-card.pc-flex
                            //   —— 一个资源卡片，名字是图标字体的文字。
                            //   拿「check」去配 `copyExisting` 怎么配都对不上，
                            //   而它看起来**像个真的选项名**。
                            //
                            //   ★ 掐完若什么都不剩 → 不 break，继续往上找；
                            //     全都只剩图标名 → `t` 为空 → 计入
                            //     `pickNoText`，抬头如实说"读不出选项文字"。
                            //     **说看不清**，比**拿图标名冒充**对。
                            const s = stripIconWords(
                                String(cur.innerText || cur.textContent || ''));
                            // 太长的多半是"包住整块"的容器，不是这一项自己的文字
                            if (s && s.length <= 60) { t = s; break; }
                        }
                        cur = ancestorOf(cur);
                    }
                    if (!t) t = stripIconWords(labelWords(n, labelOfControl(n)));
                    if (!t) { pickNoText += 1; continue; }

                    const st = checkedState(n);
                    // 外层容器和里面的 input 会**都**命中，用「文字 + 状态」去重
                    const key = t + '|' + String(st);
                    if (pickSeen.indexOf(key) >= 0) continue;
                    pickSeen.push(key);

                    const id2 = n.id ? '#' + n.id : '';
                    const cls2 = String((n.getAttribute && n.getAttribute('class')) || '')
                        .trim().split(/\s+/).filter(Boolean).slice(0, 2).join('.');
                    // ★★★★ id 是 GUID 形状时**当场拦住**。
                    //   用户看到 `#aF1407E44-…--30` 最自然的反应就是把它
                    //   填进 `copyExisting` —— 而它恰恰是最不能用的那种
                    //   （今天配明天挂，挂了会先怀疑账号和改版）。
                    const idWarn = (n.id && guidLike.test(String(n.id)))
                        ? '  ★这个 id 是渲染时生成的，**不能当选择器**，'
                            + '只能按**选项文字**定位'
                        : '';
                    picks.push('    ['
                        + (st === true ? '✓' : (st === false ? ' ' : '?'))
                        + '] 「' + t.slice(0, 50) + '」  '
                        + String(n.tagName || '').toLowerCase() + id2
                        + (cls2 ? '.' + cls2 : '')
                        + (st === null ? '  ★ 读不到状态（≠"没选中"）' : '')
                        + idWarn);
                } catch (e) {
                    pickErr += 1;
                    if (!pickErrFirst) pickErrFirst = (e && e.message) || String(e);
                    continue;
                }
            }
            push('');
            push('单/多选项（读到 ' + picks.length + ' 个 / 命中 ' + pickCand
                + ' 个候选，[✓] 选中 / [ ] 没选中 / [?] 读不到）：'
                + (pickCand ? '' : ' 页面上一个都没有'));
            // ★★ 跳掉的部分**必须自己占一行**，不能只体现在数字差里 ——
            //   读快照的人是拿着它去配选择器的，"有 N 个读不出来"
            //   和"没有"必须一眼分得开。
            if (pickNoText || pickErr) {
                const parts = [];
                if (pickNoText) parts.push(pickNoText + ' 个**读不出选项文字**');
                if (pickErr) {
                    parts.push(pickErr + ' 个**读取时出错**'
                        + (pickErrFirst ? '（第一条：' + pickErrFirst + '）' : ''));
                }
                push('    ★ 其中 ' + parts.join('、')
                    + ' —— 这**不是"页面上没有"**。选项名要往上找 5 层'
                    + '（`mat-radio-button` / `role=radio` / `<label>`），'
                    + '都找不到说明结构不一样，去 F12 里看一眼再配。');
            }
            lines.push.apply(lines, picks.slice(0, 20));
            if (picks.length > 20) {
                push('    …… 单/多选项还有 ' + (picks.length - 20) + ' 个没列出来');
            }

            // ── 列表 / 表格：CSL 列表页最关键的一块 ──
            //   行数直接关系到"现在用掉几个配额"。
            push('');
            const tables = safeDeepAll('table, mat-table, [role="table"]')
                .filter(function (n) { return !isOurs(n); });
            if (tables.length) {
                push('表格（' + tables.length + '）：');
                tables.slice(0, 5).forEach(function (tb) {
                    let rows = 0;
                    let first = '';
                    try {
                        const rs = tb.querySelectorAll('tr, mat-row, [role="row"]');
                        rows = rs.length;
                        const txt = String(tb.innerText || tb.textContent || '')
                            .trim().replace(/\s+/g, ' ');
                        first = txt.slice(0, 100);
                    } catch (e) { /* 不抛 */ }
                    push('    · 行数=' + rows + '  开头：「' + first + '」');
                });
            } else {
                const items = safeDeepAll('mat-list-item, [role="row"], mat-card')
                    .filter(function (n) { return !isOurs(n); });
                push('表格：没有。列表项（mat-list-item / role=row / mat-card）：'
                    + items.length + ' 个'
                    + (items.length >= 2
                        ? ' —— ★ 这一堆很可能就是 CSL 列表本身' : ''));
            }

            // ── 配额线索 ──
            //   CSL 上限 50，是这套方案里最稀缺的资源。页面上一般会写"已用 / 上限"。
            //   抓到了就直接说，省得再回去数。
            //
            // ★★★★ 2026-09-18 改：**分成两桶**。
            //
            //   真机证据（3.2.27 抓回来的三屏）：屏 A 上报的是 `9/50` ——
            //   那才是 CSL 配额；而屏 B 那一栏印出来是
            //
            //     30/30 ｜ 70/80 ｜ 3826/4000 ｜ 1/1 ｜ 8/8
            //
            //   **五个全是别的配额**（截图数 / 说明字数之类）。
            //   本意是"帮你找 CSL 还剩几个"，实际干的是"页面上所有 N/M 形态
            //   的数字都抓过来" —— 于是真信号（9/50）被淹在一堆无关数字里，
            //   读的人反而会以为"配额快满了"。
            //
            //   ★ 为什么不是"只留 CSL 那一条、把别的扔掉"：
            //     那又会走到另一个极端 —— 页面上**真的**只剩 `3826/4000`
            //     而 CSL 配额写法变了的时候，快照会印"没看到"，
            //     读的人**无从知道我到底看没看**。噪声不许静默扔掉，
            //     但也不许冒充信号 —— 所以分开报，标题里写清哪个是哪个。
            const quota = [];          // 判成 CSL 的
            const quotaOther = [];     // 其它"已用 / 上限"形状的
            // ★ 附近的文字里出现这些，就认它是 CSL 的配额行。
            const QUOTA_WORD = /自定义商品详情|自定义商店页|Custom store listings|配额|上限|剩余|已用|quota|limit|remaining/i;
            // ★ 真机上 CSL 配额的上限就是 **50**（这是 Google 给的硬上限，
            //   文档里写死的）。上限等于 50 → 直接认。
            //   ★ 这条**只是加一道保险**，不是主判据：万一哪天 Google 调了上限，
            //     它就不灵了 —— 但那时"附近有 CSL 字样"那条还在。
            const CSL_CAP = 50;
            // 日期形状（2026/09/17）**一定不是配额** —— 硬排除。
            const DATEISH = /\d{4}\s*[/／]\s*\d{1,2}\s*[/／]\s*\d{1,2}/;
            // 候选**周围**的文字（自己 + 往上 4 层的直接文字 + 无障碍属性）。
            // ★ 用 ownText 而不是 textContent：`ownText` 不含子元素的文字，
            //   于是"标题 + 数字"这种排版能分开读；用 textContent 的话
            //   一个包住整块的大容器会把整页的字都拼进来 → 恒真。
            const quotaAround = function (n) {
                const parts = [];
                let cur = n;
                for (let hop = 0; cur && hop < 4; hop += 1) {
                    try {
                        const t = ownText(cur);
                        if (t) parts.push(t);
                        const g = cur.getAttribute && cur.getAttribute;
                        if (g) {
                            const al = String(g.call(cur, 'aria-label') || '');
                            if (al) parts.push(al);
                            const ti = String(g.call(cur, 'title') || '');
                            if (ti) parts.push(ti);
                        }
                    } catch (e) { /* 读不到就少一条线索，不抛 */ }
                    cur = ancestorOf(cur);
                }
                return parts.join(' ');
            };

            for (const n of safeDeepAll('div, span, p, h1, h2, h3, strong')) {
                try {
                    if (isOurs(n)) continue;
                    const t = ownText(n);
                    if (!t || t.length > 40) continue;
                    if (!/\d+\s*[/／]\s*\d+/.test(t)) continue;
                    if (DATEISH.test(t)) continue;
                    if (quota.indexOf(t) >= 0 || quotaOther.indexOf(t) >= 0) continue;

                    const m = /\d+\s*[/／]\s*(\d+)/.exec(t);
                    const cap = m ? parseInt(m[1], 10) : 0;
                    // ★★★★★ 2026-09-18 新增：**输入框的字数计数也是 N/M 形状**。
                    //
                    //   真机 00:58:09：名称框旁边印着 `32/50` —— 那是
                    //   **名称长度 32 / 上限 50**，跟 CSL 配额毫无关系；
                    //   而当时名称正好是 32 个字符。
                    //   ★ 后果很具体：同一份快照系列里它从 `9/50`（名称是
                    //     "默认商品详情的副本"= 9 个字）跳到 `32/50` ——
                    //     读的人会以为"11 分钟里烧掉了 23 个配额"。
                    //   ★ 这就是本项目那条老账：**报出来的标签撒谎，比不报还贵。**
                    //
                    //   判据：附近两三层的祖先里有 input / textarea /
                    //   contenteditable → 大概率是那个框的字数计数。
                    //   ★ 只往上走 3 层：再往上会套到整个表单，
                    //     那就会把真正的配额行也一起误判成计数。
                    //   ★ 判不准时**宁可归到"别的"那一桶，也不冒充配额** ——
                    //     "没看到"是诚实的，"看到了 32/50"会让人做错决定。
                    //
                    //   ★★★★ 2026-09-18（3.2.37）**这一版是错的，重做了**。
                    //     上面那版只说"附近有输入框"，**不带任何语义判断** ——
                    //     于是"往上 3 层"这个数字变成了唯一的防线，而它守不住：
                    //     向导那一屏可能**只有名称这一个输入框**，从任何位置往上
                    //     套几层都能套到那一屏的根，于是**真配额行也被判成字数计数**，
                    //     快照直接报「配额线索 —— CSL 的：没看到」。
                    //     ★ 漏报比误报贵：误报是数字不对，漏报是让人以为
                    //       "这一页根本没有配额"，于是跑去 F12 找、或者干脆不跑。
                    //     ★ 这条不是推演出来的 —— 是**夹具当场撞出来的**：
                    //       夹具那页的根上正好只有 1 个 input，`9 / 50` 立刻就
                    //       被判成了"字数计数"，快照说"没看到"。
                    //         （夹具只管真不真、不管顺不顺，这一条又赚回来了。）
                    //     现在的判据是**语义**的，不再靠层数：
                    //       ① 往上 ≤3 层，找**第一个**装着输入框的容器；
                    //          容器里必须**恰好 1 个**输入框（那是"某个框"的外壳）；
                    //          ≥2 个 = 整块表单，认了它页面上每个数字都"挨着输入框"。
                    //       ② 而且前一个数字要**对得上**那个框：`used` 正好等于
                    //          框里当前的字数 —— 真机 00:58 就是名称正好 32 个字符。
                    //   ★ 为什么不要"上限 == 框的 maxlength"这条更好凑的判据：
                    //     真机上名称框的 maxlength 很可能**也是 50**，跟 CSL 配额
                    //     撞个正着 —— 那样同一个页面上真配额 `9 / 50` 会被它一起误杀。
                    //     一个"根上只有 1 个 input、且那个 input maxlength=50"的页面
                    //     就足以复现。宁可漏掉"空框的 0/N"，也不要误杀真配额。
                    let nearField = false;
                    {
                        const used = parseInt((/^\s*(\d+)/.exec(t) || [0, 0])[1], 10);
                        let cur = n;
                        // ★★★★★ 2026-09-19（3.2.43）：判据是**语义**的 ——
                        //   "附近的输入框里，**有没有一个**的字数正好等于这个数"。
                        //
                        //   ★ 3.2.37 那一版在这里加过一道"**恰好一个**输入框"的门
                        //     （从别处借来的类比），而它**当场就把这个判据弄坏了**：
                        //     真机 16:27 的快照报 `配额线索 —— CSL 的：38/50`，
                        //     而 38 是**名称框的字数**（`prod-b260326_buffalo_duojitai_
                        //     KT_1080_gqw` 正好 38 个字符）——
                        //     第 2 步那一屏，名称框附近还有**两个单选**，
                        //     于是"恰好一个"不成立、`>1` 又直接 break → 守卫恒假。
                        //   ★★ 用户一句话就把它戳穿了：「我明明只建了 18 个」
                        //      —— 38 这个数**根本不对**，而它被当成 CSL 配额报了出来。
                        //
                        //   → 正确判据只看**语义**：数字等于某个附近输入框的字数。
                        //     "附近有几个输入框"跟"这个数是不是字数"**没有关系** ——
                        //     第 2 步上有几个框，都不改变"38 = 名称长度"这个事实。
                        //   （跟 `nativeFieldOf` 那个"恰好一个"的区别值得写下来：
                        //     那处是在问"**这一项**的状态"，组里的框多了就不能乱取；
                        //     这里是在问"**有没有哪个框**跟这个数对得上" ——
                        //     多个框只会让这个判断更可信。**同一个词，两处的含义相反。**）
                        for (let hop = 0; cur && hop < 3; hop += 1) {
                            let fields = [];
                            try {
                                fields = deepQueryAll('input, textarea, [contenteditable="true"]',
                                    cur);
                            } catch (e) { fields = []; }
                            for (let k = 0; k < fields.length; k += 1) {
                                try {
                                    const f = fields[k];
                                    const v = String(f.value === undefined
                                        || f.value === null ? '' : f.value);
                                    if (used > 0 && v.length === used) nearField = true;
                                } catch (e2) {
                                    // 读不动就跳过这一个 —— 宁可归"别的"，也不冒充配额。
                                }
                                if (nearField) break;
                            }
                            if (nearField) break;
                            cur = ancestorOf(cur);
                        }
                    }
                    const wordy = QUOTA_WORD.test(quotaAround(n));
                    if (wordy || (cap === CSL_CAP && !nearField)) {
                        quota.push(t);
                    } else {
                        quotaOther.push(t);
                    }
                } catch (e) { continue; }
            }
            push('');
            // ★★★ 这一行的**标题文字里不能出现"数字 / 数字"这种样例**。
            //   第一版写的是 `配额线索（页面上形如 "3 / 50" 的文字）：`，
            //   而 20j 的断言是 `/3\s*\/\s*50/.test(快照)` ——
            //   于是**没抓到配额的时候它也绿**：匹配到的是这行标题本身。
            //   这是本项目第四次栽在"断言匹配到自己写的文字"上（19k/19o/19p 之后），
            //   所以这次两头都堵：标题里不放样例，断言也要求它出现在冒号**之后**。
            push('配额线索 —— CSL 的（页面上"已用 / 上限"那种文字）：'
                + (quota.length ? quota.slice(0, 6).join(' ｜ ') : '没看到'));
            // ★★ 别的配额**单独一行**，并且标题里就写明"不是 CSL 的"。
            //   混在上一行里 → 读的人以为配额快满了；
            //   直接不印 → 读的人不知道"我到底看没看"。
            //
            // ★★★★★ 2026-09-19（3.2.43）：条件从 `if (quota.length)` 改成
            //   `if (quota.length || quotaOther.length)` —— **别处有东西就必须说**。
            //
            //   原来那个条件有个洞，而且**今天就正好掉进去了**：
            //   第 2 步那一屏**只有**名称框的字数计数（`38 / 50`）、没有真配额。
            //   于是 quota 空 → 这一行被整个跳过 → 那份快照上只剩一行
            //   `配额线索 —— CSL 的：…`。读的人（当时就是我）看到的是
            //   **"CSL 配额 38/50"**，据此算出"只剩 12 个"，还提醒用户别建到一半撞墙。
            //   ★ 用户一句「我明明只建了 18 个」把这个数戳穿了。
            //   → 只要页面上有"已用 / 上限"形状的数字，**它到底是不是 CSL 的、
            //     都得摆出来**。判成"别处"不等于可以不说 ——
            //     **"我看了，它不是 CSL 的"本身就是要报的信息。**
            if (quota.length || quotaOther.length) {
                push('配额线索 —— 页面上**别处**的"已用 / 上限"'
                    + '（★ 不是 CSL 的，别拿来判断还能建几个）：'
                    + quotaOther.slice(0, 6).join(' ｜ ')
                    + (quotaOther.length ? '' : '没看到'));
            }

            push('');
            push('（本脚本面板自身的元素已排除 ' + oursCount
                + ' 个 —— 它们不是页面证据）');
        } catch (e) {
            // ★ 诊断函数宁可报"打了一半"，也不能因为页面很怪就什么都不输出。
            //   把已经攒到的部分照样返回 —— 半份快照也比没有强。
            push('★ 快照打到一半出错了：' + (e && e.message));
        }

        for (const line of lines) log(line, 'info');
        return lines.join('\n');
    }

    // ════════════════════════════════════════════════════════════════════
    // 9. MAIN
    // ════════════════════════════════════════════════════════════════════

    function hostAllowed() {
        return CONFIG.allowed_hosts.indexOf(location.hostname) >= 0;
    }

    function main() {
        if (!hostAllowed()) return;

        if (location.hostname === 'studio.youtube.com') {
            buildYtPanel();
        } else {
            buildPlayPanel();
        }

        GM_registerMenuCommand('CSL Helper：清空日志面板', function () {
            LOG_LINES.length = 0;
            const box = document.querySelector('.cslh-log');
            if (box) box.textContent = '';
        });

        // ★ 面板拖丢了（或者拖到一个你不想要的地方）时的**唯一出路**。
        //   没有这一条的话，"位置存盘"就是一把单程票：
        //   万一拖到某个刁钻角度，用户只能去油猴里手删存储。
        GM_registerMenuCommand('CSL Helper：面板回到右上角', function () {
            const key = location.hostname === 'studio.youtube.com' ? 'yt' : 'play';
            const all = storeGet(STORE.PANEL_POS, {});
            delete all[key];
            storeSet(STORE.PANEL_POS, all);

            const p = document.querySelector('.cslh-panel');
            if (p) {
                p.style.left = 'auto';
                p.style.top = '12px';
                p.style.right = '12px';
            }
            log('面板已回到右上角（位置记录也清掉了）。', 'ok');
        });
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', main);
    } else {
        main();
    }
})();
